window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_009"]={"n":"李梦阳","dyn":"明","poems":[{"t":"郑生至自泰山二首 其二","f":"五言律诗","c":["俯首无齐鲁，东瞻海似杯。","斗然一峰上，不信万山开。","日抱扶桑跃，天横碣石来。","君看秦始后，仍有汉皇台。"]},{"t":"白鹿洞别诸生","f":"七言古诗","c":["东南自有匡庐山，遂与天地增藩卫。","山根插入彭蠡湖，峥嵘背杀三江势。","地因人胜古有语，于乎万物随兴废。","学馆林宫客不栖，千岩万壑堪流涕。","文采昔贤今尚存，讲堂寂寞对松门。","松门桂华秋月圆，拄杖高寻万古源。","梅岭古色照石镜，扶桑丹霞迎我轩。","绝顶坐歌霜月净，石潭洗足芝草繁。","更有冠者五六人，峭崖穷嶂同攀搴。","草行有时闻过虎，旦暮时复啼清猿。","我今胡为公务牵，蟋蟀在户难久延。","出山车马走相送，落日遂上鄱阳船。","生徒绻恋集涯浒，孤帆月照仍留连。","情深过厚亦其礼，谫薄窃愧劳诸贤。","明朝伐鼓凌浩荡，五峰双剑生秋烟。"]},{"t":"石将军战场歌","f":"古风","c":["清风店南逢父老，告我己巳年间事。","店北犹存古战场，遗镞尚带勤王字。","忆昔蒙尘实惨怛，反覆势如风雨至。","紫荆关头昼吹角，杀气军声满幽朔。","胡儿饮马彰义门，烽火夜照燕山云。","内有于尚书，外有石将军，石家官军若雷电，天清野旷来酣战。","朝廷既失紫荆关，吾民岂保清风店。","牵爷负子无处逃，哭声震天风怒号。","儿女床头伏鼓角，野人屋上看旌旄。","将军此时挺戈出，杀胡不异草与蒿。","追北归来血洗刀，白日不动苍天高。","万里烟尘一剑扫，父子英雄古来少。","天生李晟为社稷，周之方叔今元老。","单于痛哭倒马关，羯奴半死飞狐道。","处处欢声噪鼓旗，家家牛酒犒王师。","休誇汉室嫖姚将，岂说唐朝郭子仪。","沉吟此事六十春，此地经过泪满巾。","黄云落日古骨白，沙砾惨淡愁行人。","行人来折战场柳，下马坐望居庸口。","却忆千官迎驾初，千乘万骑下皇都。","乾坤得见中兴主，日月重开再造图。","枭雄不数云台士，杨石齐名天下无。","呜呼杨石今巳无，安得再生此辈西备胡。"]},{"t":"田园杂诗五首 其四","f":"五言古诗","c":["壮时掉尘鞅，老乃即农务。","值兹田事终，怛然感霜露。","原萋日以敛，林华不守故。","严霜净游气，翔鹄在天路。","鴳雀跃蓬蒿，啄食不满嗉。","而予竟何言，饭牛发今素。"]},{"t":"赠青石子二首 其一","f":"五言古诗","c":["高鸟有违群，离兽多悲音。","懿彼婉㜻子，怅焉分此襟。","朝发南河隅，夕暮乃北岑。","玄云既无极，黄波浩且深。","君其四海翔，无言还旧林。"]},{"t":"赠青石子二首 其二","f":"五言古诗","c":["季秋凋群木，寒潦滥中轨。","笳鼓济方舟，轩车匝河涘。","攀德惜遥迈，怅分睇驰晷。","采兰徒情结，把菊为谁美。","愿子厚衣襦，霜露自兹始。"]},{"t":"自南康往广信完卷述怀十首 其五","f":"五言古诗","c":["朝离傍罗浦，东至龙潭宿。","戢枻候明发，独寤守空曲。","宵昼有常理，欲往不获速。","多虑良搅眠，强置复攒触。","起立万动寂，湍响应鸣谷。","惊风临岸激，高月散春木。","絮云吐岑岫，玉绳低以属。","慨哉复奚道，徘徊至天旭。"]},{"t":"杂诗三十二首 其四","f":"五言古诗","c":["昔余曳鸣佩，谒帝扣天阊。","圣人垂衮衣，赓歌庶事康。","鼎成不我顾，奄忽驱龙翔。","生死变化理，反覆开存亡。","荣华有销落，连茹切微霜。","晨朝在须臾，返车栖扶桑。"]},{"t":"杂诗三十二首 其二十八","f":"五言古诗","c":["自闻鶗鴂鸣，于心怀忧伤。","阴气驯以厉，庭草陨繁霜。","皋兰萎不荣，瑟风游素商。","浮云昼易冥，白日时漏光。","登山期所思，反见高鸟翔。","蹀躞岂规步，讹言倘诪张。","挥袂层霄间，抚剑增慨慷。"]},{"t":"解酋行","f":"七言古诗","c":["都昌县南乾沙上，射雁者谁三五群。","毡帽红裘黄战裙，云是解酋官达军。","沙下北风吹舰旗，边军欢喜家军悲。","朝廷日夜望俘至，雪冻酋船犹住兹。","县官逃走驿官啼，要钱勒酒仍要鸡。","姚源遗孽尚反覆，尔曹不得誇辽西。"]},{"t":"土兵行","f":"古风","c":["豫章城楼饥啄乌，黄狐跳踉追赤狐。","北风北来江怒涌，土兵攫人人叫呼。","城外之民徙城内，尘埃不见章江途。","花裙蛮奴逐妇女，白夺钗镮换酒沽。","父老向前语蛮奴，\"慎勿横行王法诛。","华林姚源诸贼徒，金帛子女山不如。","汝能破之惟汝欲，犒赏有酒牛羊猪，大者升官佩绶趋。","蛮奴怒言：万里入尔都，尔生我生屠我屠。","劲弓毒矢莫敢何，意气似欲无彭湖。","彭湖翩翩飘白旟，轻舸蔽水陆走车。","黄云捲地春草死，烈火谁分瓦与珠。","寒崖日月岂尽照，大邦鬼魅难久居。","天下有道四夷守，此辈可使亦可虞。","何况土官妻妾俱，美酒大肉吹笙竽。"]},{"t":"豆莝行","f":"古风","c":["昨当大风吹雪过，湖船无数冰打破。","冰骧?峞山岳立，行人骇观泪交堕。","景泰年间一丈雪，父老见之无此祸。","鄱阳十日路断截，庐山百姓啼寒饿。","旌竿冻折鼙鼓哑，浙军楚军袖手坐。","将军部兵蔽江下，飞报沿江催豆莝。","邑官号呼手足皴，马骡鸡犬遗眠卧。","前时边达三千军，五个病热死两个。","弯弓值冻不敢发，昔何猛毅今何懦。","李郭邺城围不下，裴度淮西手可唾。","从来强弱不限域，任人岂论小与大。","当衢寡妇携儿哭，秋禾枯槁春难播。","纵健徵科何自出，大儿牵繵陆挽驮。"]},{"t":"朝饮马送陈子出塞","f":"古风","c":["朝饮马，夕饮马。","水咸草枯马不食，行人痛哭长城下。","城边白骨借问谁，云是今年筑城者。","但道辞家别六亲，宁知九死无还身。","不惜身为城下土，所恨功成赏别人。","去年贼掠开成县，黑山血迸单于箭。","万里黄尘哭震天，城门昼闭无人战。","今年下令修筑边，丁夫半死长城前。","城南城北秋草白，愁云日暮鸣胡鞭。"]},{"t":"胡马来再赠陈子","f":"七言古诗","c":["冬十二月胡马来，白草飒飒黄云开。","沿边十城九城闭，贺兰之山安在哉。","传闻清水不复守，游兵早阨黄河口。","即看烽火入甘泉，已诏将军屯细柳。","去年穿堑长城里，万人齐出千人死。","陆海无毛杀气蒸，五月零冰冻河水。","当时掘此云备胡，胡人履之犹坦途。","闻道南侵更西下，韦州固原今有无。","从来贵德不贵险，英雄岂可轻为谟。","尚书号令速雷电，抱玉谁敢前号呼。","遂令宵旰议西讨，兹咎只合归吾徒。","我师如貔将如虎，九重按剑赫斯怒。","惜哉尚书谢归早，不睹将军报平虏。"]},{"t":"朱迁镇庙二首 其一","f":"五言律诗","c":["水店回冈抱，春湍滚白沙。","战场犹傍柳，遗庙只栖鸦。","万古关河泪，孤村日暮笳。","向来戎马志，辛苦为中华。"]},{"t":"朱迁镇庙二首 其二","f":"五言律诗","c":["宋墓莽岑寂，岳宫今在兹。","风霜留桧柏，阴雨见旌旗。","百战回戈地，中原左衽时。","土人严伏腊，偏护向南枝。"]},{"t":"早春繁台","f":"五言律诗","c":["泯泯春犹早，行行赏不违。","柳黄沙际见，草色雪中归。","积水生云气，孤城下夕晖。","谁禁台寺望，北雁又将飞。"]},{"t":"狱夜","f":"五言律诗","c":["檐景栖栖落，台居黯黯幽。","鼠缘争果坠，萤过隔衣流。","幸窃馀光照，那蠲多穴愁。","亦知广川子，局蹐为春秋。"]},{"t":"河上秋兴十首 其七","f":"五言律诗","c":["十载宋梁间，鸡鸣望四关。","月来天似水，云起树为山。","朝市今何处，流波去不还。","高秋未归客，肠断浊泾湾。"]},{"t":"南阳宅访徐祯卿","f":"五言律诗","c":["东阁能留第，南人暂亦居。","琴书迁卧内，骑马到堂除。","残树喧巢鹊，微风走壁鱼。","追思秉钧日，冠盖烂盈闾。"]},{"t":"立春东郑生问其愁病","f":"五言律诗","c":["天涯春又至，游子近如何。","病久诗难减，乡遥梦易多。","药苗春尚雪，舟楫海初波。","旧业方山下，东风遍绿莎。"]},{"t":"冬日灵济宫十六韵","f":"五言古诗","c":["贝阙昆崙外，浮生此路疑。","蓬莱移禁国，尘世出瑶池。","蕞尔双仙迹，飞腾后晋时。","论功竟恍惚，谶兆且逶迤。","怂恿精灵托，呼嘘霹雳随。","先皇亲议号，继圣必修辞。","爵陟王侯上，尊同帝者师。","龙襦分内锦，宫女准昭仪。","雨露宫城切，星辰天仗移。","琳琅摇绣栱，松柏荫丹墀。","瓶内金花踊，龛前紫凤垂。","晴还日月秘，暝则鬼神悲。","玉鼎推龙虎，瑶编述姹儿。","汉惟栾大显，秦竟羡门欺。","五帝非无术，千龄今见谁。","累朝盟誓册，玉匮少人知。"]},{"t":"秋怀八首 其二","f":"七言律诗","c":["庆阳亦是先王地，城对东山不窋坟。","白豹寨头憔皎月，野狐川北尽黄云。","天清障塞收禾黍，日落溪山散马群。","回首可怜鼙鼓急，几时重起郭将军。"]},{"t":"秋怀八首 其六","f":"七言律诗","c":["大同宣府羽书同，莫道居庸设险功。","安得昔时白马将，横行早破黑山戎。","书生误国空谈里，禄食惊心旅病中。","女直外连忧不细，急将兵马备辽东。"]},{"t":"九日南陵送橙菊","f":"七言律诗","c":["朱门美菊采先芳，玉圃新橙摘早霜。","传送满盘真斗色，分看随手各矜香。","深怜便合移樽酹，暂贮应须得蟹尝。","独醉秋堂卧风物，一年晴雨任重阳。"]},{"t":"限韵赠黄子","f":"七言律诗","c":["禁垣春日紫烟重，子昔为云我作龙。","有酒每邀东省月，退朝曾对掖门松。","十年放逐同梁苑，中夜悲歌泣孝宗。","老体幸强黄犊健，柳吟花醉莫辞从。"]},{"t":"自关西回展外舅大夫之墓用前韵","f":"七言律诗","c":["遥阡无计扫春莱，絮酒何因到夜台。","西客两年和泪到，北风千里共愁来。","田园树大身先葬，书画楼成昼不开。","殁后外孙今五尺，百年遗恨使人哀。"]},{"t":"出使云中作","f":"七言律诗","c":["黄河水绕汉边墙，河上秋风雁几行。","客子过壕追野马，将军韬箭射天狼。","黄尘古渡迷飞挽，白日横空冷战场。","闻道朔方多勇略，只今谁是郭汾阳。"]},{"t":"晚出禁闼二首 其一","f":"五言绝句","c":["杨柳南城道，芙蓉小苑通。","内使来调马，君王敕射熊。"]},{"t":"东华门偶述","f":"五言绝句","c":["银瓮烂生光，盘龙绣袱香。","但知从内出，不省赐何王。"]},{"t":"黄州二首 其一","f":"五言绝句","c":["浩浩长江水，黄州那个边。","岸回山一转，船到堞楼前。"]},{"t":"江行杂诗七首 其四","f":"五言绝句","c":["迎送山相似，舟移迷北南。","回看皂口日，已照石华潭。"]},{"t":"江行杂诗七首 其六","f":"五言绝句","c":["日出青蘋湿，江浑路不分。","昨宵驱雨至，知是海南云。"]},{"t":"送人","f":"五言绝句","c":["颇讶枫林赤，无风叶自鸣。","来人与归客，同听不同情。"]},{"t":"子夜四时歌八首 其一 春歌之一","f":"五言绝句","c":["共欢桃下嬉，心同性不同。","欢爱桃花色，妾愿桃生核。"]},{"t":"子夜四时歌八首 其二 春歌之二","f":"五言绝句","c":["柳条宛转结，蕉心日夜卷。","不是无舒时，待郎手自展。"]},{"t":"春曲二首 其一","f":"五言绝句","c":["春风度山阁，凭轩望江路。","帘动时有香，不见花开处。"]},{"t":"春曲二首 其二","f":"五言绝句","c":["翩翩谁家燕，衔泥向何所。","避人花丛里，忽复梁间语。"]},{"t":"杨白花二首 其二","f":"五言绝句","c":["宁唱采菱曲，休歌杨白花。","菱生犹有蒂，花去落谁家。"]},{"t":"相和歌","f":"五言绝句","c":["美人罗带长，风吹不到地。","低头采玉簪，头上玉簪坠。"]},{"t":"月夜吟","f":"五言绝句","c":["月出东方高，剌剌灯下语。","漂摇林中箨，淅淅如寒雨。"]},{"t":"开先寺五首 其三","f":"五言绝句","c":["瀑布半天上，飞响落人间。","莫言此潭小，摇动匡庐山。"]},{"t":"寄徐子二首 其二","f":"五言绝句","c":["东省堂前树，南阳宅里花。","春风如往日，夜月向谁家。"]},{"t":"寄都主事穆","f":"五言绝句","c":["江草唤愁生，思君黄鸟鸣。","遥心将夜月，同满阖闾城。"]},{"t":"赠客","f":"五言绝句","c":["出郭江南望，暮天云北飞。","断蓬寒更转，长路几人归。"]},{"t":"赠王左史二首 其二","f":"五言绝句","c":["君家百瓮酒，留连胡不饮。","花月我自来，醉即花间寝。"]},{"t":"送王生北行二首 其二","f":"五言绝句","c":["朝散午门西，春风起御堤。","上林花半发，几处早莺啼。"]},{"t":"汴中元夕五首 其三","f":"七言绝句","c":["中山孺子倚新妆，郑女燕姬独擅场。","齐唱宪王春乐府，金梁桥外月如霜。"]},{"t":"汴中元夕五首 其五","f":"七言绝句","c":["细雨春灯夜色新，酒楼花市不胜春。","和风欲动千门月，醉杀东西南北人。"]},{"t":"春日宴豫斋王子之第二首 其一","f":"七言绝句","c":["紫宫华宴敞春风，密树初花日映红。","向暮酒阑香不断，始知春在绮罗中。"]},{"t":"云中曲送人十首 其三","f":"七言绝句","c":["黑帽健儿黄貉裘，匹马追胡紫塞头。","相逢不肯通名姓，但称家住古云州。"]},{"t":"云中曲送人十首 其六","f":"七言绝句","c":["白登山寒低朔云，野马黄羊各一群。","冒顿曾围汉天子，胡儿惟说李将军。"]},{"t":"经行塞上二首 其二","f":"七言绝句","c":["天设居庸百二关，祈年更隔万重山。","不知谁放呼延入，昨日杨河大战还。"]},{"t":"夏口夜泊别友人","f":"七言绝句","c":["黄鹤楼前日欲低，汉阳城树乱乌啼。","孤舟夜泊东游客，恨杀长江不向西。"]},{"t":"功德寺","f":"五言古诗","c":["宣宗昔行幸，游戏玉泉傍。","立宇表巀嵲，开池荷芰香。","波楼递蹙沓，风松奏笙簧。","百灵具来朝，落日锦帆张。","万乘雷霆动，千岩灭流光。","绮绣错展转，翠旗沓低昂。","法眷撞钟鼓，宫女拭御妆。","笙镛沸两序，星斗宿岩廊。","至尊奉太后，国事付三杨。","六军各宴眠，百官守旧章。","巡非瑶水远，迹岂玉台荒。","呜呼百年来，回首一慨伤。","凤腾赤霄暮，龙归竟茫茫。","山风撼网户，紫殿生夜霜。","退朝值休沐，我行暂翱翔。","娟娟登岸林，惨惨度石梁。","废道哀湍写，松柏间成行。","启钥肃览历，过位增悲凉。","积久洒扫缺，乳鸽鸣膳堂。","旧时琉璃井，倒树如人长。","神巳佐上帝，教犹托空王。","铃磬飒鸣戛，晨昏礼相将。","盘游非圣理，操纵在先皇。","至今朝廷上，不改旧纪纲。"]},{"t":"乙丑除夕追往愤五百字","f":"古风","c":["忆昔蕤宾初，皇疾辍临仗。","维日白气亘，黑风复排踼。","俄传天柱折，忽若慈母丧。","帝本尧舜姿，末履转清伉。","敛衽接耆硕，高出文景上。","两宫悦孝子，九庙歆流鬯。","毅然整六师，霹雳无前向。","犬羊遁朔漠，鲸鲵蛰溟涨。","渊冲不凝寿，日表空殊相。","蜿蜿湖中龙，一夕拔惊浪。","回首哭苍梧，魂断湘南瘴。","念昨下明纶，臣也诚无状。","誓死叫阊阖，伸颈甘砧盎。","梁窦势如灼，汉廷色惆怅。","皇乃西园游，召彼侍供张。","从容杯酒间，似让还非让。","未剖青琐封，巳下金鸡放。","臣某讵足惜，统体关衰王。","历数古明辟，圣节畴能尚。","逝欲碎臣骨，吁帝不得迋。","攀髯眇莫及，痛哭桥山葬。","玉光动前星，朱符阐灵贶。","主器难久虚，勉起答群望。","金木歘为祟，太白昼相抗。","羯胡敢余侮，吾徒尽乘障。","呜呼榆台役，弃我六千壮。","踉跄战士骨，躐趿将军韔。","二竖固轻率，腐尸亦云当。","所恨国威辱，北鄙气悽怆。","钲鼓疑皇情，何以慰宸况。","悽悽建未月，临门遣征将。","纨裤作元戎，京军本浮宕。","翻使沿边卒，束手遭箠掠。","揭?云中城，谁复扼其吭。","胡来风雨声，胡去横拍唱。","千村与万落，人烟莽荡荡。","婴儿贯高槊，志妇经衣桁。","狐狸叫破垒，落日悄濸漭。","此辈诚鼠窃，反覆亦难量。","骐骥驾盐车，虚名缚肮脏。","世岂乏颇牧，贱或执鞭杖。","琐琐登坛子，饱之则飞飏。","吁此良太枉，国慨何由畅。","水旱而秋雷，阴阳迭骄亢。","皇天虽至公，视之但坱坱。","臣当历服始，谬进大夫行。","退朝实愤切，欲吐畏官谤。","武王秉黄钺，师事太公望。","列圣构梁栋，驾驭亦英匠。","先帝升遐日，临榻召三相。"]},{"t":"奉送大司马刘公归东山草堂歌","f":"古风","c":["东山有草堂，缥缈云峤孤。","前对祝融峰，下瞰巴陵湖。","明公昔时此堂居，麋鹿熊豕当窗趋。","洞庭日落风浪涌，倒影射堂堂欲动。","惨淡谁闻紫芝曲，独善不救苍生哭。","先帝亲裁五色诏，老臣曾受三朝禄。","此时边徼多战声，曳履谒帝登承明。","谢安笑却淮淝敌，魏相坐测单于兵。","九重移榻数召见，夹城日高未下殿。","英谋密语人不知，左右微闻至尊羡。","自从龙去不可攀，公亦卧病思东山。","湘娥含笑倚竹立，山鬼窈窕堂之侧。","上书苦死只欲归，圣旨优容意悽恻。","内府盘螭缕金织，赐出倾朝皆动色。","白金之铤红票记，宝钞生硬鸦翎黑。","崇文城门水云白，是日观者涂路塞。","城中冠盖尽追送，尘埃不见长安陌。","人生富贵岂有极，男儿要在能死国，不尔抽身早亦得。","君不见汉二疏，千载想慕传画图。","即如草堂何处无，禄食腼窃胡为乎。","乃知我公真丈夫，呜呼乃知我公真丈夫。"]},{"t":"鄱阳湖十六韵","f":"五言古诗","c":["太祖平陈日，楼船下此湖。","波涛留壮色，天地见雄图。","水上开黄屋，云中下赤乌。","士犹询后载，戈巳倒前徒。","力屈鲸鲵仆，声回雁鹜呼。","横江收玉笥，跨海定金符。","文轨遥通楚，梯航讫至吴。","虎贲虽莫敌，龙战岂全辜。","血染犹丹草，骨沉空白芜。","汀洲夜寂寂，霜月鬼呜呜。","杀气鼋鼍徙，腥风岛屿孤。","罾人拾古镞，艇客慨秋菰。","伟彼高光烈，还将萧邓须。","英谋协睿算，勇奋想长驱。","剑瘗神仍王，舟焚势与徂。","康山巍庙在，忠武激顽夫。"]},{"t":"如梦令","f":"古风","c":["昨夜洞房春暖。","烛尽琵琶声缓。","闲步倚阑干，人在天涯近远。","影转。","影转。","月压海棠枝软。"]},{"t":"禋社六章章八句","f":"古风","c":["元年仲春，吉日维戊。","天子肇修，于社式对。","二后协于百辟，既袛既戒。","其日丁已，三星彗彗。","百辟至止，萃于皋门。","三星在隅，乃辟乃阍。","有渰其云，有零其雨。","赤舄跄跄，于坛之所。","八佾剡剡，百燎盈庭。","左金右石，镛鼓孔行。","帝命元臣，曰戎朕代。","式虔式穆，厥维朕载。","元臣受命，爰肃其躬。","月出则光，三星在中。","磬管喤喤，有万斯舞。","爰配二辟，牺尊维俎。","于神来格，殷殷番番。","龙旂载杨，雷霆啍啍。","明明对越，肃肃奔走。","神既醉饱，锡辟之祐。","遹皇缵业，配天于京。","三辰允祯，曰雨曰旸。","皇降嘉实，来牟黍杜。","敷文戢戈，克绍冢上。"]},{"t":"辟雍六章章八句","f":"古风","c":["天子至止，于彼群雍。","和鸾央央，其来雍雍。","象辂金衡，有苍其龙。","光于庙宫，是依是崇。","吉日维申，修我元祀。","皇祀设乐，镛鼓万舞。","有筐有篚，以享以祀。","群执肃肃，秉德弗渝。","维其观者，三氏孙子。","其冠峨峨，来忻来止。","翩役凤鸟，集于东林。","绎其观者，其烂如云。","自门徂基，辟俨若思。","青衿济济，以辟以师。","爰命祭酒，司业拜手。","吁哉嘉谋，作民元后。","帝若曰都，戎言式弘。","匪道何程，匪猷曷承。","载弼元理，维协乃有。","众拜稽首，天子万寿。","旟旐旆旆，渊渊代鼓。","皇发辟雍，用惠下土。","自天降休，丰年穰穰。","蔼蔼王多吉人，四国用康。"]},{"t":"甘露八章章四句","f":"古风","c":["于辟是兴，皇用锡祉。","苞有八业，侯茂侯采。","填填墉壑，有严庙宫。","湛彼露斯，既沾既降。","湛彼露斯，于松于柏。","是塈是掇，罔匪泽泽。","菀彼陵树，有烂其华。","盈盈蓁蓁，光于邦家。","荡荡上帝，降监在兹。","维辟时格，岂曰匪时。","其时伊何，厥阳载升。","爰液乃濡，惠我孔明。","其昭伊何，曰帝攸绩。","靡滥靡僣，甘澍斯穫。","明明昊天，是歆是臧。","臣作诵言，告于万方。"]},{"t":"观牲五章","f":"古风","c":["赫赫明明，天子攸行。","以修肇褅，以对于上帝。","天子至止，观牲于郊。","龙旂交交，马鸣萧萧。","帝至于郊，于赫有临。","载穆载钦，曰岁事是歆。","帝降于圉，牺人脱楅。","羊牛鹿豕，■■濯濯。","濯濯甡甡，翔帝之圉。","其牲孔硕，甫甫麌麌。","城人伐鼓，帝至郊所。","干旄淠淠，虎士孔武。","乘彼大路，八鸾与与。","昭于万邦，光于皇祖。"]},{"t":"效五子之歌正德年作","f":"古风","c":["大禹曰咨咨太康，女何乐于田，十旬弗返。","百姓离逖，女厥绪用殄。","洛汭汤汤，流于冀方。","曷归曷归，我心忧伤。","大禹曰咨咨太康，敬哉有土母，荼毒下民。","母曰民小，母我崇尊。","天自我民明威。","大禹曰咨咨太康，天命难忱，慎德者昌。","维帝克堪，奄有万方。","乃罔攸序，上帝殛罚女。","大禹曰姿咨太康，母游于盘，母荒于田。","母小人是庸，嗜货靡不颠。","母曰予一人，天下予何，天方降尔瘥。","大禹曰咨咨太康，彼曰不臧，是谋是从。","此曰既经，寔戾是戕。","不念尔祖，独不念尔土。","呜呼敬哉敬哉，天罔私骘女。"]},{"t":"有鸱六章","f":"古风","c":["有鸱有鸱，集于乔林。","征夫遑遑，以北以南。","居人之子，我是用覃。","东人之子，衣服粲粲。","西人之子，车马有烂。","中人之子，噂噂衎衎。","谁屋室潭，潭谁教猱。","有冠谁遇，人艰难谁，寤寐永叹。","尔视尔友，令色令仪。","弗视尔友，靡臧靡嘉。","尔视尔友，予德予哲。","背姻背娅，罔不愆蔑。","朔日日亏，十月其雷。","山川震崩，星辰逆行。","二三君子，匪疚匪疾。","曰时则然，匪我敢逸。","燕雀在堂，翩翩其羽。","鱍鱍鲂鱮，在于河渚。","弗念弗畜，孰获尔所。","小子作诗，诲言式女。"]},{"t":"青青者莆三章","f":"古风","c":["青青者莆，生于污也。","旟旐有翩，君子攸悲。","有荡者道，其木乔乔。","有鸟哓哓，女有巢漂摇。","有石巉巉，在于中泉。","我思溉罍，畏子不前。"]},{"t":"有兔","f":"古风","c":["有兔有兔，其来??。","有罿??，虞人之缚。","有兔绥绥，瞻子伤悲。","岂女有母，我子无所。","尔粟尔糜，尔有猫狸，云胡乐而。"]},{"t":"河之杨","f":"楚辞体","c":["河之杨，其叶幡幡。","子之归矣，谁与我晤言。","河之湍兮，我心慱兮，庶见子旋兮。"]},{"t":"我行","f":"古风","c":["采虻采虻，于彼中野。","我行思子，瞻望伊阻。","我有笾有俎，湑湑我酤。","坎坎我鼓，反反我舞。","有筵有几，我有桃李。","不见子都，实维忧矣。"]},{"t":"始雷","f":"楚辞体","c":["雷之磕兮，西山之阳兮。","翕兮张兮，发坤藏兮，阐而昌兮。","雷之升兮，列缺光兮，驱罔象。","兮划幽匿兮，维民之福兮。","雷虩虩兮，民愬愬兮。","施甘雨兮，冒下土兮，登我稷黍兮。"]},{"t":"我出城闉","f":"古风","c":["我出城闉，浩浩其流。","我车我马，登彼方舟。","昔也长薄，乃今舟之。","滔滔波涂，昔也畴之。","呜呼苍天，雨无其极。","淤我良田，浥我稼穑。","卖牛买船，卖锄买楫。","夕之朝之，济有深涉。","彼负者子，涉寒号咷。","彼辈者子，陷泥中涛。","彼车者子，马颤濡毛。","彼往来者谁子，冠盖而游遨。"]},{"t":"河之渚","f":"古风","c":["河之渚，凫雁与与。","我驾我车，载言送汝。","河水濞濞，汝舟淠淠。","冬十有一月，甲申者岁。","河之沙，浩浩其霜。","人庐人处，子也独行。","庐匪不怀，兹非我邦。","岂无念处，旋我旧乡。","旧山有庐，溪则有鱼。","有车马驱，有琴瑟笙竽。","烈风旆旆，寒日冰濑，汝征汝迈。","山有栲，亦或有栳。","鱼潜于渊，或在于沼。","刍荛之言，君子敬听。","慎尔威仪，择尔友朋。"]},{"t":"型范","f":"古风","c":["器土必型，器竹必范。","绥则有蝉，冠则有范。","哲人畏威，爰矜爰业。","省之察之，春冰是涉。","帝命攸畀，而胡罔嘉。","忽心乘之，厥玉斯瑕。","圣戒罔念，贤省日三。","舆则倚之，立则如参。","渊鱼负冰，谷鸟嘤嘤。","贤岂在贵，愚匪无荣。","维彼贤人，省躬靡疚。","彼愚何人，外华中垢。"]},{"t":"归寿 其一","f":"古风","c":["春日既熙，有繁其梅。","爰启我堂，我尊我罍。","穆穆其宾，揖让先后。","介我眉寿，饮我清酒。"]},{"t":"归寿 其二","f":"古风","c":["尔生之辰，尔子遄驰。","何以献之，玉斗金卮。","春华在殷，舞衣斓斑。","庭树青葱，鸟鸣关关。"]},{"t":"归寿 其三","f":"古风","c":["又何献之，崧高之松。","翠蕤屈枝，盘盘如龙。","又何献之，维河之鲤。","玉鬐曜阳，金鳞泚泚。"]},{"t":"卫女操","f":"楚辞体","c":["有狐绥绥兮，在彼河梁。","我欲济之兮，河无航。","瞻彼故丘兮，淇水浅浅。","怀我父母兮，不能奋翻。","嗟嗟不能奋翻，予安用存兮。"]},{"t":"漆室女操","f":"古风","c":["父母不听，女言女义。","不至公门，嗟嗟柰何。","朝倚柱而吟，暮倚柱而歌。","知我者谓我心忧，不知我者谓我求。","为家吾宁为地上之茂草，诚不忍负岩墙而生。"]},{"t":"慧蛾操","f":"楚辞体","c":["翼之渐渐兮，入我襜兮。","慧远贼兮，信彼黠兮，宁尔获兮。"]},{"t":"哀凤操","f":"楚辞体","c":["凤之来兮尔胡为兮。","牛有皂兮鸡有栖。","凤兮凤兮今何归，伤哉命兮，我心悲。"]},{"t":"月星操","f":"楚辞体","c":["阴阳舛错，亦孔之遌。","斤斤其月，有星薄之。","呜呼天高高在上，意安若兮。"]},{"t":"河之水歌","f":"古风","c":["河水淲淲，舟子摇橹。","东方渐明，我不得渡。"]},{"t":"想像歌","f":"五言古诗","c":["雾邪烟邪行，草莽者兄邪。"]},{"t":"鸡鸣歌","f":"楚辞体","c":["东方白兮，鸡鸣胶胶。","鼓予棹兮，沙之坳。","明星上船桅，北斗入地离离。","芦中人，逝而逝而。"]},{"t":"内教场歌","f":"楚辞体","c":["雕兮豹鞬骑白马，大明门前马不下。","径入内伐鼓，大同邪宣府邪，将军者许邪。","武臣不习威，柰彼四夷。","西内树旗，皇介夜驰。","鸣炮烈火，嗟嗟辛苦。"]},{"t":"叫天歌","f":"楚辞体","c":["弯弓兮带刀，彼谁者子逍遥。","牵我妻放火，我言官府怒我。","彼逍遥者谁子，出门杀人，骑马城市。","汝何人，谁教汝骑马。","持刃来，持刃来，彼杀我父兄，我今遇之，必杀此伧。","彼答言：奉黄榜招安。","嗟嗟！","柰何柰何！","彼不有官，饥官赈之，出有马骑。","我有租、有猺、有役，苦楚胡不彼而。"]},{"t":"招安歌","f":"古风","c":["鹰饥则附我，父顺子逆，子右父左。","彼则万只，谁曰千只。","彼烹牛美妻，尚望樵山而秉犁。"]},{"t":"贼逃歌","f":"楚辞体","c":["戈戟团团，鸟飞不过。","汝安逃兮，毒弩蛇矛。","平林之坳兮，君不见青衣来，狼兵开。"]},{"t":"悯灾歌","f":"楚辞体","c":["火之发兮，城南暮。","飞城入兮，势冲砻急。","风逆不反，我心怛兮怫兮。","汨兮安得术，噀尔灭兮。","省之火，自门徂堂，烧两廊兮。","彼何栖者，裂栋爆瓦。","天为赭兮，烟喷喷海涌照四野兮。","嗟何鸟声，怪而赤焰，翔而不下兮。"]},{"t":"悯熯歌","f":"楚辞体","c":["东湖为陆，而我无车。","有舟滩高水浅，行不得以舒。","仓浪天疾威我人，七月不雨，田龟坼、山而鳞鳞。","夫兮出杀贼，妇哭于庐畴给我食。"]},{"t":"姚源歌","f":"楚辞体","c":["嗟崒崒是何峰攒兮，下则无底之壑。","血瀄滵潺兮，猛兽食人。","岑岑禽鸟，竦峙鸱鸢。","不可以为凤枉尔饲兮，我闻不敢以言。","举火来白刃，帐下离哉翻。","县官走，前夺驴，后叫狗。"]},{"t":"欸乃歌","f":"楚辞体","c":["五更风打头，来兮嗟嗟欸乃。","船开努力齐兮欸乃。","力把柁立兮欸乃。","努力上滩，水平平缓兮欸乃。","北风雨雪，吹我寒兮欸乃。","日渐渐冥兮，谁济此川欸乃。"]},{"t":"和方山子歌 其一 仆夫歌","f":"古风","c":["饯者在郊，黄鸟交交。","杨柳荫车，有酒有肴。"]},{"t":"和方山子歌 其二 答歌","f":"古风","c":["何柳不黄，何鸟不鸣。","匪无良朋，怀我故乡。"]},{"t":"和方山子歌 其三 舟子歌","f":"古风","c":["春水涣涣，水鸟鸣唤。","追汝者谁，白马在岸。"]},{"t":"和方山子歌 其四 答歌","f":"古风","c":["食君琅玕，佩君玉环。","春蒲再芽，北舟我还。"]},{"t":"巳哉辞","f":"楚辞体","c":["由衷丑贪，孰之廉兮，餐冰茹糵。","乃畴苦汝节，威武不屈，以身殉国。","此戾此贼，彼毅彼力。","曰：伊逮之逮之膺矣，巳哉天乎命乎。","䛆予攺之，吾曷惩矣。","栗滴沥望，首阳之清泉兮，二人者从之，汨乎终予年。"]},{"t":"三原王公寿辞","f":"楚辞体","c":["轩冕兮巍峨，公之进兮，群龙委蛇。","公今何所兮，南山岧峣。","谁与公兮，逍遥。","南山何有兮，其云油油。","出覆四海兮，归抱一丘。","公朝攀兮，暮与游。","徜徉宇内兮，复安求。","绿桂兮丹阿，公游兮酒歌。","幅巾兮鹭羽，婆娑兮公舞。","寿且康兮，慰我民望兮。"]},{"t":"招隐山辞","f":"古风","c":["山之桂青青，秋风绿叶冬不零。","王孙几时归，山空蕙草槯。","山之草萋萋，春风花发桃源迷。","子规啼竹阴，日暮愁人心。","秋之夕萤飞，山风霜露沾人衣。","洞门翳寒萝，柰兹华发何。"]},{"t":"天门开","f":"楚辞体","c":["天门开兮冥冥，沛余乘兮上征。","雷车兮电旗，班陆离兮四驰。","阳昭昭兮在下，女翩翩兮媵予。","交不周兮易离，路超远兮徒自苦。","涉海兮杨灵，楫阳侯兮贝宫。","采珊瑚兮屿间，折三秀兮水中。","望佳人兮不来，吹洞箫兮绝浦。","聊盘旋兮戏娱，时不可兮再有。"]},{"t":"贻女","f":"楚辞体","c":["龙旌兮玄牡，重阙兮紫府。","夫君兮不可以见，女踯躅兮徒自苦。","冲风起兮河曾波，岩岪崛兮桂萝。","折琼蕊兮贻女，媒不通兮怨嗟。","若有人兮乘游龙，佩苍景兮御清风。","陟帝左兮右降，又翱翔兮极中。","君游兮昆崙，又夕宴兮王母。","缓节兮永歌，纷佾兮繁舞。","望遥浦兮御舸，吹参差兮愁予。"]},{"t":"捐袂","f":"楚辞体","c":["捐袂兮沙裔，遗褋兮澧浦。","御重华兮九疑，观潺湲兮容与。","神之来兮六龙，翳琼枝兮翠葆。","驱丰隆兮挟百灵，来如云兮去冥冥。","来蹑霞兮去乘霓，叆连蜷兮复葳蕤。","山之桂兮江之枫，云飒飒兮吹秋风。","班予马兮延伫，美要眇兮中渚。"]},{"t":"怀乡","f":"楚辞体","c":["伐辛夷兮采芳芷，茸荷屋兮荫兰渚。","佳人去兮不归，灵连蜷兮愁望予。","涉世径兮历险阻，驾玄骖兮又文牡。","岁冉冉兮既不我留，怅怀乡兮汨夷犹。","葛藟离离兮石间，雨冥冥兮山之幽。","旋予马兮故阿，陟堂址兮搴女萝。","霜露交下兮亭皋，秋风夕兮洞庭波。","山何为兮巃嵷，木何为兮蒙密，公有亭兮何不日鼓瑟。","日鼓瑟兮复吹䶵，憺娱乐兮万福来。"]},{"t":"君夷犹","f":"楚辞体","c":["登楼兮送君，日盈盈兮将落，暧茀郁兮带长薄。","居夷犹兮吹间，作巢燕兮既辞，又鸣兮蟪蛄。","纷轩盖兮总总，君胡为兮南都。","若有人兮被杜衡，带薜萝兮蕙缨。","中有怀兮荃不知，临修路兮怅天涯。","怅天涯兮望烟渚，信予美兮谁与。","龙城兮贝阙，君暮趋兮朝谒。","采芳芷兮江中，寄佳人兮天北。"]},{"t":"聘望","f":"楚辞体","c":["送佳人兮江渚，袅袅兮云气下。","鸟翩翩兮戾止，蝉暮吟兮独苦。","余邅回兮隐轸，謇中洲兮偃蹇。","心相亲兮口难言，目不睹兮日以远。","风涛兮浩荡，涉浦兮聘望。","兰被汀兮葳蕤，杜参差兮夕涨。","君税楫兮前坻，复容与乎中渚。","惝恍兮将从，憺淹留兮谁与。"]},{"t":"雩旱歌","f":"楚辞体","c":["望君兮曾波，两霾兮两河。","骖丰隆兮驾冯夷，蹇将至兮风薄之。","吹笙兮击鼓，絙弦兮会舞，君不来兮使我心苦。","云冥冥兮昼晦，神灵惠兮甘雨。","我稷兮我黍，谷之兮士女。","编龙兮堂墠，禽蜥蜴兮水际。","吐云兮上下，使鸠鸟兮腾逝。","纷总总兮神欲下，猋为驾兮龙为马。","君谁须兮不求，日将莫兮怨思。"]},{"t":"祀白鹿先生迎送神辞三首 其一 迎神","f":"楚辞体","c":["吹玉箫兮眺帆，浦横蔽江兮美无舸。","謇踯躅兮旋望，宛窈宨兮山之左。","陟山左兮降右，忽而来兮倏而去。","跨白鹿兮导两螭，色含笑兮心莫知。","既登兮山椒，复南陟兮石濑。","日冥冥兮欲暮，风飘飘兮吹蕙带。"]},{"t":"祀白鹿先生迎送神辞三首 其二 降神","f":"楚辞体","c":["绿萝兮紫萸，桂生兮罗户。","风飒飒兮若有望，神驱雨兮泉浪浪。","跞我阶兮坐我几，以彭郎兮挟匡父。","兰殽兮椒醑，日中兮万舞。","美孰怒兮飘忽逝，云离离兮怨余。"]},{"t":"祀白鹿先生迎送神辞三首 其三 送神","f":"楚辞体","c":["迹不偕兮心相疑，欢虽谐兮愁易离。","君荷衣兮蕙带，逍遥山中兮桂为盖。","天门兮既辟，腾而上兮云之际。","石有涧兮山有峰，心相慕兮交不逢。","税吾车兮絷马，愿褰衣兮从子。"]},{"t":"步虚辞","f":"楚辞体","c":["被霞衣兮芝盖，蔼沛腾兮彯长带。","魂逖逖兮天门，奄周章兮云际。","吹参差兮槃舞，灯繁纷兮不歌以鼓。","水以陆兮济鬼，福釐泑兮冀望苦。"]},{"t":"芝山子辞","f":"楚辞体","c":["山之芝兮葳蕤，子出游兮不归。","子不归兮翳薜萝，謇余独兮山之阿。","山阿兮望子，芝烂烂兮茎紫。","从子兮斋房，帝座兮显清。","天门兮不易通，子归来兮山中。","石磊磊兮路修，日暮兮不我聊。"]},{"t":"拟前缓声歌","f":"古风","c":["万水东流，鱼西上游。","不虞彼有渔子，置我于其钩。","鱼告渔子，女曷太荼。","宽大福厚，不见是图。","渔乃伛偻伸钩，我脱身以游。","渔起挥手谢，天命各有由。","此鱼衔明珠，来报当日渔。"]},{"t":"拟乌生八九子","f":"古风","c":["乌生八九子，八九子，馈饲两老鸟，乃在城墙高树头。","两老乌，拮据为巢，心中实毒荼，昼夜馈饲八九子。","八九子，长成各自飞，不来顾老鸟。","巢风雨，巢漂摇，今年有巢处，来年哺子何处所。","猛虎能食人，尚复有子之亲。","蝼蚁极细小，虫奉事长上礼若君臣。","何得朋友如路人。","上车逢所知，下车称别离，泪下如雨眼迷离。","来时不知南、不知北，我去何劳问东西。","车轮班班转，老乌飞飞啄赤苋。"]},{"t":"郭公谣","f":"古风","c":["赤云日东江水西，榛墟树孤禽来啼。","语音哀切行且啄，惨怛若诉闻者悽。","静察细忖不可辩，似呼郭公兼其妻。","一呼郭公两呼婆，各家栽禾栽到田塍，谁教检取螺。","公要螺炙，婆言摄客。","摄得客来，新妇偷食。","公欲骂妇，婆则嗔妇。","头插金，行带银。","郭公唇乾口噪救不得，哀鸣绕枝天色黑。"]},{"t":"豆娘子","f":"古风","c":["汝何者物，小而轻盈，妁约悠扬。","朋从寡畏，缃衣绀裳。","或翠其衿，或朱而黄。","嬉戏长莪，窈窕水旁。","餐膏浴滋，饮露吞香。","才不我知，谋宁自臧。","儿童朴美，姬媵怜伤。","豆卿子卿，娘子豆娘。","百卉陨零，北风雨霜。","弱不敌威，蚱蜢同戕。","肃肃鸿鹄，云海翱翔。","哕哕者凤，览辉梧冈。","微末之虫，何劳短长。"]},{"t":"榆台行","f":"古风","c":["榆台高，高风吹树梢。","都摇摇，台下黄羊走黄蒿。","山头看看日落，觱策四面吹，军中白旗身姓谁。","向前看，有河河水深，彼不怕死。","我亦人力，能拔虎尾。","人虎或两存，归为鬼雄荣尔魂。"]},{"t":"白毛行甲申元日作","f":"古风","c":["元日地动生白毛，发春当暖风萧骚。","天时尚然有错迕，老夫何怪儿童曹。","君不见猛虎失势，人寝其皮，惜也岂复能咆哮。","我歌白毛，比之董逃。"]},{"t":"长歌行","f":"古风","c":["笼中鸭，望水中鸭，一鸣一答。","汝虽有羽翼，不如我汎渌波、食鱼虾。","奔萍柏藻入烟浦，笼中之鸭心徒苦。"]},{"t":"禽言六首 其一","f":"古风","c":["泥滑滑，车马不得安，何不停车絷马待泥乾。"]},{"t":"禽言六首 其二","f":"古风","c":["行不得哥哥。","东有木公西王婆，南面设曾北张罗。","行不得哥哥。"]},{"t":"禽言六首 其三","f":"古风","c":["姑恶姑恶，小姑刺龊姑不乐。","新妇早煮餔，低声奉小姑。"]},{"t":"禽言六首 其四","f":"古风","c":["提壶卢，壶卢提，盛酒背母私饷妻。","妻可再得，母思罔极。"]},{"t":"禽言六首 其五","f":"古风","c":["瘦儿瘦儿，汝为上留田，汝为尹伯奇。","独行哀叫心内饥，日逐绿树啄虫蚁，汝父汝兄宁得知。"]},{"t":"禽言六首 其六","f":"古风","c":["不如归去，南山豆熟，北山有黍。"]},{"t":"猛虎行","f":"古风","c":["猛虎本居深山，我可不入，彼来亦难。","谁令尔，今来市中游。","尽日攫人食，撑肠拄腹无歇休。","我欲击之，刃不在手，欲往告泰山之君，陆无车水无舟。","猛虎闻言向我怒，我命在天匪虎惧。","嗟嗟虎尚有时，鸱鸮遗音宁尔知。"]},{"t":"董逃行","f":"古风","c":["涉江登彼西山，下看城郭郁盘。","城中阁殿斑烂，嘉树一何纷纶。","上有鸣鸟，旦暮间关。","遥望我心浩叹。","阛阓寂阒，民生何艰。","终朝缺突无烟，胡彼来往翩翩。","绮衣车马可怜。","谁家起楼造天，歌钟舞管喧阗。","剥羊宰牛列筵，何但一食万钱。","倏忽日薄重渊。","明灯荧荧烂堂，绣帏鸡舌流黄。","乐人调瑟未央，千年万岁奉觞。","岂知老至悲伤。","日月逝矣不我留，精销时往，霜霰交流。","繁华零落山丘，心欢意爱为他人收。","哀哉胡不德求。"]},{"t":"秋胡行","f":"古风","c":["鸾鸟不可为鸱，尔胡不思颜渊。","辍历尼父见疑我，今乃何敢望圣贤。","人心中，愤闷徒苦悲，智见万里水，清终见底。","高高山上台，彼居者何谁。","厥状蜿蜒，伺人意欲牵缠。","汝虽见其形，不见汝情，乃胡营营相煎。","岂不闻我命在天。","直道古难容，树乔风集颠。","周公有何疵愆，乃为四国流言。","伯奇掇蜂，不为父怜。","迹有涉疑，惟贤知贤。","洁色为妒媒，危言良见灾。","谗说久自明，非时麟圣哀。","孤松摧为之薪，水东西流，钦犹鬼神。"]},{"t":"君马黄","f":"古风","c":["君马黄，臣四骊。","飞轩駊騀交路逵，锦衣有曜都且驰。","前径狭以斜，曲巷不容车。","攘臂叱前兵，掉头麾后驱，毁彼之庐行我舆。","大兵拆屋梁，中兵摇楣栌。","小兵无所为，张势骂蛮奴。","尔慎勿言谍者来，幸非君马汝不夷。"]},{"t":"歈歌行","f":"五言古诗","c":["虎狼不可群，日短途路长。","鱼瘠稻复涩，蔬芝鸡凤凰。","笃之无恩泽，背面辄诋戕。","锱铢苟不平，持刃起相伤。","剽悍复谲诡，水土性轻扬。","哀哉兹土民，咏歌以难忘。"]},{"t":"阪田行","f":"古风","c":["阪田瓞离离，子母长寒饥。","昨闻接京军，征夫曷时归。","特生阪田树，下有往与来。","黻裳四牡虽荣，不如与妾共餔糜。","网鱼不施网，孰能制鱼死。","征夫归来归来，不见灵宝公、安陆子。"]},{"t":"豫章篇","f":"古风","c":["晨出南浦桥，不见桥上楼。","但见火烧骨，桥下水不流。","北风吹枯树枝，无一人来游。","妖鸟群啄鸣啾啾，汝何不此地重起楼。","吴盐大舶来，越珍衔舳舻，豫章之火心大荼。"]},{"t":"仙人篇","f":"古风","c":["何者一老翁，耳垂两肩绿瞳方，来此芙蓉峰。","招我同行，耸身即老翁。","授我玉柈丹，携手游洪濛。","东至泰山颠，飞瀑杨膏波，青松荫石关。","饥叽掇瑶草，渴饮玉屑泉。","晨朝吸沆瀣，夕憩若木间。","俯视九区内，伤心泪九澜。"]},{"t":"升天行二首 其一","f":"五言古诗","c":["九州非我居，我思游冥荒。","饰舆骖玉虬，乘气切天翔。","朝餐发匡庐，夕暮嵩华阳。","上谒帝座侧，回旗拂天昌。","牵牛击河鼓，织女方七襄。"]},{"t":"升天行二首 其二","f":"五言古诗","c":["扶桑跃阳彩，海气腾瑶光。","六龙抗斗枢，九帝开云阊。","振衣蹑仙踪，飞辔骖鸾翔。","仰身操天瓢，手勺沆瀣浆。","朝嬉太乙馆，夕憩玉女堂。","驰情览八极，纵目穷遐荒。","环运无恒存，逝代多隐伤。","回旌拂九曜，捷步登文昌。","进谋芝盖侧，待问紫玉房。","群灵赠大药，诸御传神方。","无惜一粒分，遂令民寿康。"]},{"t":"洛阳陌","f":"五言古诗","c":["严飙卷枯藿，霜隼厉狄翮。","翩翩骝马子，意气一何赫。","朝驰上东门，暮遍洛阳陌。","臂弯两角弓，宝刀雪花白。","借问此谁子，无乃汉相如。","昔挈一束书，今乘驷马车。","虎士为执鞭，县令皆前驱。","倾城莫不叹，观者填路衢。","举手谢乡人，荣耀但区区。","丈夫树名勋，所志在唐虞。","扬袂径北去，万里谁能拘。"]},{"t":"丹霞行","f":"五言古诗","c":["毁誉荣辱至，海波何时平。","海中有仙山，仙人筑为城。","金银为室阙，桂树罗阶生。","鸾鸟翔且舞，美女称飞琼。","偓佺拥我盖，王子左吹笙。","踟蹰聊戏娱，餐之玩西倾。"]},{"t":"雨雪曲","f":"古风","c":["冬十一月，阻舟徐汊。","朔风北来，雨雪纷下。","禽鸟冻寂，洲村肃夜。","缆夫来言，衣单腹饿。","波流洄洄，促船难驾。","我心悽恻，羽翼傥假。","七月汉土，今幸雨雪。","往者难追，来春可沃。","我虽波阻，心则怡怿。","购蔬城市，贷米逾泽。","原阪萧条，雁鸿辑集。","贫士罔怀，一阳环复。","青青者衿，涉江我求。","大泽寒冥，胡子能来。","鹭鸾难飞，潭网顿集。","纲收鱼跳，阅忘寝食。","荒岑险艰，岂我能处。","南纪东肃，返北于土。"]},{"t":"阳鸟篇","f":"古风","c":["阳鸟攸居，于渚于野。","饮啄纡徐，行步闲雅。","我舟触惊，振翰若云。","飞之有序，还集成群。","阳生豫知，延颈跂望。","举翼万里，云罗空想。"]},{"t":"湖吟行","f":"古风","c":["鱼游于水，游于水而。","鸟游于水，饱之去斯。","云昧湖窈，冬序憭慄。","竟日无人，草莽冥寂。","百怪鸣叫，原隰谁主。","有一罾夫，荒滨守罟。","疑非怕人，问之弗言。","汝胡者人，单到此间。"]},{"t":"虎欲齧人不避豪贤篇","f":"古风","c":["吾之于人，谁毁谁誉。","貌失子羽，言失宰子。","知我者天，君子洗心。","行不愧影，寝不愧衾。","何树嶷嶷，于畛之持。","有挠俾鸣，僾风者惑。","汉申党人，宋严伪学。","冥鸿逝豫，辕驹局促。","非林何栖，非渊何潜。","驷马忧患，贫贱德音。","富而可求，其从如云。","徐子起钦，显者蔑闻。"]},{"t":"独漉篇","f":"古风","c":["独漉独漉，弃田求屋。","其屋虽大，其人则饿。","小人在旁，譬如蜂蝎。","恩之虽勤，莽之则螫。","葳葳艳阳，桃李吐英。","未曾结实，谁辨苦蜜。","锦绣围厕，过者掩口。","珠玉委途，奚异尘土。","临渊趣轮，临壑振绥。","人孰不闻，亦孰不知。","綦絇之美，不以为缬。","身尊道高，名为隽杰。"]},{"t":"苦热行","f":"古风","c":["蕴隆焚如，二仪为炉。","赤曦铄天，尘沙沸途。","居奚讳袒，行弗择憩。","鱼伏于渊，鸟张其喙。","何物为炭，谁乎为工。","橐之鼓之，金流石镕。","阆风之颠，瑶沼之阴。","飙轮扇凉，冰壑嵚崟。","下踏层雪，上攀琪树。","仙人绿发，逍遥箕踞。","俯阚人世，溷热交毒。","我欲从之，安得羽翼。"]},{"t":"鸡鸣篇","f":"古风","c":["鸡鸣月落，飘风振宇。","鴐鹅曳陆，翔鸟云举。","曜灵初出，浮云翳止。","驱马东行，条其嘅止。"]},{"t":"朝吟行","f":"古风","c":["亭毒既周，明星有烂。","羲和授鞭，九宇将旦。","寐者嘅叹，寤者嘅叹。","巉巉桧柏，覆我中庭。","鸡鸣于颠，微霜夜零。","阊阖未启，九闉尚扃。","驰神紫极，振珩阙庭。"]},{"t":"玄熊篇","f":"五言古诗","c":["猛士守四方，四方尘不杨。","玄熊在深山，百兽皆遁藏。","猎火举四泽，虞罗亘长云。","毒矢积如猬，玉石谁能分。","熊皮充下御，肉亦登君庖。","岂若犬与豵，即死无咆哮。"]},{"t":"游子篇","f":"五言律诗","c":["游子在他乡，所愿亲寿考。","水犀游于渊，惟愿水长好。","涧石虽孤处，不羡风中沙。","葛藟能缠绵，不如丝与麻。"]},{"t":"豫章行","f":"五言律诗","c":["黄河虽大川，所嗟源不清。","千里能一曲，不如直道行。","王允辅京室，李杜垂其名。","介休巾角折，乃为时所倾。"]},{"t":"析薪二首 其一","f":"五言律诗","c":["析薪如之何，爰以析其理。","结交如之何，相要在终始。","女萝施松柏，女萝千尺长。","结交不知心，结交安得常。"]},{"t":"析薪二首 其二","f":"五言律诗","c":["列曜垂四隅，灿灿冒中土。","箕星乃好风，毕宿复欣雨。","汎观愚哲士，戚戚各有营。","哲夫计千载，愚者终一生。"]},{"t":"公无渡河二首 其一","f":"五言绝句","c":["盘螭作川梁，功奇势难久。","鲂鱮尾屣屣，天吴戴九首。"]},{"t":"公无渡河二首 其二","f":"楚辞体","c":["公无渡河，河深不可渡，中有白石，齿齿崭崭兮峨峨。","蛟龙九头，戴角峥嵘，崟磕兮水鳞鳞兮冲素波。","公无渡河，吹沙暮多风。","河伯筑梁结两螭，汝无羽翼堕水中。","涉水虽可乐，不如登山阿。","噫！","嗟嗟公无渡河。"]},{"t":"空城雀","f":"古风","c":["双雀下空城，谷穗黄离离。","二雀跳踉鼓翼啄谷穗，其朋千百咸来集，小者啾啾是其儿。","谁者翁妪，被发曳鞋来打雀。","雀薨薨，飞上城，嘈嘈鸣。","两人恰欲抽身，雀便复集。","回头骂雀，辛苦长得禾，汝忍饱之我无粒。","手中乏利弹，又蔑网罗。","天旋日昏，柰尔雀何。"]},{"t":"野田黄雀行","f":"古风","c":["乐乐其所，自生禽兽，过其故丘悲鸣。","黄雀游野田，焉知鸿鹄高举情。","凤凰靡世见，生长丹山依。","玉禾白于脂，饱之忽来飞。","仲尼逢子西，乃被接舆讥。"]},{"t":"石城乐","f":"五言古诗","c":["盈盈窈窕女，当门是谁家。","十三学画眉，十五檀琵琶。","邑中有卢家，此女名莫愁。","向前问此女，女闻双泪流。","二十嫁夫郎，重门阿阁房。","临窗种桐树，五年妾身长。","自渠下杨州，置妾守空楼。","悔不快剪刀，断水不东流。"]},{"t":"大堤曲","f":"五言古诗","c":["汉水白离望，月落山黑时。","堤头石不平，走马谁家儿。","侬住襄门西，而在汉水北。","浮桥不著缆，郎讵得侬识。","大舶何处来，落帆向浓浒。","高靴白帢子，识是真州估。"]},{"t":"襄阳谣","f":"古风","c":["一滩高一尺，十滩高一丈。","湍急右巉，鱼何由上。","槔戕橹析，俾我心怆。","顺风沿水，举帆千里。"]},{"t":"白铜鞮","f":"古风","c":["谁家池，高阳池。","日暮归，倒接䍦。","醉如泥，汝为谁。","拍手歌，襄阳儿。"]},{"t":"襄樊乐","f":"古风","c":["立樯如麻，卿来谁家。","新燕营巢，风中滚沙。","鵁鶄逐鸳鸯，金井石榴黄。","珍宝丘山积，擅名黑门厢。"]},{"t":"襄阳浣妇行","f":"古风","c":["彼谁者妪，吾家浣衣新寡。","寒贱鬓发霜飞，体无完衣，十日九饥。","态度则殊，辩是知非。","妪泣荅言：妾襄宫女，少小入宫，荷主怜顾。","四十始出，嫁为民妇。","灌田禾薪，奄就贫窭。","舞裳绽污，形容攺故。","夫死男孺，藜匡靡救。","妪咽复言：侍襄定献，几三十年。","王有义辞，皇嘉特宣。","父子俱觐，妃嫔如烟。","钿笰载路，龙旂飘翩。","御使络绎，珍车班班。","汉岘同清，天歌播焉。","衮舄南还，层城言言。","鸟春日妍，桂宫有延。","杰臣觞寿，玉娥奉筵。","王既捐世，变来罔度。","闻见骇异，古殿寂寞。","妪勿更言，万类咸尔。","厥亦天道，安之则巳。"]},{"t":"雁门太守行","f":"古风","c":["雁门太守汝何人，治邦三月称明神。","我有牛羊，贼不来掠。","我有禾黍，人不敢割。","昔我无衣，今有裤著。","我思礼拜太守，太守不见怜。","但闻太守身姓边，紫髯广额耸两颧。","太守出门，四牡骙骙。","后拥皂盖，前导两麾。","行者尽辟易，居者不敢窥。","旁问太守胡所之，云访城南皇甫规。"]},{"t":"渡河篇","f":"楚辞体","c":["小麦黄，黄河波，君柰何，今渡河。","昔君游此，思君一见。","经旬累月，不君一面。","君今渡河，乃往何县。","跂予望之，泪下如霰。","汀有凫兮沚有兰，枝相亚兮居不单。","人生心事岂有殚，君慎动静加君餐。"]},{"t":"黄鹄篇","f":"古风","c":["黄鹄游四海，倦言还故邦。","中路失其雌，三年乃有双。","鸳鸯毛羽缛哉工，凰俦鹤匹渠岂同。","嬿婉欢娱殽酒丰，琴鸣瑟奏芳夜中。","乐极思来内忡忡，验新追故悲悔丛。","人生万事，慎勿轻易。","狸鼠之能，讵逮骐骥。","车牵美期，谷风兴刺。","我心自知，聿斯语谁。"]},{"t":"煌煌京洛行为曹县王子赋","f":"五言古诗","c":["时风布阳和，韡韡华春木。","清朝富才贤，蔼蔼冠盖属。","努力竞高路，鸡鸣起相逐。","白日耀飞辔，流云翼行毂。","同里多汇荐，一门有联躅。","蹶彼曹南士，双双皎如玉。","聚鸣各当晨，连翮一何急。","煌煌京洛内，济济英妙集。","二郎绅委蛇，三四锦翕熠。","大郎虽未官，俯身拾班级。","入室谈仁义，出与卿相揖。","声名既烜赫，性行复刚执。","见者勿徒羡，青云贵自立。"]},{"t":"南山篇","f":"古风","c":["南山何岩岩，上有孤鸾凰。","佳偶永相失，日飞夜悲鸣。","遗腹生雏，哺之良艰。","晨采竹实，暮取琅玕。","吁嗟哺之良亦艰。","雏成被九采，翱翔览四海。","四海睹光仪，阿母亦荣辉。","峨峨相公门，屹与南山齐。","自有鸾凤来，绰楔增崔嵬。","相逢且莫言，听我南山篇。"]},{"t":"仙人好楼居三首 其一","f":"五言古诗","c":["律律海中洲，峨峨白玉楼。","上曾结浮云，下戴神鳌游。","前檐荫白榆，青龙守门枢。","上有无始公，餐霞炼金腴。","飞琼鼓玄橐，浮丘扇其隅。","情闲览八表，出入服气舆。","日月跳两珠，回旋但须臾。","万年永福日，寤言莫相忘。"]},{"t":"仙人好楼居三首 其二","f":"五言古诗","c":["谒帝华盖侧，沐发咸池旁。","岩岩云中楼，文杏袅为梁。","黄金走阑干，银阙前相望。","耸身若轻翼，登之穷四洋。","四洋北荒沕，波澜浩杨杨。","九州一何拘，敛颜归洞房。","屑玉炼精魄，用神无何乡。","万年永福昌，寤言莫相忘。"]},{"t":"仙人好楼居三首 其三","f":"五言古诗","c":["乾鹊知来风，灵人炳先几。","超世构巍峨，上与飞云齐。","举手拂天河，白石寒离离。","牵牛不服箱，织女弃支机。","孤鸟衔若华，东来欲谁诒。","海水浅以清，俯之嗟叹咨。","眷兹勿轻道，翩翩众鸠驰。","万年永福昌，寤言莫相忘。"]},{"t":"白马篇","f":"五言古诗","c":["白马紫金羁，杨鞭过市驰。","万人皆辟易，言是卖珠儿。","生长本倡门，结交蒙主恩。","寝食玉榻侧，独聆瀀渥言。","取金大长秋，徵歌李延年。","家住十重楼，珠帘白玉钩。","绮绣裁襦裳，妖艳无匹俦。","片言即赐第，意气凌丑侯。"]},{"t":"将归篇","f":"五言古诗","c":["对面有乖绝，千里长相思。","登高望来车，入门赋将归。","惊风何飘飘，兽兔莽间啼。","群鸟各有趋，他乡难独依。","独依令人惑，悠悠浮云驰。","悠悠尚可道，霜露陨百草。"]},{"t":"荅客","f":"五言古诗","c":["子去有何见，来之奚所闻。","愿客且宁坐，为子请敬陈。","丈夫志四方，出门辙同轮。","人心投合谐，匪必邻里亲。","长风会枯蓬，飘飘逐飞尘。","既东忽复西，聿谁究其因。","引觞就岐路，有怀庶能伸。"]},{"t":"拟燕歌行二首 其一","f":"七言古诗","c":["花稀叶艳蘪芜芳，皇皇溥原修且将。","阳浮野旷云飞扬，风沙眯目熯气黄。","禽兽阻饥狐在梁，兴言送君还故乡。","牵袂欲别立徬徨，延视极骋中自伤。","缔交心违隔肝肠，尔去孰予共杯觞。","兰桡桂枻文荔樯，逝哉汗漫凌洪洋。","安能假翼东南翔，何人赠君紫玉珰。","又何赠之云锦裳，永言嗣兹无我忘。"]},{"t":"拟燕歌行二首 其二","f":"楚辞体","c":["银河耿耿秋夜长，牵牛织女限河梁。","终日美杼不成章，延颈北望涕沾裳。","自居别我之他方，锦衾灿兮独空床。","北风发发天雨霜，鸿鹄垂趐不能翔。","溪谷天寒林树苍，道路欲归多虎狼。","人烟断绝乏资粮，为君忧愁断肝肠。","思策良马逝居旁，中道失路河无杭。","揽衣踟蹰夜未央，愿为浮云归故乡。"]},{"t":"芳树二首为上海陆氏赋陆出东坡故砚姑苏全肩笔索予面赋一字起十字止 其一","f":"古风","c":["嗟，天运，春奄暮。","翩翩者鸟，集于芳树。","芳树生路隅，车马一何多。","朝看桃李华，夕看桃李柯。","爰登高丘以望，遥见长安绮楼。","楼中美人弹瑟，如闻三叹未休。","客乘白马系栖下，秉烛置酒娱夜游。","美人赠我锦绣辞，把玩不异珊瑚钩。","林阴漙露罗袂薄，明月照闼那可留。","嗟乎人生何不共努力，君不见城鸦哺子忽生翼。"]},{"t":"芳树二首为上海陆氏赋陆出东坡故砚姑苏全肩笔索予面赋一字起十字止 二 前缺八字句此篇足之","f":"楚辞体","c":["猗，君子，道为贵。","贪夫所钦，驷马高盖。","东家虽椎牛，不如西家齑。","虽有文马千驷，不如西山啜薇，猗嗟富贵良何为。","瞻彼青青兮陌上林，秾华灼灼兮一何早。","凉风有时漂摇来吹汝，坐见凄凄白露满芳草。","愿采青松寄情亲于远道。"]},{"t":"鸣雁行","f":"七言古诗","c":["鸿鹄高举摩天飞，渴饮沆瀣餐灵芝。","翅拂日月云为衣，即有矰缴安能施。","下游沧海高河汉，我思与尔时相见，羽短毛长何足辩。"]},{"t":"知足吟","f":"古风","c":["衡门可栖，藜藿可饭。","锦绮虽丽，韦布自暖。","车马虽贵，岂若仰偃。","下览林皋，上陟峦巘。","静倚垂虹憩，目送行云返。"]},{"t":"直如弦","f":"古风","c":["直如弦，死道边。","相逢且勿諠，敬听古人言。","子虽抱良璧，暗投谁为惜。","掇蜂尚见疑，何况不相知。","种桑为得衣，种谷为得饱。","结交不得心，不如绝交早。"]},{"t":"采菇曲二首 其一","f":"古风","c":["众星欲没月模胡，人家河上起相呼，相呼相唤采秋菇。","问渠早起缘何事，此草日出化作田中枯。","采菇采菇君早归，霜寒露重湿人衣。","蓝田白玉非无种，不似商山好蕨薇。"]},{"t":"采菇曲二首 其二","f":"古风","c":["白如白玉簪，香如玉田禾。","行人且莫行，听我采菇歌。","侬家住在黄河曲，一日波涛怨杀河。","河来有鱼去有麦，麦下秋霜菇菜多。","不求河血城南去，只愿年年河不波。"]},{"t":"双燕篇","f":"古风","c":["双燕来故室，不见阿母语。","穿窗入幕寻阿母，哀鸣欲栖还复举。","喃喃止翠桁，徘徊拂素帏。","浮尘积玉珈，断藓生画衣。","双燕年年春社来，阿母阿母何时归。"]},{"t":"赋得古别离送龙湫子","f":"五言古诗","c":["盈盈杨白花，汎汎绿波水。","化为浮萍草，乃与人相侣。","飘泊无根蒂，随风任流止。","今日欢聚客，明日倏千里。","千里异乡县，有时复相见。","心情岂固殊，所嗟形色变。","一见复一别，少壮头尽雪。","老大未足伤，愿言崇今芳。"]},{"t":"史烈女","f":"五言古诗","c":["梨花如雪霜，鸳鸯不成双。","我心明如镜，我心清如水。","镜明有尘时，水覆无收理。","古昔华山畿，行人下马拜。","春风两蛱蝶，绿草摇衣带。"]},{"t":"孤鹄篇寿程生大母","f":"古风","c":["有孤者鹄毛羽苍，灵气勃勃吞秋霜。","饥餐玄圃禾，渴饮瑶池浆。","朝从金母游，夕挟飞琼翔。","生有二子，二子生八雏。","双双昆崙之巅，漱芳茹膏餐玉腴。","上下嬉紫虚，青鸟为伴文凤俱。","俯视鹊鸦鹪鴳，何啻万万辈，唶唶啾啾啄腥秽。"]},{"t":"塘上行","f":"五言古诗","c":["蒲生何离离，过时采者稀。","莫言采者殊，盛衰自有时。","昔与君相见，不谓行当变。","谗言使交流，水清石自见。","孔雀东南飞，十步一徘徊。","罗鸗羽翼短，安可作雄雌。","今日乐相乐，饮酒行六博。","蒲生枝叶多，中心亦不恶。"]},{"t":"艳歌行","f":"五言古诗","c":["杲日出扶桑，照我结绮窗。","绮窗不时开，日光但徘徊。","通阡对广陌，柳树夹楼垂。","上有织素女，叹息为谁思。","步出郭东门，望见陌上柳。","叶叶自相当，枝枝自相纠。"]},{"t":"甄氏女诗","f":"五言古诗","c":["种树高堂下，枝叶何留留。","辞家奉君子，置我青云栖。","一朝意乖别，弃妾忽如遒。","昔为同沟水，今向东西流。","独守结心脾，夕暮不垂帷。","明月鉴玉除，清风一何悲。","曳絇立中庭，仰见明河湄。","明河光不回，念妾当何依。","沉思仰天叹，泪下如断縻。"]},{"t":"师旷歌二首 其一 玄鹤歌","f":"楚辞体","c":["宫筵肆兮哀弦拊，玄鹤降兮鸣且舞。","呼烟侣兮啸云友，谁能为此师旷子。"]},{"t":"师旷歌二首 其二 白云歌","f":"楚辞体","c":["招白云兮会天鬼，两冥冥兮风不止。","君好音兮徒自苦，民悲嗟兮离弃女。"]},{"t":"五仰诗五首 其一","f":"楚辞体","c":["我所仰兮在华山，侧身西望阻秦关。","莲岭阻修徒离叹，仙人赠我白琼丹。","翳三秀兮吟葛覃，我欲从之途路艰，西望咸阳涕潺湲。"]},{"t":"五仰诗五首 其二","f":"楚辞体","c":["我所仰兮在衡山，侧身南望阻荆关。","祝融岧嵉心悲酸，仙人赠我赤琼丹。","婆娑桂树山之间，我欲从之途路艰，南望洞庭涕潺湲。"]},{"t":"五仰诗五首 其三","f":"楚辞体","c":["我所仰兮在泰山，侧身东望阻齐关。","南有龟蒙东肃然，仙人赠我绿琼丹。","招我东游扶桑间，我欲从之途路艰，东望河济涕潺湲。"]},{"t":"五仰诗五首 其四","f":"楚辞体","c":["我所仰兮在怕山，侧身北望阻燕关。","飞石岑巉不可攀，仙人赠我黑琼丹。","带星辰兮佩鸣环，我欲从之途路艰，北望雁门涕潺湲。"]},{"t":"五仰诗五首 其五","f":"楚辞体","c":["我所仰兮在嵩山，侧身遥望阻韩关。","企余望之良匪难，仙人赠我黄玉丹。","手持金光翳华菅，我欲从之途路艰，遥望缑城涕潺湲。"]},{"t":"淋池歌","f":"古风","c":["翩翩黄鹄，玉距金衣。","飞引两雌，来下我池。","肃我徒，驾我舟，折荷花弓擢中流。","女杨歌，龙豹驯，阳阿杂进齐讴陈。","会鼓击，乐未央，皇家万寿民阜康。"]},{"t":"招商歌","f":"楚辞体","c":["荷为盖，水为车，女艳艳兮绣带舒。","辟阴馆，坐阳渠，招凉风兮吹玉竽。","吹玉竽，感心志，昼卷夜舒荡人思。","荣景沉，凝霜零，仰首太息沾我缨。"]},{"t":"顺东西门行","f":"古风","c":["嘅人生，七十稀，来日苦奔去难追。","贤子孙，富家资，耳聪眼明心寡悲。","酒既清，殽核时，首春禽鸣梅满枝。","人道成，世运熙，乃今不乐当待谁。","召同姓，请乡耆，鼓瑟饮醇祝期颐。"]},{"t":"妾薄命","f":"七言古诗","c":["兰房宵宴烛舒明，今者不乐岁其征。","岂伊异人惟友生，金杯玉盘殽杂呈。","恃容骄爱各极情，任心属欢密意倾。","美人顾予独目成，舄履杂蹂香泽传。","额瞬目语中意宣，主称千寿客万年。","揽衣起舞体仙仙，燕翻雪回臻极妍。","罗濡縠润汗沾颜，履遗佩绝立未安。","满堂称能灯屡前，金爵弱腕未胜持。","相擎袖遮情语微，促尊前席影齐移。","绣裾珠衱光逶迤，耳后悬瑱何累累。","皎若芙蓉出绿池，赠我彤管亲所将。","车疑马停仍罄觞，德音爱深结肝肠。","醉沉独言犹不忘，归室自解鸣玉珰。","九华流苏鸡舌香，合眼宛在君之旁。","觉来微月鉴空床，起视北斗长阑干。","踟蹰露晞目上山，义成爱施良独难。","悲思叹息泪汍澜，桂人绝代惜玉颜。","情会恩离摧我肝，愿托锦衾终此欢。"]},{"t":"苦哉行","f":"古风","c":["从军北，到长城，长城草枯窟不平。","十月风发霜霰零，人须马毛冰结成。","东归太行践羊肠，斫冰煮糜岩谷旁。","攀枝掩泪瞻故乡，红颜捣素怨夜长。","悲离恨阻断肝肠，破镜何时飞上苍。"]},{"t":"嗟哉行","f":"古风","c":["人言高树多风，群鸟巢其颠。","劲干从来易折，弱者永其年。","兰?虽异众草，秋至同一零。","君子不爱其身，身屈名乃成。"]},{"t":"朱榴篇","f":"古风","c":["朱榴虽檀名，不与众草争。","春阳炎天众草死，朱榴吐艳何扬扬。","缛瓣攒葩不结实，可怜此物终抛掷。"]},{"t":"行路难","f":"古风","c":["锦笙翠蛾心莫疑，色销言忤情遽离。","偶投响诺山岳移，背面诋訾孰复知。","川涂忧风备其舟，彼风东西流，波翻浪侧时不休。","泊船倚岸缆树根，彼何者鸟翻然喧，愿置此曲令心烦。"]},{"t":"白纻词三首 其一","f":"七言古诗","c":["镫繁月明夜何长，华袿凤髻曳鸣珰。","袅云流影归洞房，引商刻徵断人肠。","金鞭骝马立徬徨，解衣酣酒歌未央，夜阑鸡鸣不下堂。"]},{"t":"白纻词三首 其二","f":"七言古诗","c":["天河为桥一水长，双星怨夜遥相望。","玉帘金茀衢路旁，尘暗镫残芬秀扬。","转眸明月低西方，堕靥流钿飘碎光，马停车驻空断肠。"]},{"t":"白纻词三首 其三","f":"七言古诗","c":["五更月微含素波，飞雾英英没绛河。","桂宫兰室栖玉娥，外极金鳌万象罗。","万人齐和一人歌，生丁福运民太和，竟日为欢岂足多。"]},{"t":"赋大隧","f":"古风","c":["赋大隧，儿赋隧中母隧外。","母思启段段巳举，不及黄泉是何语，颍人不来其柰汝。","颍人不来犹之可，俎上分?痛杀我。"]},{"t":"公仪休","f":"五言律诗","c":["园中岂无葵，相公柰何饥。","相君即无衣，不爱室中机。","相君千万岁，请治相君栖。","桓公霸诸侯，管氏有三归。"]},{"t":"青陵台","f":"古风","c":["两山当中开，露出青陵台。","北山虽张罗，南山鸟不来。","我在南山自有匹，马牛之风岂相及，吾颈可断志不易。"]},{"t":"射潮引","f":"古风","c":["钱塘八月潮水来，蛟龙奋怒涛为雷。","天旋地拆不可止，此中云有鸱夷子。","何不张尔弓挟尔矢，射杀鸱夷潮可止。","君不见潮水年年八月来，万努射潮终不回。"]},{"t":"汝为我楚舞","f":"古风","c":["汝为我楚舞，吾为若楚歌。","黄鹄翼成将柰何，黄鹄一举横四海，君王岂有四海罗。","君无四海之罗安用此，殃君美人毒君子。"]},{"t":"博浪沙","f":"古风","c":["博浪沙中挈椎走，鸿门帐前撞玉斗，谁谓张良貌如妇。","赤帝子起鞭赤龙，臣也请归从赤松。","赤松子，在何许，君不见朝烹狗，暮缚虎。"]},{"t":"左袒行","f":"古风","c":["陵曰不可平曰可，安刘者谁勃与我。","产不信，禄不入，军右袒，计安出。"]},{"t":"申屠嘉","f":"七言古诗","c":["邓通小臣敢皇侮，错也何人毁庙堵。","臣欲戮通帝弗许，请收错诛帝罔与。","含血自歼报皇祖。"]},{"t":"辕下驹","f":"古风","c":["郑当时，辕下驹，韩安国，两首鼠。","秃老翁，竟斩汝，廷臣不语淮阳语。","君不见金家妇、王家女，一言杀儿还杀母，何况区区老秃且。"]},{"t":"栗太子","f":"古风","c":["燕燕汝今衔泥向何县，遮天蔽日过长安，堆泥作冢高如山。","飞来未央宫，衔取梁上土。","黄口见母来，哑哑张吻索虫哺。"]},{"t":"赤凤曲","f":"楚辞体","c":["前赤凤，后双燕。","头岑岑兮尾涎涎，组帻郎君夜相见。","相见骑白马，惊起城上乌。","城上乌，据巢姇儿夜相呼。"]},{"t":"雷之奋","f":"楚辞体","c":["雷之奋，翕兮张。","山之阳，发坤藏。","辟哉昌，群龙载浮列缺光。","列缺光，烜中土。","惠甘雨，介稷黍。","圣人垂衣民歌舞。","民歌舞，袪祸菑。","饥而食，饱斯嬉。","厉鬼潜灭维福基。"]},{"t":"凤之升","f":"古风","c":["凤之升，附龙云。","仪万方，昭帝文。","昭帝文，承宗禋。","安如山，翕如坤。","两宫豫，协天神。","帝临朝，奏云门。","戛鸣球，笙镛振。","昭四方，明万民。","万民愉，庶物亨。","阴阳熙，乾道成。","乾道成，皇业昌。","轶周姒，缵涂戎。","臣稽首，歌云龙。"]},{"t":"月如日","f":"古风","c":["月如日，光如轮。","轮五色，缤哉纷。","贯紫霓，扬风翎。","抶太乙，侵紫庭。","化为白气干天经。","张我弧，挟我矢。","袪祲灭妖天下理。"]},{"t":"子夜四时歌八首 其三 夏歌之一","f":"五言绝句","c":["独夕玉阶侧，仰看三星烂。","畏热不归房，徘徊夜将半。"]},{"t":"子夜四时歌八首 其四 夏歌之二","f":"五言绝句","c":["骛棹出惊流，回桡戏清沚。","擘破芙蓉花，中有双莲子。"]},{"t":"子夜四时歌八首 其五 秋歌之一","f":"五言绝句","c":["凉风吹王树，团扇置不理。","侬亦有凉热，何况戴冠子。"]},{"t":"子夜四时歌八首 其六 秋歌之二","f":"五言绝句","c":["摘叶裹流萤，应手叶先落。","本无牢根蒂，虚怨秋霜薄。"]},{"t":"子夜四时歌八首 其七 冬歌之一","f":"五言绝句","c":["郎住西水头，妾住东北浒。","何能冰遂合，永免风波苦。"]},{"t":"子夜四时歌八首 其八 冬歌之二","f":"五言绝句","c":["雪飘怅难行，室尔阻相觅。","不畏风色严，畏此雪上迹。"]},{"t":"车遥遥","f":"古风","c":["车遥遥，遥遥复迈迈，望见秋尘起。","不见车轮转，知在秋尘里。"]},{"t":"幽兰","f":"五言绝句","c":["幽兰敷紫茎，罗列生堂基。","踰时君不采，隔情当怨谁。"]},{"t":"掌上舞","f":"五言绝句","c":["晨游憩阳馆，夕宴戏风台。","盈盈掌上舞，飞飞素雪回。"]},{"t":"杂诗六首 其一","f":"五言古诗","c":["熚熚云中电，流光西北驰。","仆夫夙严驾，吾欲远游之。","出门履微霜，四顾何茫茫。","豺狼当路逵，鸱鸮薄云翔。","改辙理方舟，欲逝川无梁。","俛仰岁将宴，怆恻涕沾裳。"]},{"t":"杂诗六首 其二","f":"五言律诗","c":["西国有佳人，独立青云端。","容艳若桃李，左右佩芳兰。","含思理玉琴，泠泠一何闲。","更节有馀悲，曲终再三叹。"]},{"t":"杂诗六首 其三","f":"五言古诗","c":["棁榱蚀以倾，梁栋诚独难。","流言播四国，周公有疑患。","凉飙激颓景，奄忽不可攀。","众羽日缤纭，朱鸟戢其翰。","杀身苟无益，去去从所安。","伤哉式微诗，千载起余叹。"]},{"t":"杂诗六首 其四","f":"五言古诗","c":["明月照我怀，耿耿殊未已。","霜雪委如山，悲风中夜起。","揽衣仰天叹，涕陨不可止。","下生抱荆玉，捐躯卜终始。","青蝇倏来集，白黑反在此。","城阙屹九重，浮云日千里。","我欲竟此曲，此曲悲且苦。"]},{"t":"杂诗六首 其五","f":"古风","c":["凄霜变为雹，二气敛而藏。","天道有代谢，人谋岂怕臧。","北杓酌元化，亭亭自低昂。","上帝栖紫宫，众纬错以行。","谓山盖高，有梯可陟。","谓渊盖深，有舟可涉。","自非双黄鹄，天路安可蹑。"]},{"t":"杂诗六首 其六","f":"五言古诗","c":["茅以韧为席，柏以劲为薪。","君子忧治世，愚者幸不辰。","张罝以待兔，雉也菑其身。","物理虽云殊，罹脱各有因。","浮沙卷奔藿，朔吹扬惊尘。","日暮临大道，怅望曷能陈。"]},{"t":"发京师二首 其一","f":"五言古诗","c":["驱车彰义门，遥望郭西树。","冠盖耀青云，车马夹广路。","威风何赫奕，各蒙五侯顾。","回飙动地起，白日倏巳暮。","弃掷委蔓草，荣华若朝露。","良无金石交，人生岂常故。","絺绤足禦冬，谁念纨与素。","忾彼白华篇，气结不能愬。"]},{"t":"发京师二首 其二","f":"五言古诗","c":["茑萝附公柏，枝叶固相因。","行子恋俦匹，况遇同乡亲。","北风起河梁，日暮多飞尘。","携手同车归，驾言西适秦。","道远长渴饥，客子怀苦辛。","仰瞻天汉流，夜永不得晨。","骖马媚其曹，鸣雁各求群。","明星出东方，照见车下人。","夙兴即往道，登彼高路津。","还顾望京邑，怆焉何所陈。"]},{"t":"七哀诗","f":"五言古诗","c":["问客何方来，四月发回中。","繁霜陨百草，树木如寒冬。","客行一何遥，客颜一何憔。","举目望关山，关山郁萧条。","少壮尽乘边，崖谷何寥寥。","战马不解鞍，弓矢常在腰。","硕鼠走空仓，城上狐狸跳。","咄咄勿复陈，更问北来人。","六月天雨霜，哀哉生不辰。"]},{"t":"与客问答二首 其一","f":"五言古诗","c":["门有万里客，颜面带风霜。","左右佩双鞬，意气何杨杨。","问客何州士，逝将之何方。","客亦不顾云，但言开中堂。","手持一书札，口口称故乡。","长跪受书札，草字八九行。","上言亲戚故，下言别离伤。"]},{"t":"与客问答二首 其二","f":"五言古诗","c":["长跪牵客裾，故乡今何如。","客起长跪言，故乡不可居。","坟垄既芜没，宁复识田庐。","邻巷鲜故人，族属半丘墟。","岩岩高山谷，今为官路衢。","主人聆客言，涕泗交涟如。","离乡三十载，少女为人姑。","迩者日以亲，远者日以疏。","狐狸知故穴，牛马知故阹。","愿为连理树，托根北山隅。"]},{"t":"卫上别王子二首 其一","f":"五言古诗","c":["晨风应候至，鸡鸣各严车。","我今游宋中，子当旋旧闾。","仆夫理前绥，辕马悲鸣趋。","一别阻秦周，相望万里馀。","首春霜露重，厚汝征衣襦。","昔为同袍士，今在天一隅。","故者日以远，畴能察区区。"]},{"t":"卫上别王子二首 其二","f":"五言古诗","c":["税车朝歌里，送子辉水阳。","群雁起高飞，凌风各分翔。","敦交多故怀，况乃忧故乡。","征夫愁短日，去马知路长。","童童孤生柏，结根南山旁。","愿言采此柏，遗我心所当。","良无白鹄翼，何以得高颃。"]},{"t":"赠徐祯卿","f":"五言古诗","c":["独处忽不怿，揽衣循东厢。","树木何修修，春风起飘扬。","我友驾在门，告言适江湘。","仓皇挈玉壶，追送临河阳。","顾瞻两飞凫，并戏水中央。","翩翩厉羽翮，鸣声一何长。","柰何游客子，一别永相望。","时泽亮有周，天命固其当。","薄终义所劣，别离庸讵伤。","懿彼回路赠，慷慨由此章。"]},{"t":"赠王舍人升二首 其一","f":"五言古诗","c":["迅风激高云，朝日照嘉林。","良友忽远适，恻怆摧我心。","川原望靡极，江路浩且深。","殊域寡亲戚，孤子故难任。","荼蓼积愈苦，泪下不可禁。"]},{"t":"赠王舍人升二首 其二","f":"五言古诗","c":["揽泪瞻林木，韡韡敷华叶。","层闉带广陌，事焉暮相接。","骈裾侈高会，谁念独守妾。","岂不思方舟，川广不可涉。","葑菲遗下体，举世重红颊。","劝子且宁志，为恩孰周浃。"]},{"t":"又赠王舍人四首 其一","f":"五言律诗","c":["送美城东陌，还车望上阳。","观阙百馀尺，蓉城郁相望。","同在天一隅，子今旋旧疆。","经子故所居，我马立徬徨。"]},{"t":"又赠王舍人四首 其二","f":"五言律诗","c":["徬徨亦何为，怅望远行客。","枯桑号天风，时节倏复易。","簪绂匪我荣，弃置安所惜。","愿为东南风，遂附高翔翮。"]},{"t":"又赠王舍人四首 其三","f":"五言律诗","c":["劲翮无群栖，灵根岂业茜。","人生非苦匏，安得常相见。","动息各有因，况乃异乡县。","徘徊岐路侧，仰视云中雁。"]},{"t":"又赠王舍人四首 其四","f":"五言律诗","c":["雁征会来归，君行何日返。","惊风飘驰光，岁月忽已晚。","登山采白苓，遗我心缱绻。","上言制颓龄，下言助餐饭。"]},{"t":"赠刘元瑞五首 其一","f":"五言古诗","c":["晢晢吴中娥，奕奕宛清扬。","邂逅此堂隅，瞻顾两回翔。","攘袖发浩齿，列坐无高倡。","行云为徘徊，顺风托馨香。","周席莫不叹，侧目在流光。","何意芳盛年，峻义明秋霜。","于礼诚销薄，银汉徒相望。"]},{"t":"赠刘元瑞五首 其二","f":"五言古诗","c":["矫矫云中鹄，忽忽晨南翔。","连翩客游子，驾言逝何方。","霜露日夜零，东路悠且长。","意欲从子逝，我马玄以黄。","徒思谅无益，欲置难遽忘。","爱子千金躯，双亲在高堂。"]},{"t":"赠刘元瑞五首 其三","f":"五言古诗","c":["埋轮国东门，驾舟越洪洋。","晨发天北偶，日夕至建康。","皇居槩太清，陵树何苍苍。","白马服衡轭，飘飖过路旁。","敦交岂独薄，贫贱多顾藏。","所志在宁亲，荣耀乃其常。"]},{"t":"赠刘元瑞五首 其四","f":"五言古诗","c":["青阳献嘉岁，玄鸟鸣我堂。","远子念行役，驱车发南疆。","岂不诚辛苦，王事切中肠。","駪駪溯原薄，拊剑何慨慷。","群形冒休泽，朽干扬朱芳。","君子法天造，小人曷能臧。"]},{"t":"赠刘元瑞五首 其五","f":"五言古诗","c":["回车太行谷，结辔登羊肠。","羊肠何崔嵬，俯视见大江。","大江日东注，游子悲故乡。","故乡复迢递，欲济河无梁。","晨起振我缨，驾言行朔方。","丈夫贵荣名，临路徒离伤。"]},{"t":"赠徐陆二子","f":"五言古诗","c":["清晨思行游，驾车郭西门。","凝霜被野陆，莽莽多荆榛。","霜雨不归川，四顾无行人。","何意岐路侧，怅然获所亲。","晤言不须臾，含意俱未申。","云问富才杰，具区产名珍。","一为时所知，光耀在清云。","情交苟不劣，穷显非所论。","感激平生义，匪尔谁当陈。"]},{"t":"申州赠何子","f":"五言古诗","c":["翩翩双黄鹄，凌风各将去。","哀鸣岐路侧，一步一回顾。","何异同心子，失散在中路。","别君倏五载，我发忽巳素。","今逢不须臾，趋驾一何遽。","临分但踟蹰，道语不及故。","山川何悠悠，白日奄欲暮。","努力爱玉体，慰我长思慕。"]},{"t":"赠康修撰二首 其一","f":"五言古诗","c":["晨步城西冈，遥望终南岑。","荆棘高蔽天，白曜翳以阴。","鸡食鸾凤饥，蛾眉谗妒深。","葑菲遗下体，一别成飞沉。","出门眺四郊，莽莽悲风吟。","海水有可测，伤哉谁谅心。"]},{"t":"赠康修撰二首 其二","f":"五言古诗","c":["少阴盛霜雪，崎阻鸿雁饥。","荷斧入林谷，日暮谁共归。","林树窈冥冥，径路多虎罴。","北斗横塞岑，邰野风振悲。","欲往河无梁，念子忽如迷。","荣耀在须臾，亡没谁复知。","思附玄鹤翼，从子以高飞。"]},{"t":"赠王生滇南","f":"古风","c":["人生如枯蓬，团团随风转。","朝犹同一隅，夕暮异乡县。","凤凰择林游，奋翼思高飞。","一飞万馀里，路涩常苦饥。","岑峦造青天，蹊涧何崣?。","食寻竹实餐，栖必梧桐栖。","德音倘不隳，慰我心所期。"]},{"t":"送侄木北上","f":"五言古诗","c":["群鸦竞时食，孤鸿独高翔。","丈夫四海心，谁能安旧疆。","杖剑辞所亲，策马登前冈。","岁晏霜露繁，原野何茫茫。","草枯禽兽饥，潢潦浩以长。","感吟悲蒹葭，试鸣候朝阳。","勖哉树名勋，念兹西颓光。"]},{"t":"送秦氏","f":"五言古诗","c":["健足慕千里，倦翮常卑安。","陶子重折腰，贡生乃弹冠。","黄龙日南游，长江浩澜澜。","竹实匪不甘，凤孤谁为欢。","故庐倚青松，悬崖激鸣湍。","返真谢形役，庶以成盘桓。"]},{"t":"送谷氏","f":"五言古诗","c":["零雨晨微微，艾叶何旆旆。","端居辍中忧，驾言送狂迈。","黄河流汤汤，飞云下燕代。","临汀罗觞俎，趁景徙倾盖。","辕马望路鸣，仆夫整衣带。","孰非金章容，子也独所爱。","行行树声猷，及此明良会。"]},{"t":"别李氏二首 其一","f":"五言古诗","c":["逸禽耻淹栖，良驷竞先步。","出门有行游，诸所岂得顾。","辞燕恋旧垒，渚雁企高骛。","情离诚有猝，心期固其素。","匪无便儇子，新人不逮故。","踟蹰野飙夕，分手即前路。"]},{"t":"别李氏二首 其二","f":"五言古诗","c":["前路乃何之，迢迢梦云泽。","霖雨暮戢戢，嘱子且停轭。","陨箨委川径，潢潦浩以白。","荧荧双龙剑，佩服我所惜。","水行蛇虫匿，陆迈虎兕辟。","愿言承心欢，庶与备朝夕。"]},{"t":"赠宁氏二首 其一","f":"五言古诗","c":["野薮萎平畛，寒露一何早。","凝霜一以零，兰蕙亦众草。","美人中夜兴，忧心惄如捣。","玉石诚靡别，妍华恃畴保。","瑟瑟谷中松，见者岂不宝。","良无匠氏顾，叹息岁将老。"]},{"t":"赠宁氏二首 其二","f":"五言古诗","c":["白日何冥冥，送子黄河阳。","执手无一言，仰见双雁翔。","处卑心罔怡，奋飞多中伤。","抚剑两踟蹰，低头涕沾裳。","天运有销盈，志士怀刚肠。","去去受景耀，离别固其常。"]},{"t":"送闵氏","f":"五言古诗","c":["怦怦困暑溽，悠悠抱中戚。","时蝉迩户响，流汗挥复积。","登高散我忧，忽觏远行客。","为问客者谁，是我心所怿。","律律伫征云，迢迢逐归翮。","孰无室家念，忖尔欢聚夕。","伊余胡寡仇，茕茕痛离析。"]},{"t":"长歌行赠房氏二首 其一","f":"五言古诗","c":["捷步竞先鸣，达人贵沈几。","鸿鹄翅摩天，于世常高飞。","煌煌冠盖朝，疏也乃独归。","谁云伤秋子，而为鲈鱼肥。","彼哉枌榆俦，岂知千仞辉。"]},{"t":"长歌行赠房氏二首 其二","f":"五言古诗","c":["瀰瀰夏川广，惊风夕扬波。","眷言送诚归，轩骑匝巾阿。","倦鸟故林趋，兽离怀前窠。","君看累累实，岂复华其柯。","皓首声利途，攸见无乃颇。"]},{"t":"忆昔行别阎侃","f":"五言古诗","c":["忆昔少年时，遨游咸阳都。","邂逅尘埃里，相邀入酒垆。","半酣击剑起，挟弹青门隅。","风蓬离本根，奄忽浮云徂。","聚散良靡期，晤言谁复图。","濛濛零雨辰，悠悠梁园途。","翩翩白马鸣，蔼蔼朱华敷。","昔逢美姿颜，今也白头颅。","中藏难遽宣，相看但捋须。","前路浩崎岖，爱子衰暮躯。"]},{"t":"赠沈氏二首 其一","f":"五言古诗","c":["辞马鸣故群，羁人恋心知。","身也匪木石，孰无怀与思。","蔼蔼轩盖途，才捷竞先时。","冥冥归林翮，爰集非无枝。","龙蛇悟易训，蟋蟀感唐诗。","情感辰靡延，把袂竟河涯。","赠子金错刀，申子古别离。","德爱诚匪他，遘君岂无期。"]},{"t":"赠沈氏二首 其二","f":"五言古诗","c":["旦日子当发，淹留复今宵。","良之美盘餐，为君品鸣箫。","君子岩下松，霜霣颜不消。","众草苟移时，化为艾与萧。","聆曲复不怿，惓焉伤迢遥。","携手步前庭，仰面看招摇。","巢子潜箕阳，四岳俞唐尧。","愿言修九苞，曳佩鸣天朝。"]},{"t":"送蔡帅备真州三首 其一","f":"五言古诗","c":["晨飙下严霜，波水白浩浩。","鸡鸣人语动，趋驾恨不早。","出门望原野，四顾但衰草。","芒砀一何寥，惊雁鸣寒蓼。","老骥志千里，烈士轻远道。","临事母谓难，为善岂在小。"]},{"t":"送蔡帅备真州三首 其二","f":"五言古诗","c":["飏舟逾长淮，登陴望大江。","气势何郁盘，皇矣真我邦。","宫殿槩高清，钟山变青苍。","横飙静霜夕，天堑如沸汤。","时平智士拙，货贱良贾藏。","无言边境勋，宁居亦慨慷。"]},{"t":"送蔡帅备真州三首 其三","f":"五言古诗","c":["陨霜凋枫木，泽薮莽虞虞。","结徒策青骊，行狩聊我娱。","左发殪玄兕，右捎仆文駼。","插羽坐草间，饮酎炙鲜腴。","川光夕明灭，雁骛风叫呼。","立马千仞冈，仰送浮云徂。","弹剑问所私，何如李金吾。"]},{"t":"时命篇","f":"五言古诗","c":["代马不恋越，荆禽岂巢燕。","鸲鹆渡汶水，君子忧未然。","柰何容游子，率尔辞故山。","行兽顾丘林，出云有归还。","交交声利途，轩车日骈阗。","谁念牛下人，悲歌夜中叹。","豪门有弃襦，我衣怕不完。","张仪惧诸侯，泄柳乃闭关。","贫贱岂尽愚，时命当自安。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其一","f":"五言律诗","c":["天门郁岧峣，虎豹守其隅。","番番九苞禽，颉颃舞云衢。","衔书奏至尊，青龙与之俱。","光夕绝还响，徙倚空愁予。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其二","f":"五言律诗","c":["帝居杳何许，苍苍隔九阍。","白玉为阿阁，黄金为重门。","可望不可扣，仰见飞云奔。","何当发炎旭，下照孤葵根。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其三","f":"五言律诗","c":["鼗响久不作，烈士常苦辛。","魏裾已寂寞，汉褴空嶙峋。","邈焉向千载，曶曶怀斯臣。","皇心苟识察，百死宁一身。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其四","f":"五言律诗","c":["悬车曜回景，夕风起乔林。","抚兹散沉忧，浩荡开重阴。","回翔瞻阙门，踌躇思玉音。","宵坐焰明烛，怀古伤我心。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其五","f":"五言律诗","c":["大化罔不亏，人生固多艰。","汎观畴昔人，浩然发忧叹。","自非餐霞侣，伊谁驻朱颜。","律律南山岑，拂衣会当还。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其六","f":"五言古诗","c":["孟夏草木长，垂云一何凄。","零雨宵始歇，西山朝复隮。","兀然坐高舂，时闻鹁鸠啼。","逢辰寡宿欢，履运伤前迷。","既无杯中物，何以写我悽。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其七","f":"五言律诗","c":["飘风自南来，飒飒入我怀。","我欲随之翔，北向三重阶。","守阍遥望予，阊阖何由排。","戚戚勿重陈，危言多厉阶。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其八","f":"五言律诗","c":["夕云郁峥嵘，颓阳入西丘。","返景漏林端，明我屋上楼。","静久得玄理，源澄复何求。","永怀邹阳子，聊以抒我忧。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其九","f":"五言古诗","c":["苔井肃阴森，岳庙闷以清。","车前当路翻，红葵夹阶生。","羁人散烦疴，纡徐步中楹。","时禽变好音，庭柯敷夕荣。","讵知沮洳场，旷然获悠情。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十","f":"五言律诗","c":["青青庙中槐，交交一双禽。","为巢育其儿，结构良苦辛。","一朝惊弹罗，移栖向高林。","我行适见之，叹息空弥襟。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十一","f":"五言古诗","c":["湫宇夕阴阴，寒灯焰不长。","气楼递微明，飘忽如清霜。","人云网恢恢，我胡寓兹房。","墉鼠语床下，蝙蝠穿空梁。","惊风振南牖，徂夜倏已央。","于邑不成寐，展转情内伤。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十二","f":"五言古诗","c":["小草生枯桑，芊芊竞芳辰。","虽云殊本根，寄托各有因。","自我罹幽囚，忽焉经浃旬。","我兄千里馀，渺渺长河津。","妻子日望余，苍苍隔西邻。","所幸二三友，笑言越昏晨。","宵镫促燕膝，昵语忘苦辛。","患难苟相得，毋论骨肉亲。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十三","f":"五言古诗","c":["檐月何徘徊，晨风复依依。","载言别同居，仓皇倒裳衣。","处者各惆怅，去者从此辞。","挽手刺刺语，寄言家中知。","丁宁故与亲，愿勿长相思。","明明昊天威，我久宁在兹。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十四","f":"五言古诗","c":["皇矣彼上帝，赫赫敷明威。","四序舒以惨，中有玄妙机。","烛龙跃天门，一朝景光回。","昔为霜下草，今为日中葵。","稽首沐罔极，欲报难为词。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十五","f":"五言古诗","c":["明月出东方，徒行反家室。","室人走相讯，问我何由出。","明知非梦寐，欲辩仍自失。","喜极双涕零，转面各衔恤。","垂镫照缃卷，浮埃满朱瑟。","愁言卒未倾，忽复见晨日。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十六","f":"五言古诗","c":["鸣镳踰广陌，执简谒彤闱。","道逢相识问，倏如远行归。","虎拜阁门下，龙颜霁晨辉。","二后邈以诏，吾皇嗣其徽。","从谏如转九，旁求炳先几。","令闻洽四国，寿与南山齐。"]},{"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十七","f":"五言古诗","c":["臣本草野士，弱冠承恩私。","黾勉簪绂间，低回赧容姿。","直湍寡回波，劲木无弱枝。","天运不易测，物情谅如斯。","修涂方浩浩，驾言赴前期。"]},{"t":"离愤五首正德戊辰年五月作是时阉瑾知劾章出我手矫旨收诣诏狱 其一","f":"五言古诗","c":["采采河边兰，鲤鱼何盘盘。","念我同胞人，诀绝摧心肝。","事变在须臾，浮云逝无端。","临发路踟躇，谁敢前为言。","原鸰杭高声，我行何时还。","十步九回头，泪下如流泉。"]},{"t":"离愤五首正德戊辰年五月作是时阉瑾知劾章出我手矫旨收诣诏狱 其二","f":"五言古诗","c":["练练晨明月，郁郁风中柳。","苍茫遮我车，识是平生友。","感君故意勤，赠我双琼玖。","虎狼夹衡轭，狐狸草间走。","东方渐发白，聊归勿为久。","天威煽方处，君子毖其口。"]},{"t":"离愤五首正德戊辰年五月作是时阉瑾知劾章出我手矫旨收诣诏狱 其三","f":"五言古诗","c":["北风号外野，五月知天寒。","海水昼夜翻，南山石烂烂。","丈夫轻赴死，妇女多忧患。","中言吐不易，拊膺但长叹。","永夜步中庭，北斗何阑干。","裂我红罗裙，为君备晨餐。","车动不可留，伫立泪汍澜。","愿为云中翼，阻绝伤肺肝。"]},{"t":"离愤五首正德戊辰年五月作是时阉瑾知劾章出我手矫旨收诣诏狱 其四","f":"五言古诗","c":["驱车重行行，前上西山陲。","白日忽已冥，归鸟来何迟。","飘风吹征衣，北逝方自兹。","行路见我行，不行为嗟咨。","苦称途路涩，君子莫何之。","欲诉难竟陈，天命自有期。"]},{"t":"离愤五首正德戊辰年五月作是时阉瑾知劾章出我手矫旨收诣诏狱 其五","f":"五言古诗","c":["结发事君子，缔结固不解。","青蝇玷白璧，馨香逐时改。","恩阻爱不周，弃掷良在此。","红尘何冥冥，白日沦西海。","对面有诀绝，何况万馀里。","得宠各自媚，谁为展情理。","讹言方猬兴，君子慎其始。"]},{"t":"赴江西之命初发大梁作","f":"五言古诗","c":["戚戚辞故里，盛阳远行游。","入门揖兄嫂，征马已驾辀。","日午登前冈，浮云逝南流。","零汗透衣巾，仆夫行悠悠。","躯微惧命重，慷慨但怀愁。","还望故所居，匹鸟鸣相求。","而我独何为，道路常怀忧。"]},{"t":"杂诗三十二首 其一","f":"五言古诗","c":["英雄树大业，奋志常慨慷。","捐身赴国仇，效命争战场。","明甲耀皎日，挽弩千石强。","矢石下如猬，杀声如沸汤。","被刺目不逃，阽危气益昂。","雄名辉册符，生死固其常。"]},{"t":"杂诗三十二首 其二","f":"五言古诗","c":["大司肃制度，鸿儒振英仪。","生杀原异门，为猷视厥施。","峨冠巍堂上，巧笑芙蓉姿。","狐心生暗鬼，耳闻佯不知。","膏梁媚妻妾，无赖充王师。","白刃起如林，狗马用羁縻。","荣达信有命，叹息将奚为。"]},{"t":"杂诗三十二首 其三","f":"五言古诗","c":["共工触山折，夸父去无还。","娲氏怀忧伤，鍊石思造天。","妖姬鼓哀瑟，嬉戏王台间。","草昧怨无侯，哲者中自煎。","小鸟填巨海，芦灰遏洪川。","力诚有不及，心情良可怜。"]},{"t":"杂诗三十二首 其五","f":"五言古诗","c":["命驾将何之，意欲快我心。","蛮方乱如麻，匈奴寇榆林。","挥剑誓俱亡，彼军忽如沉。","岂为尺寸勋，国仇怒至今。","昆崙贡织皮，鸱鸮怀好音。","功高固不赏，谗妒来相寻。","哀哉险侧子，倾词谁见钦。"]},{"t":"杂诗三十二首 其六","f":"五言古诗","c":["大道竟焉陈，末运忺相欺。","谗疑进贝锦，交乱令心悲。","鸱鸮翔茂林，乌鹊游下枝。","人情有偏好，触意生乖离。","长门绪清吟，鱼肉怨新诗。","玉分石见仇，咄嗟当语谁。"]},{"t":"杂诗三十二首 其七","f":"五言古诗","c":["遨游写愤懑，驾言凌洪涛。","洪涛匪我游，改马登山椒。","朔风一来至，林谷何萧萧。","鬼怪时以兴，云逝谁能招。","禽鸟相聚鸣，原兽复晨号。","置此勿徒苦，乘云可宏翱。"]},{"t":"杂诗三十二首 其八","f":"五言律诗","c":["有衍东园椒，结实何累累。","条远敷不易，斧者见行摧。","燕雀本小鸟，志欲翀天飞。","哀哉不自谅，失路将安归。"]},{"t":"杂诗三十二首 其九","f":"五言古诗","c":["悲风厉岁晏，宵旦未云巳。","寒冬雨雪至，江汉骄南纪。","临堂翳孤松，杳杳叹成理。","凉潦不溢泽，时雁鸣高起。","一飞摩青天，倏忽乃万里。","讯言蓬蒿士，沓沓竟何以。"]},{"t":"杂诗三十二首 其十","f":"五言古诗","c":["晨出进贤门，南向望东乡。","清川激崇岑，弥野何茫茫。","白骨皓四隅，群鸟噪枯桑。","阖门已杀戮，鸱鸮复来翔。","日昃时易冥，漏网顿天纲。","思此愁我心，还车眺河梁。","玄鹤靳高鸣，于世常激昂。","一逝声影灭，谁哉见孤颃。"]},{"t":"杂诗三十二首 其十一","f":"五言古诗","c":["登山望四海，日夕忽至沉。","俯身眺城廓，痗然沾我襟。","交路夹芳兰，逝驷何骎骎。","朱树蔼閒榭，奇巧媚荒淫。","北里进异舞，高唐呈妙音。","纤罗振芬芳，朝云递嘉吟。","不见秋至草，零落愁春心。"]},{"t":"杂诗三十二首 其十二","f":"五言古诗","c":["兀然坐空堂，戚戚怕窃悲。","旷世怀一鸣，燕雀翻见欺。","恶名收范公，文致诋朱熹。","身亲罔自明，万世余焉知。","霜露陨华草，憔赣今其时。","百年俟论定，恃此良可嗤。"]},{"t":"杂诗三十二首 其十三","f":"五言古诗","c":["倚闾迟佳人，日莫期不来。","拂衣舍之去，去上延秋台。","旗旌蔽原坂，鼓角鸣且哀。","黄鹄翔不下，腐鼠鸱见猜。","壮士愤国难，抚剑但徘徊。","白日倏西倾，怆惋肝肺摧。"]},{"t":"杂诗三十二首 其十四","f":"五言古诗","c":["灼灼缀枝华，荣艳一何好。","朝阳溢其葩，馀光照寒槁。","冠盖沓衢路，致身竞先早。","磬折名誉场，销铄成丑老。","一夕不复晨，陨落随秋草。","逍遥可竟世，繁华讵足保。"]},{"t":"杂诗三十二首 其十五","f":"五言古诗","c":["阳回杳无朕，朔风振江郊。","翩翩者何禽，衔枯创新巢。","长短有成理，环也特其遭。","穷者非尽愚，显岂皆贤豪。","羲阳奄西驰，今夕明复朝。","如何途路子，得意怕自骄。"]},{"t":"杂诗三十二首 其十六","f":"五言古诗","c":["无荣亦无辱，倚伏还相随。","韩侯叹良弓，宁复歆昔时。","华春敷明阳，各艳容与姿。","孤松秀严冬，历世谁可期。","照耀东门瓜，前贵今岂知。","较计毁誉间，无乃贤达卑。"]},{"t":"杂诗三十二首 其十七","f":"五言古诗","c":["昔有玩世士，乃处匡山阿。","其人久巳冥，春林发烟萝。","故址栗里旁，见者不忍过。","荷锄岂不苦，刈薪行且歌。","诋毁日来加，醉酒良靡他。","沉冥在一时，千载固难磨。","小儿为督邮，磬析将如何。"]},{"t":"杂诗三十二首 其十八","f":"五言古诗","c":["旨余游淦南，曾上升天台。","兹也诚玄冥，万里悲风来。","松柏槯路傍，玉梁安在哉。","举手招王乔，三洲限蓬莱。","黄鹤舞高岑，清云曳徘徊。","叹息长久术，怆恻今人哀。"]},{"t":"杂诗三十二首 其十九","f":"五言古诗","c":["玉梁不可游，回登怀玉颠。","应龙喷白雾，接我升云烟。","凭轩望四海，溷闷良可怜。","可怜者谁子，白马来翩翩。","明哲困槽糖，康子骛轻轩。","嬿婉逞一顾，力违成过愆。","倾城亦何益，伤哉诚嗟叹。"]},{"t":"杂诗三十二首 其二十","f":"五言古诗","c":["黄涂亘东西，六龙驾天车。","一驰濛泛间，百计无柰何。","弯弓倚扶桑，抗手招阳戈。","浮云徂我前，逝鸟鸣相过。","凤凰愁丹山，溟海日夜波。","行行欲安之，念此纷滂沱。"]},{"t":"杂诗三十二首 其二十一","f":"五言古诗","c":["今日苦炎热，风雩可徜徉。","亭亭一孤松，乃在匡山阳。","李公宅深冥，朱氏扬其芳。","仰身攀林岩，俯之泪数行。","势路纷狭斜，随利来相戕。","命驾且复去，誓与朱凤翔。"]},{"t":"杂诗三十二首 其二十二","f":"五言古诗","c":["贵贱各有命，昧者苦保持。","殷勤话言接，转面不可知。","一言相千秋，冠盖嚇来驰。","鴳雀鳱梧桐，翕习鸾凤饥。","鸡鸣市朝动，董生方下帷。"]},{"t":"杂诗三十二首 其二十三","f":"五言古诗","c":["惙惙怀坦途，由之乃江河。","波起旁所骇，舟中如室家。","中林设暗罟，鸿鹄逝九阿。","谗巧诚相戕，飞鸟日暮过。","修短自然理，作色将谁何。"]},{"t":"杂诗三十二首 其二十四","f":"五言古诗","c":["匡山有老人，自称岩下公。","绿发渥朱颜，皎若云间鸿。","往来骑白鹿，姿美精肉充。","招我将从之，心阻难遽通。","流情复高翔，翩翩驾天风。","夙昔思此人，寤言期与同。","感此重枉顾，德音常在衷。"]},{"t":"杂诗三十二首 其二十五","f":"五言古诗","c":["驺虞不食草，志士宁苟安。","矩步挥芬芳，凛义不可干。","吐辞程大猷，妻子常饥寒。","中心思美人，遥夜起长叹。","延颈望西岐，欲鸣途路难。","踯躅待天晨，宵夜徂漫漫。","明月鉴房帷，涕泪交汍澜。"]},{"t":"杂诗三十二首 其二十六","f":"五言古诗","c":["临事戒愤切，愤切增烦心。","君子被短褐，小人富黄金。","璇机造变化，何浮不有沉。","不见游波蛤，前是詹中禽。","池鹍奋羽奋，倏忽四海阴。","沐浴濛泛间，飘飖终邓林。"]},{"t":"杂诗三十二首 其二十七","f":"五言古诗","c":["少年抚长剑，放浪三河滨。","累累道旁者，云是金邓坟。","歘翕随龙飞，策符登茂勋。","南阳多贵人，烜赫阗未轮。","委身今黄土，千载不复晨。","首阳有采薇，饿死谁为闻。","遗义凛秋霜，见者常酸辛。"]},{"t":"杂诗三十二首 其二十九","f":"五言古诗","c":["昔余挟诗书，京里扬鸣珂。","敷藻艺林间，结交聚边何。","岂云倾人城，绝代耀姿华。","分散倏老丑，孤游江湘阿。","出攀芳桂林，倚岑挥浩歌。","荆榛蔽丘原，浮云一何多。","灵剑有合并，咏言伤嗟跎。"]},{"t":"杂诗三十二首 其三十","f":"五言古诗","c":["莫笑一杯水，覆地东西流。","人命苦飘光，起忽谁能留。","藜藿足充饥，岩峦可遨游。","衣文附灵牺，庄子诚见羞。","黄雀乾下庖，白刃临九州。","一为华屋吟，俄顷归山丘。","脱身幸及今，世事如蜉蝣。"]},{"t":"杂诗三十二首 其三十一","f":"五言古诗","c":["毁誉不可校，校之心烦悲。","荣名盖一世，千载谁见之。","塞翁失其马，马归驹来随。","生死尚无常，万事诚尘灰。","舒啸饮醇酒，聊与玄化嬉。"]},{"t":"杂诗三十二首 其三十二","f":"五言古诗","c":["窭人困贫贱，忉切常自悲。","达者竞先步，所苦名位卑。","旦荣昏暮零，二者谁复知。","二者不可知，懊恼将何为。","不见旷世子，埋没随蒿藜。"]},{"t":"渡汉五首 其一","f":"五言律诗","c":["好游良有殚，今朝竟言归。","汹汹舟下涛，乱之将畴依。","异途各为趋，同木相随飞。","遹观千仞禽，谁复瞻其辉。"]},{"t":"渡汉五首 其二","f":"五言律诗","c":["万事虽贵豫，数极谁竟猷。","朅来弹我剑，且复三河游。","迤东望濠梁，嘅言怀庄周。","黄鸟孰兴篇，枌榆乃见尤。"]},{"t":"渡汉五首 其三","f":"五言律诗","c":["于心怀佳山，背之每自顾。","相逢鲜久要，那得不念故。","塞翁罔忧马，马归人始悟。","游女非召南，千年没贞素。"]},{"t":"渡汉五首 其四","f":"五言律诗","c":["霖雨濡我轨，寒潦河滔滔。","坟亩畯徒悲，汉流怒洪涛。","思美叹晨夕，欲济难容舠。","限隔岂固逖，踟蹰为谁忉。"]},{"t":"渡汉五首 其五","f":"五言律诗","c":["闲登古樊城，回望岘首山。","鴳雀跃寒蓬，畴念朱岑翰。","小人竞锥刀，羊子乃探环。","智愚固生性，融晦靡我叹。"]},{"t":"杂诗三首 其一","f":"五言律诗","c":["宛宛春田鸠，飞鸣柔且闲。","一朝化为鹰，肃肃厉羽翰。","众禽不敢并，孤立秋云端。","鸟既不自知，人胡究其然。"]},{"t":"杂诗三首 其二","f":"五言律诗","c":["绵绵谷中葛，引蔓在修楚。","修楚代为薪，葛也安所附。","岂无絺与绤，可以禦清暑。","烈烈严冬时，忧君乏纩絮。"]},{"t":"杂诗三首 其三","f":"五言律诗","c":["汎汎河上舟，摇摇靡攸止。","我欲维此舟，川广不可涘。","振振凫与雁，栖食在波水。","岂不良幽寞，夙心耽乐此。"]},{"t":"辕驹叹","f":"五言古诗","c":["世径互险夷，富贵安所需。","昔为枥中骏，今为辕下驹。","白日仰悲鸣，青云立踟蹰。","未蒙主人顾，何由效驰驱。","朝思碣石津，夕睇流沙隅。","常恐侣凡蹇，弃捐中路衢。"]},{"t":"李广","f":"五言古诗","c":["李广昔未遇，射猎谁见称。","君王犹未识，他人宁不轻。","日从田间饮，夜止灞上亭。","醉尉前呼呵，小吏亦见凌。","一朝剖郡符，飞盖赴北平。","凭轼览百邑，树羽宁千城。","亭障不设燧，枥马跃顿缨。","弯弓射虎归，淡淡黄云生。","自从结发战，舍镝无虚鸣。","威慑五单于，胡人寤寐惊。","孰知身运乖，数奇竟无成。","壮颜逐年衰，白发忽见婴。","寄言雄图者，俟命莫吞声。"]},{"t":"豫让","f":"五言古诗","c":["士有气相感，杀身酬所知。","伯氏既谢世，族姓无孑遗。","噬炭甘若饴，漆身亮何为。","生既荷君遇，没敢求君知。","仇闻再三叹，揽泪惠新衣。","玉剑四五动，左右神为摧。","怆哉彼流水，迄今为鸣悲。","行路伫叹息，芝兰绕坟基。","人生固有毕，节义诚难亏。"]},{"t":"怨歌行","f":"五言古诗","c":["怨违情有悲，欢聚理无欺。","欢怨非中则，感离难重持。","才见春华交，倏巳晨露滋。","秋风吹罗袂，团扇不复施。","团扇与罗袂，用舍各有时。","炎寒启迭运，超旷多远期。","勿徒叹捐弃，恩爱倘中移。"]},{"t":"咏古镜","f":"五言古诗","c":["荧荧堂中镜，皎皎悬秋月。","宠移明与夺，势满光仍缺。","美人昔提携，拂拭生皎洁。","用以奉君子，义投物不忽。","良无刮劘费，岂谓遽乖绝。","悲故情自懘，争妍道所劣。","掩抑经冬春，芜蚀怨芳节。","黄鸟及候吟，朱兰有时歇。","推移准运理，显晦遵前哲。","显晦亦何怜，所叹在乖别。"]},{"t":"葑菲叹","f":"五言古诗","c":["菁菁田中葑，与与疆上菲。","托根岂诚异，敷叶为谁美。","采掇女心叹，遵路劳情理。","鲜茎入素手，终朝不盈篚。","置之独长惋，抆泪沾衣里。","白华肇卑薄，谷风启怨诽。","色衰使交离，弃美因下体。","空瞻寸晷旋，倏见严飙起。","徒持履霜戒，谁念禦冬旨。","吟叹非贞喻，托物聊在地。"]},{"t":"有梦","f":"五言古诗","c":["濡迹古梁郊，托兹洪河疆。","流景逝不处，众草忽巳霜。","玄云骇崇原，鸣风激空桑。","侯予竟此夕，念独涕沾裳。","人欲天必从，神交讵无方。","解襟即幽寐，执袂奉颜光。","道暌未终巳，舒体各异乡。","鸣鸡在东壁，薄月鉴空床。","精诚谅有合，暂违宁讵伤。"]},{"t":"鸡鸣篇","f":"五言古诗","c":["宛宛天运周，鸡鸣夜复旦。","疾者寡长寐，思者多寤叹。","癙忧积中肠，绪理一何乱。","众人沓经营，君子乐衎衎。","高山变为陵，深谷化为岸。","愿从詹氏卜，乘槎问河汉。"]},{"t":"驰景篇","f":"五言古诗","c":["小至方浃辰，居然届寒腊。","澄空暮霜敛，云物次吐纳。","眷念河关阻，怅望三川楫。","城阴多悲风，驰景杳难接。","遥忆鹿门驾，缅轸冯驩铗。"]},{"t":"时序篇","f":"五言古诗","c":["邈矣时序迈，悠悠羁思悬。","少岁觌飞龙，振步蹑云烟。","杨芬凌紫霄，结驷览黄渊。","王纲袛以穆，四海屡丰年。","晨趋谒云陛，晚沐踏京尘。","流觞拥华馆，藻翰飞阳春。","逸者眷多暇，壮士耻无闻。","徒阅芳华改，何有尺寸勋。","日月不我待，倏忽星运移。","抱疴届兹夕，怃然伤夙期。","玄发难久恃，母令达者嗤。"]},{"t":"岁晏行","f":"五言古诗","c":["岁晏幽阴积，寒霖夕馆空。","浮云起城阙，浩眇安可穷。","悠扬横太虚，回薄蔽鸿蒙。","我有一丛兰，种之良亦难。","飘风忽来吹，零露苦相残。","劝君留此草，萧艾不可宝。"]},{"t":"苦热篇二首 其一","f":"五言古诗","c":["大运互伸缩，二仪每骄蹇。","阳威苟不烈，阴驭何能反。","避暑蹑清榭，栻汗望幽巘。","密绿暵丰林，萋芜萎修坂。","逃饮岂其性，对食不能饭。","嗟彼驰骋子，晨暮各忘返。","执热古有经，愚智讵相远。","何当苏海宇，余亦遂仰偃。"]},{"t":"苦热篇二首 其二","f":"五言古诗","c":["伏阴会当升，愆阳固有期。","墙茨覆鲜实，蟪蛄夕以哀。","所虞大火流，即值凉霜催。","轩辕制六律，大舜弹鸣丝。","四气为之和，民生寡忧思。","古理日云邈，季运安所师。","我怀良已永，炎曜况倭迟。","愿言惠清飙，飒然均此施。"]},{"t":"潜龙篇","f":"五言古诗","c":["骄阴不可制，坚冰忧我衷。","阳驭倏来返，玄律播阴风。","譬彼昼与夜，循环固难穷。","古人闲行旅，九市禁相通。","阳升惧不力，静以收其功。","养木当以萌，养德当以蒙。","眇哉一丝微，柰此群阴攻。","脉脉渊泉底，畴能拔潜龙。"]},{"t":"孔翠篇","f":"五言古诗","c":["孔翠耀其羽，乃为俗所珍。","神龙处九渊，潜跃固有因。","小人役琐屑，君子扬其芬。","遐哉颜闵烈，千秋洒灵芬。","出事金玉昆，入奉堂上亲。","恩义苟不亏，岂必馔芳薰。","爰骋六艺圃，载泳诗书津。","何当继乔木，振佩蹑高云。"]},{"t":"有鸟二首 其一","f":"五言古诗","c":["有鸟东方来，长鸣向西北。","竦身欲缚鸟，自愿无羽翼。","白日蔽高陆，玄阴视无极。","风飙昼烈烈，积霰堕我侧。","星纪虽云周，沴气尚难测。","逝者一何速，来者惧不力。","杕杜生道左，孤桐弃遐域。","虽怀壮士情，讵捕阳和德。"]},{"t":"有鸟二首 其二","f":"五言古诗","c":["一为羁旅士，遂使年岁积。","人情感新故，惨惨不得释。","夜视天上星，翳翳云霰隔。","阳道即光明，何由在德泽。","离居多永忧，怅念在今夕。","借问怅念谁，是我同袍客。","岂谓凉暄殊，所叹阻疆埸。","缄书寄游云，会托南征翮。"]},{"t":"卧疾二首 其一","f":"五言古诗","c":["寒飙振疏牖，十日岁华改。","王孙怨修路，芳草若相待。","寸心百虑婴，移疾屡朝晦。","范甑蛛网生，翟门雀罗在。","叹息中林蕙，望望何能采。"]},{"t":"卧疾二首 其二","f":"五言古诗","c":["眠疴感岁晏，中意长刺刺。","展策不能读，对酒寡欢怿。","晨风激幽林，坚冰满川泽。","短景不可驻，倏忽变昕夕。","飞云迅南征，归鸟厉其翼。","地北常苦寒，寤寐想温域。"]},{"t":"值雪咏怀","f":"五言古诗","c":["索居倦晨暮，沓沓伤岁穷。","玄云为谁屯，流霏夜常风。","映隙既窈窕，穿窗亦玲珑。","凌高似有缀，填卑忽若崇。","裒多虽称物，益寡竟谁功。","匪无盈尊酒，斟酌解我忡。","途路怅伊阻，佳期杳莫同。","握瑾惜楚老，枝瑶怨国风。","人欲天必从，积感理能通。","钟弦旷易绝，郢论寡弥工。","持为知音说，庶以折其衷。"]},{"t":"至后上方寺酒集","f":"五言古诗","c":["久阴痗昏氛，我行值嘉明。","白日展冬耀，雪霁松林清。","景异赏贵延，朋集杯难停。","入筵午未端，归骑夕巳冥。","衡风振岩廊，铃索抗高鸣。","塔虚响先奔，珠圆光易倾。","超物虑可澹，遗荣累果轻。","久枉证诠理，一悟得所徵。"]},{"t":"上巳海印寺二首 其一","f":"五言古诗","c":["劳生苦役役，况乃值温阳。","林园有嘉荣，蹊者生柔芳。","秉蕳迹已陈，韨褉难独忘。","驾言适莲宇，迂纡陟虹梁。","峨宫延暮色，陂树蔼青苍。","距知幽胜区，占兹佳丽乡。","居然心境寂，弥增尘路伤。"]},{"t":"上巳海印寺二首 其二","f":"五言古诗","c":["眺远及丽辰，登危开我襟。","秉炬蹑佛榭，杳杳夕光侵。","芳湖递澄鲜，幽隍覆层阴。","毕景没长甸，轻霏变春岑。","仰瞩双龙阙，却瞻上苑林。","归翼矫以翔，鸿雁多哀音。","荟蔚桃李场，孰分松柏森。"]},{"t":"春游篇二首 其一","f":"五言古诗","c":["东气散广陌，北杓栒青陬。","美人惜春阳，鸣鏕事遨游。","遨游览万物，纡迟驻道周。","京邑蔼九衢，合沓喧轮驺。","黄鸟集于林，碧草生御沟。","御沟多垂杨，芳树夹朱楼。","卑崇冒休泽，郁哉帝王州。"]},{"t":"春游篇二首 其二","f":"五言古诗","c":["朝游东市陌，暮出北城衢。","夕林何嵚岑，华月耀西隅。","宵征溯皇垣，回策遵玄湖。","春冰日以薄，凫雁聚喧呼。","逶迤浦溆贯，金刹据中区。","前有三石梁，宛若垂虹纡。","却顾云中观，翳翳蔽松榆。"]},{"t":"春日洪法寺后冈","f":"五言古诗","c":["暄阳入广墟，平阡暧烟芜。","税鞅寻高禅，陟丘眺袖都。","白日丽中衢，青霏蔼林岨。","碧草一何萋，丛葩亦已敷。","累累谁氏坟，崷崒三浮屠。","凿石锢九泉，雄构耀城隅。","舆台盗绮衣，苔藓封丹枢。","矫首视天宇，剡剡浮云徂。","崇名古所钦，多藏秪区区。"]},{"t":"秋日重过上方寺","f":"五言古诗","c":["居闲怀行游，触景慨时速。","昨来春华敷，秋草倏巳绿。","弱蘋布霜涟，丛兰委寒陆。","累果媚西阳，漂萚满空曲。","物遇信绵旷，情移乃踯躅。","夷犹步前庭，迤逦陟曾麓。","夕风一何厉，行云结相逐。","铎音抗高听，塔影骇流瞩。","聿非封侯骨，虚拟燕颔肉。","飞缨靡不荣，芒屩谅应足。","寄谢世上人，吾久脱羁束。"]},{"t":"苦寒行","f":"五言古诗","c":["白日敛光曜，北风如剑刃。","泽坚走鸣车，水雪峙千仞。","登高望四海，四海水将结。","蛟蛇壅巢窟，虎豹潜于穴。","巑岏太行谷，苍莽阴山戎。","沙碛书飞霜，垒门吹烈风。","鸟雀堕岩壁，黄狐啸空城。","居人掩阙卧，客子无复行。"]},{"t":"京师元夕有怀丘子兼忆旧游而作","f":"五言古诗","c":["名都郁垝垒，浮云荫孤台。","宿昔与丈人，揽袂凌崔嵬。","延眺殊未已，明月从东来。","俯身览九陌，车马何諠豗。","朱门竞笙竽，钟鼓趣行杯。","讵知前代人，寒隧生青苔。","金珠委瓦砾，铅华安在哉。","沉冥日云富，感激人心哀。","丈人方岳裔，夙质谢尘埃。","婚嫁慕向子，幽栖放颜坏。","七十尚蛇蛰，白衣潜草莱。","嗟余纠簪绂，俛仰阻沿洄。","逝将亲逸躅，荣盛等浮灰。"]},{"t":"元夕友人见访","f":"五言古诗","c":["春月多丽辉，白雪媚其姿。","美哉京洛夕，银潢郁逶迤。","逶迤带紫陌，车马驱以驰。","繁灯张四衢，都人竞游嬉。","道者便静性，俗夫乏远资。","林塘枉冠盖，缱绻非我期。","金波低宛转，明星渐离离。","清光苟不亏，永与浮云辞。"]},{"t":"月夜饮别徐氏","f":"五言古诗","c":["仲月玄鸟集，蚯蚓蟠于庐。","朅从徐氏饮，置酒临中除。","明月一何光，众星烂高虚。","中有参与商，相望憯不舒。","人生虽有欢，讵得常相于。","夷犹广庭内，恻恻掺子袪。","哲人重明德，迈士怀离居。","离居谅复合，行矣慎所须。"]},{"t":"行省树下","f":"五言古诗","c":["中林溽雨积，芜径暑日薄。","众鸟集于樾，鹓凤眇焉托。","披云瞩岑观，缥缈三阿阁。","踽踽怀昔贤，扰扰疾棼错。","夷犹攀荣柯，慷慨念幽壑。"]},{"t":"赠王康边何四子","f":"五言古诗","c":["绵绵远道积，冉冉岁华晏。","冰霜夕转严，星斗夜仍烂。","兰缸照寒户，旅士怀乡县。","方幸厕鳞翮，讵谓各分散。","岐路忽在兹，山川复悠缅。","王子万人特，英论薄烟汉。","康生千里足，迈景速流电。","瑰玮钦奉常，秀朗推中翰。","冲标汎光蕙，逸思凌玄雁。","所嗟异根株，逝矣悲霜霰。","兴言念暌晤，佳期阻欢宴。"]},{"t":"九子浴九首 刘户部远夫 其一","f":"五言律诗","c":["远夫振英驾，乃自仪封里。","孟复既鹰奋，秉衡亦飙起。","献贼拟扬雄，弹铗笑冯子。","时异各暌隔，蓬转自兹始。"]},{"t":"九子浴九首 王户部邃伯 其二","f":"五言律诗","c":["矫矫王邃伯，深心托玄素。","岂谓万里空，见此天马步。","独行迕流议，苦志涉烦务。","曰余驽钝姿，倘辱导前路。"]},{"t":"九子浴九首 王职方锦夫 其三","f":"五言律诗","c":["职方昔垂髫，邂逅在梁汝。","游关匪豹隐，攀邵遂鸾翥。","鸿词振宛洛，一一中音吕。","访戴谅不惜，纵凫非所许。"]},{"t":"九子浴九首 穆检讨伯潜 其四","f":"五言律诗","c":["清庙播芳叹，朱鹭激潜调。","沉冥会诠理，刻苦尤逾耀。","注易在今兹，醴酒企馀照。","载吟古离咏，蹇拙惭赓绍。"]},{"t":"九子浴九首 其五 马给事中敬臣","f":"五言律诗","c":["敬臣闺闼彦，处世怕自拘。","朝谒金马门，暮向青琐趋。","朝隐慕方朔，修辞剧相如。","太阿不在掌，非君独嗟吁。"]},{"t":"九子浴九首 陶行人良伯 其六","f":"五言律诗","c":["陶子三泖英，妙小富篇翰。","至响本无声，隐璞畴能辨。","运甓不云若，漉酒聊自玩。","解龟幸心许，倾盖荷清宴。"]},{"t":"九子浴九首 马进士君卿 其七","f":"五言律诗","c":["君卿素所昧，密竟宛相向。","醉酒似马周，读书薄刘向。","时人固不识，古志益肮脏。","试睹同游子，磈礧尽英行。"]},{"t":"九子浴九首 戴进士仲鹖 其八","f":"五言律诗","c":["南州实才窟，小戴亦横骛。","探镮乃叨窃，对孔岂在屡。","左右佩采荠，追趋信阳步。","倾城在夙昔，赠我陆机赋。"]},{"t":"九子浴九首 孟行人望之 其九","f":"五言律诗","c":["孟生瑚琏器，英迈徵古篇。","登泰夙所期，望洋岂徒然。","钦趋瞠颜后，抗志耻卢先。","吾方把任钓，倘借襄阳蝙。"]},{"t":"赠姚员外二首 其一","f":"五言律诗","c":["高鸟厌群飞，孤云怕自辉。","绸缪诚靡垂，何必久要期。","倾盖有芳讯，白首则见疑。","崭崭龙沙滨，风波暂徘徊。"]},{"t":"赠姚员外二首 其二","f":"五言律诗","c":["零濛不泽物，冲风夕曾波。","送归念维楫，眇言望江河。","鸿逝摩九天，萧艾被泉阿。","长涛蚀孤屿，峙此将如何。"]},{"t":"别诸生汉口","f":"五言古诗","c":["大江流浩浩，五日与子期。","风潮变日暮，六日达汉湄。","人心重攸爱，酬德视其施。","伊兹匪不幸，所急非睽离。","晨飙望我帆，夕也宿共涯。","浮月每皓皓，逆云递逶迤。","情渊分有穷，怆子当分乖。","昔为同池萍，今向东西开。","大别峙嵬嵬，林蝉暮何哀。","俛首前逝波，倚舻各徘徊。"]},{"t":"赠张含二首 其一","f":"五言古诗","c":["巳严蓬池驾，遽返夷门歇。","商风动荣草，檐雨鸣不绝。","客病良易积，况值变华节。","悠悠城西馆，倏尔双经月。","昔玉体流汗，莎鸡傍户聒。","子也苟宁志，川广岂难越。"]},{"t":"赠张含二首 其二","f":"五言古诗","c":["流光逝忽忽，天地一何轧。","六月子来至，月也今巳八。","客子悲远道，时气侵肃杀。","岂不念尔单，室迩泥路滑。","三日两赓歌，一日一通札。","寂轩倚衰柳，柰此夕鸣蚻。","父母不下堂，归轸何时辖。"]},{"t":"送张含还金齿","f":"五言古诗","c":["百忧强自排，感之辄复积。","亦知别心苦，所柰欢爱客。","迢迢西南夷，叹子此行役。","出云怀旧山，倦鸟厉归翮。","时情苟靡遭，勉合亮奚益。","还道尚云远，去去加餐饭。"]},{"t":"酬提学陕西朱君以巡历诸什见寄","f":"五言古诗","c":["煌煌百二宅，怀里念前都。","孰无雍门哀，恨役久长途。","登赋时有望，所苦言辞粗。","自蒙新什惠，披玩忘晨晡。","疏越发潜响，烂若湍锦舒。","惭亦作者末，欲画安我愚。","浏浏回中吟，宛游秦陇隅。","清渭韵浟浟，南山笔巍如。","谁云篇目寡，已包千里馀。","读既摇我心，倘附西飞凫。"]},{"t":"酬秦子百泉之招人事羁滞颇兴延阻之叹五首 其一","f":"五言律诗","c":["暑阻虑难周，弦促调不缓。","风雩徒情叹，濯热为谁纂。","昨枉泉上期，结念在晨晚。","折花信延伫，欲往心莫展。"]},{"t":"酬秦子百泉之招人事羁滞颇兴延阻之叹五首 其二","f":"五言律诗","c":["心展会有时，迹乖难重期。","自我别林岑，倏焉周二期。","物灵赏不延，神往情讵移。","想像北池游，回桡骛南漪。"]},{"t":"酬秦子百泉之招人事羁滞颇兴延阻之叹五首 其三","f":"五言律诗","c":["南漪乱渚烟，北池美清涟。","芙蓉发锦苞，白石响涧泉。","虑澄美莫致，景入情更牵。","攀英迟来迹，倚壑怅周旋。"]},{"t":"酬秦子百泉之招人事羁滞颇兴延阻之叹五首 其四","f":"五言律诗","c":["周旋欢莫同，回策入云峰。","阳崖亘积雪，六月如严冬。","若人竟何乘，孤游邈难从。","倘遇仙潭鲤，露我蹑云踪。"]},{"t":"酬秦子百泉之招人事羁滞颇兴延阻之叹五首 其五","f":"五言律诗","c":["蹑踪诚靡寻，伫瞻劳我心。","高高望云霓，横绝天中岑。","游泉叹昔女，隔阻匪惟今。","投桃遣来使，倘惠琼华音。"]},{"t":"将赴南邑借丘长公巾车","f":"五言古诗","c":["北游情未敛，初吉复南骛。","积疴畏登涉，怛焉惮修路。","控衔力不任，执绥性有慕。","愿蹈高贤辙，惧枉邯郸步。","谅兹无憾心，庶慰车中顾。"]},{"t":"襄阳篇奉寄周知李公","f":"五言古诗","c":["晨登大梁城，南望襄阳郭。","汉流趋何急，樊山气参错。","树高风来集，道大惟淹泊。","投沙理虽迫，召贾恩非薄。","幸且便山郡，聊游谢羁缚。","仰攀蹑孤岫，俯眺聆大壑。","寒江敛夕霁，远岩映林薄。","习池宴山简，英寮敞翠幕。","偶同携葛强，飞翰凌觞酌。","归闻铜鞮唱，行和岘山作。","览迹验物理，触叹徒今昨。","沉忧亮无益，流坎任所托。"]},{"t":"寄题陇州阎氏林亭","f":"五言古诗","c":["出处信不易，卜筑岂在远。","闻君壮年日，颇此遂仰偃。","创基倚北阜，开窗面层巘。","杂树莽蓊蔚，长流激清浅。","迹异愿不隔，路阻日遂晚。","愉悦各殊趣，幽意不逮显。","春风翻深谷，袅袅葛叶展。","代耕与灌园，垂老付所遣。"]},{"t":"送张六还京口","f":"五言律诗","c":["云黄风色歇，送子逾修畛。","野风吹江树，波水清且紧。","归舟本自骛，兄值顺流稳。","金山会当聚，别暂情可忍。"]},{"t":"送裴生京师","f":"五言律诗","c":["大江积风雨，骄阴久我仇。","怀役念戈殳，潢潦忧中畴。","戚戚感物虑，况子行远游。","郁哉朝宗心，殷勤眺风洲。"]},{"t":"赠郑淳","f":"五言律诗","c":["路绵家室怨，久别谁柰著。","荏苒及春孟，冰消舟莫阻。","临觞叹河迈，指景趁前侣。","汀曲帆易隐，劳心望徒伫。"]},{"t":"赠李佥事衢","f":"五言古诗","c":["处世寡谐合，营道无贞心。","缅邈伯牙弦，叹息谁为音。","窃禄匪我志，随风岂能任。","所以弃朱绂，穷年卧空林。","君子枉荣顾，驷马一何骎。","轻盖荫白日，轩车匝庭阴。","宴晤及春期，列筵享同襟。","目快淑气草，耳聆悦时禽。","肴至弗徒归，觞举恨不深。","末路校通塞，鉴止无飞沉。","托意诚匪殊，在远固宜钦。","愿言附松萝，子其断坚金。"]},{"t":"将赴江西寄别殷伊阳明府","f":"五言古诗","c":["引年岂必老，求志不在奇。","曰余逾壮龄，遭斥还山栖。","事与北门合，迹拟东陵齐。","灭音谢人徒，四暑忽逮兹。","向平果遗荣，谢安终徇时。","讵意值嘉运，末照及葵藜。","简书下我庐，急遽谁得辞。","迢迢江西帆，别当首夏期。","束装逐流潮，改服团炎飔。","情郁为念故，寄重惭余卑。","虞弦改自调，孔铎湮谁持。","江汉诚暂浮，匡庐宁久羁。","返贞意巳坚，抒怀告心知。"]},{"t":"鸢山访汪氏因赠","f":"五言古诗","c":["昨余发弋邑，急霰舞鸣湍。","滩高果莫溯，改骑凌层山。","山层水复曲，岁晏岚风寒。","扪萝冒崄艰，踏冰涉洄沿。","日入达平夷，倏觌君子关。","清溪交远圳，高松夹路间。","遗荣靡所希，时仕义乃诠。","未美焚鱼高，颇钦奇字传。","矧伊连枝芬，慰我同心兰。","缪绸促宴斝，曙猿响南峦。"]},{"t":"冬日抚州赠友","f":"五言古诗","c":["晨光郁将布，时严气自懔。","阳也谅匪力，厥阴无亦甚。","时极理终固，情成势难寝。","徒然江汉纪，莫制北飙凛。","寒湍落孔家，霜色峻石廪。","甘菊冬始华，赤树纷如锦。","校阅才及旬，劳拙遗安枕。","既巳阻携玩，胡由接芳衽。","拟岘行共陟，寄言备醇饮。"]},{"t":"内弟玉园庄归","f":"五言古诗","c":["逾年始及村，日入复言归。","言归亦何为，景异情难持。","沙禽唳唳鸣，园林收暮霏。","暮霏转急湍，春草碧漫漫。","我行巳逾堤，我心念犹攒。","志往物不隔，室远讵无端。","诚乏静者虑，郊野岂徒安。"]},{"t":"内弟左国玉挽歌","f":"五言古诗","c":["滔滔水东逝，靡靡日西驰。","日驰虽更晨，水逝无还期。","清醑满华尊，鸣琴在旁兹。","门堂不改故，若人竟何之。","天枉独兼今，凝澄究若斯。","二纪罔自保，千秋宁讵知。","情恸道与结，感往志弥悲。","皇皇徂暑月，捐我就郊岐。","故筑即新坟，广路席前基。","狐兔夕向啼，芳麻延碧滋。","解铗心巳许，回辕痛岂欺。","永测游魂理，徒此眩盈亏。"]},{"t":"改营外舅大夫园域","f":"五言古诗","c":["贵贱无二死，贤愚同一丘。","明公昔谢世，迹骇理夷犹。","夷犹及兹年，墓木拱巳稠。","志决物可赞，运旋情更酬。","悽悽临圹穴，崩迫览阴幽。","昔为美丈夫，今与腐者俦。","枯骨蔓草缠，剑佩攒蚍蜉。","痛沉秪愈迷，神期竟何游。","名崇寿罔积，露陨蕙先秋。","芳尘满华屋，故马咆行辀。","改园仅逾阡，穿地即我谋。","方期枌槚成，庶纡生者忧。","为惟国士遇，因恸遂成讴。"]},{"t":"熊御史卓墓感述","f":"五言古诗","c":["幽幽山下江，峨峨山上松。","累累松下墓，瑟瑟松上风。","慨昔与君游，并游京华中。","峨冠省台内，鸣銮趋步同。","中更叹莫偕，永逝当何逢。","绝弦巳易惨，挂剑今谁从。","驾舟乱回洋，展墓临高崇。","浮云骇南流，顾望摧我衷。","德音既长巳，情感胡由通。","秪馀泣麟意，悲歌伤命穷。"]},{"t":"徐子墓","f":"五言古诗","c":["晨兴驾我车，行行造古墓。","墓门一何寥，踟蹰久延顾。","白阡修且直，青松夹中路。","借言葬者谁，汉时徐孺子。","麟出谅不偶，龙潜竟何以。","峨峨东都会，蔼蔼青云士。","一鸣争及时，迈迹歆先轨。","冠盖纷若云，车马阗京里。","鸣玉气自振，排闼情难已。","鸿钟有竞动，大策无停纪。","斯人独岑寂，哀叹劳心理。"]},{"t":"温太真墓","f":"五言古诗","c":["双鹅谶妖端，一马前休兆。","中原既板荡，臣主周奔峭。","长蛇恣吞噬，白日掩孤曜。","心违祖逖楫，事踬扶风啸。","康屯见斯人，辱巳存机要。","建侯竟谁功，江介无飞旐。","勋成身乃殂，天逝徒心悼。","侧惟盈缩理，虚咎燃犀照。","遗坟阚清千，古树寒新庙。","来阡莽回郁，弭节纷延眺。","载瞻徐墓迩，益壮风流绍。"]},{"t":"澹台灭明墓","f":"五言古诗","c":["子游昔宰邑，邑有澹台公。","非公不见宰，不径垂无穷。","身殁埋豫章，豫章乃城中。","长松何寥寥，石墓坚且崇。","崩馆昼常阴，古树多悲风。","丸丸拥基藤，垂垂网户虫。","喧寂本异感，慨惋当何同。","道伸固难灭，瞻睇摇晴虹。"]},{"t":"孺子墓夏谒","f":"五言律诗","c":["怀贤意实勤，展谒良巳屡。","丰茸蔓草盛，间关夏禽哺。","野蔹延竹户，丹华缀高树。","徘徊想故榻，留连果谁遇。"]},{"t":"孔庙松","f":"五言古诗","c":["夫子庙前松，童童一青盖。","盘拿若苍龙，借问自何代。","灵籁度笙竽，古色积烟黛。","峨然森翠中，郁彼风云会。","绝胜讲坛杏，应并阙里桧。"]},{"t":"犬诗二首 其一","f":"五言古诗","c":["惊夜力不赡，逐兔非所任。","吠花春院闭，戏草日移阴。","家贫称恋主，时乖坚始心。"]},{"t":"犬诗二首 其二","f":"五言古诗","c":["吠尨闻昔咏，走卢钦故名。","游园方载猃，重鋂宁自行。","发踪难可遇，沾草空含情。"]},{"t":"咏信州茗和郑子","f":"五言古诗","c":["厥草有佳种，灵味固无匹。","丰内谢华干，卑丛类谦抑。","阳和散林彩，修修吐英特。","濯影金屑泉，敷芬玉岩侧。","完馨重伊始，漙露浥其色。","采掇屈柔腕，制之成我德。","三缄附贡品，遂入君子食。","入鼎沸银浪，随风可倾国。","涤烦古有经，通仙讵堪惑。"]},{"t":"余怀百门山水尚矣颇有移家之志交春气熙忻焉独往述情遣抱四咏遂成示同好数子 其一","f":"五言古诗","c":["鲁连蹈东海，介子逃西山。","方舟信超越，岩径安可攀。","扬烈犹靡惩，置金徒嗟叹。","伊余秉拙讷，薄游及兹年。","急湍有奔桴，迫路无停辕。","惨惨沧流月，悽悽沙塞烟。","徒钦静者意，未遂同袍言。","偶耕慕庞公，石栖景焦先。","扪衷谅有持，顾巳竟谁谖。","复来感方寂，解作忧更牵。","抑心二十载，始别金门还。","积疴谢人徒，颇与疏遁便。","眷兹丘园荣，岂美场苗篇。"]},{"t":"余怀百门山水尚矣颇有移家之志交春气熙忻焉独往述情遣抱四咏遂成示同好数子 其二","f":"五言古诗","c":["浮海伤固穷，逾河叹诚迈。","濯缨万里流，高视九州外。","功成奔运徂，气至流飙代。","凄凄秋柯零，冉冉春条媚。","周览倦河坝，孤悰冀岩濑。","道以沉寂超，赏与崇深会。","岂惟超远情，亦因谢尘籁。","聿想山中人，风吹女萝带。","折麻凌险屼，采秀越森荟。","眷弥志终申，独往竟谁碍。","嵉嵉太行峰，峣峣百门对。","抗手别故欢，乘云美烟瀣。"]},{"t":"余怀百门山水尚矣颇有移家之志交春气熙忻焉独往述情遣抱四咏遂成示同好数子 其三","f":"五言古诗","c":["阅图访名奇，久钦苏门山。","危峰罗县牖，积石喷鸣泉。","情吟激卫女，嘉遁招古贤。","出游结梦想，神往理谁诠。","连岩既郁纡，回渚复绵芊。","猿吟曙霏豁，雁泊暝阴还。","杖策蹑丰茸，解裾濯潺湲。","仰视游云翮，俯察戏藻鲜。","览物慨幽杂，抚化怀宜筌。","况逢春华交，更此眺孤烟。","毕婚非达生，一啸复何言。"]},{"t":"余怀百门山水尚矣颇有移家之志交春气熙忻焉独往述情遣抱四咏遂成示同好数子 其四","f":"五言古诗","c":["山客戒明发，朋故来攀留。","岩潭窈叵测，险径增离忧。","曰余负幽僻，诵古歆远游。","陟怀康乐屐，浮羡鸱夷舟。","探讨倾子长，浪迹多阮侯。","若人不可作，瑶草竟何酬。","事往悲易深，情存道难侔。","以此激孤誺，喟焉睇沧洲。","安波有覆舻，坦路无全辀。","危虞在岂崄，薄劣终见尤。","愿附绿萝缘，永与栖者俦。"]},{"t":"自太过渡河趋陂沙冈","f":"五言古诗","c":["凌春远行迈，游目恣沿越。","渐辨林中曙，遽失霞上月。","触物谁为情，悲叹曷可歇。","载登隋疆场，况眺宋城阙。","阳坡散初柳，阴曲峙寒雪。","只此判气候，岂必殊燕粤。","湝湝浊河驶，畟畟晨风发。","扬帆截惊赣，倚棹望穷发。","凫雁眇难即，汀兰翠堪结。","美人既莫期，天路复幽绝。","陂冈郁参错，岸沙皓明灭。","日暮孤云与，何以慰忡惙。"]},{"t":"阳武咏怀陈平张苍遂及慱浪之事","f":"五言古诗","c":["玉玺戒不力，金镜沦无光。","大人既龙兴，烈夫亦鹰扬。","伊人各乘时，矫若孤云翔。","韩椎岂在屡，秦气日以丧。","六奇佐挥戈，五运开灵昌。","时来屠沽奋，迹往英雄伤。","平生冀风期，况乃逾故疆。","洒泪越修坰，含凄溯河梁。","古坟密嶕峣，春沙郁茫茫。","徒瞻松柏路，讵申椒蕙芳。","遗荣竟何尤，任智终自戕。","羡彼赤松游，援笔即此章。"]},{"t":"览游百泉乃遂登麓眺望二首 其一","f":"五言古诗","c":["束发怀幽奇，览籍冀有遇。","来登百门泉，果协佳胜趣。","毖毖圆波踊，蔼蔼浮阳聚。","止坎渟泓洌，激石迅湍注。","昔闻沧浪濯，今解川上喻。","岂惟伤卫歌，兼以发蒙虑。","况值春序中，群物巳改故。","菰蒲冒清深，鳞介各有慕。","行羡浴渚凫，静对栖云鹭。","岩霏空潭影，林蔼变朝暮。","极目北上帆，朝宗感游寓。"]},{"t":"览游百泉乃遂登麓眺望二首 其二","f":"五言古诗","c":["发鞍憩林木，杖策陟陉岘。","岩连岭参错，洲曲岸回转。","白日丽兰薄，原绿静如洗。","啸台既清峻，行窝更幽缅。","慨念昔时人，瞻望泪巳泫。","薜荔夕摇曳，萝径复谁践。","碑板半磨灭，石门积苔藓。","代异道岂隔，事迈迹空显。","独采石间秀，眷此何由展。","逝鹄无卑音，潜虬厌污浅。","旷哉古今意，难与世人辩。"]},{"t":"登大梁故城","f":"五言古诗","c":["登高与处卑，由来虑多端。","登高尚寡悰，处卑焉能欢。","以兹历荆榛，褰衣蹑巑岏。","土豪带阴风，楼橹危急湍。","岩岸苦崩奔，椴苇何漫漫。","周望鲜故物，俯察多忧叹。","潜鱼葺其鳞，惊鸟无停翰。","云浮诚不任，渊沉谅何难。","终附岩穴栖，斯地非我安。"]},{"t":"德安趋浔阳","f":"五言古诗","c":["始征晨风息，云流日色展。","登陆艰且涩，厉涧一何缅。","维时仲秋交，飒飒林飙卷。","绿竹垂我车，丹花映行幰。","冒峦维有松，绣石尽成藓。","攀搴虽多悦，亘顿乃劳倦。","日中迫庐岳，蹊径愈回蹇。","云涌连遥崿，雨暗失近巘。","奔崩万壑会，崄绝一径转。","遽讶川梁没，幸遇石濑浅。","道以习坎利，用待既济显。","介石谅益固，巨川岂遂眩。","谁哉能豫谋，随寓斯可遣。"]},{"t":"宿圆通寺","f":"五言古诗","c":["晓发蒲亭邑，暮投石耳峰。","仆夫困沾濡，山雨犹响松。","兹壑况罙阻，顾望惟溟濛。","幽岩托层房，豁然临猴江。","竹修苞北基，岩峭垂南窗。","俯观袅户萝，仰聆走檐淙。","挹此暂足遣，逖想情难降。","陶公有遗坟，黄子留孤踪。","通止良固殊，羁缚谁为悰。","坐闻吟猿瞑，秪念归思忡。"]},{"t":"钓台亭成","f":"五言古诗","c":["飒飒风涧泻，累累山石峻。","卜构倚岑削，檐楹阚奔迅。","俯之才一壑，仰面巳千仞。","歌游竟日夕，载色掖英俊。","故杉改新荫，鲂鲤况充牣。","本轻任公钓，讵慕庖丁刃。","素飙袅延蔓，商气敛芳润。","临深悟邃奥，睹逝识大顺。","却笑矜名子，美鱼一何吝。"]},{"t":"卧龙潭","f":"五言古诗","c":["出游青天涧，遂至卧龙潭。","重岑上无极，白日蔽寒岚。","巉峭讵能步，崄绝谁可探。","历石诚巍倨，扪壑惊谺谽。","我行值秋季，霜藟摇匡南。","午攀日忽夕，足倦情逾酣。","雷瀑响岩涧，孤花媚澄涵。","抚似悟命意，循迹想名庵。","庵废人踪绝，岩剥文半灭。","世异坦道塞，慨兹忍能说。"]},{"t":"白鹿洞遍览名迹","f":"五言古诗","c":["情高忽凌厉，步健轻巉缅。","葛弱亦须扪，崖滑每独践。","涉清爱重屡，探阻遗惊眩。","始兹陟五峰，遂憩松不巘。","岩桂纷始华，石耳翠可卷。","追想白鹿迹，伊人竟何遣。","触端绪自萦，薜荔况在眼。","慨叹意莫置，顾望日已晚。","夕湖浴岑峭，流光灭兰坂。","命酒写幽独，鸣琴且游衍。"]},{"t":"始至白鹿洞","f":"五言古诗","c":["旷哉超世志，缅邈平生思。","郁壹眷名迹，久注匡山陲。","南涉枉嘉命，果谐夙所期。","仲秋岩壑清，宫馆复在兹。","白石激寒湍，岩萝袅空基。","黯伤逝者往，密惭来者追。","性同道岂隔，途异理空悲。","兴言怀昔贤，日竟眺前岐。","榛荒徒郁纡，林崦一何罙。","感情匪哀叹，聊咏昭言垂。"]},{"t":"陟峤","f":"五言古诗","c":["伊昔谢衔归，志颇谐纶钓。","甘追河上迹，切慕蓬池啸。","孰知紫芝虑，竟荷青云耀。","值秋历江郡，弭节登庐峤。","沉深九叠秀，峻极千峰峭。","锦绣乱岑㟧，晨夕改观眺。","晶晶游气敛，皓皓寒日曜。","飞瀑信雷迈，奔峡还龙跳。","耽游遽忘归，久住轻时诮。","天池绝亦扪，石镜扳可照。","矧兹二三子，芬馥含清妙。","霜岚澄西夕，从歌效希调。"]},{"t":"庐山秋夕","f":"五言古诗","c":["山壑寒气早，日夕风色紧。","火流桂将歇，霜至蕙草陨。","蟋蟀集涧馆，禾委被疆畛。","物感忧自攒，排遣情讵忍。","年徂身与衰，时弃世所哂。","踌踷夜不寐，起坐万念轸。","崖倾月西流，嶂曙松犹隐。","噭噭露猿啼，行行采芳菌。"]},{"t":"落星石","f":"五言古诗","c":["千江势欲倒，蠡门支孤屿。","辉辉云崖映，汹汹湍濑注。","霜水落丈馀，石角露龃龉。","探奇犯崄涉，停旄挈贤侣。","搴裳入松寺，倚竹望风渚。","崩奔乱帆下，蔽曳波鸟举。","秋空澹明澄，浮山互吞吐。","灵根合道蕴，旷荡豁褊阻。","贞靡亚砥柱，险可并滟滪。","不闻永嘉胜，秪因谢公许。"]},{"t":"泛左蠡","f":"五言古诗","c":["辞山意不悦，水泛暂可乐。","徵风逗帆席，日竟展光耀。","扬歌荡溟昧，鼓枻极窈窕。","指顾异晨暮，俯仰改观眺。","出没湖中山，明灭海上峤。","素轻左蠡险，今觊石壁峭。","谢屐久巳芜，陶矶寂谁钓。","解吟松门咏，令人发悲啸。"]},{"t":"骑登谢址复舟观于石壁","f":"五言古诗","c":["奋鹄有奇翰，古铎无追响。","游云迹易灭，鸣世情难想。","昔吟瞻眺咏，今觌湖中赏。","松门既岑峙，川水深以广。","昏旦候自变，伊人竟焉往。","岩劓徒空嵌，堂基鞠为莽。","扉径不可识，悲愉异今曩。","石壁屹寒岸，葛崖啸魍魉。","揽驭意巳极，登舟秪弥惘。","抱兹久延伫，遵渚路回枉。"]},{"t":"南岩寺","f":"五言律诗","c":["岩高屯屋巨，谷邃至迹罕。","仰之讶天缺，登顿徒云满。","木零鹘巢露，松冷猿啸缓。","一滴聆不厌，五级袅可践。"]},{"t":"赴怀玉山作","f":"五言古诗","c":["始临清溪寺，不谓兹路艰。","崎岖踰南岭，转见山郁盘。","重阴起北谷，冻雨响前峦。","志定迈孰禦，勇往竟孤攀。","挽葛接悬狖，架木凌飞湍。","律律岩壑变，飒飒岚风寒。","隔港望绝岫，嵉嵉巳云端。"]},{"t":"至怀玉山会起书院","f":"五言古诗","c":["冒险登云峰，云涌风不卷。","凄凄松霰响，濡濡竹露泫。","沾涂意巳困，睹构色颇展。","故堂改颓制，新筑负幽巘。","代材但旁谷，砻石况非远。","清渠激修溜，巅亩旷以衍。","偶至若期遇，天定固良鲜。","仰止古有训，静成力可挽。","秪虞游业子，捷径为世莞。"]},{"t":"薛家楼宴","f":"五言古诗","c":["闲游北城隅，俯视清江郭。","洪川带名都，形势自相错。","楼观蔼郁郁，街巷纷以漠。","北城良巳高，况陟城上阁。","轻裳拂倒景，飞槛聆天乐。","夕山一何苍，夏潦弥井络。","冲风激回流，玄云骇难泊。","暗观逝者危，遂悟居者乐。","慷慨亮易感，扪心果谁恶。","夷险非我为，弹剑且尽酌。"]},{"t":"曲江亭阁","f":"五言古诗","c":["缆舟金华潭，遂陟冈上阁。","蹊径阻纡郁，岩水光参错。","夏林一何清，馀雨浙未落。","高览景自异，况值晚霁廓。","夕日明锦湍，归云拥华薄。","近山聿苍翠，远岭复岑崿。","旷荡感遇寓，俛仰叹今昨。","不见往者悲，秪觌来者乐。","顾瞻大江流，愈恨代谢速。","源涌竟谁禦，谦守谅能曲。","所贵遗荣名，睹义愿有勖。"]},{"t":"发丰城属江涨风便","f":"五言律诗","c":["午晴发丰邑，挂席溯修濑。","潮起果谐志，风助利击汰。","棹歌落日上，游目波峤外。","巨川信易涉，贞固乃宜戒。"]},{"t":"武阳抵进贤","f":"五言古诗","c":["大宇流玄化，生情互阴朗。","积霖夜犹注，寒阳朝遽上。","肃肃晦色敛，皛皛川水广。","枫林一何赤，沙屿鸿竞往。","涉河历纡郁，登岭暂停鞅。","抚江信萦带，钟陵气弘敞。","荆俗杂浇厚，徵赋则邦壤。","佩刀岂民性，剪戮叹幽枉。"]},{"t":"自南康往广信完卷述怀十首 其一","f":"五言古诗","c":["越旬不出门，所值疑初觏。","长湖迄华岳，融景递澄秀。","鼓枻聿行迈，览物每欣遘。","飘飘颐帆风，逶迟敛云昼。","鸣鹤矫丰田，文鱼驶闲溜。","有生孰靡适，时及异荣疚。","彼哉吾岂仇，乘运视所受。","履兹良巳快，乃馀足云究。"]},{"t":"自南康往广信完卷述怀十首 其二","f":"五言古诗","c":["迅风会高云，逝逝曷能巳。","朝耸冠剑驰，夕暮遭累系。","荣辱邈何因，嘅嘅昧成理。","湖程莽复阔，滩溜于春驶。","肃肃东骛帆，晨夜不得止。","仰睇啼柯猿，俛伤跃清鲤。","一言季布召，斥以一言毁。","从古谁靡然，寄语求全子。"]},{"t":"自南康往广信完卷述怀十首 其三","f":"五言古诗","c":["金阁简英儒，玉书托纪纲。","丝言一何谆，黜佞抡圭璋。","澄清有夙愫，揽辔诚慨慷。","聿兹历三始，矢志千载芳。","风波骇非意，多口乱否臧。","九阊眇以玄，欲扣六翮伤。","所司专爱憎，威刑丧厥常。","彼方耸轻盖，宁知嗟道傍。"]},{"t":"自南康往广信完卷述怀十首 其四","f":"五言古诗","c":["渊云谅殊性，予岂经世俦。","驰驱二十祀，学宦寡谐谋。","昔斥还三河，誓言永林丘。","靡坚今咎谁，畜志竟莫酬。","在难归贻阻，眇焉痗前修。","陟崇望波岭，翔云骇西流。","春羽振桑榆，念之心形仇。","东徂叹伊始，怀哉俾无尤。"]},{"t":"自南康往广信完卷述怀十首 其六","f":"五言古诗","c":["一气噫太虚，吹万良不同。","伊余就幽役，春序奄巳中。","芳辰下霜雹，寒暄乖故风。","北柯沮靡荣，南林曷由丰。","临门翳孤松，悠悠慨初终。","张仪相六廷，虞氏哭途穷。","首阳乏长薇，洛都鞍马雄。","天定俟何时，咏言摧深衷。"]},{"t":"自南康往广信完卷述怀十首 其七","f":"五言古诗","c":["云和易成霖，羲阳一何冥。","淹哉沮洳区，佳日闲我扃。","覆瓦仅蔽床，颓壁支数棂。","凄飙惊中帷，雹霰时复零。","天道有常乖，万殊谁竟宁。","子期久巳徂，纵陈孰为听。","当道有豺狼，琐言訾螟蛉。","习坎固终利，从兹效无形。"]},{"t":"自南康往广信完卷述怀十首 其八","f":"五言古诗","c":["静居百虑屏，孤树乃墙隅。","奄兹华叶更，搔首睇淹如。","时云布灵谷，天令震高衢。","霖潦灌百川，万壑寡安鱼。","东京构党祸，郭子逝于于。","伊匪四顾勤，孰崛南阳庐。","京燠非力排，裘葛从所须。","龙蛇翳厥身，孔赞宁我谀。"]},{"t":"自南康往广信完卷述怀十首 其九","f":"五言古诗","c":["赦者小人幸，臣诚小人侪。","匪图轩盖荣，山海有奇怀。","礼法无复拘，评者靡我排。","思夙慕华贵，振鞅登要逵。","烜赫岂不快，寤寐忧所乖。","识几既不早，今恋非鄙哉。","乘桴越洋涛，采兰及春滋。","于焉可佳容，庞叟心所期。"]},{"t":"自南康往广信完卷述怀十首 其十","f":"五言古诗","c":["一夕复一辰，倏忽春务易。","云叶布丰林，蚯蚓盘我壁。","田窦仇片言，厥怒一何赫。","笑谑有白刃，千载乃露迹。","倦兹掩陈记，出户睇高翮。","积讟聆民谣，欲采不可译。","英骖振飞靷，出入势煇奕。","哀哉彼何子，踌踷秪沾臆。"]},{"t":"广狱成还南昌候子十首 其一","f":"五言古诗","c":["一淹经六旬，扬舲复焉极。","脱然虽靡由，事事嘉可即。","依依春功奏，朗朗维夏逼。","故兹波与岭，触目异前昔。","逸云散归雨，川水浩崩溢。","挂帆趁风溜，览岸凑悲怿。","昨犹罝中兔，今为颃林翼。","邈言念先古，展矣我心获。"]},{"t":"广狱成还南昌候子十首 其二","f":"五言古诗","c":["直木防见伐，兹言岂我欺。","若华耀四海，孤邈畴见知。","庄鹍运池溟，举翼九天垂。","风积苟不厚，中路将安期。","叹息竟何语，俛视川波驰。","溢霖骛洪涛，千载固厥时。","燕石一何珍，有骥不自持。","野飙激灵襟，逝言惋长岐。"]},{"t":"广狱成还南昌候子十首 其三","f":"五言古诗","c":["时至鲜枯林，朱兰被长坂。","临峤觌贤迹，停楫暂游衍。","灵雨吐葛花，桕叶巳复展。","佳哉溪上邑，流峙亘而缅。","岑岑徐岩秀，飞泉洒丹巘。","岩亭交景风，裾带时自卷。","居高乃虑孤，涉历悟攸遣。","枚枚三陆宫，千秋竟兹显。"]},{"t":"广狱成还南昌候子十首 其四","f":"五言古诗","c":["馀于滨臣湖，厥土旷以浮。","津驿暮何嚣，避之泊南丘。","遣子省其母，析棹诣江州。","明星波洄洄，欲发仍复留。","有端肇丝微，涓涓遂成流。","拊心实罔惭，患来谁诚谋。","纷纶及今兹，事巳遥尚忧。","志士常苦贫，饥渴无我尤。"]},{"t":"广狱成还南昌候子十首 其五","f":"五言古诗","c":["昔游东山日，览古肇新宫。","徐令实经营，弦诵溢其中。","阅兹奄三年，离滞心莫同。","我舟非不维，柰此西逝风。","乃子胡德余，于迈远从公。","朝旦发龙津，暮栖依瑞洪。","湖山没如拳，波途浩难穷。","伫瞻有深怀，贻谣勤坚崇。"]},{"t":"广狱成还南昌候子十首 其六","f":"五言古诗","c":["夕栖瑞洪渚，遥览渚北山。","相传洪崖子，乘云自此间。","履迹今尚存，其人邈莫攀。","粤余登征途，频年涉间关。","毁誉一婴心，寤言多所叹。","于兹诚踟蹰，振衣蹑前峦。","浲水莽浩浩，惊风荡回川。","欲济惜无梁，飙轮傥中还。"]},{"t":"广狱成还南昌候子十首 其七","f":"五言古诗","c":["登舻倏五日，览接渐增阔。","汹汹北汪川，浏浏得纵壑。","剧哉风水虑，履顺故靡豁。","高鸟厌尘集，智士贵处末。","交甫怀汉滨，婉变情遽夺。","结驷匪不侈，险至谁竟遏。","沉身厥亦罕，万世惜不脱。","遥遥哀云岑，瑶草烂孰掇。"]},{"t":"广狱成还南昌候子十首 其八","f":"五言古诗","c":["明晦每无常，人道岂不然。","归云徂靡馀，日华耀清涟。","戚愉繄为谁，喟然想千年。","姑苏宠宰嚭，越孤辞会山。","梅将辅番君，范子逝不还。","乖岁君子贫，枉寻矜大贤。","时霖润万物，莸蕙乃同妍。","东门可栖迟，归欤聿奚言。"]},{"t":"广狱成还南昌候子十首 其九","f":"五言古诗","c":["阳鸟逝无馀，觏者鹙与凫。","青青泽溆毛，刈之粪谁畬。","经过问当年，云兹夙属吴。","归命丧厥仪，长云奄西徂。","抚床竟空言，金陵乃以都。","桓侯威八州，温氏阐雄图。","聆言怆我衷，徬徨感终初。","混一今其时，舟聘非尔虞。"]},{"t":"广狱成还南昌候子十首 其十","f":"五言古诗","c":["仲冬别豫章，涉夏兹复临。","凉燠殊厥时，能不摧我襟。","楼观蔽泰清，众木凄以阴。","倚挠陟龙沙，优游眺洪深。","鱼鳖溃惊流，澜骇遂至今。","中有夙纵凫，振翼回哀今。","波阻杳莫即，驰景忽西沉。","抗手自兹辞，万世怀飘音。"]},{"t":"袷祭颂述","f":"五言古诗","c":["呜呼大圣人，肇迹或渔樵。","苍龙戢其角，志固无丹霄。","德祖始侧微，浚叶开皇朝。","礼盖视后稷，面南统群昭。","大哉九庙仪，亲尽敢不祧。","再迁及皇熙，世室閟以寥。","袷辰复来集，凤凰鸣箫韶。","惟皇率百辟，孔祀自今朝。","白日照实旂，御气如绛绡。","将将磬筦鸣，飒飒灵旗飘。","恍惚帝醉饱，诸王亦飘飘。","下有开国勋，偃蹇罗金貂。","愚臣叨对越，精魄为之摇。","鼓钟送群公，玉户风萧萧。","唐侯昔践位，十八号神尧。","皇实秉敦默，龙性无逍遥。","道合天人际，志与神明超。","降祉倘冥漠，四海无征徭。"]},{"t":"清庙篇","f":"古风","c":["岩廊肃文钦，芳区恣幽骋。","宽纠岂异性，拘旷本殊摬。","嵚岑路寝东，森疏嘉树静。","珍丛媚朱夏，秀干扬修景。","曳琚群彦集，拄笏万虑屏。","仰望南城苑，飞除带崇岭。","?峞白玉阁，要眇黄金井。","季主饰观眺，哲王摈游幸。","自非渊圣姿，谁保天步永。"]},{"t":"丙寅元日朝退有作","f":"五言古诗","c":["赫赫大明朝，皇皇启八叶。","谅闇在冲龄，忧勤缵洪业。","真心改革殊，屡睹祯祥协。","春王肇元载，万国咸臣妾。","端冕御兹辰，缥缈仙云接。","神飙翊紫盖，翔龙舞浩劫。","哲后畏天威，惕若春冰涉。","古编昭日星，有躅尚可蹑。","大哉五始义，允矣三阳浃。"]},{"t":"从军四首 其一","f":"五言古诗","c":["汉虏互胜负，边塞无休兵。","壮丁战尽死，次选中男行。","白日隐碛戍，胡沙惨不惊。","交加白骨堆，年年青草生。","开疆整未已，召募何多名。","萧萧千里烟，狼虎莽纵横。","哀哉良家子，行者常吞声。"]},{"t":"从军四首 其二","f":"五言古诗","c":["从军日巳远，备兹途路艰。","驱车太行道，北度雁门关。","天寒雨雪冻，指堕曾冰间。","登高望虏境，白沙浩漫漫。","单于数百骑，飘飒猎西山。","彀我乌玉弓，赫然热肺肝。","安得奋长剑，一系名王还。"]},{"t":"从军四首 其三","f":"五言古诗","c":["别家亦云久，昨得家中书。","书中何所云，父母与妻孥。","昔来柳依依，素雪今载涂。","岂不念还归，天子西击胡。","登山眺故乡，存没两呜呼。","丈夫死国雠，安能恋里闾。","生当取封侯，怨别秪区区。"]},{"t":"从军四首 其四","f":"五言古诗","c":["久处行伍间，渐知苦乐情。","能蟠丈八鎗，徒御不我轻。","府帖昨夜下，烧荒有我名。","秣马待天曙，肃肃寒霜零。","左鞬插雕羽，雄剑跃且鸣。","日高渡黄河，东过受降城。","所羡在灭胡，富贵何足荣。"]},{"t":"屯田二首 其一","f":"五言古诗","c":["叶落归故根，孤云有时还。","凶年闾里尽，谁门今幸全。","全者自何归，皮肤半不完。","百租丛其身，欲诉谁见怜。","吾家十八军，独我犹从战。","昨当战交河，左髀贯双箭。","本不识犁锄，况复千亩租。","三诉吏不语，锁颈投囹圄。"]},{"t":"屯田二首 其二","f":"五言古诗","c":["日落苍天昏，奔驰吏下屯。","扬言科打使，论丁不论门。","老军出听卯，老妇吞声言。","边城寡机杼，耕种育儿孙。","诛求馀粒尽，竭力豢孤豚。","昨当总管来，宰剥充盘餐。","言既复长号，吏去收他村。"]},{"t":"塞上杂诗二首 其一","f":"五言古诗","c":["边烽日夜至，飞符来会兵。","羊牛入高砦，鸡犬皆震惊。","壮士按剑起，鞍马若流星。","鎗急万人靡，笑上受降城。","生系五单于，归来献天庭。"]},{"t":"塞上杂诗二首 其二","f":"五言律诗","c":["胡儿追野马，迸蹄若惊鸿。","一马带双箭，堕我边壕中。","敢望不敢近，踟蹰各按弓。","抽身复北去，天寒沙碛风。"]},{"t":"翠华岩","f":"五言古诗","c":["洞劓耶律词，其名翠华岩。","俯视耸观阁，仰面攒松杉。","厥维何王代，鬼斧开崭碞。","精气久削薄，烟岚郁相欃。","屡憩验足薾，独往悲情凡。","入萝畏石坠，转峤惊日衔。","飘飘万里风，吹我秋衣衫。","放迹慕康乐，入道怀贺监。","载思武陵避，愈怅桃花岩。","去住亦由人，极目江上帆。"]},{"t":"望湖亭","f":"五言古诗","c":["来登望湖亭，始尽览历妙。","布席倚岩嵌，波望领佳要。","山花落天镜，钩帘巨鱼跳。","岩潭递隐见，圆浪浴奔峭。","屼嵂百万阁，日落展光耀。","羁缚阻延放，临渊羡孤钓。","霜寒椴菼白，沙晚鸹鸧叫。","吾非阮生伦，于此亦长啸。"]},{"t":"吕公洞","f":"五言古诗","c":["厓根豁一门，怪石相撑拄。","谽谺自吞呷，白昼亦风雨。","阴处汎清泉，积苔荫链乳。","往闻茅山胜，风慕华阳主。","路遐限孤往，倏历十寒暑。","经亘骋心目，小憩偕道侣。","兹洞虽人境，固足托茅宇。","惕然忽内咎，我何恋簪组。"]},{"t":"香山寺","f":"五言古诗","c":["万山突而止，两崖南北抱。","凿翠置殿榭，级石上穹昊。","高卑各称妙，曲尽结构巧。","有泉如线缕，盘转出松杪。","嗜奇忘登顿，缘危肆探讨。","险绝逼牛斗，萧飒若风岛。","夜宿来青轩，天色碧可扫。","湖沙静莽莽，海月白皓皓。","想当邦邑初，此地只蒿草。","绮丽仡谁凿，岩壑澜相袅。","但看全盛时，民力为兹槁。"]},{"t":"平坡寺","f":"五言古诗","c":["西山万佛宇，烂若舒锦锈。","平坡凭风迥，突出众山右。","宫阁因岩坳，面势巧相就。","百里见琉璃，截嵲戴云构。","朋游探绝迹，杪秋历群岫。","得此目力展，恍疑出氛囿。","仰看北斗逼，俯恐东海溜。","雄压香山丽，阔掩望湖秀。","落木响岩牖，寒岚染衣袖。","延缅古今拜，伫立悲慨凑。","盛叶虑反始，危基有倾仆。","千载谁复临，逆想蓬蒿茂。"]},{"t":"天宁寺观塔碑","f":"五言古诗","c":["旧瞻天宁塔，今览天宁寺。","兹塔多鬼怪，光芒夜夜至。","不知何时殿，结构今颓弃。","剔藓读其碑，识是隋文字。","蝌蚪半剥落，蛟龙犹奰屃。","我来值时暮，揽逝发潜喟。","修陆控赵代，长山卫燕冀。","苍然野眺合，一洒杨朱泪。"]},{"t":"镜光阁","f":"五言古诗","c":["我生走纷境，性意苦不适。","朅来镜光游，不觉袛树夕。","鸟藏丹阁暮，萧槭杮叶赤。","杳如造岩壑，阒其寡人迹。","其王戴金冠，天子之所客。","迓我薝卜下，坐我红罽席。","落日入虚牖，窈窕云光白。","团团石莲灯，照耀锦绣壁。","忽闻铃磬发，转怅俗务迫。","静躁本殊科，利义各有癖。","伊余竟何为，奔并阻行役。","乞君摩尼珠，一照幸不惜。"]},{"t":"娲皇墓诗送乔太常","f":"五言古诗","c":["伊闻女希氏，奋迹鸿荒日。","神功羲农并，吹簧豁阴郁。","鳌极本寓言，蛇身竟恍惚。","遗墓赵城侧，古庙松杉密。","霍岭峙巑岏，汾川眇荡潏。","穆穆秉德臣，肃肃拳瞻谒。","祈灵溯遐躅，明禋备精物。","天虽积清气，运久恐漏阙。","徒炼五色石，寥廓讵能越。","送子顾周道，俾我心于邑。"]},{"t":"三忠祠","f":"五言古诗","c":["忆昔汉诸葛，龙起荅三顾。","志决竟星陨，呕血为军务。","鄂国与信国，屹屹两王柱。","杀身不救国，冤愤水东注。","往事勤钟鼎，新庙傍官路。","惨惨冠剑并，凛凛生魂聚。","翠旗晚明灭，往往鬼神驻。","怀叹各不申，翻然向烟雾。","我征久奔迫，过此感伤屡。","时来展肃谒，系马门前树。","香台野蔹上，罗幔虫蚁蛀。","烈士为吞声，清风激顽懦。"]},{"t":"艮岳","f":"古风","c":["城北三土丘，揭?对堤口。","黄芦莽瑟瑟，疾风鸣衰柳。","云是宋家岳，豪盛今颓朽。","我闻帝王富，东京实罕有。","凿池通嵌窦，移山媚户牖。","岌嶪楼观合，欻吸风雷走。","岩阴翡翠吟，海窟蛟鼍吼。","燕赵矜丽人，搜剔充妃后。","君臣互沉湎，斯道讵能久。","鸣呼花石费，铢锱尽官取。","北风卷黄屋，此地竟谁守。","迢迢五国城，二龙回其首。","向使任忠良，邦国得灭否。","余来值寒暮，悲歌坐林数。","狐狸窜古垒，破瓦没藜莠。","孤城峙我前，苍苍日将西。"]},{"t":"天马","f":"五言古诗","c":["天马从西来，汗血何历历。","天子顾之笑，置在黄金枥。","呜呼神骏骨，草豆日萧瑟。","瘦骼突硉兀，衔辔挂在壁。","白日涕至地，青云志抛掷。","朝望竭石津，夕盻流沙碛。","犹能肆横行，倘君赐鞭策。"]},{"t":"古意","f":"五言古诗","c":["有鸟何方来，哀鸣向西北。","我欲缚此鸟，天路险且棘。","悠悠浮云行，照我暮颜色。","丈夫重几微，男儿死邦国。","长鲸一奔逃，万网不可得。","平生反掌志，对此空叹息。","亭亭特生杜，道傍皖其实。","孤桐虽良材，弃掷处遐域。","而余竟焉往，呜呼泪沾臆。"]},{"t":"遣兴二首 其一","f":"五言古诗","c":["余陵固丽地，幽蓟亦名城。","皇天作南邦，北斗开瑶京。","万国梯航入，宫殿造泰清。","大哉帝王居，海岳自环萦。","禹功肇胼胝，汤也勤四征。","煌煌肯构训，圣人垂其情。"]},{"t":"遣兴二首 其二","f":"五言古诗","c":["四海为我土，九夷尽来王。","贡琛至北户，北至玄谷阳。","我祖秉天钺，血战开其疆。","当时受命佐，一一皆忠良。","喷薄倚日月，万古瞻腾翔。","乘运虽有时，盛业当自强。"]},{"t":"岁暮","f":"五言古诗","c":["轩坐意悄悄，感此岁年暮。","一气有肃杀，昊天纵霜露。","衰容摇万物，日月立复度。","赤骥初长成，自谓中君御。","扬鞭过都市，万马不敢步。","天寒草萧瑟，侧塞在中路。","良辰不再至，我发忽巳素。","不见古贤达，尽被名所误。","沉吟惜蟋蟀，延伫羡鸥鹭。","终然托远适，馀者岂足顾。"]},{"t":"苦热","f":"五言古诗","c":["伏阴固当奋，亢阳乃逾缅。","嘈嘈蟪蛄鸣，树杪风不展。","上天收雷雨，万物沮沾洗。","推案忽大叫，蓐驭何时返。","赤日厚地裂，挥汗无晨晚。","古时有虞舜，弹琴理骄蹇。","轩辕制六律，四序无乖舛。","何当挽二圣，吾欲遂仰偃。"]},{"t":"十五夜","f":"五言古诗","c":["夜陈芳宴会，座有离群友。","中秋而无月，何以慰尊酒。","宾主惨不乐，周席尽回首。","向黑明镫入，云景烂虚牖。","尚觊光破满，时问阴薄厚。","吁哉至精物，汝亦蒙此垢。","上天悲隔远，人生怨分手。","月既有开塞，吾宁息奔走。","霜露栖蔓草，疾风下高柳。","劝君聊尽觞，居诸亦何有。"]},{"t":"十六夜","f":"五言古诗","c":["四海蒸为云，三夜皆天风。","他方纵有月，不照长安中。","长安十二楼，户牖凿玲珑。","贵家金张徒，高宴开帡幪。","华烛代明月，何必光遂通。","夕露久巳晞，欢娱良未终。","迫塞谅有殊，盛衰宁见同。","悠扬云中魄，既满还自穷。","鬼神恶盈踰，天道怀其公。"]},{"t":"十七夜","f":"五言古诗","c":["幽意竟不惬，待月坐沙际。","久阴固当豁，明月忽堕地。","桂枝没半轮，蟾兔职业废。","姮娥饰粉妆，愁绝云楼閟。","鸾忧不解舞，竟夕掩孤袂。","崔嵬黄金阙，何由诉天帝。","景破力不敌，光满云仍蔽。","徬徨步林樾，为尔一流涕。"]},{"t":"小至","f":"五言古诗","c":["日为众阳宗，来往成谢代。","来之生万物，往以告成岁。","亭亭羲和驾，建此南飞旆。","双龙服偃蹇，流云翼其外。","和风卷冻雾，重阴飒无赖。","枢知化工斡，冥与天意会。","大君肃嘉礼，君子幸亨迈。","谁能助新阳，为我激灵籁。"]},{"t":"赠徐子","f":"五言古诗","c":["偃王世芜没，石麟亦埋翳。","徐子发东吴，英论有馀地。","龙游沧波阻，日出浮云蔽。","呜呼献王士，竟洒荆山涕。","光掩明珠弃，宠奋西施废。","古来共如此，不独君遭际。","余本澹荡人，倾盖托末契。","酣歌继日暮，醉酒无阴霁。","各为征蓬散，吾岂匏瓜系。","旧时南阳宅，回首成迢递。","蹈海有夙期，与子自兹逝。"]},{"t":"七夕遇秦子咏赠","f":"五言古诗","c":["皎皎河汉月，照我西南楼。","七夕远宾集，置酒城东陬。","展席对双星，盈盈隔中流。","艳艳睹妆女，欲济无方舟。","神爽即易合，茫昧竟难求。","明明君子德，寡妁谁为仇。","岂无采唐约，失身良见尤。","人生信龃龉，世事良悠悠。","不见古时人，皓首犹公侯。","葵藿不饿死，富贵安可谋。","愿絷场下驹，尽我盘中羞。","我今为秦声，子也当吴讴。","酣歌达清曙，临分赠吴钩。"]},{"t":"赠王御史","f":"五言古诗","c":["夕寒风自起，集雪耀中宇。","朗月一何速，早巳烂芳醑。","邂逅我兰友，设尊款清语。","连翩忽竟夜，悲叹为故侣。","瑶华虽莫折，羽觞时复举。","念昔青年日，共矫凌风羽。","啄食九天步，宿必华池渚。","中路更险艰，风波各失所。","大明荡妖氛，回光荫衰腐。","诸贤既连茹，王子岂羁沮。","馀生实自庆，追念良巳苦。","搣促广陵散，怆恻山阳旅。","事谐终合并，感往徒心楚。","弃置且安寓，欢娱弄尊俎。"]},{"t":"酬伊阳殷明府追忆见寄","f":"五言古诗","c":["弱龄负奇节，志欲凌海岳。","白马金陵来，游戏宛与洛。","出从七贵饮，醉调五侯谑。","妍华不见售，谗巧思爱夺。","凉风卷团扇，世路随飞藿。","谪居宰山邑，颇喜占名郭。","川岭郁森秀，烟云日喷薄。","况当素秋霁，清霜扫天末。","龙门既疏峻，伊水复澄豁。","启牖眺飞泉，据案望岑崿。","独抚岩中琴，遥枉汴上作。","怀贤谅在兹，感旧但如昨。","徒然伫王凫，未果偕缑鹤。","终期谢纷坱，携手向嵩岳。"]},{"t":"殷明府期嵩少诸山不果","f":"五言古诗","c":["旅寓限崩迫，骚屑隘烦务。","向来嵩少约，屈指谓旦暮。","岂惟攀时彦，兼欲展秋步。","仆夫戒衣粮，车马亦充数。","胡然泥行迈，遂此叹乖遌。","峨峨云中峰，阻尔独何故。","伫瞻风峤突，侧耳右泉注。","夜来逍遥梦，忽落嵩山树。","累垂松猿噭，澹沲岩姿露。","存巳超彷佛，醒若涉颠遽。","彼美眇何许，兹端怆难屡。","采蕙忌及晚，我疾畏晨露。","烟萝四时佳，春服易为具。","河阳群葩发，振策冀有遇。"]},{"t":"酬秦子以曩与杭子并舟别诗见示余览词悲离怆然婴心匪惟人事乖迕信手二十二韵无论工拙并寄杭子","f":"五言古诗","c":["忆年二十馀，走马向燕甸。","缙绅不识忧，朝野会清晏。","嗜酒见天真，愤事独扼腕。","出追杭秦徒，婉娩美柔翰。","探讨常夜分，得意忘昏旦。","雪雨亦扣门，仆马颇咨惋。","葳蕤香山阁，崷崒蓬莱殿。","登频穷日力，延揽侔壮观。","孔翠不易驯，人生本无泮。","萧萧田中蓬，随风各分散。","杭生比适越，秦子游瀍涧。","南北两文星，光芒亘霄汉。","余衰更乖谬，挂一每漏万。","夙遭青门斥，差胜黄州窜。","偃息于沙泽，游遨傍河岸。","秦也虽共区，累月不一见。","秦实困劳冗，余亦怕梳盥。","何况阻疆域，杭也江之畔。","怦怦睽隔积，郁郁岁年换。","无计脱烦促，转坐迫滋蔓。","再读并舟篇，愈切山阳叹。","诵言各钦德，悲离古所患。"]},{"t":"暮春逢林子邂逅殊邦念旧写怀辄尽本韵","f":"五言古诗","c":["赤骥奋途路，神龙厌池沼。","不登泰山顶，岂见众山小。","明公昔际遇，志与青云杳。","烂承夕扉诏，番苦司隶扰。","君乎实愤切，轩然争臣表。","朝野凛生气，树鲜安巢鸟。","名孤众毁集，窜薄忧心悄。","一投海滨郡，遂守荒江眇。","辽辽岭南国，借尔揭文旐。","中天行日月，戛戛孤鹓矫。","君虽关仕产，迹自闽中肇。","叶从考亭入，统为横渠绍。","伊余放旷人，渔潜侣荷蓧。","亡羊以多岐，望洋徒浩溔。","暌离历十暑，邂逅植春杪。","日谈恨易夕，夜坐忽及晓。","苑花虽寂寂，风絮尚袅袅。","回首通州别，屈指日不少。","今看两白发，谁忍置清醥。","君行秉大轴，吾歌入幽渺。","林岑有夙愉，烟萝阒袅袅。","诚无王良顾，空山没騕袅。"]},{"t":"安南歌送许给事中天锡","f":"五言古诗","c":["芳阡藉文毂，垂杨绾鸣珂。","使君且勿发，听我安南歌。","安南古夷隩，岭屿蔚陂坨。","炎原吼象兕，溟窟豗鼋鼍。","爰自秦汉降，憯怛寻干戈。","天皇操化枢，环海无惊波。","永执臣妾礼，稽首心靡他。","珠犀走北陆，翡翠供虞罗。","王臣乘匹骊，駊騀金盘陀。","朝济白藤江，暮涉富良河。","白日破蛮雾，铜柱孤嵯峨。","雕题睹汉仪，芭舞何傞傞。","皇仨罄所宣，纡征采民哦。","使君聆我词，慷慨不顾家。","仆夫杖明钺，绛节拂林华。","楼船下烟溆，鼓吹达海涯。"]},{"t":"田居左生楷二李见过二首 其二","f":"五言古诗","c":["去官今七暑，渐与农务亲。","随宜谙土性，言话群野人。","时或溯微风，行歌响空榛。","先民邈何攀，慨焉伤我辰。","慨伤遹谁知，所有二三宾。","文论日往来，炯炯高义伸。","炎雨回众姿，凉飙起修畛。","兀然林木下，日入忘归轮。","玄蝉夕益聒，去鸟一何频。","野行畏多露，无使侵衣巾。"]},{"t":"城南别叶夏集二首 其一","f":"五言古诗","c":["田居本自娱，况兼林水情。","聿兹暑衣晨，而与佳士并。","挈榼溯芊绵，临隑弄深情。","娟娟浴沙鹭，交交鸣枝莺。","虽非岩潭区，閒旷足我营。","菰蒲袅寒阴，陨果时自惊。","有空矧伊迩，遐哉谢尘萦。"]},{"t":"城南别叶夏集二首 其二","f":"五言古诗","c":["荷锄侈高咏，濯缨肆佳吟。","畴知稼穑场，乃尔蒹葭侵。","步风逾曾堤，徙筵趁重阴。","于情既有托，瞩寓良自深。","逶迤波上云，征征草间禽。","峭台信巳古，巍城方肇今。","验物果足遣，杯乾聊复斟。"]},{"t":"庆都篇","f":"五言律诗","c":["于昭开帝则，荡荡协钦文。","高辛初缵服，大舜复升闻。","瞻依太古日，怅望春空云。","缓策遵墟里，翱翔咏放勋。"]},{"t":"帝乙 其一","f":"五言律诗","c":["帝乙归元岁，沩汭降高秋。","白雾凌苍璧，文烟结綵楼。","枫陌三公引，云衢六马游。","行当瞻月驭，伫想咏河洲。"]},{"t":"帝乙 黄衢二首 其二","f":"五言律诗","c":["黄衢会日月，紫气悬阴阳。","冉冉神龙下，英英朱凤翔。","兰烟凝玉阁，桂月满金堂。","礼元歆九庙，德巳合无疆。"]},{"t":"帝乙 其三","f":"五言律诗","c":["桂宫新降驭，蚕室烂生氛。","曳绨成汉业，采葛相周文。","会奉重轮日，先胆五色云。","秋明天路夕，瑞雨碧氤氲。"]},{"t":"十二月朔","f":"五言古诗","c":["积阴凌紫极，玄雾暗三辰。","黄龙游帝畤，万乘若浮云。","六虬何蚴蟉，杂沓走天神。","明王熙庶载，至敬达郊禋。","玉辇亲牛豕，重瞳注鹿群。","精诚先百物，咸德届牺人。","扬銮回御道，九宇冀阳春。"]},{"t":"夏歌","f":"五言律诗","c":["积潦溢广泽，炎云翳崇台。","玉阶履綦绝，紫殿生莓苔。","萤流疏竹静，风动绤帏开。","佳期怅千里，竟夕以徘徊。"]},{"t":"湘妃怨","f":"五言律诗","c":["采兰湘北沚，搴木澧南浔。","渌水含瑶彩，微风托玉音。","云起苍梧夕，日落洞庭阴。","不知篁竹苦，惟见泪斑深。"]},{"t":"春曲","f":"五言律诗","c":["萋萋百尺台，南临大道开。","月明珠箔捲，尘暗宝车来。","豪雄五都侠，意气万人摧。","带醉穿林径，垂鞭拂阁梅。"]},{"t":"结客少年场行","f":"五言律诗","c":["灯如列宿行，月似九秋霜。","番番七贵儿，灿灿五侯郎。","杂沓凌香陌，徘徊竞夕光。","各携万金剑，结客少年场。"]},{"t":"侠客行","f":"五言律诗","c":["幽并豪侠地，燕赵称悲歌。","千金市骏马，万里向交河。","公卿赠宝剑，君王赐玉戈。","捐躯赴国难，常令海不波。"]},{"t":"从军行","f":"五言古诗","c":["弃家从上将，报主扫胡戎。","弩满常随月，旗翻数起风。","右指昆邪尽，左盻月支空。","驰名紫塞外，开府玉关东。","不逢百战日，谁识万夫雄。"]},{"t":"出塞曲","f":"五言古诗","c":["单于寇边城，汉将列长营。","旌旗蔽山谷，钲鼓昼夜鸣。","乘我浮云骑，彀我明月弓。","奇兵左右出，长驱向云中。","彭彭阵结虎，飒飒剑浮虹。","一战皋兰灭，再战沙漠空。","归来献天子，长揖不言功。"]},{"t":"铜雀伎","f":"五言律诗","c":["帷飘雀台上，弦奏舞衣前。","群悲一以望，春草为谁妍。","芳岁销兰怨，流尘集锦筵。","为问西陵道，孰与汉家阡。"]},{"t":"漳津夕眺","f":"五言古诗","c":["扬舲乱北渚，靡盖望西陵。","帐殿牛羊下，歌台麋鹿升。","日夕松柏路，萧萧响风树。","连沙改故浦，空山没苍茂。","徘徊望霸气，邺城在何处。"]},{"t":"吕仙祠","f":"五言古诗","c":["孤游逢吕迹，永逝感卢生。","眷彼炊梁术，契我遗世情。","苍山故国道，落日邯郸城。","阴阴祠宇夕，宛宛曲池清。","不见金芝侣，谁闻朱凤声。","田鼯穴桂壁，野葛蔓松楹。","宁知往来者，不是寐中行。"]},{"t":"三月河上宴集","f":"五言古诗","c":["触霁迈芳坰，修韨临长洎。","虽非曲觞饮，聊异秉蕳戏。","波延拾翠舸，岸匝寻青骑。","羽爵恋驰景，鸾箫剧春思。","群谣狎凫雁，抚适欢同志。","亦以扩凡超，流连岂吾事。"]},{"t":"咏乐溪","f":"五言古诗","c":["濯足荒溪口，延望大江浔。","石树环碧綵，泉潭生翠阴。","经亘涉清涟，沿洄登素岑。","日暮樵响绝，但闻山水音。","鸿雁遵渚飞，麋鹿聚空林。","而子岂不乐，其如兼善心。"]},{"t":"赠刘主事元瑞二首 其一","f":"五言律诗","c":["驾舟越洪川，飘风扬其波。","白日不可驻，浮云一何多。","搴芳涉北沚，采虻陟南阿。","怅我平生友，伤此欲如何。"]},{"t":"赠刘主事元瑞二首 其二","f":"五言律诗","c":["濛濛孤舟夕，横笛坐烟浦。","秋绿被汀沙，落雁不可数。","烈调千行云，激商复流羽。","曲竟和者谁，坐人泪如雨。"]},{"t":"湘江吟","f":"五言律诗","c":["对酒歌绿猗，岁宴怀佳人。","山寒翠袖薄，微霰沾衣巾。","空持紫鸾箫，欲致愁无因。","日暮湘江曲，浩荡烟波春。"]},{"t":"春曲五首 其一","f":"五言古诗","c":["维南有曾城，下瞰梁王台。","痽构翳云日，歌钟暮徘徊。","芳草遍旧畿，山川邈悠哉。"]},{"t":"春曲五首 其二","f":"五言古诗","c":["春城花烟满，杳霭生夕阴。","白马系芳树，绣袪弹鸣琴。","樗蒲少年子，一掷千黄金。"]},{"t":"春曲五首 其三","f":"五言古诗","c":["绮阁俯通阛，后有百尺楼。","并坐紫罗茵，双引青玉瓯。","扬花起薄暮，糁糁萦芳洲。"]},{"t":"春曲五首 其四","f":"五言古诗","c":["菁菁艳阳月，郁郁美人思。","游丝罥白日，炯若春风姿。","零落垂手舞，空传白纻词。"]},{"t":"春曲五首 其五","f":"五言古诗","c":["借问美人居，云住城东隅。","背有桃李馆，前临车马衢。","十三妙歌舞，十五冠名姝。"]},{"t":"朔日","f":"五言古诗","c":["朔日悲风起，空除落叶平。","犹闻砧杵急，巳复剪刀鸣。","一夜传霜箭，黄云满塞城。"]},{"t":"槿树","f":"五言古诗","c":["槿树依空砌，寒时尚著花。","未能堪暮色，徒自绚朝霞。","寄语闺中女，无多镜里华。"]},{"t":"槿园","f":"五言律诗","c":["槿园秋气夕，唧唧寒螀聚。","风回啼欲断，月落归何处。","爰悲在堂吟，复咏山枢句。","感尔中夜兴，微霜下庭树。"]},{"t":"春情","f":"五言律诗","c":["俗萦一何绵，驾言春巳分。","绿郊鲜行轮，朱树花将纷。","鸣雁起前墟，浮阳蔼东濆。","徙倚孤台侧，伫回送征云。"]},{"t":"游寺","f":"五言律诗","c":["褊心俦辈寡，幽境每苔步。","绵郁倚磴歇，冯孤眺迥屡。","洞塔阴古宇，芬萝袅澄树。","伫观野禽哺，此外岂吾虑。"]},{"t":"升天行","f":"五言律诗","c":["市居苦烦溽，陆暑怀清波。","缅思溪壑侧，丹崖卷曾阿。","仙人挂树下，窈窕攀青萝。","我独尘歊内，营营欲如何。"]},{"t":"春游篇","f":"五言律诗","c":["古台悲帝子，歌吹馀春愁。","草绿夷梁野，云浮河海流。","击壶咏四泽，鼓钟眺三洲。","扳条已无那，驾言谁倦游。"]},{"t":"四清篇","f":"五言律诗","c":["盘松屹当户，修筠静依槛。","羁远桐丝涩，萧瑟鹤思减。","归伤园坞废，坐令荒秽斩。","弹曲憩疏荫，皋唳清露湛。"]},{"t":"正德四年七夕上方寺作","f":"五言古诗","c":["逸人厌嚣俗，达士乐閒胜。","乃兹城中林，而非车马径。","积雨豁新霁，云石掩秋映。","微阳下孤塔，潦水夹明镜。","巳疑尘寰隔，况睹莲方净。","岂惟慕真觉，亦以叩诠證。","玄蝉共西夕，浮云本无定。"]},{"t":"戊寅早春方方寺","f":"五言古诗","c":["逾年罔涉兹，过之门巷疑。","匪畏霜露辰，肯与春事期。","径兰芊故丛，苑松发新蕤。","陟丘念废居，升危眺回漪。","抱以幽旷豁，情缘悽怆移。","惊风递虚塔，振振空廊悲。","得遣复安较，劳生良尔嗤。"]},{"t":"夕集上方寺辛巳春","f":"五言古诗","c":["晨飙奋以厉，夕林回晏温。","郊游怅伊阻，驾言乃松门。","春湖静瑶宇，塔萝袅清樽。","遥睇被原草，近搴临水荪。","花雨时自落，法云凝复奔。","淹留迟宝月，破此人径昏。"]},{"t":"山中","f":"五言古诗","c":["山中雨乍歇，一夜瑶草长。","风吹翠岩竹，下应石濑响。","时来展书坐，悠悠绝尘想。"]},{"t":"置薪","f":"五言律诗","c":["读书古木阴，置薪倚其根。","露零石径滑，云起溪日昏。","白虎启巍观，金马开高门。","君自薄簪绂，难称国未恩。"]},{"t":"九潭诗","f":"五言古诗","c":["岧岧千仞岭，下有百尺潭。","夕风起微澜，浟浟动晴岚。","俯之鉴我心，伫玩云波涵。","流蕤飏寒清，跃鱼手可探。","蹊暝樵响歇，猿鸟来相参。","寄语泥中物，长蟠恐未堪。"]},{"t":"登东城楼晚下楼作赠同游数子二首 其一","f":"五言古诗","c":["登高散凉目，隤然日云暮。","逃暑良巳恹，恋景复延顾。","广野起暝色，层闉合昏雾。","眷言楼中客，共此城上步。","蚊虫扑面游，蝙蝠时自度。","二仪但莽莽，一气黯回互。","昼夜本定理，明晦非难悟。","日入各言息，钟鸣复驰骛。","崷崒宋帝阁，突兀信陵墓。","往似宿沙禽，来如缀花露。","徙倚千仞梯，长谣发悲愫。"]},{"t":"登东城楼晚下楼作赠同游数子二首 其二","f":"五言古诗","c":["盛阳丽楼台，烂如锦绣错。","日入暝烟起，俯视但冥漠。","即此悟人理，天道固可度。","动静启晦明，代谢有今昨。","凉飙逐夕兴，回声满虚阁。","四顾水明灭，宿鸟喧相索。","哑哑啼城乌，噭噭上云鹤。","忉怛感晨暮，徙倚罢觞酌。","北斗忽复低，西月隐长薄。","闪烁海光动，翕沓氛雾廓。","无恃黑头在，早定沧洲约。"]},{"t":"寄赠端溪子二首 其一","f":"五言古诗","c":["叹凤世巳远，悲麟竟何为。","兰蕙秘幽岩，萧艾盈路岐。","君子抱明德，伤也谁复知。","随流非我心，特立乃见疑。","亭亭南山松，匪无霜霰摧。","寒蕤但不改，孤贞常自持。"]},{"t":"寄赠端溪子二首 其二","f":"五言古诗","c":["智者尚高契，达人慕希声。","旷世有相感，同时怅难并。","烈风起玄朔，百卉忽以零。","登高望所思，慨焉念徂征。","鸿雁序翅飞，麋鹿呦呦鸣。","为言明馨子，盍簪终有成。"]},{"t":"赠苍谷子","f":"五言古诗","c":["玄云翳白日，积阴何漫漫。","风气日以凄，泥雨常不乾。","漂萚委川涂，百卉良可叹。","览物怀伊人，抚时悲凉寒。","忧来如乱丝，理之棼无端。","为霜念逝鹄，多露怨芳兰。","所嗟声影隔，匪惧馨香残。","徒把瑶华音，长谣望林峦。"]},{"t":"赠刘潜","f":"五言古诗","c":["人生无常因，飘如风中云。","昔别大江隅，今也长江濆。","凉飙起霜夕，陨叶何纷纷。","我菊有佳色，毅然独芳芬。","迟速良有时，勉哉树高勋。"]},{"t":"赠崔子","f":"五言古诗","c":["鲲鱼游北溟，凤鸟翔南涯。","扶摇非无运，鸣世自有期。","显夫竞钟鼎，遁士潜蒿藜。","驷马岂不荣，泉石安且怡。","悠悠西山人，匪为薇蕨饥。","寄言青云客，策勋及今兹。"]},{"t":"赠孙生","f":"五言古诗","c":["古人种桃李，不为搴其花。","君子振英芬，岂在文与华。","炎阳赫晴彩，百卉流丹霞。","蕡彼东园实，累累一何嘉。","采者自成蹊，举世徒咨嗟。"]},{"t":"赠王生二首 其一","f":"五言古诗","c":["凤鸟世希有，众人常见疑。","一朝下西周，戛焉鸣高岐。","光彩照四极，观者惊以咨。","神物耻自衒，卑鄙甘见欺。","骥马匪伯乐，盐车空号悲。","烨烨丰城剑，非华谁固知。"]},{"t":"赠王生二首 其二","f":"五言古诗","c":["伯牙违钟期，有琴不复弹。","兹意奚以取，良为知音难。","得失有荣枯，合离成怨欢。","万鹄戾天云，玄鸿渐河干。","浅夫贵多矜，狭士贱自残。","幸子固明志，显塞察所安。"]},{"t":"赠崔生","f":"五言古诗","c":["伊昔振我衣，连步千仞冈。","岩谷窈疑阻，岐径回羊肠。","与者咸莫从，子也乃同行。","举手撼天枢，纵目揽大洋。","星斗何历历，海波浩茫茫。","登山贵及颠，涉水非无航。","愿言穷高深，念哉母相忘。"]},{"t":"赠魏子二首 其一","f":"五言律诗","c":["霖潦久乃歇，晨兴送还辀。","野寒泥淖盛，念兹途路修。","人生苟相许，岂必曾绸缪。","踟蹰东路岐，赠子双吴钩。"]},{"t":"赠魏子二首 其二","f":"五言律诗","c":["八月浙潮满，念子鼓南楫。","海月团会峰，山风下江叶。","里闾多宴娱，任宦有荣业。","早回北向辕，昼日望三接。"]},{"t":"三士篇赠医李郑张","f":"五言古诗","c":["严飙厉时威，稿叶下荣木。","春风一以敷，病草奄回绿。","天道岂常肃，人事有还复。","七情既吾贼，六淫乃为殰。","农经发玄旨，轩问扩英馥。","代殊理易昧，行乘计相逐。","陈荄抱绵息，寒根蕴真育。","李生起专门，郑子振空谷。","张也剖金匮，奏效更神速。","饮橘秪自衒，种杏亦可恧。","诵我三士篇，聊以助清穆。"]},{"t":"寺游别熊子四首 其一","f":"五言律诗","c":["天地固常尔，遇之情不同。","但看摇夏树，何似飞秋逢。","古来怨离人，岂必穷与通。","默默两无语，坐披琳殿风。"]},{"t":"寺游别熊子四首 其二","f":"五言律诗","c":["夕风起凉阁，入耳松搣搣。","当此佳胜区，谁忍遽离析。","篇鹳戛戛鸣，萝翠满衣席。","异时冠盖场，倘忆幽赏迹。"]},{"t":"寺游别熊子四首 其三","f":"五言律诗","c":["散眸七宝地，觞尔孤云台。","一望碧云合，四面清风来。","流影荡我前，炎树生秋哀。","一笑问天地，劫灰安在哉。"]},{"t":"寺游别熊子四首 其四","f":"五言律诗","c":["独立台上阁，俯兹城下湖。","为问黄金鱼，径尺今有无。","愚者人尽笑，贤之乃谤诬。","二者吾适从，不如乘海桴。"]},{"t":"甲申中秋寄阳明子","f":"五言律诗","c":["风林秋色静，独坐上清月。","眷兹千里共，眇焉望吴越。","窈窕阳明洞，律兀芙蓉阙。","可望不可即，江涛滚山雪。"]},{"t":"赠李世德","f":"五言古诗","c":["豢畜不生麟，鸾穴无鹯鹪。","求水贵求源，佳木无亚条。","李门世清修，三辈烨雄超。","黄扉早杀翮，中叶乃沦凋。","生也困逾励，奋飞竟云霄。","大钓干神化，万物随生消。","英英畹中蕙，化为艾与萧。","愿坚谋始心，全我全石要。"]},{"t":"寄赠玉溪子","f":"五言古诗","c":["松桧不栖蝉，熊皮不上蚁。","秉性死不易，斯足验人理。","苟投信若饴，义交固如水。","如水遐则思，若饴背乃毁。","悠悠徂暑月，眷眷念君子。","霍云停复飞，汾水荡而驶。","山西回夕阳，皎如觏光美。","徒操孤绝弦，叹息竟何以。"]},{"t":"初秋上方寺别郑生","f":"五言古诗","c":["胜地亮常尔，佳士难屡并。","未穷结驷游，遽复扬帆行。","古林郁城隅，石门敞幽清。","趁风选浓荫，布席觞群英。","竹凉时自来，残暑骄未平。","戒饮今二期，为子杯一倾。","义投不在故，迹远心自萦。","念兹徘徊意，时哉树嘉名。"]},{"t":"赠郑生三首 其一","f":"五言律诗","c":["杪秋木叶脱，霜露告成岁。","驱车溯寒郊，触物念征迈。","戒舟有程日，维驹阻心爱。","所幸旦暮留，前途或风濑。"]},{"t":"赠郑生三首 其二","f":"五言律诗","c":["伊予解组归，汝也美少年。","骏马臂两弓，射猎梁王川。","感子重意气，授之黄金鞭。","万里不易致，悲鸣为谁前。"]},{"t":"赠郑生三首 其三","f":"五言律诗","c":["英英百寻木，时至乃黄落。","楚楚青俊郎，还家鬓萧索。","桂树寒正荣，溪鱼白而跃。","山行采瑶草，寄我长生药。"]},{"t":"寄程生","f":"五言古诗","c":["河日淡莽莽，飘风但尘沙。","阴阳为谁争，时至枯亦葩。","念离伤岁穷，怀音怨途赊。","彼美杳何许，孤吟弄瑶华。","夜揽海门月，晨吸波上霞。","苦心谁固知，延望长自嗟。","浦雁回故翼，汀兰茁新芽。","无负汴上约，梁园多奇花。"]},{"t":"赠梅国子","f":"五言古诗","c":["烈士有心许，佳人重情欢。","投义既不易，识者良独难。","清秋理瑶瑟，为君发高弹。","一曲未云乱，仰视孤鸿翻。","一举狭千里，再举青云端。","我欲从之逝，羽短才力单。","声影中藏之，傥接排风翰。"]},{"t":"赠定斋子","f":"五言古诗","c":["水澄万形一，镜明别丑好。","哲人静以俟，愚者苦纷扰。","君本观海人，扬旆向东道。","高步登岱巅，横览尽洲岛。","匪云波水浩，秪见众山小。","孔林秋飙入，漂萚委寒草。","明禋展躬谒，芜翳为涓扫。"]},{"t":"雨后往视田园同田熊二子二首 其一","f":"五言古诗","c":["鸟性悦俦匹，人情岂无慕。","亟见不云数，独行必相呼。","昨有城上眺，今复郭南步。","膏雨回原绿，丰林宿残雾。","久芜慨我庐，旱水两妨误。","夏禾既岑漠，秋秫庶能穫。","酿具粗巳足，念子有长路。"]},{"t":"雨后往视田园同田熊二子二首 其二","f":"五言古诗","c":["雨暵自有期，岁功讵云差。","昨来偶滂沱，万物皆颜华。","晴晨子见过，毅然巾我车。","荒径蹄辙稀，泽国疏桑麻。","长风起修林，夕响连蒹葭。","芁芁南山豆，离离东陵瓜。","怀古看行云，矫首徒咨嗟。"]},{"t":"庄上晚归车阻于潦渠徒步始达于岸","f":"五言古诗","c":["暮醉各言归，风起草猎猎。","潢潦溢中轨，车至不可涉。","野黑径复曲，鱼贯踵相蹑。","良惧苍耳窟，重为蜥蜴怯。","童稚行我先，沟塍负而躐。","世路本夷崄，人情有惊怗。","閒素轻波涛，临川想维楫。","履坦合自咎，长吟咏匏叶。"]},{"t":"山夜","f":"五言律诗","c":["孤月上东岫，白鹤激秋泪。","凉风振溪壑，林影飒摇泄。","山居本深静，夜气复澄霁。","冥心向千古，眇焉托真契。"]},{"t":"蒸热三子过我东庄","f":"五言古诗","c":["林蜩午不歇，日毒土色赤。","郁言森密里，时华媚深碧。","三人者胡来，无乃不速客。","黄公苍须髯，二生颀而晢。","入荫齐解带，对酒各岸帻。","篱萱挺其秀，槛果垂易摘。","无言岂为默，有形忘所役。","杯乾时一斟，遽复至西夕。"]},{"t":"田园杂诗五首 其一","f":"五言古诗","c":["朝阳暧秋木，凝露未即晞。","翩翩啄榴鸴，自惊集复飞。","众穑既登载，我事亦渐稀。","晨兴坐东牖，兀然对红薇。","噭噭一白鹤，北逝将畴依。","忍兹稻粱辰，而汝甘长饥。"]},{"t":"田园杂诗五首 其二","f":"五言古诗","c":["大车行棘棘，小车响额仄。","随分各有营，急者稼与穑。","旦出在田野，日入未遑息。","长阴下西夕，萧飒起寒色。","云霞变彩气，照我桑麻国。","立看劳者归，露濡径不湿。"]},{"t":"田园杂诗五首 其三","f":"五言古诗","c":["野清云气满，场功亦云毕。","收穫虽有殊，大小各盈室。","感兹狼戾年，追念忧苦日。","纷然嗿其馌，妻子孰遑佚。","岁工借寒热，人事坐劳逸。","萧萧原野霜，何草不垂实。"]},{"t":"田园杂诗五首 其五","f":"五言古诗","c":["田居亦安娱，患者寡朋仇。","农谈或时歇，仰视苍云流。","青衿者谁子，道言即我谋。","开尊面圃场，剥棘充盘羞。","物小意固勤，觞既情仍留。","皛皛远天色，秋旸下林丘。"]},{"t":"秋诗二首 其一","f":"五言古诗","c":["百卉凄以腓，游行散我瞩。","夕风一何瑟，入园乃华馥。","菊也纷其英，修篁积寒绿。","人生匪金铁，荣落譬草木。","磬折者谁子，誓死日争逐。","贤贵与贱愚，灭去孰还复。","鸟雀各有安，无为智者辱。"]},{"t":"秋诗二首 其二","f":"五言古诗","c":["北风胡雁急，小禽亦南飞。","轻侠群少年，求伺争有为。","弋弹无遗木，毕施在中逵。","百发不一获，用心良足嗤。","黄雀堕计中，鸣咷如得依。","白鹄举云汉，览之心内悲。","小大有分量，琐琐岂知微。"]},{"t":"咏鹭","f":"五言古诗","c":["天风下厉霜，海色清严冬。","朱鸟逝云远，玄禽眇焉踪。","翩翩委波羽，鸣飞何雍雍。","去若雪毬散，来疑玉梭从。","回旋渌蒲漪，映照青莲峰。","戏滓不染洁，浴湜转丰茸。","群起若避惊，孤立如有慵。","孔言崇九思，周歌羡斯容。","我容亮多泽，君子良冲瀜。","亦应惧凫雁，幸少宽鰅鳙。","保尔贞素姿，倘附春涛龙。"]},{"t":"桂岩行","f":"七言古诗","c":["白龙不识渔溪恶，化为渔服遭人缚。","黄发先生困泥阻，白马小儿气挥霍。","道傍朽木藏蛟龙，霹雳犹闻夜火红。","寄谢少年诸数公，贫贱岂必皆愚蒙。","桂岩紫芝春尽发，骑驴且觅商山翁。"]},{"t":"崖松行","f":"七言律诗","c":["峭石嵷巃木相樛，孤松拄日崖光幽。","朔风北来霜雪暗，山深草黄途路修。","此时亭亭见松意，排空柯干流云气。","大厦倾时梁栋急，君看此物终难弃。"]},{"t":"丹穴行哀丘翁","f":"七言古诗","c":["北风飒飒吹丹穴，幽篁梧树寒萧屑，孤凤威垂眼流血。","兰阳丘公昨谢世，使我杯乾巳数月。","出门骑马向谁适，世事悠悠忍能说。","薄俗跄趋始为敬，老夫平生性懒拙。","后生讥讪转多口，白璧青蝇从点缺。","宋门汪隆颇好事，见我握手肝肺热。","近亦客死临清州，北望伤心路途绝。","可怜亲友日零散，老成耆旧灰烬灭。","不争汝曹灰烬灭，又值天寒地欲裂。"]},{"t":"苦寒行","f":"古风","c":["前日雪落伤麦根，北风刮地天色昏。","沙飞石走拔大树，雪积林坳出无路，城中死者不知数。","我归三年河不冻，今年冰坚车可渡。","触面憭慄厚地裂，四顾乾坤莽明灭。","尺薪粒米贵如玉，君不见日晚空墙贫士哭。"]},{"t":"夜行歌","f":"七言律诗","c":["月轮未安光巳皎，我行夜出夷梁道。","力疲足酸堤上坐，黄狐怒立啼向我。","宋家宫殿尽瓦砾，陂湖烧盐焰婀娜。","忽忆东京全盛时，月行对此谁能那。"]},{"t":"古白杨行","f":"楚辞体","c":["百泉东岸三古杨，下枝扫拂书院墙，上枝瑟飒于穹苍。","空山野阴雷雨黑，柯干冥冥动山壁。","剪伐难为栋梁用，盘踞番逃斧斤厄。","但见白日悲风发，宁知六月撑霜雪。","烟色惨怆精灵聚，孤根倔强源泉裂。","忆昨访古憩其下，居人不敢留车马。","落萚尚禁牛羊食，污秽颇遭县官打。","丞相古柏霹雳碎，将军大树空萧洒。","罔头石路莎草长，孙邵李许同一堂。","春风漂泊予到此，不见古人惟古杨。","古扬萧萧暮流急，波翻浪倒蛟龙泣。","卫女幽忧拾锦花，逋臣寂寞愁难立。","君不见太行羊肠莫比数，上有毒蛇下猛虎。","樵斤猎火不虚日，桂柏椅桐气悽苦。","呜呼杨兮杨兮，尔何盘根据兹土。"]},{"t":"泉上杂歌二首 其一","f":"古风","c":["游子乐游复长叹，临深坐歌白石烂。","石泉漠漠常东流，我今胡为坐泉头。","渚花冥冥野阴薄，溪日杲杲苍云愁。","君不见古来争战地，山寒雪暮风飕飕。"]},{"t":"泉上杂歌二首 其二","f":"七言律诗","c":["美人被服貂襜褕，春日游行春水曲。","绿萝无烟山雪暝，扣石长歌叹幽独。","拨刺红鳞锦湍游，我欲钓之且复休。","金盘玉箸在何许，为尔临渊泪如雨。"]},{"t":"自从行","f":"古风","c":["自从天倾西北头，天下之水皆东流。","苦言世事无颠倒，窃钩者诛窃国侯。","君不见奸雄恶少椎肥牛，董生著书番见收。","鸿鹄不如黄雀啅，盗蹠之徒笑孔丘。","我今何言君且休。"]},{"t":"大梁城西门行","f":"七言古诗","c":["水门堤口双柏树，种之何年不记数。","风餐雨蚀生气微，枝叶半凋委官路。","乌鸦蝼蚁复啄食，我行见之泪如注。","古来根本忌先拨，呜呼柰此栋梁具。","及今可为当语谁，半夜吞声向北去。"]},{"t":"羁旅翁行","f":"古风","c":["自焚阙里手植桧，天下斯文忽坠地。","锦衣使者日旁午，青衿冑子时流涕。","霾风翩翩起白旐，五月黄尘暗天际。","君不见河上羁旅翁，时乘此老遭拘绁。"]},{"t":"宝刀篇","f":"古风","c":["我有吴王双宝刀，龙鳞雪花烂照地。","奉君清宴可君意，佩之十年不曾离。","黄金鞶带白玉钩，出入魍魉魑魅愁。","功高见款反遭怒，此物抛掷今两秋。","丈夫生世轗轲亦如此，终日戚戚何为尔。"]},{"t":"秋夜叹二首 其一","f":"古风","c":["君不见梁上蝠，飞走掠蝇虫。","蝇虫四散不受掠，而我胡在缧绁中。","岂即运命委霜雪，要知腐草生华风。","沉吟彻夜不能寐，此时天风雨将至。","但闻虫声啾啾复唧唧，鸿雁嗷嗷忘南北。"]},{"t":"秋夜叹二首 其二","f":"古风","c":["臭虫多足蚊有翅，当我眠时忽而至。","愤闷披衣坐叹息，竟夜搔爬无气力。","寒霖萧萧响荆棘，君不见坎灯无烟四壁暗，野狐跳梁鬼啾唧。"]},{"t":"思归引","f":"七言古诗","c":["疾风吹寒破南极，冻雨濈濈山树黑。","天昏岁暮百忧并，中夜悲歌泪沾臆。","起视众星白烂烂，我今胡为在长安。","思归路阻多苦寒，嗷嗷何处失群雁，翅湿高飞嗟汝难。"]},{"t":"归来行","f":"七言律诗","c":["天下儒冠岂尽误，迂谬弃捐仍道路。","九月江山冻烟雾，百年裘马冲霜露。","穷达自知休怨天，归来且种东陵田。","齿过四九已不小，钓鱼猎兔亦得饱。"]},{"t":"弘治甲子届我初度追念往事死生骨肉怆然动怀拟杜七歌用抒抱云耳 其一","f":"楚辞体","c":["吁嗟我生三十三，我今十年父不见。","浊泾日寒关塞黑，杳杳松楸隔秦甸。","梁王宾客昔全盛，我父优游谁不羡。","当时携我登朱门，舞嫱歌媵争看面。","二十年前一回首，往事凋零泪如霰。","呜呼一歌兮歌一发，北风为我号冬月。"]},{"t":"弘治甲子届我初度追念往事死生骨肉怆然动怀拟杜七歌用抒抱云耳 其二","f":"楚辞体","c":["母之生我日初赫，缺突无烟榻无席。","是时家难金铁鸣，佁皇抱予走且匿。","艾当灼脐无处乞，邻里相引失颜色。","男儿有亲生不封，万钟于我乎何益。","高天苍苍白日冻，今辰何辰夕何夕。","呜呼二歌兮歌思长，吾亲俨在孤儿傍。"]},{"t":"弘治甲子届我初度追念往事死生骨肉怆然动怀拟杜七歌用抒抱云耳 其三","f":"楚辞体","c":["有弟有弟青云姿，以兄为友兼为师。","十五遍探古人籍，十九不作今人诗。","从兄翱翔潞河侧，宁料为殇返乡域。","孤坟寂寞崔桥西，渺渺游魂泣寒食。","呜呼三歌兮歌转烈，汝虽抱女祀绝绝。"]},{"t":"弘治甲子届我初度追念往事死生骨肉怆然动怀拟杜七歌用抒抱云耳 其四","f":"楚辞体","c":["有姊有姊天一方，风蓬摇转思故乡。","岁收秫秉不盈百，男号女啼常在旁。","黄鸟飞来啄屋角，硕鼠唧唧宵近床。","洪河斗蛟波浪怒，我欲济之难为梁。","呜呼四歌兮歌四阕，我本与尔同肉血。"]},{"t":"弘治甲子届我初度追念往事死生骨肉怆然动怀拟杜七歌用抒抱云耳 其五","f":"楚辞体","c":["古城十家九家空，有姊有姊城之中。","哨壑直下五千尺，鸡鸣汲回山日红。","犁锄纵健把岂得，病姑垂白双耳聋。","小孤痴蠢大孤惰，霜闺夜夜悲回风。","呜呼五歌兮歌五转，寒崖吹律何时变。"]},{"t":"弘治甲子届我初度追念往事死生骨肉怆然动怀拟杜七歌用抒抱云耳 其六","f":"楚辞体","c":["冰河蜿蜒雪为岸，忽得鲤鱼长尺半。","剖之中有元方书，许我是月来相看。","腊寒岁穷多烈风，日暮高楼眼空断。","梁都北来道如砥，熟马輶轮为谁绊。","呜呼六歌兮歌未极，原鸰为我无颜色。"]},{"t":"弘治甲子届我初度追念往事死生骨肉怆然动怀拟杜七歌用抒抱云耳 其七","f":"楚辞体","c":["丈夫生不得志居人下，低头腼面何为者。","薄禄不救诸亲饥，壮志羞称万间厦。","东华软尘十丈红，入拥簿书出鞍马。","王门好竽不好瑟，何如归樵孟诸野。","呜呼七歌兮歌思停，极目南山空翠屏。"]},{"t":"西来行","f":"七言律诗","c":["冬廿六日十二月，西来泛湖雨明灭。","雨寒著树尽成雪，天波■霮路幽绝。","鸹鸧秃鹙立如人，衔鱼避船偷眼嗔。","天开猎夫会寻汝，乘时早可收其身。"]},{"t":"飞蚁叹","f":"古风","c":["今朝天光鸟鸣唤，草萋柳长江涣涣。","怪尔飞蚁何烂熳，填门扑窗坐我案。","夜来不虞风骤至，尾瓦吹飞船打岸。","孤城晦冥霏霏雨，前叫鸹鸧后鹅鹳。","共言此崇飞稀鹃，我欲击之还复叹。","明明上天非无宰，蚁也琐细何须算。","灾祥感召固其理，先时苟备终无患。","君不闻汉家满堂客，不贵徙薪贵焦烂。"]},{"t":"癸酉生日","f":"七言律诗","c":["庐山腊日地冻裂，白猿鹿麂啼深雪。","卧病松林北岸湖，黄蒿古阪行人绝。","巳今行年四十二，我辰安在百忧结。","小孙呼爷戏床侧，纵恼忍能即嗔说。"]},{"t":"馀干行","f":"七言古诗","c":["荒滨鹘立夕啼鹕，春行缘岸竹木枯。","黄蒿破屋走白狐，东至信州西鄱湖。","男儿输粟妇刈刍，问谁为此军前须。","去年冰雪十丈馀，凋瘁至今犹未苏。","姚源带甲巳数万，岩淤莫展金仆姑。","近闻杀官兵复此，道路諠传真有无。","安能飞刀取贼颅，貂裘白马还京都。"]},{"t":"叉鱼行","f":"七言古诗","c":["汉江七月黄水涨，男妇叉鱼立江上。","岸斜波紧喣泡转，千人目侧精相向。","巧者十叉五叉中，血飞银尺翻金浪。","鳊鱼中叉独更稳，顿之泥沙半倔强。","我舟其时行遘此，仰视皇天色惆怅。","深山药苗熟流汝，一毒江河万形丧。","鲦鲨糜烂不直钱，小琐暴弃同蚶蟓。","走鲵吞泓吞山滚，蹴踏犹能开浩荡。","渡子徒誇好身手，如飞快桨谁曾傍。","夜风大声吼盘涡，地坼澒洞豗鼋鼍。","如瓮之蛟手可得，蛇龙岂复安巢窝，消息定理鱼柰何。"]},{"t":"襄阳歌四首 其一","f":"古风","c":["烈风夜行岘山道，天阴城空鬼鸣啸。","蒹葭委折波涛白，通济桥头老鸧叫。","人言黄昏虎抟牛，牛虎两伤归各忧。","万事岂尔能前谋，不如置之宽且休。","君不见百足之虫光如虹，雷火烧死枯树中。"]},{"t":"襄阳歌四首 其二","f":"古风","c":["岘石巉嵾孤根深，下盘厚土云气阴。","中有千万窍突如，风来遇之如笙琴。","昨当醉狂推撼此，天地忽然为之动，山鸣鬼哭百兽吟。","我时便欲驱使六丁移之去，家遥屋卑无顿处。","于乎一石且无顿处，徘徊归来日沉树。"]},{"t":"襄阳歌四首 其三","f":"古风","c":["襄阳山势何所似，东如翥凤西虎蹲。","墓堆累累不空地，于中岂少英雄魂。","大堤先前花艳时，朱楼细柳黄金羁。","但看旧园歌舞处，掘发金钗知是谁。","君今有酒不饮，恨不驷马轩车驰。","纵及金张许史将焉为，身后埋没蒿草畴见知。"]},{"t":"襄阳歌四首 其四","f":"古风","c":["昨来三日雨不住，逢人面色如地皮。","老龙之堤岂易打，襄阳难是养鱼池。","南倒江势虽汹涌，我堤如山撼不动。","但虑祸患起细微，丁宁疆吏防蝼孔。","我闻斯地连年垂雨旸，二麦麦死秋禾伤。","众心詾詾久未定，小儿何得跳商羊。","天公好生民寿康。"]},{"t":"苦雨篇","f":"七言古诗","c":["波涛日陷蛙鸣起，梁园一夜满城水。","屋庐半塌塌人死，可怜哭声水声里。","忆昨出饮黄昏归，零濛巳洒力尚微。","岂知中宵鬼神怒，雷翻电滚雨如注。","我时怵愓不得眠，窗灯扑杀无计燃。","汹涌一任霹雳走，恍忽若有蛟龙缠。","地轴震仄久益急，披衣起坐坐复立。","鸡鸣气势幸稍缓，积渐天明日光入。","琴沾书湿开我堂，二仪高下云低昂。","黄鹂晒翅燕语梁，前何恐惧今何康。","万事夷险谁豫量，及时弗乐头颅苍。"]},{"t":"苦雨后篇","f":"古风","c":["小儿?哑始学语，育之后屋逢今雨。","包裹移置夜我旁，儿惊屡叫安之乳。","霆雷虩虩屋瓦震，疾电绕床乱走鼠。","大儿明农隔城住，即有缓急谁视汝。","旦日报至心则降，雨未伤人伤稷黍。","前时三月点雨无，大儿忧色禾半枯。","日日望雨雨反荼，荡然畎亩为江湖。","天晴微风波水动，沟渠四注长河涌。","明晦反覆何代无，嘱儿更备宜秋种。"]},{"t":"久雨柬黄子","f":"七言律诗","c":["微晴见月月仰瓦，城中水淹雨犹下。","郊园浃旬不一出，不畏冲泥畏没马。","苔藓自上匡氏壁，蓬蒿日深仲蔚舍。","人言甲子船入市，幸君豫问能舟者。"]},{"t":"种竹","f":"七言律诗","c":["自从有竹水烂死，使我竟日颜不欢。","顷来移置复傍此，遽觉六月回秋寒。","龙姿凤苞生不易，可怜芜没今人弃。","窈窕郊园草树中，何人道有凌云器。"]},{"t":"放蛇引","f":"七言古诗","c":["花蛇错落五色备，毁垣掘出蛇惊悸。","昂头宛颈若有诉，盘旋瞥捩如奔避。","深山大泽岂无窟，荒郊短草真何意。","豺虎公然白昼行，花蛇何得更纵横。","秪知毒口能戕物，未解皇天实好生。","洪流自古容微细，吾叱园丁纵蛇逝。","风驱雷霆急雨过，彩虹倒挂青天霁。"]},{"t":"送何舍人赍诏南纪诸镇","f":"七言古诗","c":["先皇乘龙去不返，悲风惨淡吹宸极。","四海哭若丧慈母，百官狂走天为黑。","忆昨临危坐御床，手挈神器归今皇。","密语丁宁肺腑裂，三老亲闻眼流血。","金縢立剖石室秘，此事难从外人说。","我君谦让不可得，割哀践阼弘祖烈。","日月重悬万国朝，雷雨赦过群方悦。","越南海北霹雳动，蛮夷尽奉王正月。","此时九道使臣出，舍人亦辍螭头笔。","白马朝腾蓟北云，锦帆暮闪江沱日。","江沱秋交多裂风，洞庭云梦俱眼空。","巴陵县令舍人兄，接诏会弟西楼中。","童年题诗在高壁，六载不到纱为笼。","南岳以南惟峻山，苦蒸毒雾何盘盘。","天王新令雷电掣，妖蛇不敢啼林端。","五溪官长喘喙拜，黔州父老垂泪看。","却瞻苍梧云气黑，斑竹临江怨幽色。","翠华缥缈空冥间，此时此恨谁知得。","君不见马援拄孔，明碑剥落黄蒿里。","千年莓苔待君洗，万里之行自此始，归来何以献天子。"]},{"t":"上元访杜鍊师","f":"古风","c":["宣皇昔时乘八风，御龙游戏行烟空。","马前两两侍王女，别馆多在蓬莱宫。","朝天宫中旧时殿，楼台昼锁无人见。","琉璃井塌青苔满，松柏森森月如练。","呜呼往事难具陈，灯火如山又一春，北斗坛西访隐沦。","我师黄衫白?巾，坐我更致西楼宾。","玉杯潋滟赤玛瑙，织罽四角银麒麟。","酒肉山堆满堂醉，仙厨往往来八珍。","孝宗之朝五真人，师也磊落当其伦。","自言召见亲赐食，曾把丹书献紫宸。","如今寂寞看春色，银鱼玉带无消息。","岂惟鱼带无消息，欲语吞声泪沾臆。","劝师对此莫酸辛，世间万事如转轮。","且将芝草供生计，聊与烟霞作主人。","月偏彩云当牖生，旋呼两童吹玉笙。","闻师妙得逡巡术，百壶倒尽还须倾。","古来仙子尚谁在，饮者翻垂千载名。","名垂千载亦区区，酒阑灯昏夜复徂。","不见泰陵草已宿，春生树啼双老乌。","此时亦应群帝趋，金灯翠旗光有无。"]},{"t":"二月四日部署宴饯徐顾二子","f":"七言古诗","c":["春日载阳官署幽，东吴二子过我游。","庭空日斜吏人散，窅然何异经林丘。","今晨惊蛰暖气达，昨夜哀鸿呼故俦。","中庭古槐苍藓溽，上有百鸟何啁啾。","仓庚交交刷其羽，君看巨细各有求。","明时冠轩几邂逅，得暇胡不攀淹留。","自从去年识徐顾，令我意气倾南州。","徐郎近买洞庭柂，顾子亦具钱唐舟。","浮生飘转若飞藿，倏忽聚散谁能谋。","风光烂熳况复尔，愿写清壶销客忧。","故人若称不好饮，举杯入唇还复休。","妙歌时时激慷慨，鄙夫何以答绸缪。","严柝沉沉静夜色，北斗倒挂城南楼。","秪恐天明驱马出，揽袪延望河之洲。"]},{"t":"七峰歌寿范郎中渊","f":"七言古诗","c":["我闻桂阳江上峰，平地突出七芙蓉。","三峰岧嵉如列戟，四峰袅袅翔飞龙。","孤水东来走其下，上岩下岩惟古松。","有时云雾满四壑，洞中仙侣时相逢。","使君磊落中行后，家傍前峰对江口。","暗想精灵盘礴初，岳降生申理或有。","平生气与苍壁高，落笔烟霞常在手。","六载为郎不爱身，五十生儿将白首。","湘南新鲊红胜王，燕京高会多名酒。","岁岁登堂娱笑歌，歌我七峰为尔寿。"]},{"t":"送人还关中","f":"古风","c":["君不见刘毅贫时，一掷常百万。","君不见唐时郑虔，道高坎壈腹无饭。","英雄际会各有时，人生岂必皆如愿。","关中老翁燕蓟客，昔何慷慨今何怨。","王通无媒番叩关，扬雄有赋何由献。","君归射猎南山麓，得钱且学樊侯贩。"]},{"t":"寄兵备高佥事江","f":"七言律诗","c":["三月无雨乾杀麦，六月雨多禾耳黑。","长江浪高蛟龙斗，陶河鸂鶒啼清昼。","此时怜君备吴越，天阴不见日与月。","白衫盐徒愤风涛，我军慎勿贪仓猝。"]},{"t":"寄内弟玉","f":"七言古诗","c":["自汝林居将一月，我心不宁长惙惙。","郊寒岁暮风色苦，旷野无邻天雨雪。","亟欲载酒往问子，冰路难行畏跄跌。","岂无轻裘与快马，玉也视之如敝幭。","此道于今识者稀，劝弟宽怀慎药物。"]},{"t":"雪柬郑生","f":"七言古诗","c":["夜来雪花如掌大，无事闭门但眠卧。","僵牛死马非所虑，天翻地裂畴能那。","近时好事最者谁，徽州郑生差爱我。","瓮头春酒不馀沥，天明梳洗午尚坐。","北风其凉二仪闭，雪吹飞沙映天过。","老夫畏寒淣无力，生也乃是雄豪佐。","梁园之陌平若掌，放兔呼鹰无不可。","不然骑驴学尔祖，乘兴一鼓山阴柁。"]},{"t":"吁嗟行示周生","f":"古风","c":["吁嗟周生千万驹，今行不得如蟾蜍。","虽有宝剑寒吹毛，一日不遇成铅刀。","子不见丰城，紫气干云霄。","盐车之下多悲号，张华伯乐行相遭。"]},{"t":"送郑器","f":"七言律诗","c":["梁园仲冬雪积阻，惨惨风乱平沙树。","泥深马瘦不得行，缥缈金陵在何处。","青丝络酒提玉瓶，强出送子城东亭。","旦望淮河暮江水，云飞鸿雁天冥冥。"]},{"t":"寄鲍宇","f":"七言律诗","c":["愧我夷门草堂寂，种菊芜秽生蓬蒿。","尔家华堂近江浒，开花烂熳秋云高。","去年此日同为客，今年对菊遥相忆。","黄山练水在何处，独倚南窗望南国。"]},{"t":"三鹤歌为丘三公寿亦载厥实事焉","f":"七言古诗","c":["老鹤东来度海水，与雌俱飞引其子。","回翔万里始一息，丘家麦田泽泚泚。","逍遥洗濯饮食足，烱如烟雪无泥滓。","此鸟千年丹始成，口衔赤玉苍龙精。","落地化作金光草，采食还丹毛骨轻。","古来拔宅将妻子，肯使丘翁地上行。"]},{"t":"君不见赠郑庄","f":"古风","c":["君不见江上雁，嗷嗷唤俦侣。","劲羽轻毛常趁风，往来漂泊如羁旅。","男儿落地既有身，谁能龊龊犹妇人。","怀中有剑亦不贫，吴下阿蒙君莫嗔。"]},{"t":"呜呼行寄康子以其越货之警","f":"七言古诗","c":["呜呼皇天不可测，一冬无雪春无雨。","黄霾翻风白日动，前飞秃鹙后飞鸨。","堂堂古路长蒺藜，万家之城走豺虎。","百姓诛求杼柚空，儿号女啼守环堵。","饥寒尽化为盗贼，可惜良民作囚虏。","腰弓带箭百成群，少年驰马仰射云。","苍山日落行旅稀，醉唱胡歌各自归。","山东赵实巳授首，南阳回贼同猪狗。","诸君但欲树功业，玉石俱焚理或有。","近者内丘大宁河，横贼八骑持干戈。","裕州知州与贼战，康也扶柩冲之过。","资粮荡尽仅身免，月暗天昏路途远。","吉人作善番轗轲，痛哭寒城白云返。","顷闻留滞在襄国，百口仰给县官食。","吾兄匹马走问之，半月更复无消息。","夜立中庭北极高，昼看河朔风沙黑。","汝宁以南土尤赤，空城二月生荆棘。","㪷米可以换娇女，牛马饿死枯蒿侧。","比来官吏守空印，柂男抱女尽向北。","即防此辈更充斥，恐汝后归归不得。"]},{"t":"送席副使监贵州屯学二事歌","f":"古风","c":["我昔在北京，送君向河南。","岂料在河南，送君如百蛮。","瘴云苍苍途路艰，牂牁罗施皆峻山。","法官要自褰帷入，倏忽开明众山出。","大抵夷狄似禽鸟，制之虽勤忌拘急。","此曹亦是人心性，顷来渐慕衣冠习。","文翁化蜀岂无本，李牧屯田务招辑。","所恨故人恨万里，令我蚤夜心于邑。","丈夫巳际飞龙会，野人犹抱枯鱼泣。","感新怀旧心肺酸，万事回头百忧集。","弘治之间时世异，与君次第陈封事。","许身谬比汉贾生，推君每称唐陆贽。","朝回对坐香炉省，出门并结青云辔。","自从分手哭遗弓，缙绅漂洎余亦同。","抱瓮梁王修竹园，遗址宋帝蓬莱宫。","生涯放逐似羁旅，混迹迂腐随村翁。","曾闻伏枥有老马，岂即道路伤秋蓬。","天下疮痍况未息，西南贡篚防难通。","杜鹃尚识君臣礼，蛟龙终收云雨功。","相如谕蜀文章壮，马援平交德业雄。","扶危济弱付公等，临岐怅望天南鸿。"]},{"t":"送鲍滶还歙","f":"七言律诗","c":["昔时贤达或未遇，途路坎坷常固穷。","盐车骐骥亦抛弃，人生岂得无西东。","君年五十犹未通，江湖去住随飞鸿。","黄山紫阳日索寞，题诗蚤向轩辕宫。"]},{"t":"送鲍相如金陵","f":"七言律诗","c":["去冬君行雪积阻，相送城东念羁旅。","今冬相逢不逾月，再别令我情更苦。","金陵市头酒如蜜，此去酣歌与谁侣。","我在梁园独岑寂，寞教碧草生春渚。"]},{"t":"君不见赠马佥事应祥","f":"古风","c":["君不见庭中树，今冬憔悴春作花。","君不见桑上草，含阳籍上抽紫葩。","富贵讵有种，贫贱岂无涯。","君今身为指南车，何不留之殿京华，北游汉水南长沙。","君虽在汉水与长沙，高不愁虎卑无蛇。"]},{"t":"得冯御史允中书","f":"七言古诗","c":["凤凰不识梧桐树，一落蓬蒿鸟雀欺。","沧洲鸿鹄长毛羽，纵有云罗柰尔为。","昨日郴阳冯侍御，临流寄我锦双鱼。","黄河崚嶒雪十丈，过腊逢春始得书。","开缄不见下江舸，梅花满枝空泪予。"]},{"t":"秋夜徐编修宅宴别醉歌","f":"古风","c":["徐郎三杯拂剑且莫舞，听我击节歌今古。","曲畏调悲不易竟，天地荧荧月东吐。","燕山八月风力怒，落叶交加映尊俎。","怆时感事百忧集，死别生离同一苦。","身逢累朝全盛日，弘治之间我亲睹。","朝廷无事尚恭默，天下书计归台府。","五陵鞍马速雷电，千官气势如风雨。","却忆年年秋月时，日与尔辈同襟期。","如渑之酒差快意，袒跣呼号百不思。","弦张柱促衣冠祸，综覈崩奔学士疲。","仓皇世事难开口，物极则还理宜有。","羸疾巳分沙田草，遭逢复折都门柳。","富贵在天得有命，人生反覆如番手。","不见去年临别处，吞声踯躅莺求友。","邂逅寒暄不自知，隔绝荣华为谁守。","歌残酒乾天欲曙，门外骊驹巳西首。","哀鸣胡雁亦南飞，露湿群星朝北斗。"]},{"t":"发京别钱边二子","f":"古风","c":["秋风淅淅吹燕山，游子杖剑出燕关。","车脂马饱夜将发，钱边二子来相攀。","此时群星觐上帝，骖鸾翳凤云之际。","君不见牵牛与织女，一水盈盈独流涕。"]},{"t":"东园翁歌","f":"七言古诗","c":["东园翁今六十馀，面常泥垢发不梳。","身藏宝剑人不识，反闭衡门读古书。","此翁十五二十时，欬唾落地迸成珠。","陆机不敢以伯仲，管辂警敏空嗟吁。","生鳞即与蛟龙伍，未汗宁同凡马趋。","尔时射策黄金阙，三百人中最英发。","骅骝举足狭万里，便欲登天揽日月。","岂知德尊常轗轲，独买扁舟泛吴越。","三十年来万事变，富贵于我直毫发。","归来灌园种琼花，荷锄自理东门瓜。","夜眠海月挂丹牖，昼看江风滚白沙。","辽东合有逢萌宅，齐西称睹陶朱家。","北郡李生三十六，摈斥高歌卧空谷。","前辈后辈道岂殊，同坐同行限江麓。","东望东园乱心曲，安得逐尔骑鸿鹄。"]},{"t":"苦热柬屠参议","f":"古风","c":["豫章之热真毒淫，六月巳破仍不禁。","赤云行空日在地，万里一望炎烟深。","东蒸扶桑干欲槁，黑河水乾龙不吟。","院松亭亭我所爱，比遭摧炙无好阴。","纵令跣足欲何往，此地寸冰如寸金。","层檐大厦尚喘喙，矫屋茅堂泪满襟。","滕王有阁高百寻，阁下澄江清映心。","紫薇使者卧其上，卷幔恰对西山岑。","赤脚门子摇大扇，行坐吟哦挥素琴。","几欲往访簿书积，岂我无酒同谁斟。","亭午蕴隆潭水沸，蛟蜃下徙鼋鼍沉，何况走原兽、栖枝禽。","呜呼豫章之热其苦有如此，而我胡为营营与世争华簪。"]},{"t":"豫章遇钟子送赠","f":"古风","c":["豫章八月江势轻，水关行马沙觜平。","闻君缆舟挽君往，向夕恶风银浪生。","顷时收帆万船集，波颠石倒蛟龙立。","中流艓子独何意，欹反犹摇双浆入。","天清未风君巳回，帆色诏迢万里来。","拂衣汉口凫雁乱，击榜南浦芙蓉开。","汉口逢君又南浦，人生聚散风中雨。","黄石公赤松子在何所，君今抽簪我簪组。"]},{"t":"董公衙赏绯桃行","f":"古风","c":["吁嗟董公垂老官不迁，途虽坎坷志不变。","三岁提兵两列衔，此事堪伤亦堪羡。","二月南风捲章水，黄昏西省开芳宴。","刑司军司皆集衙，盆中絩桃俄放花。","董公捋须向客誇，客起环视咸咨嗟。","情酣展转移灯照，酒气扑花花欲笑。","逢人合与世酩酊，衰颜若被春勾调。","君不见玄都观里树，不与武陵源上殊。","时来开落各异地，董公董公今宵与客且倒花前壶。"]},{"t":"得家书寄兄歌","f":"七言律诗","c":["三年路遥消息阻，缄书实冻兄心苦。","鸿雁无愁奋翅难，鹡鸰且暂游寒渚。","时望东湖西日微，雪冬庐岳北思归。","独虞四海干戈满，生别悲伤见面稀。"]},{"t":"寄郑生歌","f":"七言律诗","c":["南康烈风无时休，将归船滞增烦忧。","空城雪埋狐兔走，十日冻合鼍河洲。","庐山咫尺不得往，汝在梁园独予想。","开缄叹恨东游阻，琅玕天姥春空长。"]},{"t":"余邹二子游白鹿书院歌","f":"七言古诗","c":["洞原路冰山径微，二子日游过夜归。","岩宫割刻遍览读，马时跄跌泥在衣。","顷来烈风号季冬，雪霾不见五老峰。","苦心数子守寂寞，我病讲堂虚鼓钟。","二子此行真特奇，异时独往今可知。","虎吟狐啼且不惧，肯使杨朱泣路岐。"]},{"t":"戏赠周纪善","f":"古风","c":["广文先生何为者，十欲出门九借马。","只今徒步襄水滨，衰鬓漠漠常风尘。","凤凰在笯鸡啄食，苜蓿阑干半青黑。","君不见楚筵醴罢暮归来，甑尘妻子无颜色。"]},{"t":"龙沙行别袁生","f":"古风","c":["君不见玉虚观前松，去年冻乾今复生。","树灵力排雷雨会，干大每与蛟龙争。","下有万古不定之龙沙，风滚无时休。","英雄奋发各有时，运至贾贩皆公侯。","腐草尚为萤，何况堂堂七尺躯、万物之灵。","高牙大纛苟不我，石泉白云谁复争。","举眼江汉鸿冥冥，与尔倒此沙头瓶。"]},{"t":"浔阳寄毛君湖口","f":"七言律诗","c":["大江六月凉风发，匡庐清波滚明月。","削出万朵青芙蓉，水底摇动金眼阙。","美人盈盈坐湖县，昏叩石钟曙晞发。","怅望迢迢碧云合，早晚扁舟向蛮越。"]},{"t":"郑生山游归予作此歌","f":"古风","c":["跂予望之六六峰，欲往争柰今严冬。","石林崎岖积雪盛，日中无烟虎豺病。","生也孤往胡所稀，冻攀幽崄探其微。","手皴面黑逾旬归，太室少室何者奇，曾否首阳歌采薇。","北邙逶迤清洛远，天白冰崇伊阙晚。","灞上骑驴尔靡辱，袁安高卧吾应腼。","忽然想生经行宋家陵，往来寂寞东西京，翘首泪下嵩山青。"]},{"t":"丈人行","f":"七言律诗","c":["丈人九十牙齿存，行曳竹杖挈玄孙。","只知灌园同汉阴，何须采药游鹿门。","山房春归碧草萋，蕙帐月白露满蹊。","少微星沈湖水涌，松林夜夜猿啸啼。"]},{"t":"鹤癯子歌","f":"古风","c":["鹤癯子，汝人也，而何为乎鹤形。","美髯修修双瞳青，闭肆夜读黄庭经，晨出荷琛掘茯苓。","鹤癯子，汝岂无万里骨、刀剑翮。","路遥朋寡日云暮，弱水蓬瀛壮心隔。","君不见江中老龙亦高卧，鹤乎鹤乎谁汝那。"]},{"t":"寄殷给事人歌","f":"古风","c":["斑鸠赋形百鸟内，化为苍鹰百鸟避。","秋空万里试一击，洒毛纷纷称鹰意。","回旋簸荡风沙开，海宁光清鸾凤来。","天地炯炯元精回，此以赠君君毋猜。","金陵虽隔黄金台，汝翊紫盖临三台。","飞章御览不十日，道路阒静豺狼哀。","惜昔匹马长安走，殷何徐陆皆吾友。","楚姬娉婷华色并，殷生棱眉独方口。","何郎短小亦不丑，仳离今各经年久。","梦寐犹存上苑花，飘零寂寞西湖柳。","丈夫致身贵不朽，陟要阶华亦何有。","贾谊才名信早知，姚崇相位非难取。","大江滚滚东北趋，群龙霜蛰鼍叫呼。","汝登凤台念老夫，为我致一凤之雏。","我不敢玩亦不敢狎，诚心喂饲毛羽全，使听箫韶翔舜都。"]},{"t":"送田生赴京歌","f":"古风","c":["正月八日天骤黄，大风昼晦沙飞扬。","河水慄烈人不行，鴐鹅鸨雁交踉跄。","黄鹄呼曹厉毛翼，一举横天向天北。","君不见左生北上田生俱，长安走马花九衢。"]},{"t":"送陈冠歌","f":"古风","c":["虎子堕地气巳粗，骅骝汗血自为驹。","陈生垂髫骨即殊，双瞳炯炯唾成珠。","前年汝与计吏俱，承明谒帝未生须。","丈夫志欲日月并，云雨且使蛟龙须。","冬风猎猎吹楚湖，怜汝送母催楚舻。","调?腊尽江门水，戏彩春停汴上都。","忆昔乘骢按南国，汝在诸生独英特。","三秋自阻北飞雁，万里今逢旧颜色。","私计彭宣晚必亲，敢言裴俭前能识。","寒温始知君子厚，杖屦番增世人惑。","匏子柳烟风日和，力疾送子临黄河。","汝亲日望泥全使，老夫拟作琼林歌。"]},{"t":"芝柈行","f":"古风","c":["霜严夜清月在南，灯明酒温客气酣。","铜瓶玉芝铿堕地，客将传玩誇神异。","仰芝把蒂行金杯，苍文古紫当筵开。","巳惊潋滟菡萏动，更诧屈错蛟龙回。","忆芝初出盘精气，云流石立魍魉避。","赤箭琅玕色尽枯，神诃鬼守求非易。","泄秘直遭天地怒，怀珍顾使时人忌。","自从获芝升我堂，琴书几席俱辉光。","晴日徐看瑞气合，炎天每挹仙云凉。","燕山豪士来何方，悲歌起舞宵未央。","芝乎自衒亦太异，顿令四座深林觞。","觞行逶迤月转白，月色芝光巧相射。","酕醄触击玛瑙碎，淋漓迸落真珠赤。","君不见玉屈卮，金叵罗。","珠花绣草枉自艳，停杯听我芝柈歌。"]},{"t":"张将军塞猎歌","f":"七言古诗","c":["将军堂堂七尺躯，虎头昂藏紫虬须。","据鞍笑撚金朴姑，弦鸣仰堕双飞乌。","南平川汉北歼胡，蛇矛卧地刀剑芜。","朔风吹霜塞草落，马腾士奋于狩作。","将军夜令晨步同，碛沙黄黄日色薄。","部下游击五千人，竞时争能各有神。","驱飞翼走入我网，千队万队何駪駪。","气酣前赴逞一决，零乱旌旗倏明灭。","杀气上回灵武云，火烈直透天山雪。","张公觏此番逡巡，红衣白马如神人。","衣也蟠蟒金麒麟，朝廷所赐荣功臣。","拦头报捷者谁子，手提禽兽血满身。","生截罴豹累雉鹑，中军小校额抹巾，见之一骑风起尘。","左射奔鹿右毙豕，更追狡兔趫穷榛。","张曰于乎奚用是，昊天肃杀存至仁。","摐金按节止中野，燖腯炰鲜燕蒐者。","礼乐行军分自严，赏罚正簿谁能假。","何地真收吐谷驼，一卒乃获大宛马。","长城窟冰胡雁稀，轻鼙缓吹诸部归。","悬戟惨淡鸦鸟委，垂鞍碨礧熊兕肥。","少年犹忿杀获微，翻身彀弩追云飞。","我闻蒐狩古侯礼，三驱六御今何以。","缵武虽存于貉文，戒荒合避长扬侈。","将军抹马厉部士，为防西北烽烟起。"]},{"t":"送仝仪宾朝天歌","f":"七言古诗","c":["风吹黄尘暗河甸，行子拍马来相见。","春寒昼阴沙冥冥，九衢散乱花如霰。","自言手捧紫瑶函，驰轺谒帝黄金殿。","甥婿当朝礼觐同，往来遣答犹亲面。","南阳贵人骨固殊，敦亲倍钖明光宴。","八议轻微实惋恻，时情讵识皇心眷。","开函烂熳百色备，龙盘凤曲流云气。","绣女咨嗟洹绪工，体裁吻合三宫意。","吴罗叠雪秪怀赧，南金象齿堪沉避。","自离京国十年馀，每悬金阙忆金鱼。","班行日侍诸王聘，混一曾瞻万国书。","君过上林聊驻车，春风旧树花应舒。","有暇更欲问西湖，扫地垂杨今有无。"]},{"t":"送田氏","f":"古风","c":["寒城野霜鸿嗷嗷，羊肠木零熊豹号。","彼汾沮洳望心劳，葭菼委折风波涛。","山西刑司气何豪，西迈白日行旌旄，七星丸丸明佩刀。","君不见黄河飞云立如盖，一鹗乘之向并代。"]},{"t":"赠郑郎","f":"古风","c":["郎来张拱向我揖，玉树亭亭我旁立。","叩之论语背诵毕，曲礼幼仪汝能习。","黄河柳绵飞欲尽，练水桐花放将及。","汝父昨来今汝归，有琴在抱书在笈。","君不见师山后人代非乏，勉旃无效群儿狎。"]},{"t":"太华山人歌","f":"七言古诗","c":["山人昔居太华峰，结屋玉井餐芙蓉。","夜随金精朝白帝，误挝天鼓撞鸿钟。","帝怒谪之荒江滨，泪添江汉齐朝宗。","阊阖九重豹虎蔽，霜雪十年鸿雁冬。","江边诸山不可眼，梦寐犹跨双茅龙。","有时梦到西嵿坐，环海内物尽么么。","一线黄天泾渭流，拳石白昼岷峨破。","翳凤骖鸾觐玉京，羽节云軿度婀娜。","织女虚无指前路，沐发有盆不借我。","山鬼含笑倚岩立，仰看明星斗如大。","猿啼蛇吟万壑静，山人归来泪交堕。"]},{"t":"相逢行赠刘按察元瑞","f":"古风","c":["一别六年不相见，风尘歘觏刘郎面。","西关官亭车马都，使君骢马朱雀符。","有虔秉钺映交衢，把臂道故情郁纡。","仰视高天白日徂，忆昔同殿含香趋，万事反覆难具铺。","秋风飒飒响枯树，蛟龙立斗黄河怒。","舟子无忧旬浃阻，大夫且试登高赋。","城南柳径梁王苑，庙门书院松林晚。","此时与子临高台，边侯绮席金尊开。","芒砀微云气出没，但见悲风万里从东来。","寒空孤雁叫且哀，鸨鸧鼓翅号其侪。","飞沙激雾相徘徊，愿宾与主酩酊归。","不见昔时杜甫与高李三子者，气压百代今尘埃。"]},{"t":"王郎行","f":"古风","c":["将军开国弓剑传，子孙章甫能朝天。","相国沉冥二十年，怀宝弗售人所怜。","飞缨跃马赫动地，公也视之如浮烟，雅歌日醉金尊前。","生有三男子，不令学剑令青编。","大郎早蹑黄金榜，声名佐郡青云上。","二郎秾郁更英特，掇青拾紫犹翻掌。","三郎年十馀，头颅角崭如。","拱立向人前，解背经与书。","二郎昨别我，云将还故乡。","马蹄驰逐秋槐黄，龙泉出匣光自射，骅骝历块畴能当。","连翩骑从喧皇州，春风紫陌行鸣驺，生儿当如孙仲谋。","于嗟相国胡所忧，浊醪惟恨不满瓯。","听我王郎行，我行还自歌。","何以赠之珊瑚柯，又何赠之玉山禾。","愿郎归，白玉珂。"]},{"t":"郭生行","f":"古风","c":["君不见大梁郭生少小能英奇，生长富贵心寒饥。","兀坐日诵书与诗，下究王伯上轩羲。","郭生有父王国宾，有母食邑称之君。","鲤庭独立犹诗礼，熊胆亲丸或夜分。","生有两男子，大者览辉起，次者郭生鼓翅亦上青霄里。","忆昔匹马走燕甸，长安三月花如霰。","射策曾登金马门，垂衣帝在蓬莱殿。","三十年间万事变，后生衮衮蜚英彦。","结绶初諠东阁宾，弹冠复报南州荐。","太平既极边功开，武帝射蛟江未回。","上林会有誇胡猎，愿生早试长杨才。"]},{"t":"结交行赠李沔阳","f":"古风","c":["古人结交如种稷，今人当路裁荆棘。","世间万事各有极，人生何必相倾仄。","君不见李沔阳五马昨朝天，天冰地裂冲寒烟。","三月不遇见天子，归途困顿心忧煎。","南行波涛值汹涌，蛟龙失势鼋鼍踊。","留滞聊栖梁孝台，醉歌直据侯赢冢。","却忆当年侯未须，识者尽道骅骝驹。","落笔遽掩羽猎作，挺身遂上青云衢。","百战不侯李广辱，一麾出守延之吁。","峡霾光射卞和玉，月明泪迸鲛人珠。","李沔阳，汝无学云梦吞，亦莫效江南哀。","六龙挽车日月轮，万里簸荡风沙开。","弃君舟楫理衔辔，有人物色腾骧材。"]},{"t":"薏苡行赠王氏","f":"古风","c":["南征马援还东都，人言满载皆明珠。","发封视之乃薏苡，群臣失色天子吁。","世情毁誉本好恶，后生轻信迷真误。","暗投固宜明月弃，同居岂免娥眉妒。","自君夙夜歌在公，尊中醴酒常不空。","德尊日见儿孙盛，名成反致谗邪攻。","虽云乔树多烈风，曷有寸雾残高空。","君不见周时吉甫称大贤，孔门弟子推颜渊。","掇蜂拾塺尚见惑，岂我千得无一愆。","君堂有客俸有钱，槐庭偃蹇花含烟。","胡不酩酊金罍前，万事置之休问天。"]},{"t":"徒步东行赠鲍滶","f":"古风","c":["鲍生六月徒步东，久暵赤日昏沙风。","旦行眼眩扶桑红，足疲暮憩空桑中。","帽浥衣沾乾复湿，必逢佳树始一立。","道傍有驴无钱骑，短咏微吟口翕戢。","杜甫遗诗人罕全，鲍生记之将及千。","论工尚恨黄初浅，泥古常卑大历前。","岂知才大番为祟，临岐独下杨朱泪。","盐车虽蒙苴滓辱，长鸣未折风云气。","生今坎坷三十年，同时细估豪熏天。","出门宝马双翩翩，道逢鲍生不举鞭。","生不见五羖大夫歌扊扅，商歌饭牛声夜悲。","贤达困穷何代无，仰视万里浮云徂。"]},{"t":"夏日田居苏生携酒过","f":"古风","c":["疾风六月树枝折，火云累锤白絮裂。","城南老夫正高卧，荒郊款段苏生过。","尘埃满面髸发乱，手携清壶来饷我。","季子才名三十年，射杨百发百叶破。","逢时幸首南宫荐，塌翮尚忍西山饿。","丈夫生世古难同，苏也巷西我巷东。","追寻不计褦襶热，淹留秪恨金尊空。","君不见昨朝雨雷今则风，世事反覆谁豫通。","得时无誇好身手，失意岂必皆愚蒙。","野池纷披莲半红，黄鹂噤语空林中。","劝子尽醉休匆匆，人生几何吾巳翁。"]},{"t":"送人使安南","f":"七言古诗","c":["安南陪臣骑驰突，歌吹春喧洱水窟。","蛟潭飞雨动霹雳，岛城毒云开日月。","黄门使者白泽袍，南来气与秋天高。","当今天子古圣人，谕尔岁事勤包茅，永令炎海无波涛。"]},{"t":"有鹤篇赠翟翁","f":"古风","c":["有鹤褊褼海上来，乘风爰止梁王台。","洪河怒涛野萧瑟，含情顾影却飞回。","十洲来往群仙戏，举身下上随云气。","君不见夜来东海头，南极一星光照地。"]},{"t":"赋得姑苏台送李推官士允","f":"七言古诗","c":["少年何官骑白马，秋日经过古台下。","回瞻远虑意搣促，下马行歌泪盈把。","猗嗟筑此谁为台，千年弃土犹崔嵬。","屧廊娃馆瓦砾积，美人白骨生青苔。","枯蒿虫吟莽飒飒，飞云叫雁双徘徊。","当时金屋玉起楼，岂谓台成麋鹿游。","宝钿黄金裹瑟瑟，雨时濯出樵人收。","李生豪士扶风俦，悲歌久抱流连忧。","世家各读日一过，独废吴越伤春秋。","复思鸱夷气益奋，怒目每送长涛流。","抉眼东门事巳往，兹台再过君休上。","日暝烟波湖水深，范归恐有同行桨。"]},{"t":"送王子归鄠杜","f":"七言古诗","c":["贤兄巳上苍龙阁，令弟犹甘饱藜藿。","膝下虽无一寸绶，腰间常吼千金锷。","骑驴狂走长安市，酣歌击缶白日落。","黄金不成徒自叹，乌裘脱尽那堪著。","道逢石室举鞭揖，谓尔骨相殊不恶。","终南鄠杜豪侠窟，从来意气无京洛。","归家早铸双玉龙，提携来献明光宫。"]},{"t":"赠郑生","f":"七言律诗","c":["狐裘骝马谁家子，往来驰骤尘沙起。","右撚羽箭左把弓，仰射忽堕双飞鸿。","野寒日昏惨惨风，下马揖我立我东。","一箭直西贯杨树，抽身上马入城去。"]},{"t":"石峰子歌","f":"古风","c":["石峰子，昔住石峰山，茅堂岩壑谽谺间。","松孤桂丛白日静，坐玩硊礧聆潺湲。","石峰子，骖鸾觐帝今几秋，狖猿哀啸鸿鹄愁。","顷为四岳振南州，珠崖琼海毒厉收。","丹穴有凤鸣啾啾，愿子早致仪西周，经过旧山莫淹留。","君不见旧山头，葛藟蔽翳寒泉流。"]},{"t":"寄寄庵子","f":"七言古诗","c":["嘤其鸱矣彼何求，天下愿识韩荆州。","心倾义投神便往，万古不废江河流。","张侯崛起西南裔，览辉振翮风云际。","钩陈苍凉阊阖闭，排阍直谒蓬莱帝。","豸冠峨峨不动绅，挺身遂作兰台宾。","窃愤辛裾谓淟涊，誓与朱槛争嶙峋。","巳看騕袅狭道路，复讶雕鹗卑风尘。","霜飞维扬海月苦，阳行沮洳汾花春。","还朝衮衣换日月，立仗正色揩星辰。","行步既工马从瘦，谏草每就鸡将晨。","馀力犹驰翰墨圃，先秦两汉文心苦。","壮志真趫剑阁铭，幽怀缅拟归田赋。","拖珠响玉岂不足，腼面徒餐竟何补。","及时愿作朝阳凤，不然退与渔樵伍。","予也纶竿孟诸客，心本无他众莫白。","李白世人欲杀之，苏轼能诗遭贬斥。","雷剑虽埋光在天，卞玉未剖终为石。","垂老重逢四海清，虚名幸免诸公掷。","思君欲追嵇吕驾，赠言辄践回由迹。","有田负郭不饿死，且自射猎芒砀泽。"]},{"t":"龙仙引赠骆员外","f":"楚辞体","c":["壮士狭四海，万古一大梦。","俗夫醯鸡耳，生死不出瓮。","灭没等蒿草，劳劳竟焉用。","君求勾漏学稚川，往来栖息罗浮烟。","自从异人授丹诀，行也乃作飞龙仙。","左携浮丘右洪厓，樗里景纯执我鞭。","昆崙巑岏倚天外，黄河九曲如衣带。","南支江湖楚蜀汇，北支崄塞华夷界。","少时振衣登贺兰，开眼巳无西北山。","中年谒帝听广乐，曳裾赤于摇天关。","朝揽金台云，夕披玉峰雾。","翔鸾锵锵导前路，左蹲文豹右伏虎。","旌幢旖旎杂翠葆，龙兮龙兮汝虽变化回测慎无使头角露。","祥麟威凤世见希，泄秘尽巧鬼神怒。","深山大泽多戢鳞，龙也穆沕幸自珍。","缑城玉笙两鹤舞，太室珠树三花春。","从兹谢人放浪去，笑跨白鹿乘飙轮。"]},{"t":"送李中丞赴镇","f":"七言古诗","c":["黄云横天海气恶，前飞鹙鸧后叫鹤。","阴风夜撼医无闾，晓来雪片如手落。","中丞按辔东视师，躬历崄隘挥熊貔。","巳严号令偃鼓角，更扫日月开旌旗。","椎牛李牧将士跃，射虎李广匈奴知。","屯田金城古不谬，卖剑渤海今其时。","塞门萧萧风马鸣，长城雪残春草生。","低飞鸿雁胡沙静，远遁鲸鲵瀚海清。","不观小范擒戎日，谁信胸中十万兵。"]},{"t":"雨燕醉歌","f":"七言古诗","c":["迅雷击城鸦欲翻，黑云压天白昼昏。","展席斜对城南门，长安大雨如倾盆。","我马巳世锦障泥，主人况具黄金尊。","睥睨将将下万瀑，龙蛇翻翻动高壁。","出门牛马不复辨，炎雾毒蒸静如拭。","酒酣为君如意舞，夕雨转急风转怒。","秪恐溪壑受不得，海倒江翻亦难测。"]},{"t":"结肠篇三首 其一","f":"古风","c":["哀者且停声，吊客坐在堂。","听我结肠篇，曲短哀情长。","五月廿七吾妻亡，厥明奠之罗酒浆。","其牲伊何豮与羊，痛哉釜鬵结豮肠。","神灵恍忽心骇伤，团圞肉毬出中汤。","左回右盘准流黄，经纬缠纠文阴阳。","底形并字圈两旁，翼翼彷佛双凤凰。","有绥在下累而长，上有提襻五寸强。","汝乎无意岂为此，呼汝欲问魂茫茫。","十呼不应百转咽，肠乎肠乎为畴结。"]},{"t":"结肠篇三首 其二","f":"七言古诗","c":["结肠结肠忍更闻，妾年十六初侍君。","父也早逝母独存，为君生子今有孙。","昔走楚越迈燕秦，万里君宁恤妇人，外好不补中苦辛。","中年得归计永久，命也百病攒妾身。","言乘意违时反唇，妾匪无迕君多嗔。","中肠诘曲难为辞，生既难明死讵知。","千结万结为君尔，君不妾知肠在此。"]},{"t":"结肠篇三首 其三","f":"七言古诗","c":["结肠三阕声更咽，汝肠难解我肠结。","夙昔失意共奔走，汝实千辛我跄跌。","宦归家定今稍宁，岂汝沉绵遽离绝。","魂乎魂乎游何方，儿号女哭周汝旁。","劘心饮泣看彼苍，愚者何寿慧何亡。","伫立逶迤若有望，迫而即之独空床。","梁间二燕哺子急，触落青虫污我裳。","锦衾尘埃委鸳鸯，穗帷中夜风琅琅。","魂惊梦摇中惨伤，阴雨啾唧灯无光。","呜呼此曲不可竟，为君赓歌妾薄命。"]},{"t":"哀才公","f":"七言律诗","c":["仲冬东南天鼓鸣，我军灭胡功可成。","道之将行岁在已，星落辕门悲孔明。","尚书头颅血洗箭，马革缠尸亦堪羡。","夷门野夫国士流，痛哭天遥夜雷电。"]},{"t":"哭新县","f":"七言律诗","c":["苦死可怜灵宝子，有官十数同时死。","四路萧萧人断行，一军尽惊床夜徙。","新民反覆谁不知，性实虎豹佯蝼蚁。","白金綵段纵宽汝，朝廷有问将何以。"]},{"t":"观灯行","f":"古风","c":["宋家累叶全盛帝，宽大实皆称令主。","百姓牛马遍阡陌，太仓米粟忧红腐。","宣和以来遂多事，呜呼烂费如沙土。","海石江花涌国门，离宫别殿谁能数。","群臣谀佞秪自讦，天下骚然始怨苦。","正月十四十五间，有敕大驾观鳌山。","万金为一灯，万灯为一山。","用尽工匠力，不破君王颜。","此时上御宣德门，乐动帘开见至尊。","奔星忽经于御榻，明月初上堆金盆。","倾城呼噪声动地，可怜今夜鳌山戏。","窈冥幻巧百怪聚，金蛾翠管堪垂泪。","借问幸臣谁，云是李师师。","外有蔡京与蔡攸，夹楼锦幄罗公侯，丞相之幄当前头。","奚儿腰带控紫骝，如花少女擎綵毬。","但闻楼上唤楼下，黄帕笼盘赐玉羞。","月高鸣鞭至尊起，幄中环佩如流水。","争道齐驱辇路窄，寺桥窈窕尘埃白。","火树龙灯又一时，千光万焰天为赤。","常言宴安成祸基，从来乐极还生悲。","君看二帝蒙尘日，数月东京荒蒺藜。"]},{"t":"玄明宫行","f":"七言古诗","c":["今冬有人自京至，向我道说玄明宫。","木土侈丽谁办此，乃今遗臭京城东。","割夺面势创巀嶪，出入日月开帡幪。","矫托敢与天子竞，立观忍将双阙向。","前矻石柱双蟠龙，飞梁逶迤三彩虹。","宝构合沓殿其后，俨如山岳翔天中。","金银为堂玉布地，千门万户森相通。","光景闪烁倏忽异，云烟鬼怪芃杳濛。","以东金榜祠更侈，树之松槚双梧桐。","溟池岛屿鰋鲤跃，孔雀翡翠兼罴熊。","那知势极有消歇，前日虎豹今沙虫。","窗扉自开卫不守，人时游玩摇玲珑。","陛隅龙兽折其角，近有盗换香炉铜。","青苔生泥獍面锁，野鸽哺子雕花栊。","忆昔此阉握乾柄，帝推赤心阉罔忠。","威刑霹雳缙绅毒，自尊奴仆侯与公。","变更累朝意叵测，掊克四海真困穷。","长安夺第塞巷陌，心复艳此阉何蒙。","构结拟绝天下巧，搜剔遂尽输倕工。","神厂择木内苑竭，官坑选石西山空。","夷坟伐屋白日黑，挥汗如两斤成风。","转身唾骂阉得知，退朝督劳何匆匆。","人心嗟怨入骨髓，鬼也孰复安高崇。","峨碑照耀颂何事，或有送男充道童。","闻言怆恻黯无答，私痛圣祖开疆功。","渠干威福开者谁，法典虽严柰怙终。","锦衣玉食巳叨窃，琳宫宝宇将安雄。","何宫不镌护敕碑，来者但看玄明宫。"]},{"t":"康郎山歌","f":"古风","c":["君不见康郎山，屹立东湖中。","波涛撼蚀山脚塌，破庙枯木常烈风。","芒砀草昧赤帝出，挥剑遂使凡蛇空。","卧榻之外事亦小，万方有罪惟朕躬。","美姬宝玉归御幄，浮尸蔽江江水红。","发踪刘陶固其力，恐战难言非数公。","秦人枉哭崤函瘗，汉祖轻酬垓下功。","至今有庙此山侧，天阴雨湿时见朱旗白马光如虹。"]},{"t":"乾陵歌","f":"古风","c":["九重之城双阙峙，前有无字碑，突兀云霄里。","相传翁仲化作精，黄昏下山人不行。","蹂人田禾食禾豕，强弩射之妖亦死。","至今剥落临道傍，大者虎马小者羊。","问此谁者陵，石立山崔嵬。","铜铁锢重泉，银海中萦回。","巢也信力何由开。","君不见金棺玉匣出人世，蔷薇冷面飞尘埃。","百年枯骨且不保，妇人立身何草草。"]},{"t":"刘子有金陵之差遂便觐省","f":"七言古诗","c":["使君昔居紫荆关，日登燕峤望吴山。","逢人颜色郁黯黕，对酒涕泗交潺湲。","使君南向金陵去，孤帆夜拂春天树。","旅枕常欹月落时，梦魂先到云飞处。","杨子江头青草斜，大孤山前开杏花。","行人三月重回首，游子一年初到家。","出门烟草满芳甸，凤凰台接麒麟殿。","游陌联翩追宿娱，墨场婉㜻罗宾宴。","人生意气无南北，白马青袍动江色。","即看舣舸石头城，还闻税鞅钟山侧。","钟山崒嵂压秦淮，燕赵风云入望来。","芙蓉秋雁多愁思，问君何日锦帆回。"]},{"t":"送仲副使赴陕西","f":"古风","c":["骢马白玉鞍，长鸣下云端。","今朝发汴水，何日到长安。","孝王台前雪如山，垂杨扫地春风还。","使君不带冰霜色，却带春风入汉关。","相思明月楼，西望古秦州。","河南咫尺不可见，何况千山万水头。","西望秦州是我乡，陇树秦云空断肠。","褰帷杖钺经行地，欲寄双鱼到庆阳。"]},{"t":"徐子将适湖湘余实恋恋难别走笔长句述一代人文之盛兼寓祝望焉耳","f":"古风","c":["峥嵘百年会，浩荡观人文。","建安与黄初，叱咤皆风云。","大历熙宁各有人，戛金敲玉何缤纷。","高皇挥戈造日月，草昧之际崇儒绅。","英雄杖策集军门，金华数子真绝伦。","宣德文体多浑沦，伟哉东里廊庙珍。","我师崛起杨与李，力挽一发回千钧。","天球银瓮世希绝，鳌掣鲸翻难具陈。","洪川无梁不可越，日暮怅望劳余神。","徐郎生长苏台阴，二十作贼雄海滨。","朅来抱玉叩阊阖，长安绣陌行麒麟。","是时少年谁最文，太常边丞何舍人。","舍人飘飖使南极，直穷金马探泸津。","尔虽不即见颜色，梦中彷佛形貌真。","余也潦倒簿书客，诸公磊落清妙身。","大贤衣钵岂虚掷，应须尔辈杨其尘。","休令黼黻怨岑寂，要与琬琰增嶙峋。","海陵先生雅爱士，晚得徐郎道气伸。","乔王款接虽不数，迩闻亦欲来卜邻。","骅骝造父两相值，一瞬万里谁能驯。","都门二月芳草发，御沟杨柳垂条新。","徐郎绾牒将远适，使我旦夕生悲辛。","为君沽酒上高楼，月前醉舞梨花春。","天明挂帆向何处，鸿雁哀鸣求故群。","南登会稽探禹穴，西浮湘水吊灵均。","洞庭波寒木叶下，峡口风急猿啸闻。","司马太史有遗躅，归来著书追获麟。"]},{"t":"龙州歌送沈编修使安南","f":"七言律诗","c":["龙州南接六那溪，白鹇里猿相间啼。","乌蛮滩头苦竹密，伏波庙前春日西。","杨旌走马迎天使，拥节封王壮汉仪。","试向殊邦观礼乐，交南元是旧边陲。"]},{"t":"汉江歌送范子之桂阳","f":"七言律诗","c":["汉江江上鶗鴂鸣，汉江游客无限情。","青山落日下帆影，芳草月明闻棹声。","黄鹤矶头暮云尽，鹦鹉洲边春水生。","莫倚仲宣能作赋，洞庭南接桂阳城。"]},{"t":"孤鹤篇寿豫斋王子","f":"古风","c":["孤鹤无下朋，达人有高步。","出入凌紫氛，翱翔在天路。","白玉城中十二楼，明月夜上珠帘钩。","飒沓歘降万羽节，蚴蟉或见双花虬。","鸟喙者谁发蓬首，问之云是西王母。","玻盘巳进昆崙桃，金壶复泻长生酒。","下视黄蒿鹪鴳飞，争安竞稳一枝依。","垂天更忆扶摇翼，六月谁知变化机。"]},{"t":"聊城歌送顾明府","f":"七言古诗","c":["聊城累累枕桑野，使君怀古聊城下。","龙蛟惨淡七雄斗，当时谁是排纷者。","海东隐沦难见面，平原不见安平见。","巳闻笑却邯郸军，还遣书飞燕将箭。","平生急难轻列侯，功成岂必千金酬。","只今往迹浮云尽，遥瞩沧溟日暮流。"]},{"t":"李进士醉归图歌","f":"古风","c":["谁将一幅雪白绢，放笔横扫黄金殿。","五云飞花白片片，李生胡此开生面。","御河尘昏杨柳暮，彷佛初罢南宫宴。","皇帝龙飞十二春，同时三百登要津。","曹生李生余最亲，曹甥李也传经人。","光耀虽云丈夫末，不闻致君须致身。","自汝白手扣阊阖，想像紫陌行骐驎。","曹留李归事亦变，李生意气图中见。","醉归扶起杏林下，眼花熟人无识者。","飞乌来窥进士巾，游丝故罥誇官马。","即论此马亦有神，画出紫焰方瞳真。","嚼勒齧膝如待人，长行大步不动尘。","络头鞈?纯用银，细巧似织翻江鳞。","汝昔出门驴无骑，曹生共被甘盐齑。","比许欲入周召列，成就耻与萧朱齐。","于乎男儿一旦荣幸果如此，生不报国老空悔。"]},{"t":"郑生画像歌","f":"七言古诗","c":["岩风飒飒树叶赤，秋林紫气丹丘积。","问君胡为坐石根，微吟极望天云昏。","南归舟楫杳将滞，故园花莺当复存。","浚仪张生好作笔，貌尔形似兼其魂。","细模妍描岂乏手，传真水月烟中柳。","意气朗如千里骨，精神合居万人首。","忆昨观君飞射时，弯弧走马实男儿。","更求张笔须传此，欲识豪雄岂啻诗。"]},{"t":"画鱼歌","f":"古风","c":["吕公手持画鱼障，清晨挂我北堂上。","岛屿晴开云荡荡，众鱼出没随风浪，四壁萧萧起寒涨。","嗟此数尺障，天机妙入神。","信手扫绢素，惨澹开金鳞。","濠梁断裂东津远，任公掣钓沧溟晚。","此时天黑众鱼出，鼋鼍徙穴蛟龙返。","或言乘湖万鱼集，细小亦趁云雷入。","只尺波涛有得失，屈强泥沙恐难立。","细观又似洪河风，昆崙既道龙门通。","霹雳殷殷行地中，鲤眼下射盘涡红。","非独一身生羽翼，亦有数子随飞龙。","山根小鱼更无数，鳣鲔昂藏喷烟雾。","美人修竿淇水阔，渔子孤舟洞庭暮。","我生好奇古，览画心不动。","吕公此障谁为之，令我一见神色竦。","想当经营始，笔端万钧力。","五湖齐倾四海立，空窗滚滚拔浪急。","阳侯逆走天吴泣，不然千鱼万鱼何由集。","我闻神怪物，变化不可料，点晴破垣古有兆。","即恐风雷就壁起，饔人挥刀莫相笑。"]},{"t":"林良画两角鹰歌","f":"古风","c":["百馀年来画禽鸟，后有吕纪前边昭。","二子工似不工意，吮笔决眦分毫毛。","林良写鸟秪用墨，开缣半扫风云黑。","水禽陆禽各臻妙，挂出满堂皆动色。","空山古林江怒涛，两鹰突出霜崖高。","整骨刷羽意势动，四壁六月生秋䬞。","一鹰下视睛不转，已知两眼无秋毫。","一鹰掉颈复欲下，渐觉飒飒开风毛。","匹绢虽惨澹，杀气不可灭。","戴角森森爪拳铁，迥如愁胡眦欲裂。","朔云吹沙秋草黄，安得臂尔骑四驖。","草间妖鸟尽击死，万里晴空洒毛血。","我闻宋徽宗亦善貌此鹰，后来失天子，饿死五国城。","乃知图写小人艺，工意工似皆虚名。","狡猎驰骋亦未事，外作禽荒古有经。","今皇恭默罢游燕，讲经日御文华殿。","南海西湖驰道荒，猎师虞长俱贫贱。","吕纪白首金炉边，日暮还家无酒钱。","从来上智不贵物，淫巧岂敢陈王前。","良乎良乎宁使尔画不直钱，无令后世好画兼好畋。"]},{"t":"吴伟松窗读易图歌","f":"古风","c":["仄岩泉流石无数，素壁濛濛起烟雾。","君家屋宇在城市，何以堂上生松树。","侧闻江夏生，气酣扫毫素。","绝笔风雷拔地起，意匠凿天天为怒。","泰山古根生眼前，俄顷缩出徂徕山。","悬萝挂薜袅袅里，复有草舍松之间。","窗间老人鬓发秃，羊翻一编周易读。","空山瑟瑟翠涛激，长干冥冥暮花扑。","远知既巳死，希夷不复作。","青丘石室杳何许，恍然置我此溪壑。","翻愁一夕雷电入，六丁追书上廖廓。","又画石下根，屈曲如老龙，胡奴暝踏孤岩菘。","蓬头赤脚露两肘，月明汲泉山涧中。","却忆前年召画师，江夏吴生亦与之。","短褐垢脸见天子，礼貌虽村骨格奇。","帝令待召仁智殿，有时半酣被召见。","跪翻墨汁信手涂，白日惨澹风云变。","至尊含笑中官羡，五侯七贵争看面。","请观此幅松舍图，黄金失价连城贱。","吴生吴生太气岸，一言不合辄投砚。"]},{"t":"钟钦礼山水障子歌","f":"古风","c":["钟生始学戴文进，后来颇自出机轴。","山林槎枒波漫靡，骨格虽传气不足。","此幅树石差可意，缀得茅堂傍江麓。","连山远势亦可取，转折颇似潇湘曲。","竹屿陂陀九疑隔，苍梧桐庭湿云白。","黄陵美人把瑶草，天寒日暮行空泽。","鹧鸪双飞鸿雁宿，槲树飒飒江水碧。","细看谷口花，又疑武陵源。","孤舟欲往不可得，对此彷佛闻清猿。","亭间更著四老翁，衣冠各异须眉同。","紫芝山深石漠漠，怅望万里来悲风。","人生有形贵自适，我今胡为尘埃中。","观画感事面颜红，有画如此何必工，歌彻目送沧洲鸿。"]},{"t":"赠郭氏画登游快阁歌","f":"古风","c":["昨朝快阁举目无，江湖凭阑二豪俱。","徘徊把杯思欲丹青写之人，则无城中郭，清狂一生弄丸戏洪垆。","方瞳如水霜半颅，展纸为扫登阁图，邑城隐见林木扶。","画我怏阁上，半天风立楼观孤。","急流波涛沸欲动，前山雷雨势可呼。","二豪意态各亦足，彷佛指说荆与巫，回顾东海犹一盂。","是日南风万船集江隅，郭亦画出樯之乌。","精密似跨北海杜，笔力颇凌江夏吴。","江中流云西北徂，又若万里独往朝京都。","我心与客方念此，郭能画之真奇士。"]},{"t":"观序上人所藏陶成画菊石歌","f":"楚辞体","c":["陶生画菊石，老草有笔力。","此石与此菊，今为序公得。","两株徙倚石根前，古石苔藓屈连钱。","复有馀株散在地，平坡杂草青烟绵，回株点缀花翩翩。","含姿弄态不一足，背向纤秾皆可目。","突如大家贵介女，珠翠虽摇气庄肃。","近时名手计汝和，此生笔力方之过。","江东徐霖学画石，效颦差胜王与何。","亦知神品多冥契，下笔巉岩拓高势。","石磊磊兮菊漫漫，清霜古路花斑斑，远意颇类东林山。","东林昔筑莲花台，彭泽攒眉不肯来，归家对菊独衔杯。","序公丛林号白足，不重莲花番重菊。","终然画饼不充腹，何如种向西山麓。","秋林寒芳采服食，煮石炼药亦为得。","爱鹰爱马古有之，不独序公何太息。"]},{"t":"题画二首 其一","f":"古风","c":["雪城阴阴气萧瑟，郑生提画来相访。","面颜戚促意不乐，告我欲买南行舫。","览画指点色惆怅，雨倒江翻拔层浪。","君不见江上蓑笠翁，归迟水逆忧天风。"]},{"t":"题画二首 其二","f":"七言律诗","c":["江寒雨急莽无路，渔人撒网乘烟雾。","鱼虾琐细不直钱，汝休轻触蛟龙怒。","展画见此心中悲，犯崄觅利古所卑。","只今风浪无晨暮，为问安流归者谁。"]},{"t":"张侯藏张翚山水歌","f":"七言古诗","c":["张翚有名成化间，大涂小抹成山水。","树石燥硬笔意古，往往人间落片纸。","此幅粗浅色更枯，或谓非翚出其子。","张侯识鉴天下精，物物如金见沙底。","尔家图画千万轴，素壁高堂安用此。","宁知上智不滞物，牝牡不贵贵者骨。","尺山即如对玄圃，草屋临崖气出没。","崖根林堂颇清迥，远云澹沲开秋岭。","霜萝细纡岩槛暝，昏猿接挂花溪静。","自从去年抛弃官，梦想山游驾江舸。","见此拂衣便欲往，攀缘转玩情无那。","崖亭更著一人坐，斗绝看书树婀娜。","张侯豪旷人共知，敏捷言谈皆胜我。","盐车郁没骐骥弃，蹇拙逢时每相左。","昆崙洞庭不我隔，异时倘结烟霞果。"]},{"t":"画马行","f":"七言古诗","c":["呜呼骅骝不可见，世人任耳不任目。","玉勒金羁满地行，可道中无千里足。","君收此马画者谁，凝豪苦意求其骨。","尺缣飒爽毛鬣动，凌风似欲真驰突。","曹霸画马无此精，拂拭惨澹神气生。","细观决非近代物，印押剥落无姓名，四海只今多战争。","安得此马一敌万，络头骑出千人惊，擒戎破虏任横行。"]},{"t":"西山湖春游图歌","f":"古风","c":["我家挂出西山图，上有西山下西湖，主堂见者怒气粗。","问客何所怒，何得生此嗔。","纵使撑天拄地无比伦，古人局量非今人。","鏬间虽添两秃松，孰与远势开心胸。","银山铁壁皇陵东，彷佛下走追无龙。","一曲一折苦不易，可怜片素腾云气。","落花冥冥万壑静，白日杲杲千岩碎。","森沉不见雷霆仗，照烁尽压金银寺。","回思开疆帝秉钺，燕山突立五凤阙。","锦绣离宫巀嵲入，龙欢水戏沧溟竭。","君不见辇道哀湍泻，松柏摧枯虎出没。","至今守僧住湖傍，琉璃涌动鼋鼍忙。","事关体统画合讳，点缀半露还半藏。","伊昔休沐屡憩此，耳边尚戛金琳琅。","上林花艳何所无，东风只恁吹西湖。","夹岸小杏欲烂熳，骑驴纱帽西郭途，同行康何咸我徒。","秪须十钱买尺鱼，旋挑土荠甘如酥。","朝来青，暮望湖，紫衣行童随挈壶。","大者鼓簧小吹竽，烂醉花下鸟每呼。","汝曹何处吾已翁，十年独看梁园红。","伤心痛定忍复说，回首万事真匆匆。","呜呼故旧离合谁，独无使我不悲堂上图，使我不悲堂上图。"]},{"t":"画竹行","f":"古风","c":["鄢陵王孙称竹溪，手自栽竹堂东西。","巳诧白昼雷雨入，遽使六月秋云低。","王孙拈笔传竹神，不得乃忆能传人。","黄筌异世与可灭，本朝颇数东吴真。","一幅千金掷不惜，有时客来挂之壁。","壁上阶前翠相射，风行琳琅戛摩仄，四座慄慄生寒色。","陂陀沙屿意势远，洞庭木落潇湘晚。","白云悠悠去不返，丛篁寂寞双妃怨。","于乎画形难画心，黄陵鹧鸪啼至今。","月不常盈日中昃，人生何必长悲吟。","堂有佳宾膝有琴，美酒一酌还一斟。","竹溪子，斟竹叶，歌竹枝，醉据玉案吹参差。","左杯酹竹右画师，李乎孔乎吾则谁。","更须名手画六逸，并画王孙逸为七。"]},{"t":"题京口人山水图","f":"七言律诗","c":["青山逶迤如北固，山下彷佛京口树。","茅堂花蹊三月暮，萋萋旧草春游路。","一从画师扫烟墨，客堂日夜流江色。","江色依微带瓮城，游子归魂逗南北。"]},{"t":"题画扫笔成诗","f":"七言古诗","c":["去年得归离江州，七日遂登黄鹤楼。","南风捲江浩呼汹，豗轰欲翻鹦鹉洲。","七泽莽昧不入眼，孤舟屈曲襄河转。","数月巳掷檀家湖，梦飞每到羊公岘。","岘脚山南东道楼，秦川公子醉悲秋。","槛边斑竹古犹活，云石寂寞苍梧愁。","重华驭遥不可叫，白沙黑猿疏树幽。","看图彷佛曾游处，素壁青天汉水流。"]},{"t":"钱选画张果图歌","f":"古风","c":["张翁纸驴真有无，钱也何意传其图。","印记虽明幅断裂，李侯完之亦奇绝。","所恨图尾钱有诗，就蛇添足将无痴。","忆昔翁来集贤院，入宫诏许肩舆便。","一日声名人主动，千年面目吾今见。","帝貌深沉玉榻雄，侍人一异三人同。","汉皇信有瑶池降，秦始枉慕蓬莱通。","玄言未竟铃殿风，寸驴跃出青箱空。","有僮追捉双眼红，此驴䠥?盘当中。","李侯一看一绝倒，每称独苦嗟良工。","细观张翁骨格古，徐福五利宁其伍。","曰嫔真令天下疑，遄归转觉皇心蛊。","长生殿前牛女辰，广寒仙桂舞鸾身。","世间但识申师巧，谁解中条放浪人。"]},{"t":"周文静画雪山图歌","f":"古风","c":["周生雪山世稀见，远水近水一疋练。","玉崖嵚崟插湖脚，粉笔徐移扫高阁。","琼枝铁柯两迥亚，龙鳞犀甲歘参错。","林风飒飒急霰起，白日冰花逐毫落。","天愁地惨意各出，雾合飙回势逾恶。","人言四时冬最难，周生善雪仍善山。","虚堂突立万仞壁，尺素乍转千重湾。","彷佛寒封洛阳道，得无白拥蓝田关。","袁安甘卧几时起，退之遭窜终召还。","倚山亭亭一孤松，仄崖峭壑盘其中。","分毛耸干一何杰，画者有意排严风。","君不见古来梁栋必此物，愿君爱之频拭拂。"]},{"t":"题画山水送人还歙","f":"古风","c":["黄山沙溪杳何许，图之山水无乃是。","轩辕宫、宰相里，山人一出弥荆?。","石林漠漠蹊径苔，霜鹤夜悲猿啸哀。","红颜踪迹半湖海，白头览画思归来。","溪头系一船，画师本无意。","宛如倦游者，无复舟航事。","水云迤逦山云高，静定方知动者劳。","回思少日欢娱地，至今梦寐犹波涛。"]},{"t":"寿兄图歌","f":"七言古诗","c":["猗嗟我凤生三雏，二雏成立少者殂。","为巢抱卵两不易，自挺独立身羁孤。","兄既躬耕浊河岸，弟亦塌翅青云途。","儿长女大愿各足，鸡肥酒熟时相呼。","仲氏吹篪埙者伯，兄今六十我半百。","敢言意气激隤俗，要使纷纷睹标格。","大梁张路固好手，湖州生绢照眼白。","当堂掉臂扫丹墨，倏忽老面开生色。","盘松葳蕤杂花远，云屏石几文茵软。","灵芝底出琅玕瓶，蟠桃突磊琉璃椀。","鹤行昂藏疑欲啄，复缀山麋意逾宛。","大公乌纱微俯身，中心爱弟爱复亲。","次公氅服青罗巾，傍兄袛顺情性真。","壶陈爵设即未举，俨如酬劝言辞谆。","其言伊何怀二人，飘风烈烈吹三秦。","衔悽西望道路阻，高丘莽杳狐兔邻。","又如自叙伤夙昔，衰暮安宁思苦辛。","季冬十日兄生日，今日天开皎日出。","长裾珠履坐上满，剥羜椎牛酒盈室。","此时此图挂之壁，观者嗟咨黯如失。","二公揖逊恰相向，回看乃在画图上。","骨法形神各不疑，舆台缉御俱惆怅。","逶迤拂拭诸欲动，展转顾惜嗟宗匠。","瓶中梅菊谁致女，倒映芝挑故相荡。","韡灼真回绮席春，芳香解溢金罍鬯。","兄今健饭犹廉颇，丹砂我炼寻黄婆。","复闻张生善山水，买绢请扫青嵯峨。","嵯峨一扫一千幅，一年一幅南山歌。"]},{"t":"登天池寺歌","f":"古风","c":["庐山绝顶天池寺，铁瓦为堂白石柱。","传言周颠劳圣祖，天眼尊者同颠住。","崄绝下阚无底壑，屈曲穿缘惟一路。","顷属秋晴强攀陟，俯之四海生云雾。","岷峨累垂西向我，杳杳长江但东注。","君不见寺东崖石镌竹林，穹碑御制山之岑。","周颠胡不留至今，周颠胡不留至今，虎啼日暮愁人心。"]},{"t":"御制庐山周颠碑歌","f":"七言古诗","c":["庐山绝顶白鹿台，上有御制周颠碑。","石龟下蹲高结螭，天葩震烈云汉回。","文古两汉仍过之，忆昔草昧龙虎斗，黄旗紫盖颠能知。","颠也似真还似痴，帝非感悟宁用兹。","百年势移功渐泯，碑亭毁裂将及碑。","诃持白昼鬼神泣，光耀天阴雷电随。","先朝虽允僧奏劄，修葺其如归有司。","有司有司颠莫疑，试看碑文碑后诗。"]},{"t":"游栖贤桥歌","f":"古风","c":["雷泉峡激石巃嵷，日湍山陷回光动。","吁嗟此壮观，万古谁为开。","涡黄潭黑窈莫测，秀黛碧玉何崔嵬。","人言窟底有龙卧，气吐白昼常风雷。","去年重九登吹台，翘望名山思袅娜。","今年今日谁料吾，醉踏穷山蹑礧砢。","拂衣欲上万仞壁，濯缨还就孤崖坐。","秋风吹林猿狖语，浮桥横空袅相拄。","岚寒细飘瀑布雪，峰云破碎芙蓉裂。","金芝瑶草真有无，缥缈仙灯暮明灭。","君不见此桥今千年，谷冷迹绝无人烟。","岩劖苔蚀石漠漠，太白紫阳俱我前。","对此不须更惨怆，明朝且上香炉巅。"]},{"t":"怀玉山歌二首 其一","f":"七言古诗","c":["怀玉之山玉为峰，四面尽削金芙蓉。","东风破碎瀑布落，有潭十八龙为宅。","山头草堂开者谁，斩木通道余心悲。","白猿啸雨岩竹裂，石路上天风树吹。","我闻龙乃变化物，群然卧此龙何为。","胡不滂沱惠下土，一洗四海无旌旗。"]},{"t":"怀玉山歌二首 其二","f":"古风","c":["君不见怀玉山，山七盘，盘盘上无极。","阴霾白日崖洞黑，隆冬雨路谁来得。","稻田月池山上头，半天有地今我游。","石坛剥落古佛弃，木落俯见东岩湫。","湫中巨鱼长如人，红眼射日翻金鳞。","天台桃源在何许，采药避秦此处吾告汝。"]},{"t":"铁柱引","f":"七言古诗","c":["豫章古城牙城南，何年凿井置铁柱。","井深江通没不见，时寒水涸始一露。","玩之非石亦非铁，孤立差牙若枯树。","人言旌阳锁水母，此语荒唐奚所据。","或云藉此压江涛，兹理或有谁者劳。","顾今伏腊尽奔走，归美真君瑶殿高。","金灯翠旗日来御，雕阑玉槛围周遭。","俗论纷纷不须辨，秋风日暮尘满县。"]},{"t":"快阁引","f":"七言古诗","c":["四月月圆登快阁，天半晚窗雷雨入。","邑中上客携酒至，欧阳罗子咸来集。","去年为阁初筑台，我时登之雷雨来。","神明似有两岁约，晴雾歘值千山开。","千山回转江中流，徙倚阑干增暮愁。","夕日下看衡岳破，波涛左顾匡庐浮。","苦思昨年生盗贼，大江南接江之北。","烽火遥连海岱红，杀云眼见鄱阳黑。","斯邑汹汹今始安，我今对酒能不宽。","诸君稍减般移苦，百姓新回种植欢。","北风江涌月东来，更说夙昔俱停杯。","阴晴仓卒不自料，万事恍惚谁能猜。","潢池暂殄干戈衅，向隅犹抱疮痍哀。","劝君置此勿复道，放歌且与云徘徊。"]},{"t":"九江陆还南康望东林","f":"七言律诗","c":["匡庐山北东林寺，前年八月游曾至。","只今马出莲峰道，西望东林但缥缈。","风吹槲栎猿昼啼，却忆石门临虎溪。","旧听石濑尚在耳，雷烧碑树今应死。"]},{"t":"观水帘泉歌","f":"七言古诗","c":["水帘瀑布人罕至，三级背悬五老峰。","涧石嵯岈路险涩，深窟风草吟蛇龙。","自从开辟藏难见，可怜彼暴蒙称羡。","走势天晴万古雷，流光壑暝常留电。","乱峰云走白日微，玩罢催君及早归。","鬼神忌才亦好静，恐有骤雨沾裳衣。"]},{"t":"杨花篇","f":"七言古诗","c":["洛阳三月东风起，杨花飞入千门里。","只见朝萦上苑烟，那知夕逐东流水。","苑烟流水无休歇，暖日轻盈度仙阙。","赵女瑶台贮綵霞，班娘团扇啼明月。","綵霞明月几沉辉，陌上行人乱扑衣。","征夫柳塞愁看雁，少妇香闺懒上机。","柳塞香闺万馀里，草色连天度陇水。","玉门关外雪犹飞，章台树里风先起。","谁家浪子千金马，平明挟弹章台下。","头上罗巾玳瑁簪，腰间宝铗珊瑚把。","踏絮来寻卖酒家，特香坐调当垆者。","当垆美女怨阳春，笑掇杨花衬绣裀。","青楼薄暮难消遣，白雪漫天愁杀人。","冥冥漠漠春无极，此时惟有杨花色。","一朝风雨蘼芜烂，独掺垂条三叹息。"]},{"t":"明星篇","f":"七言古诗","c":["明星出地一丈高，天门沉沉鱼钥动。","沙堤露下玉珂寒，直庐鸡唱金莲重。","千门万户晓钟发，明星渐高河渐没。","灿烂疑侵翔凤栖，依稀故抱飞龙阙。","凤楼龙阙带曾城，翠辇朱衣夜夜行。","黄昏竞奏催花宴，天明犹听打毬声。","兰烟桂火煇如日，明星迢迢照不入。","百子池头青草生，长信宫中紫苔集。","草色苔香秋复春，此日乘槎若问津。","明星晓落宵还见，白发黄金愁杀人。"]},{"t":"汉京篇","f":"古风","c":["汉京临帝极，复道众星罗。","烟花开甸服，锦绣列山河。","山河自古称佳丽，城中半是王侯第。","峻阁重楼夹道悬，云房雾殿森亏蔽。","牧豚卖珠登要津，樊侯亦是鼓刀人。","时来叱咤生风雨，奄见吹嘘走鬼神。","平津结兄盖侯弟，杯酒相看何意气。","执鞭尽是虎贲郎，守门不说长安尉。","长安烽火入边城，挺剑辞君万里行。","去日千官遮马饯，归来天子降阶迎。","朱弓尚抱流沙月，宝铗常飞翰海星。","不分燕然先勤石，直教麟阁后标名。","岂知盛满多仇忌，可惜荣华如梦寐。","第宅田园夺与人，丹书铁券成何事。","霍氏门墙狐夜号，魏其池馆长蓬蒿。","三千剑客今谁在，十二珠楼空复高。","后车不戒前车覆，又破黄金买金谷。","洛阳亭榭与山齐，北邙车马如云逐。","阴郭豪华真可怜，云台将相珥貂连。","当时却怪桐江叟，独著羊裘伴帝眠。"]},{"t":"去妇词","f":"七言古诗","c":["孔雀南飞雁北翔，含颦揽涕下君堂。","绣幕空留其菡萏，罗袪尚带双鸳鸯。","菡萏鸳鸯谁不羡，人生一别何由见。","只解黄金顷刻成，那知碧海须臾变。","贱妾甘为覆地水，郎君忍作离弦箭。","忆昔嫁来花满天，贱妾郎君俱少年。","瑶台筑就犹嫌恶，金屋妆成不论钱。","重楼复道天中起，结绮临春照春水。","宛转流苏夜月前，妻迷宝瑟烟花里。","夜月烟花不相待，安得朱颜常不改。","若使相逢无别离，肯放驰波到东海。","薄命难交娣姒知，衰年恨少姑嫜在。","长安大道接燕川，邻里携壶旧路边。","妾悲妾怨凭谁省，君舞君歌空自怜。","郎君岂是会稽守，贱妾宁同会稽妇。","郎乎幸爱千金躯，但愿新人故不如。"]},{"t":"荡子从军行","f":"七言古诗","c":["胡兵十万起妖氛，汉骑三千扫阵云。","隐隐地中鸣战鼓，迢迢天上出将军。","边沙远离风尘气，塞草常萎霜露文。","荡子辛苦十年行，回首关山万里情。","才闻突陷贤王阵，又遣分围右校营。","纷纷铁骑朝常警，寂寂铜焦夜不鸣。","沧波积冻连蒲海，雨雪疑寒遍柳城。","地分玄徼指青波，关塞寒云本自多。","严风凛凛将军树，苦雾苍苍太史河。","扬麾拔剑先挑战，征旆凌沙犯霜霰。","楼船一举争沸腾，烽火四连相隐见。","戈文耿耿悬落星，马足骎骎拥飞电。","终当取骏效先鸣，岂暇论功称后殿。","征夫行乐践榆溪，倡妇衔怨坐空闺。","蘼芜旧曲终难赠，芍药新诗岂易题。","池前怯对鸳鸯伴，庭际羞看桃李蹊。","荡子别来年月久，贱妾空闺更难守。","凤凰楼上罢吹箫，鹦鹉杯中临劝酒。","同道书来一雁飞，此时缄怨下鸣机。","巳剪鸳禽帖夜被，更薰兰麝染香衣。","屏风宛转莲花怅，窗月玲珑翡翠帏。","个日新妆如复罢，秪应含笑待郎归。"]},{"t":"沈大夫行","f":"古风","c":["沈大夫，遗我以凛冽玉壶之冰，报汝以离离朱瑟之绳。","绳以发凌云绝响之妙曲，冰以涤卓荦硊礧之清膺。","此曲可以崛地懿、扬天经、宣融风、召遐龄。","奏之敬姜室，允宜轲母庭。","沈大夫，奉诏且还家。","松江鲈鱼白跃玉，土居斫笋如斫麻。","烹羊击鼓会亲戚，太守长吏争趋车。","猗乎嘉哉，男儿生不显亲，譬如锦衣夜行，虽贵何足誇。"]},{"t":"雪山歌送万子","f":"楚辞体","c":["雪山高哉峞乎岌兮吾不知，几千万仞但见云峰之崔巍。","岩冰陵竞缟壑，荧石皛皬而崒嵂兮，悬猱不得度，飞乌何由回。","大峰如老翁，冕佩凌紫埃。","诸峰似儿孙，罗列芙蓉开。","江日汹涌地轴动，孤光倒曳生奔雷。","岌乎峞哉雪山之高不可以攀陟，斧斤不入松柏如麻。","霜干翳蔽，云根槎枒。","渗膏结苓实，轮囷走龟蛇。","君今策驷过其下，车徒滚滚如飞沙。","何不斸取松下苓，献之堂上翁，上以介寿考，下以召祯祥。","噫吁戏，雪山之高吾不可得而名，惟有峨眉玉垒万古遥相望。"]},{"t":"广州歌送罗参议","f":"楚辞体","c":["丽哉遐乎广之为州兮，辟炎区奥雄跨乎南陲。","天作五岭奠玄武，排空下走何崔嵬。","拓邦几千祀，浩荡人文开。","秦还汉往不复识，但见古城苍苍生绿莱。","上则盘冈曲丘龙蛇虎蹲，其下膏场绣浍晻暧而渟洄。","水银丹沙布平地，珍错奚翅犀与瑰。","夷舲贾舶竞追逐，白首浩淼谁曾回。","土产之异尚如此，何况四民者挺然参三才。","君今绾牒向南去，清风吹袂心悠哉。","峥嵘五羊城侧有千尺台，曩昔闻君坐其上醉睨沧溟如一杯。","是时榕蹊雨初霁，茉莉霜成堆。","君尝梦游而神适兮，岂知七载还复来。","男儿成名贵及早，英雄多少埋尘埃。","羡君青鬓结明主，出参方岳声如雷。","金章紫绶不可以幸致，如君者谓非历块之龙媒。","罗浮三千六百丈，矹律倚穷隈。","巨鳌戴之与波下上，三十五莲峰照耀云中辉。","群仙跨飞龙，流影乱岩霏。","我欲从之叹无术，送君翘首空徘徊。"]},{"t":"冰车行","f":"古风","c":["黄门飞鞚西北趋，白马如龙血如珠。","万人齐呼冰窖开，大车小车如山来。","但见风行九市陌，宁知玉积五侯宅。","道傍暍士僵阑干，唇乾口燥真大难。","侯门晏罢夜乌起，朱残粉落明星里。","君不见积冰花作堂前水。"]},{"t":"盐井行","f":"古风","c":["山头井乾生棘蒿，山下井塌不可熬。","官司白牌促上庾，富家典牛贫典女，谁其使之华阳贾。","华阳贾子多少年，拥金调妓高楼边。","夜驰白马迎场吏，晓贯青丝还酒钱。","君不见场吏乘酣气如虎，盐丁一语遭箠楚。"]},{"t":"清夜引","f":"古风","c":["桂魄团团霜兔泣，玉龙夜吟冰喉涩。","仙人起踏白芙蕖，手撚一枝珊瑚株。","伏猊香喷红?毹，蜡凤啼春虾捲须。","九华丹焰夺行月，五虬轹云声轧轧。","银筝翠管声咿哑，繁讴杂舞欢意匝。","盘中紫枣大于瓜，谁其擎之萼绿华。","双桂逶迤头两丫，密情芳绪芳且嘉。","琼城夜半重重闭，偷桃小儿安得至。"]},{"t":"顾侯寄陈留公砥柱障子并诗予为作歌","f":"古风","c":["东吴顾子相公客，扫绢画水复画石。","天冲地击河怒号，嶷嶷一柱当洪涛。","突立固知气势稳，鼓荡转见孤棱高。","淋漓新题墨犹湿，封缄远寄心诚劳。","昔公平章握军国，执义委有排山力。","甚哉赣如汉汲黯，老而纯过唐师德。","言违谏阻去何决，群倩众怒不动色。","同时门客顾最亲，隔绝梦寐怀伟人。","峨峨砥柱公实伦，顾也歌之情句真。","画者谁子笔更新，数尺绢面开嶙峋。","遂令观者重回首，堂上恍忽河声吼。","嵚岒若遘虎豹踞，蹙沓似睹蛟龙走。","奇怪常虞霹雳夺，孤危定遣神明守。","君不见鳌极有时臲，昆崙有时翻，柱乎柱乎永且安。"]},{"t":"雷电行赠宪卿何公美其伐也","f":"七言古诗","c":["黄尘蔽日贼大战，元年年除夜雷电。","我军后之天威前，一鼓破贼淮阳川。","昨者此贼生齐东，眼中久巳无河嵩。","渡河转战势果炽，长矛健马六石弓。","睢陈飞刃昼接白，亳颖劫火宵连红。","一路生灵喂饿虎，中原杀气回春鸿。","于时中丞秉钺出，誓不灭贼如此日。","三军素壮元老猷，诸将咸遵丈人律。","孔明纶巾不离首，羊祜轻裘仅掩膝。","精采遽增朱雀帜，运用或参白猿术。","陷阵直如风扫叶，追北譬之蜂就蜜。","二月朔日振旅归，夹道桃花照铁衣。","倾城尽出牛羊犒，父老争迎锦绣旂。","喜气真随阳气发，愁云化作轻云飞。","捷闻天子喜动色，满朝誉公降褒敕。","白金绮缯宁足酬，异日凌烟看画墨。"]},{"t":"送儿诗四首 其一","f":"七言绝句","c":["冬至至后风愈严，野冰皓皓霜冻髯。","河澌日昏不易涉，孤剑匹马慎汝楫。"]},{"t":"送儿诗四首 其二","f":"七言绝句","c":["北风萧萧狐裘薄，蔽堤立马劝汝酌。","汝伯煨酒友奉盂，路人不行为踟蹰。"]},{"t":"送儿诗四首 其三","f":"七言绝句","c":["壶乾日斜客子发，臂弓上马意气勃。","斩蛟擒虎及汝时，我幸健饭无父思。"]},{"t":"送儿诗四首 其四","f":"七言绝句","c":["平生自许万言书，今往谒帝承明庐。","春风走马未为得，下有管乐上契稷。"]},{"t":"边马行送太仆董卿","f":"七言古诗","c":["治贤在朝乱在野，唐虞圉牧皆贤者。","国君之富马为急，次者仆卿首司马。","汉人五郡开河西，中土始间胡马嘶。","此马硊礧一直万，黄金宁轻璧可贱。","夺骏曾空大宛国，按图径上长安殿。","苜蓿虽誇近苑春，荆榛谁记沙场战。","致远番归草木功，清芽秀味走胡骢。","三边尽跨连钱种，六苑群嘶污血风。","人亡世殊霜雪急，草豆萧瑟马骨立。","骅骝气丧甲士苦，长城窟寒鸿雁集。","朝廷每勤西顾忧，四岳拜手推董侯。","攻驹暂出薇花廨，揽辔远过葡萄州。","行卿官冷心不冷，固知董侯今伯囧。","碛沙日黄云锦乱，徵侯定上金华省。"]},{"t":"风沙篇送王生北行","f":"七言律诗","c":["颠风吹沙江海波，汝乘玉驷超天河。","豫章千寻势自稳，黄鹄万里谁能罗。","我逾五旬须尽白，日采山精炼白石。","临分赠汝一粒丹，愿言宝之勿轻掷。"]},{"t":"赠张帅","f":"七言律诗","c":["张侯五十彀强弩，遇敌控马气如虎。","年来威坐都统衙，境内盗息无尘沙。","自言少壮从征虏，北扫朔漠南闽楚。","暇时勤出射云鸿，古来矍铄成大功。"]},{"t":"赠鲍帅","f":"七言律诗","c":["苍鹰自与凡鸟异，虎子堕地食牛气。","鲍侯三十名誉成，才猷吐布千人惊。","只今塞上风尘起，朝廷拊髀思颇李。","君之寮寀皆英奇，同升早勒燕然碑。"]},{"t":"白河篇送李南阳","f":"古风","c":["白河日赤沙吐云，人喧吏閧迎神君。","三月万花拥车入，满城竹马儿童出。","君昔坐郡襄汉东，气势三楚生雄风。","擿奸无论汉张敞，秉义直到唐梁公。","霜飙偶折奋翅鹗，日月竟照凌云松。","铁干久拟作隆栋，剑翮即暑追飞龙。","空同老儒不君识，倾盖逢之喜动色。","论文开口夜尝旦，愤事扼腕昼遽黑。","南阳虽迩路终隔，音书易通见难得。","我欲扳君数日住，南民望之馁待食。","君心透彻皓如玉，壶之清冰君材磊。","落岿如万仞之立壁，高议足以排山岳，伟文足以华人国。","只恐兹邦难久留，汉庭来徵郭细侯。"]},{"t":"汴河柳送沈生","f":"古风","c":["汴河柳，袅袅拂也长，雪花风起春飞扬。","送君立马古堤口，踟蹰劝尽黄金觞。","有车辚辚官道旁，辕驹喘啑何彷徨。","于中岂无神骏骨，伯乐不遇谁为彰。","人生富贵信有命，英雄仰面高天苍。","高天苍，饭牛牧豕皆腾骧。"]},{"t":"王孙馈冰诗以酬之","f":"七言律诗","c":["流金毒日赤堕地，忽有冷色寒人心。","谁敲水晶迸大壑，力剖冰井开重阴。","高盘礧堆久不化，老齿瀺灂差能禁。","安得移之白绕座，一尊一酌还一斟。"]},{"t":"赠赵将军","f":"七言古诗","c":["丰沛之间河乱走，汹汹之势成陂薮。","大船愁浅小愁贼，贼船如飞苇滩黑。","自从将军镇东土，昼夜人行路不涩。","将军本是将门种，躯干堂堂万人勇。","入山缚虎百兽慑，赤手批蛟色不动。","射杨叶尽矢亦尽，始知百发还百中。","武宗见之屡凝顾，戟郎遽拔千夫总。","英雄自古不下人，将军献策况有文。","骅骝暂蹙历块足，雕鹗竟上横秋云。","世情金多位乃高，图名交结须贤豪。","将军无钱自树立，于人傲气但长揖。","挤出事体虽云垂，威势我喜行河淮。","黄流稳帖遁鲸鳄，白日光彩收狼豺。","大同反刃血未乾，甘州磊卵人心寒。","荐书何由至天子，拜将早筑黄金坛。"]},{"t":"赠胡石陵","f":"七言律诗","c":["世情认假不认真，脂粉罗绮登上嫔。","娥眉入室众女妒，辛苦年年织纨绔。","织成进君冀君怜，腐草回日光在天。","荆山石中抱神异，气如白虹勿轻弃。"]},{"t":"赠沧洲道人","f":"七言律诗","c":["沧洲道人年半百，颜如渥丹发不白。","饥餐玉芝坐双凤，渴收石髓煮金液。","海月西照宁仙桥，道人桥头吹紫箫。","夜半鸡鸣日毬跃，扶桑滚滚生红潮。"]},{"t":"送李帅之云中","f":"七言律诗","c":["黄风北来云气恶，云州健儿夜吹角。","将军按剑坐待曙，纥干山摇月半落。","槽头马鸣士饭饱，昔无完衣今绣袄。","沙场缓辔行射雕，秋草满地单于逃。"]},{"t":"赠张生","f":"古风","c":["男儿三十骨格成，贫贱富贵皆天生。","张生广额日月角，自幼勤书饱文学。","十年雌伏人不知，一日雄飞动河岳。","君不见宋朝宰臣云姓周，少时坎坷风尘游。","偶然夜梦更美须，泥蟠遽尔行天衢。"]},{"t":"送王封君还四明","f":"古风","c":["季札如鲁请观周，子长足迹半九州。","向平且然志五岳，谁肯龌龊终一丘。","封君昨年出吴越，长啸梁园醉秋月。","春风垂杨绾不住，便复归山采薇蕨。","鉴湖花开云锦浮，凫鹥前导红莲舟。","餐霞坐收赤城气，晞发卧看扶桑流。","古云徐卿百不忧，君亦滚滚生公侯。","君不见大郎绣衣昔持斧，声名赫赫今台府。"]},{"t":"何仪宾生日赠歌","f":"七言古诗","c":["宾客白马黄金鞭，入门长揖皆峨冠。","堆冰五月窗阁冷，风帘碧簟光琅玕。","主人平生贵然诺，季布一言重山岳。","人闻杜良数郡至，坐无车公众不乐。","列筵解带罗庶羞，万年为寿千金酬。","向夜铜槃灼绛蜡，凤笙龙笛何啾啾。"]},{"t":"七夕赠王昌程诰","f":"古风","c":["橘酒椒羊召朋侣，拟向今宵看牛女。","雨来飒飒枫林秋，张灯促燕开东楼。","王侯既驾铁马立，前驱北首旌旗湿。","程生贾棹亦欲归，长江南望云飞飞。","人生去住料岂得，一日同欢有南北。","君不见双星一水意脉脉，转眼阴晴不可测。","且倒金尊浇我万古之胸臆。"]},{"t":"再送沈生","f":"七言古诗","c":["去年酌汝池莲红，今年酌汝黄菊丛。","秋风飒飒吹枯蓬，飘转向西忽复东。","世情敬贵不敬贤，黄金不多人不怜。","如脂白玉隐在璞，孰肯剖致君王前。","白河马归玄雁起，南阳宾客梁园比。","送君高歌枚子篇，脩竹团栾夹池水。"]},{"t":"画鹰歌赠鲍帅","f":"七言律诗","c":["鸷鸟决眦如愁胡，猛将气每吞匈奴。","自将黑鹰挂堂壁，百鸟窥之不敢呼。","安得此鹰生即起，击鬼擒狐日千里。","将军弯弓骑紫骝，一箭射天落旄头。"]},{"t":"岁暮四篇 其一","f":"七言古诗","c":["天霜草枯风波涛，思心恐惧贤心劳。","群聚饥兽野鸣号，高飞路逆鸿嗷嗷。","有狐河梁閒且得，冰行绥绥柰尔曹。"]},{"t":"岁暮四篇 其二","f":"七言古诗","c":["百骑横矛自提刀，我军菜色马猬毛。","谁谓河广不容舠，北旗猎猎风黄蒿。","可怜十羊杭一虎，尘沙暗河暮淮浦。"]},{"t":"岁暮四篇 其三","f":"七言古诗","c":["长风烈烈吹山寒，有松瑟瑟山之端。","铺蕤布荫芘小草，霜势雪力莫可干。","皋兰畹蕙日摧陨，美而不遇良可叹。"]},{"t":"岁暮四篇 其四","f":"七言古诗","c":["枯蓬飞沙原野昏，律穷物惨生意存。","尚夕气严扃我门，霜白月冻啼夜鹍。","围炉煨芋啖浊酒，有话细与妻儿论。"]},{"t":"徒涉叹","f":"古风","c":["两山欲交水断破，洪川无梁日渐堕。","徒涉纷纷江复深，鼍喧龙斗真愁心。","无言既济平安子，得路回看转不禁。","君不见岸风翻翻卷瓠叶，皇天倘赐筑岩楫。"]},{"t":"松泉子歌","f":"七言古诗","c":["颠崖嵚岑撑一松，铁干屈曲如老龙。","精灵岁久发光彩，寒蕤古翠芙蓉峰。","石泉清冷日漱洗，汨滵瑟飒松风里。","山人何年住其侧，手斸茯苓煮泉水。","近来潇洒落风尘，卖药救世能通神。","我劝山人且勿归，金鎞玉匕行阳春。"]},{"t":"飞星篇","f":"七言律诗","c":["十月廿七昏尚坐，一星出垣斗如大。","碎光万点长烛天，轩牖尽明向西堕。","俗子蒙头不读书，鲁人钟鼓拜爰居。","天道悠悠谁复知，世间鱼目为明珠。"]},{"t":"吟思翁","f":"古风","c":["吟思翁，翁我思。","苍松碧梧世希有，海月红云如见之。","孤鹤引唳，志在万里。","吞舟之鱼，岂游涔水。","嗟嗟噫嘻，我思者翁，翁思者何，停云日暮沧溟波。"]},{"t":"钤山堂歌","f":"古风","c":["先生昔随玄豹住，丹壑冥濛日烟雾。","先生今与赤龙飞，南望碧山空翠微。","茅堂苍苍云气入，囊琴锁户阴阴湿。","沚兰沙温春鸟暮，庭松月清夜鹤立。","君不见山下石，峞?千尺矶，经年不钓苔成衣。","玉琪羊裘各有分，可问王孙归不归。"]},{"t":"题张路松鹤障子赠豫斋翁","f":"七言古诗","c":["张路画松气英杰，老根崭岩干屈铁。","风毛瑟飒似欲动，高堂六月生霜雪。","树根倚坐者谁翁，面颜恰如十五童。","玄笔涂抹遽成鹤，昂藏意欲凌云空。","问翁自言不记岁，曾与太古鸿濛戏。","食桃落核昆崙坳，桃长今与昆崙高。","桃也开花复结实，东方小儿窃其七。","此论荒唐旧所闻，画笔画出真如神。","愿将仙品投仙侣，常作乾坤不老人。"]},{"t":"和母太夫人八十寿歌","f":"七言古诗","c":["遐龄可得不可必，有儿能贤百当一。","夫人今年岁入十，发霜鬓雪晴如漆。","早起晏卧思虑周，盐豉醯酱咸经眸。","儿妇孙妇罗前头，跪进美酒兼珍羞。","曾孙耍马气食牛，夫人抱弄百不忧。","秋清风凉露欲白，大带峨冠满堂客。","坐中谁老谁最故，感触停觞念畴昔。","回思和李通家始，夫人红颜我童子。","修短悲欢各不齐，五十年来一弹指。","长辈幸有夫人存，母寿儿贤萃一门。","词人特献南山笔，贺客争开北海樽。","买屋我欲为比邻，桑麻地接如云屯。","年年再拜萱华侧，孰谓今少朱陈村。"]},{"t":"沐浴子","f":"五言古诗","c":["玉盘两鸳鸯，拍拍弄兰汤。","振衣馨香发，弹冠有辉光。","岂念蓬首女，含情怨朝阳。"]},{"t":"怨歌行","f":"五言古诗","c":["汉主十离宫，凉至花尽歇。","面面窗玲珑，烟纱印秋月。","天公顾我笑，手弄双玉玦。","但笑不肯留，去若流云没。","忧来抱团扇，扬颦望丹阙。"]},{"t":"少年行","f":"五言古诗","c":["白马白如雪，银鞍耀明月。","骑出青云楼，挥鞭向金阙。","自言事武皇，出身为椒房。","结交乐通侯，擅名斗鸡场。","尚主复赐第，轩盖一何光。","被酒过都市，杀人如剪蒿。","左殪南山虎，右斩北溟鳌。","昨朝兵符至，单于寇临洮。","奋身出玉门，杀马衅宝刀。","横行万馀里，叱咤威风起。","夺马贰师城，长揖见天子。","调笑大将军，醉骂柱下史。","生憎汉相如，白首文园里。"]},{"t":"长干行","f":"五言律诗","c":["皑如玉山雪，皎如瑶台月。","郎来骑白马，调妾桃树下。","桃叶何柳柳，不谓君行久。","倚门问来船，见郎寄书否。"]},{"t":"洛阳道","f":"古风","c":["桃花马，金络头，白面郎，紫貂裘。","三月洛阳道，垂柳荫清沟。","沟水东流不记春，花开花落几回新。","东风日暮杨花起，愁杀高楼独倚人。"]},{"t":"宋中诗","f":"五言古诗","c":["六鹢退而飞，乃向宋都过。","四海一震荡，青天白石堕。","世人见此鸟，仰面忽大笑。","谁知影不灭，干载落光耀。","余方卧空山，闻此一长啸。"]},{"t":"河上公","f":"五言古诗","c":["昔有河上公，结庐蓬蒿下。","万乘时一顾，旌旗蔽原野。","手挥玉如意，颜貌何潇洒。","曳裾授道经，谈天妙无穷。","清光耀白日，四海高其风。","言既忽不见，竦身蹑星虹。","凤凰栖梧桐，鴳雀巢寒蓬。","饥鸢嚇腐鼠，笑杀高飞鸿。","物固有如此，何必较愚蒙。"]},{"t":"野田黄雀行","f":"古风","c":["鹑奔奔，鹊彊彊。","来逢野田雀，相逐过南疆。","北地苦霜雪，南地多稻粱。","人生美食被绮衣，不及鸿雁能高飞。","鸿雁下天遭网罗，不食柰尔黄雀何。"]},{"t":"邯郸才人嫁为厮养卒妇","f":"五言古诗","c":["妾本寒家女，误入崇台宫。","粉黛三千人，花颜笑春红。","君王重歌舞，幼小不曾通。","一朝意相迕，弃掷如秋蓬。","昔为高唐云，今为马牛风。","夜前邯郸道，不识邯郸中。","金殿秋月满，歌吹行烟空。","白日耀千春，何时烛微躬。"]},{"t":"苦寒行","f":"古风","c":["太行之山何崔嵬，天寒溪谷禽兽饥。","黄熊赤罴力相食，翠衿绣翼徒南飞。","啄食饮泉百意足，野田椎子寒无衣。","张罗挂毕伺鸟雀，口作雌雄鸣且悲。","鹌鹑小鸟鼓翅落，鼎食之家意不乐，顿箸待尔登品错。","奏应钟，开玄堂，毡帏锦幄冬夜长。","微禽效体樽俎光，秃鹙驾鹳当檐翔。"]},{"t":"结交行","f":"古风","c":["昔时韩生有艳妻，其君使筑青陵台，南山有鸟不肯来。","乌鹊虽小禽，不受鸾凤猜。","以此筑台成，二人葬寒灰，举国见之悲且哀。","悲且哀，断人肠，坟上连理树，变为两鸳鸯。","扼吭交颈绮翼张，春风蛱蝶花飘扬。","君不见郦吕结交日，朝为刎颈暮抛掷，如此结交复何益。"]},{"t":"梁园歌","f":"古风","c":["朝发金台门，夕度博浪关。","黄河如丝天上来，千里不见淮南山。","淮南柱树弄婆娑，挂席欲进阻洪波，我今亦作梁园歌。","梁园昔有信陵君，名与岱华争嵯峨。","三千珠履不动色，屠门执辔来相过。","功成不显涕滂沱，青蝇白璧一何多。","我为梁园客，不登梁王台。","锦帆扬州门，一土何时回。","荒烟白草古城没，登台望之令心哀。","令心哀，歌且谣。","迷涂富贵苦不足，宁思白骨生蓬蒿。","人生三十无少年，积金累玉空煎熬。","独立天地间，长啸视今古，城隅落落一堆土。","千年谁继白与甫，揽泪浮云洒烟莽。","洒烟莽，风吹卷波涛，沈吟投箸不暇食，蹴天浊浪何滔滔。","君不见昔人然诺一相许，黄金斗印如秋毫。"]},{"t":"梁园雪歌二首 其一","f":"古风","c":["昔对燕山雪，岧峣白玉京。","晓曳王恭氅，飘飖入紫清。","今为梁园客，独对梁园雪。","黄云索寞连沧海，九疑望尽飞鸿绝。"]},{"t":"梁园雪歌二首 其二","f":"古风","c":["飘风动三极，霏雪洒烟海。","天地倏低昂，虚无变光彩。","梁台空嵲屼，枚马今安在。","飞光超忽若游龙，我欲从之问千载。"]},{"t":"送友人入关","f":"五言律诗","c":["南山郁幽幽，丰水白浩浩。","乌啼汉城树，尘起咸阳道。","骢马东方来，长鸣翻玉蹄。","春风吹绿草，明月满关西。"]},{"t":"送李生京试歌","f":"五言律诗","c":["黄龙玉帝宅，紫极绕逶迤。","迩行霜雪尽，恰值春风时。","天起桃花浪，烟摇御柳丝。","要知走马地，非是冶游儿。"]},{"t":"送友人之京三首 其一","f":"五言律诗","c":["与君何处别，汴州金梁桥。","下有古时水，遥接广陵潮。","君摇锦帆去，万里上云霄。","我掇金光草，方期白鹤招。"]},{"t":"送友人之京三首 其二","f":"五言律诗","c":["凤凰鸣珠树，紫雁沧溟外。","贾邓登云台，宁说富春濑。","此情难具陈，临河挽衣带。","积雪太行路，明灭客行迈。"]},{"t":"送友人之京三首 其三","f":"五言律诗","c":["田方澹荡人，侯嬴亦监门。","老马尚悲辛，肯负信陵君。","宝剑赠烈士，明珠报王孙。","纵令沧洲去，终恋紫宫恩。"]},{"t":"春日柬王相国","f":"五言律诗","c":["白露陨瑶草，佳人秋思悲。","叶落今几时，忽复春风吹。","荣芊冒残雪，故柯发新蕤。","为问酒狂客，金尊开对谁。"]},{"t":"避暑","f":"五言律诗","c":["避暑空林酌，行歌采绿薇。","南来一行鹭，倒昳金尊飞。","淹留桂树夕，潇洒芰荷衣。","明月宛相待，休赋醉言归。"]},{"t":"佘园夏集赠鲍氏","f":"五言律诗","c":["晓挈金玉友，出挹池风清。","脱巾薜萝下，悠然听流莺。","白云行杯中，红蕖媚初英。","得意时自笑，冥哉尘外情。"]},{"t":"赠鲍演二首 其一","f":"五言律诗","c":["我爱汝长子，远志日超忽。","浮云似其心，秋水清到骨。","纵酒见天真，探桂迟月窟。","携手眺大野，沧波杳出没。"]},{"t":"赠鲍演二首 其二","f":"五言律诗","c":["蒲亭杳何许，云海日浩荡。","团团桂枝月，秋照沙溪上。","几负春草曲，空馀采菱唱。","盈盈吴门水，何时理归榜。"]},{"t":"把酒","f":"五言律诗","c":["把酒望天地，邈然无可亲。","龙蛇洞庭浦，雪霰洛阳春。","雾林坐鸣琴，烟径无归人。","相思东山月，夜夜悬西秦。"]},{"t":"赠张生二首 其一","f":"五言古诗","c":["怪尔辞江汉，长歌入宋梁。","北风吹冻野，岁晏天雨霜。","老马弃不育，闷杀田子方。","拍手笑侯嬴，捐生计不彰。","顾瞻台阙地，寒莽但苍苍。"]},{"t":"赠张生二首 其二","f":"五言古诗","c":["揽衣断崖口，悲风振古台。","叫雁惊逆云，万里天为开。","雪榛覆寒莎，松殿扃馀苔。","昔人邈安在，日落寒色来。","弃置勿复道，且釂黄金杯。"]},{"t":"别田进士","f":"五言律诗","c":["子进河上云，我望城中月。","不共眼前酒，况乃天外别。","白沙乱海曙，黄云下燕雪。","后期转超忽，吾将泛溟渤。"]},{"t":"岁暮夜怀寄友二首 其一","f":"五言古诗","c":["梁客梁甫吟，北风号沙林。","连山激湍波，海气结愁阴。","虽持一杯酒，而有万古心。","越鸟不巢燕，代马不恋越。","天明太行雪，霜冻洛门月。","飒飒湘流深，冥冥苍梧隔。","逝矣徒离忧，芳兰为谁结。"]},{"t":"岁暮夜怀寄友二首 其二","f":"五言古诗","c":["岁穷长年悲，越吟游子思。","寒风起枯杨，夕坐知天霜。","落星动海白，飞沙吹云黄。","萧萧孤蓬转，万里何超缅。","沉吟卷道帙，恻怆泪如霰。","入河讨沉沦，蹈海事游衍。","传书寄麻姑，与尔期相见。"]},{"t":"冬日夷门旅怀","f":"五言古诗","c":["十日五日雾，一冬半冬阴。","行子念归旋，朔风莽悲吟。","苍苍孟诸原，惨惨杼秋林。","东望清浅流，颇剧溟海心。","川陆旷超缅，浩然烟水深。","百龄一何遒，万化相推寻。","徒传羽化迹，不见鸾吹音。","清霜飒满镜，红颜倏颓侵。","邈彼五湖子，贤哉吾所钦。"]},{"t":"行歌古泽中二首 其一","f":"五言律诗","c":["古泽古云游，带索被羊裘。","川寒冻日白，海溟孤云愁。","鸱鸮叫秃木，鸿雁遵方洲。","肠断悲哉客，黄河不断流。"]},{"t":"行歌古泽中二首 其二","f":"五言律诗","c":["川原望不极，愁思满归襟。","云蔽长安目，水流湘浦心。","颓阳灭远树，积雪明寒岑。","醉起海月照，行歌入雾林。"]},{"t":"白雾树累累作花","f":"五言古诗","c":["不作江南客，空登河上台。","梦中到孤山，笛里落寒梅。","今朝走白雾，万枝参差开。","紫宫散花女，骑龙下瑶陔。","恍惚弄珠人，玉尘生罗袜。","葳蕤复飒沓，光采半明灭。","朝阳勿遽晞，留之慰超忽。"]},{"t":"故人殷进士特使自寿张来兼致怀作仆离群远遁颇有游陟之志酬美订约遂有此寄","f":"五言古诗","c":["我生寡谐俗，志与山林期。","谬拟渭川载，岂羡荆山悲。","弱龄不解事，走马长安郊。","紫绶虽挂身，丹丘阻逍遥。","心随万里云，舒卷何萧萧。","翩翩朱凤凰，飞集梧桐树。","冠盖交路衢，青云有捷步。","弹冠无钝硎，结交尽雄才。","殷君起东鲁，我使关西来。","揖鞭尘埃中，朗如玉山开。","时从二三友，览古黄金台。","四序更代易，人生岂常遇。","相如归蜀都，贾谊长沙去。","去去游梁园，耕钓孟诸薮。","日月东西没，黄河落天走。","云沙白皓皓，万里见海口。","雄剑挂土壁，褐衣被两肘。","朝从河上公，暮逐墟中叟。","有时弄清漪，明月在我手。","寿张三百里，北望一何迩。","未移山阴掉，先枉石川鲤。","剖鲤得素书，故人今何如。","锦字偕华星，照耀蓬蒿庐。","空谷激寒雷，冬庭转兰芳。","晓起诵瑶音，夜梦君之旁。","书中何所有，相期陟东岳。","巉岩丈人峰，彷佛几前落。","倏如佩苍龙，倒景骑玄鹤。","愿从东道主，握手翔廖廓。"]},{"t":"纪梦","f":"五言古诗","c":["夜梦走西陆，半天落金城。","天门两壁开，见之骇心情。","大江横其西，落日悬金盆。","日流江波涌，霞彩照乾坤。","我问此何方，云是涌金门。","挥手上云楼，邂逅钱世恩。","把袂凌天梯，笑倒黄金樽。","袖出石室诀，饮我金茎露。","人区沓难托，东指蓬莱路。","梦醒不见君，空江暝烟雾。"]},{"t":"大雾翟左二子来访","f":"五言古诗","c":["蒸烟暝万古，垂云结楼台。","白日堕空冥，天地安在哉。","川岳冰穹崇，寒林倏花开。","对酒不能饮，拥褐心悲哀。","翟生雀罗裔，左氏麟经才。","攀稽涉古陂，访戴临河隈。","两骑踏苍茫，宛如空中来。","日夕严飙兴，稍见归鸦度。","虽开宴台云，不辩焦桥路。","呼儿斸冻蕨，然蒿写秋露。","谈玄析绵邈，览古悲沿溯。","停杯划一笑，茫然独四顾。"]},{"t":"翟生苦节尚志人也迩从余河之上余嘉敬焉作诗以赠","f":"五言古诗","c":["原子悬鹑衣，仲蔚蓬蒿丘。","苍烟卧木石，浮云傲王侯。","常怀一饭恩，不顾千金酬。","弦歌空桑里，登啸大冈头。","眷念墟中约，慇勤河上游。","我亦钓鳌者，佳期杳沧洲。"]},{"t":"世不讲曹李诗尚矣内弟会余河上能章章道也惊有此赠","f":"古风","c":["曹植白马篇，李白飞龙引。","流光耀千古，不与日星陨。","世人捧心戚，番为西子哂。","左生三十岁，雅志测沉冥。","鲸饮倾百川，自称吾酒星。","今朝理酒船，来过子云亭。","高谈叫太白，八斗挥雷霆。","霜云连山海气恶，柳枝簌簌冰花落。","此时万里无人烟，谁信清吟动池阁。","动池阁，生暮愁，雪泽古龙寒啾啾。","他时尔献三都赋，我钓长江万里流。"]},{"t":"酬水部锡山之招","f":"古风","c":["无锡钱少阳，招我栖锡山。","江上千万峰，袅袅凌江关。","下有震泽湖，旁有太伯湾。","昔时苏公慕阳羡，阳山锡山对相见。","我独何为阻兹游，西风吹心落吴甸。","我问钱少阳，汝今在何所。","振辔金马门，看花曲江浒。","徐庶竟辞刘，张翰忆吴州。","鹅湖云屿间，鸿山林树秋。","我今放浪黄河隅，遥忆白粲心郁纡。","几时弹剑赋归来，与尔共醉芙蓉湖。"]},{"t":"寄钱水部","f":"古风","c":["我今在何所，牧钓睢川阳。","子今在何所，飞盖临东方。","高山大泽不我限，胡为日夜遥相望。","鸿雁日南飞，不寄一封书。","离别春草生，想思秋叶疏。","朝看渤海云，暮眺沧洲月。","树寒多天风，相思几时歇。"]},{"t":"十四夜翛然台二首 其一","f":"古风","c":["中州可以望天地，黄河之水何恍忽。","为此筑台临其涯，坐看月生复月没。","今年中秋地无云，绿烟溟濛海月发。","金流水波贝宫涌，蛟龙出游争海月。","我欲乘槎捉蛟龙，浪高力微惧灭殁。","呜呼灭殁不足惜，只恐竟无益。"]},{"t":"十四夜翛然台二首 其二","f":"古风","c":["蓬池有啸台，夷门有吹台。","二台突兀眼前一抔土，英雄落莫成今古。","我今有台不啸复不歌，月高霜白如夜何。","临洪河，望四海，山川悲，月不改。","昔日芒砀五色气，烟销浪灭今安在。"]},{"t":"十五夜","f":"古风","c":["去年燕山南、易水北，中宵待月不可得。","阴云峥嵘蔽瑶阙，顿箸停杯三太息。","今年有月复有台，海门烟灭没，四顾天地开，何为不饮歌且哀。","君不见少年时，驰逐京洛陌。","夜夜欢呼山月白，挥鞭不顾五陵客。","月圆月缺天有之，人生岂复如旧时。","不如采取灵兔药，富贵浮云岂足乐。"]},{"t":"十六夜","f":"古风","c":["唧唧复唧唧，当户鸣促织。","月中何所有，云是山桂枝。","此桂开花复结子，安得夜夜常不亏。","君不见梁园酒一斗，钱十千，昔时信陵有宾客，不饮岂足称豪贤。","直须酩酊卧草泽，明日射猎睢阳川。"]},{"t":"十七夜","f":"古风","c":["三日不见月，见之半轮没，清光犹能鉴毛发。","不愁倒却婆娑树，只恐损破清虚阙。","清虚阙，在何许，白气荧荧走金虎。","虽有三万六千户，手提玉斤不敢补。","凉风飙飙自西来，吹我衣，心独苦，长歌潜行槛洲莽。"]},{"t":"客有笑余霜发者走笔戏之","f":"古风","c":["客且尽，手中觞，不须笑我头上霜。","客尽觞，且停之，听我高歌霜发词。","君不见天上鸟，东跳西走不相待。","又不见黄河水，万古滔滔向东海。","我身不是南山松，又不是山上峰。","柰何与年少争春风，斗鸡走狗倾春红。","君不见昔时孔仲尼，辙环憔悴无已时。","盗蹠杀人如乱麻，锦衣高寿颜回嗟。","听我霜发歌，歌短情则多。","轩车驷马浑等闲，何似日衔金叵罗。","金叵罗，青玉案，何以赠客锦绣段，头白头白何须叹。"]},{"t":"戏作放歌寄别吴子","f":"古风","c":["惟昔少年时，弹剑轻远游。","出门览四海，狂顾无九州。","献策天子赐颜色，锡宴出入黄金楼。","扬鞭过市万马辟，半醉唾骂文成侯。","结交尽是扶风豪，片言便脱千金裘。","弯弓西射白龙堆，归来洗刀青海头。","昆崙河碛不入眼，拂袂乃作东南游。","江海汹涌浸日月，岛屿蹙沓混吴越。","匡庐小琐拳可碎，鄱阳触怒踢欲裂。","泽中龙怪能人言，喷涛吹浪昏涨天。","大鹏举翼四海窄，笑尔弋人何慕焉。","东吴子，君非淟涊闇穆取位之丈夫，余亦岂卑卑与世而浮沉。","恂复共斗非庸劣，廉蔺终投万古钦。","攀鳞扫氛代不乏，我岂复恋头上簪。","鹿门黄犊稳足驾，商颜紫芝山固深，有飞倘附秋空音。"]},{"t":"晋州留别州守及束鹿令用李白崔秋浦韵","f":"五言律诗","c":["荒原送行客，白杨起西风。","双凫下云汉，五马系秋桐。","连城滹水上，驰誉燕代中。","登高望云海，离思浩无穷。"]},{"t":"客过属骤雨过","f":"五言律诗","c":["鸣雷不终夕，急雹偶来同。","城波静绮席，苑树生长风。","雨残白日外，虹垂青雾中。","为爱扬州客，留连尊酒空。"]},{"t":"结客行","f":"五言律诗","c":["翩翩紫骝马，灿灿云花袍。","结客梁州市，倾心赠宝刀。","意气凌朱亥，英声盖伯高。","见说烟尘起，横行是尔曹。"]},{"t":"程生游华山归也誇我以观动我以灵篇爰赠此章抒我夙愫","f":"五言古诗","c":["君行值杪秋，飘飘登云巅。","笑弄石莲花，俯漱玉女泉。","秦时采松女，有无嬉紫烟。","双骑两茅龙，曾逢呼子先。","夜栖何峰室，遇师叩何诠。","一虎啸海月，万壑惊风旋。","飒然毛骨换，错落神光圆。","晨兴扳长萝，朗咏青霞篇。","黄河衣带去，蓬莱瞪目前。","赤日跳扶桑，仙掌发红鲜。","伊予歉兹游，桂心三十年。","梦想落雁顶，携诗问青天。","林麓限层云，奋飞怅无缘。","安能振衣去，共尔追群仙。"]},{"t":"怀湘曲","f":"五言律诗","c":["湘筠寒翠满，白日起秋云。","美人杳何处，江气长氤氲。","手持紫玉管，遥望青霞君。","蔼蔼波水暮，何由致慇勤。"]},{"t":"猎雪曲二首 其一","f":"五言律诗","c":["日光摇白雪，黄云片片裂。","狐裘谁家郎，骏马如电掣。","驰骋复徘徊，掉臂角弓开。","一发中双狸，笑上梁王台。"]},{"t":"猎雪曲二首 其二","f":"五言律诗","c":["荒荒冻日白，出门雪一尺。","爰爰道左兔，意态一何适。","我弦才一鸣，不见彼行迹。","寄言游猎人，姑待春草碧。"]},{"t":"桴溪吟","f":"五言律诗","c":["济川何必舟，编竹便可涉。","秋风芦白花，洄沿水一叶。","浅之不用维，渡深岂须楫。","黑潭有龙气，云起腥风接。"]},{"t":"送藩幕张小山入朝","f":"五言律诗","c":["骝马向风嘶，银鞍翻玉蹄。","结装紫薇下，别我绿杨西。","记室发点漆，参军髯过脐。","冯唐莫恨老，神物不终泥。"]},{"t":"赠程生之南海","f":"五言律诗","c":["生为海南客，几度登罗浮。","天清众岛出，万水朝宗流。","乘桴圣者叹，望洋游子愁。","明珠与翡翠，岁岁到神州。"]},{"t":"近竹吟","f":"五言律诗","c":["萧萧数竿竹，每与岁寒期。","翠色酒中满，清风琴上吹。","疏值月来处，密当云起时。","万动纷华里，一杯聊自持。"]},{"t":"水司陶君种桃柳成各有诗予和二首 其一","f":"五言古诗","c":["沿堤万万树，一插即成林。","五柳陶公意，甘棠邵伯心。","许我听莺去，携壶就绿阴。"]},{"t":"水司陶君种桃柳成各有诗予和二首 其二","f":"五言古诗","c":["如何梁苑地，忽见武陵津。","汎汎青霞水，盈盈红锦春。","果熟贫民食，无儿许妇人。"]},{"t":"赠谢子二首 其一","f":"五言律诗","c":["凉风吹海月，当酒堕我怀。","爱此皎洁光，愿与君子偕。","揽之不入手，仰面看昭回。","银潢南北流，竟夕但徘徊。"]},{"t":"赠谢子二首 其二","f":"五言律诗","c":["大河起长风，挂席破黄涛。","问子今何之，岭海聊游遨。","罗浮绿发人，思之我心忉。","幸君叩丹诀，顺风托鸿毛。"]},{"t":"相逢行赠袁永之","f":"五言古诗","c":["清晨客叩门，投我一书札。","开缄锦云烂，铿然玉相戛。","问客何方来，新下黄金台。","扬鞭指河洛，回旆陵高崖。","选珍掇琪草，探美收与瑰。","路逢赤松子，并举收氛埃。","道同心乃冥，神投谊难垂。","古人重良契，岂必声影偕。","行行报嘉绩，贡此明堂材。"]},{"t":"郊观斋居柬边乔二太常","f":"五言律诗","c":["人日过仙院，春霞缈缈分。","碧回瑶泽草，红绽蕊宫云。","独处依松树，清斋对鹤群。","桃源知并入，惆怅不逢君。"]},{"t":"郊坛值雪","f":"五言律诗","c":["凤辇连宵发，鸡鸣雪满畿。","严随黄钺至，清绕翠华飞。","伏谒深沾佩，朝回半湿衣。","悬知清切地，冲默迓天威。"]},{"t":"西天门候祀","f":"五言律诗","c":["瑶坛暮雪尽，月出禁门西。","地静鸣珂碎，沙寒簇仗低。","台官移斗柄，卫士扫云梯。","遥识龙文气，争传法驾齐。"]},{"t":"恭陪郊祀纪成","f":"五言古诗","c":["御气三更合，君王在閟宫。","燎烟凝碧落，墀月起微风。","上帝居歆夕，文王陟降中。","诸坛严从幕，元祀报成功。","侑食圭璋洁，登歌玉磬同。","神旋仍醉饱，万舞向春空。"]},{"t":"郊祀以病不与","f":"五言律诗","c":["端月温风至，圆丘瑞雾多。","开坛洽百礼，伏枕想登歌。","日月春旂闪，雷霆昼辇过。","年年觐上帝，只为乞民和。"]},{"t":"卧病酬边君天坛步月见怀之作","f":"五言律诗","c":["霁夕开芳甸，祠官怅独游。","银潢横殿落，壁月抱坛流。","汉畤饶烟雾，秦城逼斗牛。","甘泉词调绝，疫病若为酬。"]},{"t":"大行皇帝挽诗三首 其一","f":"五言律诗","c":["午门朝遂罢，西殿临真哀。","泪满乾坤暮，日黄风雨来。","虎贲犹宿卫，龙驭几时回。","莫测皇天意，中崩帝业摧。"]},{"t":"大行皇帝挽诗三首 其二","f":"五言律诗","c":["大训文华践，英谋武范遗。","先朝无顾命，大渐问班师。","上食金舆备，移宫素幔垂。","向来激切疏，优渥小臣知。"]},{"t":"大行皇帝挽诗三首 其三","f":"五言律诗","c":["元老烱仍在，退朝无昔呼。","閒阶惟玉辂，夕日已金铺。","望幸霓旌远，埋灵山殿孤。","君看霜露节，冠冕灞陵趋。"]},{"t":"候挽","f":"五言律诗","c":["冬月初圆夕，仓悲候辇东。","阁门犹警跸，松柏已新宫。","象卫悲风入，龙旂白雾中。","有髯浑欲挽，云堕鼎湖弓。"]},{"t":"望泰陵","f":"五言律诗","c":["昔临围西内，悲风入紫冥。","今来松柏望，夕日泰陵青。","殿起云烟入，龙游剑玺扃。","万国今多难，孤臣涕倍零。"]},{"t":"谒孔庙","f":"五言律诗","c":["端笏陪朝列，时禋谒圣林。","戟门留石鼓，春殿静珠琴。","奎府星连切，璧池龙跃深。","诜诜趋国子，早晚翠华临。"]},{"t":"坛祀酒会","f":"五言律诗","c":["斋居新宴合，桂里戟门开。","雁趁龙旌到，蛩喧羯鼓催。","松筠分曙色，剑佩接行杯。","日上云霞散，骖驔羽骑回。"]},{"t":"益王颂","f":"五言律诗","c":["宪宗王十子，益府实称贤。","体统朝廷半，敦崇德业全。","书堂斜昼日，琴殿净秋烟。","问寝还英嗣，时研世子篇。"]},{"t":"骊山","f":"五言律诗","c":["绣岭花仍绣，汤泉满故宫。","禁池人自浴，新月古应同。","玉殿兴亡后，青山涕泪中。","千岩歌吹入，犹想翠华东。"]},{"t":"桥山","f":"五言律诗","c":["青宫栖古岑，白露静松林。","忽下乌号泪，遥悲龙去深。","衣冠万国后，辙迹四方心。","一气流群帝，哀哉笙凤音。"]},{"t":"瓠子","f":"五言律诗","c":["沈璧馀瓠子，横汾怀帝歌。","波涛满眼送，城郭没年多。","虎战仍三晋，龙游失九河。","宋人饶事迹，今望亦滂沱。"]},{"t":"岘山","f":"五言律诗","c":["大名终不灭，堕泪此山碑。","后进才非乏，风流尔足师。","古堂阴汉水，新路改城池。","回首隆中接，秋云两处垂。"]},{"t":"鹿门山","f":"五言律诗","c":["庞公真汉陇，孟子复唐诗。","旧宅新秋叶，孤坟千载遗。","泉袅石穴细，葛倚松门垂。","望望青峰近，君襟旷尔期。"]},{"t":"冬日过故王坟二首 其一","f":"五言律诗","c":["寂寞何王殿，遗坟此径孤。","玉阶番雪草，野日自金铺。","庑暝牛羊聚，林风鸟雀呼。","白头香火者，犹护赤龙符。"]},{"t":"冬日过故王坟二首 其二","f":"五言律诗","c":["二冢累累接，聊城复定安。","情哀宫独盛，世异柏同残。","久雨石门塌，新霜帷殿寒。","西陵时节望，谁见绮罗叹。"]},{"t":"令婆坟","f":"五言律诗","c":["国初抡秀妪，分遣入周宫。","但睹丘坟郁，宁知乳哺同。","后王忘昔日，颓屋锁春风。","寒食莺啼切，林花落自红。"]},{"t":"始谒徐祠","f":"五言律诗","c":["庙古傍湖偏，春行更可怜。","楚城芳草遍，红日此堂悬。","榻想陈公后，时悲孝献前。","亦知遗像误，瞻拜泪油然。"]},{"t":"徐墓书张相国碑铭","f":"五言律诗","c":["不读南州传，谁知高士心。","江城遗冢在，春日古祠深。","竹鸟嘤嘤合，松墙靡靡阴。","曲江千载碣，书罢泪盈襟。"]},{"t":"陈祠在徐墓东","f":"五言律诗","c":["可讶司徒庙，偏邻孺子坟。","哲人堪一哭，汉鼎竟三分。","门引江畔草，榻留松上云。","纷纷车马客，谁此荐清芬。"]},{"t":"韩文公祠","f":"五言律诗","c":["袁州山在城，韩庙倚山清。","冕服前朝貌，文章百代名。","石苔犹马路，春竹自莺声。","立望潮阳近，翻翻海气征。"]},{"t":"武阳郡公祠","f":"五言律诗","c":["惠爱前人迹，追思后代心。","洪都观察庙，香火古江浔。","白日江山过，青松霜露深。","亦知精爽异，应厌鼓鼙音。"]},{"t":"徐苏二祠","f":"五言律诗","c":["孺子真高特，云卿崛后先。","挥锄傲汉冕，捆屦卧江烟。","宁饫糟糠毕，耻同贪浊全。","凄凉百代宇，怅望一潸然。"]},{"t":"鹅湖书院","f":"五言律诗","c":["书院佛堂边，颓垣岭谷连。","四时僧酒扫，千古俨高贤。","立壁东莱毅，悬河子静偏。","众流终一海，流泪考亭前。"]},{"t":"经长陵诣黄花镇","f":"五言律诗","c":["沙岭群峰会，黄花一径穿。","临崖防马骇，枯木有蛇悬。","锁钥关门壮，星辰陵阙连。","旧驱悲虏贼，得失岂皇天。"]},{"t":"白洋城","f":"五言律诗","c":["京西太行崦，孤垒白洋间。","巳巳曾通贼，居庸并立关。","水合桑乾去，峰连塞上山。","圣君敷远德，秋日战旗闲。"]},{"t":"至黄花","f":"五言律诗","c":["黄花城压岑，山合昼多阴。","坐见五陵雾，来为九月霖。","泥生剑戟涩，寒重鼓鼙沉。","寂寞松林外，那传孤雁音。"]},{"t":"银山寺","f":"五言律诗","c":["银山倚铁壁，天外削三峰。","下见林中寺，来闻午后钟。","僧徒住石屋，雷雨拔门松。","西望诸陵接，云成五色龙。"]},{"t":"出塞二首 其一","f":"五言律诗","c":["胡蔓黄河限，秦亡紫塞存。","碛沙浮落日，寒雾宿疏墩。","哨马三边动，烧荒千里昏。","将军拜金印，白骨不曾论。"]},{"t":"出塞二首 其二","f":"五言律诗","c":["碛日淡无晖，胡沙惊自飞。","望烟寻戊垒，闻雁忽沾衣。","大将搜河套，游兵出武威。","贺兰山下战，昨日几人归。"]},{"t":"环县道中","f":"五言律诗","c":["西人习鞍马，而我惮孤征。","水抱琵琶寨，山衔本钵城。","裹疮新罢战，插羽又徵兵。","不到穷边处，那知远戍情。"]},{"t":"寺","f":"五言律诗","c":["不睹空王宇，谁兴浩劫心。","散花疑白象，布地果黄金。","水雾飞梁洒，夕阳迥殿阴。","独嗤簪绂客，游赏托云林。"]},{"t":"繁台春望","f":"五言律诗","c":["野旷孤烟静，高台独望时。","地残隋氏苑，天阔禹王祠。","晚日云争白，阴崖花自迟。","目断南来雁，萧然故国思。"]},{"t":"繁台别业","f":"五言律诗","c":["地亦因台峻，天能纵屋高。","宋朝四帝国，禹庙九河涛。","上下见陵墓，风烟含野蒿。","昔人闻醉此，简懒愧吾豪。"]},{"t":"高远亭","f":"五言律诗","c":["虚亭盖树杪，四顾果平芜。","嵩岳杯前出，浊河窗外纡。","寺杉时送响，塔鹳每来乎。","一约朋知饮，归车醉每扶。"]},{"t":"诣别业","f":"五言律诗","c":["局蹐岂吾事，郊游惟独行。","风回疑引骑，雪落故连城。","塔树凝先白，台云曳未平。","感时侵岁晚，白发暗心惊。"]},{"t":"登盘山顶顾望三湖","f":"五言古诗","c":["为访三湖寺，春山独自来。","千盘不到顶，万壑划争回。","石罅鸣鸡犬，林风过虎豺。","俯观侯赵树，西望白云台。","峰日明寒雪，溪泉激暗雷。","若非武陵口，那得有桃开。"]},{"t":"中湖寺二首 其一","f":"五言律诗","c":["龙象何年地，千岩一涧回。","我来寻石镜，隔竹望香台。","树绕啼猿入，人从鸟道来。","坐飧霞气晚，只拟是天台。"]},{"t":"中湖寺二首 其二","f":"五言律诗","c":["陟崄扣岩扉，一钟鸣翠微。","丹崖森竹树，雪壁映花飞。","屋隙鸣泉写，山昏麋鹿归。","松风高壑起，云卧欲沾衣。"]},{"t":"南湖","f":"五言律诗","c":["中湖果奇绝，逾岭复南湖。","石磴回相倚，岩泉有乍无。","开窗众壑积，当殿一峰孤。","更览千林竹，因怀长啸徒。"]},{"t":"北望畏雨不至","f":"五言律诗","c":["乱山上云气，孤客发西岑。","徒瞻北湖寺，其如东路心。","岭猿愁瞑雨，岩鸟下空阴。","回首太行麓，萧萧松橡林。"]},{"t":"下南湖","f":"五言律诗","c":["湖僧骑牝马，相送石门峰。","欹仄乱石路，日瞑渔樵逢。","苍茫翠微里，风落青山钟。","羡尔岩居者，终期尘外踪。"]},{"t":"晓行云梦泽","f":"五言律诗","c":["晓行云梦泽，云起失湖村。","历历横江雨，冥冥远岫昏。","鼋鼍当马吼，鸥鹭背人翻。","欲拟浮湘作，吾生异楚魂。"]},{"t":"刘家隔","f":"五言律诗","c":["匹马淮山尽，孤舟渐楚歌。","远商吴蜀杂，新雨汉江波。","骄雁斜斜下，轻鸥片片过。","整帆迟明发，天色定如何。"]},{"t":"浮汉","f":"五言律诗","c":["杳杳向前城，杨船浮汉行。","水闻天上转，色出雨中明。","已近鸣鵙月，长看龙雾生。","陈诗叹秣马，风浪独含情。"]},{"t":"浮江","f":"五言律诗","c":["浮江晴放舸，挂席晓须风。","日倒明波底，天平落镜中。","开窗问赤壁，捩柁失吴宫。","万古滔滔意，浔阳更向东。"]},{"t":"九江","f":"五言律诗","c":["九江江九流，庐岳负江州。","世代催前浪，图书羡上游。","城孤落日映，虎去暮天幽。","夜笛邻舟送，曲终无限愁。"]},{"t":"发九江","f":"五言律诗","c":["已发南风盛，须时且复停。","岸沙延系缆，竹色隐回汀。","行待江水稳，卧看庐阜青。","此生谁固料，湖海一浮萍。"]},{"t":"丰安庄","f":"五言律诗","c":["地气南逾热，僧林晚暂栖。","云开一江去，日在万山西。","修竹凉风至，昏鸦古木齐。","凭高忽洒泪，清世有征鼙。"]},{"t":"圆通寺阻雨","f":"五言律诗","c":["岩扉邻虎穴，淹坐面猴江。","山动云生服，风回雨入窗。","渐交松际响，蓦斗石间泷。","铃磬烟萝外，高峰只自双。"]},{"t":"圆通寺阻雨闻石门涧桥断水涌阻往东林","f":"五言律诗","c":["石门雨断桥，途阻虎溪遥。","仄想远公室，秋莲应尽飘。","愁猿吟雾里，落叶重林腰。","更有天池望，岩岩向碧霄。"]},{"t":"五老峰","f":"五言律诗","c":["东南涛浪吞，五老古今存。","秀色彭湖浴，诸峰庐岳尊。","中宵见海日，南斗豁天门。","霜雪颜常静，云烟解变魂。"]},{"t":"再至洞院","f":"五言律诗","c":["昔别秋色苦，今游风涧清。","穿石竹犹活，雨过泉自生。","礼殿古门换，钓台新路平。","独来谁每见，云日此峰情。"]},{"t":"回流山亭","f":"五言律诗","c":["亭高山尽入，回首见鄱阳。","天地开吴楚，弦歌有宋唐。","峰云低栋白，湖日倒碑黄。","六月吾来此，凉风不可当。"]},{"t":"折桂寺","f":"五言律诗","c":["折桂何朝院，开基分翠峰。","窗明五老雪，门掩半崖松。","泉瀑飞人过，香台印虎踪。","千岩谁得到，百里但闻钟。"]},{"t":"团山登望","f":"五言律诗","c":["团山当县口，石壁对朝饶。","日静湖波敛，天低岛色遥。","风云馀霸气，吴楚混前朝。","秋水年年落，英雄恨不消。"]},{"t":"芝山望","f":"五言律诗","c":["吴楚分何代，乾坤此郡孤。","江从树里断，山入雨中无。","战斗名空在，英雄世与徂。","酒酣抚长剑，极目尽重湖。"]},{"t":"芝山寺感事","f":"五言律诗","c":["偶到芝山寺，遥伤荐福碑。","霜雷十月动，秋战万家悲。","凉入丹枫堕，崖高黄葛垂。","洪钧融万物，黔首独旌旗。"]},{"t":"龟峰","f":"五言律诗","c":["立壁有天地，浮云无古今。","仲冬诸客到，落日乱峰阴。","峭峡通人过，危岩把酒唫。","奇多看不彻，昏黑更登临。"]},{"t":"泊安仁","f":"五言律诗","c":["官舟商泊同，城近月濛濛。","戍鼓夜长击，渔灯时自红。","乌鹊枝难稳，豺狼穴易空。","向来论大树，心切古人风。"]},{"t":"铅山","f":"五言律诗","c":["山水交闽越，东南古县闻。","一峰晴冒雪，雨水昼蒸云。","石井鹅湖倚，车盘鸟道分。","儒宫荆棘里，寒叶痛纷纷。"]},{"t":"明远楼春望","f":"五言律诗","c":["贡院初开阁，春阴独倚栏。","柳边千舰聚，花里万家残。","风雨江声壮，兵戈地色寒。","断肠沙雁北，群起向长安。"]},{"t":"市汊夜泊","f":"五言律诗","c":["此夜章江月，无端照独舟。","人生真梗泛，岁暮且帆游。","腊逼寒灯焰，波吞霁雪流。","坐吟风雁起，渔笛满前洲。"]},{"t":"丰城夜泊","f":"五言律诗","c":["夏至北风至，晚清凉意增。","江船逼新月，沙色乱疏灯。","暗桨故相拨，浮阳还自蒸。","倚樯看剑气，仍见斗间曾。"]},{"t":"舟往临江即事","f":"五言律诗","c":["直岸含风细，中江放舸安。","地随帆席转，风进晚潮残。","霞树迎窗过，晴山卷帽看。","遥惊双浴鹭，色举向云湍。"]},{"t":"雨泊丰城","f":"五言律诗","c":["古岸花层湿，阴江鸥半飞。","波回撼船重，雨侧入帘微。","潭爱金华涌，亭伤宝气稀。","二年三历此，肠断北舟归。"]},{"t":"夜行旰江","f":"五言律诗","c":["灯火遵山闪，旌旗折路频。","仙坛沓不见，片月故须亲。","土俗渐异楚，人言多杂闽。","岂无嚚不足，讼简爱吾民。"]},{"t":"赴新喻","f":"五言律诗","c":["露树且乌啼，孤舟晨向西。","萧滩千百转，昏暮到罗溪。","古驿屯云密，平沙没日低。","扬帆更前去，月夜不须迷。"]},{"t":"自进贤趋抚州","f":"五言律诗","c":["炎域霜何厉，寒泉木欲稀。","肩舆随落叶，晨日上征衣。","路势东南转，北风鸿雁归。","东乡新血战，巢破鸟犹飞。"]},{"t":"云山渡","f":"五言律诗","c":["渡古云山积，江明日色饶。","霜融木更落，野静路堪遥。","冠盖行相望，干戈气未消。","伤心弄兵者，汝业本渔樵。"]},{"t":"玉峡驿夜泊","f":"五言律诗","c":["暑泊无风夜，江船深自凉。","云纤沾葛细，月涌去波长。","古峡衔孤驿，名山引玉梁。","前途堪跃马，旦发问仙乡。"]},{"t":"白沙驿","f":"五言律诗","c":["沙古幽幽白，江新泯泯清。","水衔村作国，山绕驿为城。","万里将南徼，孤槎且暮征。","壮心与落日，的的向波明。"]},{"t":"宜春台春望","f":"五言律诗","c":["古州图记见，今望临高台。","人倚楚天尽，风驱湘色来。","密云生晓瞑，远水上春雷。","尚有干戈泪，冯轩眼倦开。"]},{"t":"涧富岭赴安福二首 其一","f":"五言律诗","c":["三月赴安城，遥攀岭路行。","前驱真避虎，绝壁亦啼莺。","周览物色换，极高云气迎。","俯看南赣路，孤舸会将征。"]},{"t":"涧富岭赴安福二首 其二","f":"五言律诗","c":["山行忽百里，步步山情新。","萝拥千盘透，花齐万谷春。","寒暄不异地，忧喜暂随人。","默诵垂堂戒，私嗟名利身。"]},{"t":"郁孤台","f":"五言律诗","c":["朔日送客返，慨然登郁孤。","悲歌为闽广，指顾尽江湖。","南俗羌夷杂，北流章贡俱。","兵舸尚满眼，绎绎诣饶都。"]},{"t":"晓至邬子驿","f":"五言律诗","c":["湖夜乘风过，天明见驿楼。","数家依独树，落日隐春洲。","日抱越峰上，江奔吴徼流。","姚源东水外，兵甲气还浮。"]},{"t":"再至玉虚观","f":"五言律诗","c":["龙沙欣自昔，久泊遂今期。","雨露新松大，丹青旧殿移。","岸云通绣栱，江日抱金池。","欲倚门东阁，愁看日暮时。"]},{"t":"仙楼","f":"五言律诗","c":["仙楼忽欲暝，钟鼓下江烟。","独坐一烛秉，当门新月悬。","石寒坛近斗，沙静树浮天。","半夜朝群帝，珊珊羽节还。"]},{"t":"谢岩秋日始集","f":"五言律诗","c":["百战江山在，吾来草木秋。","孤城洞口落，襄水席边流。","去国双王灿，题岩只谢侯。","醉归忆山简，飞兴习池头。"]},{"t":"秋望","f":"五言律诗","c":["蝶戏犹馀蕊，蝉吟已怯枝。","乾坤入汉日，霜露望乡时。","屈子偏生楚，王通不负隋。","晚风江更苦，莫上岘山祠。"]},{"t":"古城春望","f":"五言律诗","c":["阴阴日欲暮，迢迢春望稀。","野色吹寒立，林鸦逆雨归。","孤城还麦秀，白首且花飞。","临路长杨袅，前朝今是非。"]},{"t":"东陂秋汎三首 其一","f":"五言律诗","c":["久说东陂好，今陪上客游。","绮筵开画舫，哀笛奋中流。","舞每低轻燕，歌先起白鸥。","稍前休更进，吾爱荻花洲。"]},{"t":"东陂秋汎三首 其二","f":"五言律诗","c":["水寺通人少，松亭隔芰荷。","问僧舟暂舣，登岸酒同过。","草木秋风入，湖山晚色和。","返桡须痛饮，前路满渔歌。"]},{"t":"东陂秋汎三首 其三","f":"五言律诗","c":["进艇晨烟碧，回槔晚日黄。","宿禽喧乱苇，饥獭窜空梁。","放浪形骸得，牵缠世路忙。","要君待明月，此水是沧浪。"]},{"t":"与骆子游三山陂三首 其一","f":"五言律诗","c":["库部平生友，湖山百代心。","追思宫阙地，芜没水云深。","连马穿芦入，群鸥坐石吟。","谁能堪落日，莽莽古城阴。"]},{"t":"与骆子游三山陂三首 其二","f":"五言律诗","c":["岳壑胸应满，乾坤眼独真。","扬鞭指河洛，立马说周秦。","古墓笙歌地，前朝战伐尘。","秋风飒飒起，白草正愁人。"]},{"t":"与骆子游三山陂三首 其三","f":"五言律诗","c":["日扇逢林却，风旗改路回。","悲凉元此岳，攀陟复何台。","云破远峰出，天秋孤雁来。","明朝异南北，归骑莫教催。"]},{"t":"上方寺钟楼","f":"五言律诗","c":["台上一钟鸣，登台万里平。","蒹葭天正远，云气暮还生。","饥雀喧空泽，黄蒿断古城。","不堪临眺屡，况是感秋情。"]},{"t":"上方寺钟楼晚登","f":"五言律诗","c":["危阁秋登霁，寒烟晚坐重。","长风欲动地，落日故衔峰。","苇飐腾双鹜，云拖挂一龙。","此怀吾不浅，怪尔暮鸣钟。"]},{"t":"春日台寺","f":"五言律诗","c":["寺僻春还丽，人闲午任游。","行随碧草远，话为老僧留。","池竹晴常润，龛花晚更幽。","塔端两巢鹤，怪尔亦优游。"]},{"t":"春晴野寺和李大","f":"五言律诗","c":["野阔爱春幽，新晴觅寺游。","立僧当径望，融雪向门流。","净色悲诸界，浮生哂一丘。","怜君厌嚣俗，行处即沧洲。"]},{"t":"城南夏望和王相国","f":"五言律诗","c":["散步郊南望，雏鸦款款飞。","园林惟草色，时序巳絺衣。","试粉莲初腻，残香栋乍稀。","亦思河朔饮，无柰赏心违。"]},{"t":"陶行人宅赠","f":"五言古诗","c":["大道僧门对，萧然陶舍深。","未论五杨柳，真悬一素琴。","坐向霜烟夕，时闻鸿雁音。","城笳流海思，边月起秋阴。","苦劝蒙腾醉，应怀长别心。","但看得云翼，冥冥谁竟寻。"]},{"t":"酬京师友人见寄","f":"五言律诗","c":["浮云悲故国，积水起鸣雷。","不见长安日，愁登古吹台。","故人三月别，天上一书来。","欲问经行处，山中杜若开。"]},{"t":"繁台饯秦子二首 其一","f":"五言律诗","c":["异地同为客，看花更属秋。","云连去国目，雁引望乡愁。","陇树迷关道，吴山蔽驿楼。","忍将宋玉恨，还共李膺舟。"]},{"t":"繁台饯秦子二首 其二","f":"五言律诗","c":["万里游燕客，十年归此台。","只今秋色里，忍为菊花来。","霜露凝秦望，衣冠饯楚材。","不堪分袂苦，落日一鸿哀。"]},{"t":"送秦子","f":"五言律诗","c":["梁国秋砧满，范阳风叶稀。","如何故人去，不与雁同飞。","北路蓟门古，寒天易水微。","君行莫怨雾，霜日指南辉。"]},{"t":"闻李公寓郊园寄赠","f":"五言律诗","c":["几日栖东屿，昔林今若何。","主人能醉客，世事且狂歌。","黄鸟晴吟竹，红蕖晚出波。","自怜门士末，眠病阻呜珂。"]},{"t":"答殷伊阳见寄","f":"五言律诗","c":["古县垂新柳，独吟酬好春。","琴清山在眼，花碧酒随人。","柰此河阳少，曾于汉署亲。","邮筒定不惜，有句念沉沦。"]},{"t":"寄殷伊阳二首 其一","f":"五言律诗","c":["自枉去年札，约为嵩少行。","梦常飞洛水，诗屡到伊城。","萝殿王乔舄，花台子晋笙。","君行奋双翮，吾此学长生。"]},{"t":"寄殷伊阳二首 其二","f":"五言律诗","c":["可怪伊阳尹，冬来不寄诗。","从怀白雪调，况逼暮云时。","日落山城黑，风鸣邑树悲。","身危属抚字，为尔一凄其。"]},{"t":"送鲍生下第南归","f":"五言律诗","c":["只期横直上，岂料戢鳞归。","抱玉终难掩，投珠安所希。","秋风吹独马，落日照征衣。","南到江亭上，还瞻北雁飞。"]},{"t":"杭刑部东卿谈其师鼒","f":"五言律诗","c":["国难逢骄虏，时危惜俊才。","盐车在泥淖，骐骥亦悲衰。","片月清秋照，商风一夜来。","思君不相见，惆怅对西台。"]},{"t":"张子抱疴避諠山寺阔别旬月作此怀寄","f":"五言律诗","c":["楚楚张公子，悲吟度岁华。","弃官临野寺，服习向山家。","石髓遇不识，黄精春始花。","洞中日月秘，强食胜丹砂。"]},{"t":"寄钱水部世恩","f":"五言律诗","c":["雪时挥袂别，见雪即怀君。","河馆冬难暮，沙洲晚更云。","清为苍水使，静对白鸥群。","昨夜寻君梦，微茫路不分。"]},{"t":"风夕柬徐子","f":"五言律诗","c":["严冬万卉寂，苜吹迥添愁。","岭日微含照，川云半逆流。","频斋忘肉味，乍冷觅羔裘。","差胜山阴夜，能孤访戴游。"]},{"t":"送舍侄木还汴","f":"五言律诗","c":["天涯逼除夕，念尔独归人。","夜宿芦沟雪，朝逢易水春。","为驹先污血，藏剑莫愁身。","到及张灯候，遥知戏彩频。"]},{"t":"得何子过湖南消息","f":"五言律诗","c":["及遇荆门信，洞庭秋巳凄。","湘江饶苦竹，几听鹧鸪啼。","马援留铜柱，王褒祀碧鸡。","向南冲瘴疠，药物去曾携。"]},{"t":"忆何子","f":"五言律诗","c":["忆尔辞京日，余歌万里行。","经秋无过雁，索处若为情。","去巳穷滇海，归应滞岳城。","凤凰池上草，春到为谁生。"]},{"t":"何子至自滇","f":"五言律诗","c":["醉折荷花别，宁期花复开。","川原一回首，云日共徘徊。","知向百蛮去，云从三峡来。","进舟虽一赋，胡弃楚阳台。"]},{"t":"春归柬谢员外","f":"五言律诗","c":["寂寂鸣禽变，阴阴弱絮飞。","烟花从客久，风雨会春归。","且尽退随饮，休伤节序违。","无端临暮景，番忆谢玄晖。"]},{"t":"晚过序上人","f":"五言律诗","c":["塔日微微堕，禅居隐隐凉。","轩开惟有竹，坐定始闻香。","万古风尘地，三生水月乡。","频来寻白社，不为礼空王。"]},{"t":"再过序公月夜","f":"五言律诗","c":["岁巳残冬逼，月馀今夜圆。","光侵僧磬发，清傍佛楼悬。","鸣鸟疑深树，高云静暮天。","夙心如解此，更欲问何禅。"]},{"t":"晚过定上人","f":"五言律诗","c":["中秋镜阁临，向晚过西林。","月自湖间动，鹊翻袛树深。","静宜钟磬发，寒更塔廊阴。","万物辉今夕，悠悠尘外心。"]},{"t":"秋雨访李鍊师","f":"五言律诗","c":["便静寻丹侣，飞梁度赤城。","洞花含雨落，阶鹤下松迎。","云雾生仙袂，秋寒咽凤笙。","余情会浩荡，先品步虚声。"]},{"t":"送鲍光雄南归","f":"五言律诗","c":["世事风波远，悠悠素发新。","乾坤万里色，江海独归人。","岸柳牵行舫，汀花照暮春。","山中采芳杜，好荐北堂亲。"]},{"t":"田生闻余浩然访于东郭花下酒集二首 其一","f":"五言律诗","c":["花林吾自酌，见觅尔情亲。","转觉花饶笑，番惊蝶趁人。","百年秦地客，万里宋宫春。","酒罢烟城暮，无言对怆神。"]},{"t":"田生闻余浩然访于东郭花下酒集二首 其二","f":"五言律诗","c":["令兄真国土，吾子更超然。","同住孤城里，相邀东郭前。","攀桃映落日，折柳向春天。","更有梁台约，风尘入暮烟。"]},{"t":"佘氏园庄二首 其一","f":"五言律诗","c":["无端二月至，不分百花开。","林坐斜阳入，郊暄沙色来。","秾葩偏近牖，弱柳故临杯。","共是天涯客，无辞酩酊回。"]},{"t":"佘氏园庄二首 其二","f":"五言律诗","c":["百年吾不醉，一岁几何春。","况接桃花暮，难禁柳色新。","君为避世客，余是放歌人。","烂熳题诗遍，林莺莫漫嗔。"]},{"t":"庚午十月佘氏东庄","f":"五言律诗","c":["南客招延屡，东游野兴高。","乾坤侵肃杀，云木半萧骚。","暖泽喧饥雀，冬林秀晚桃。","时清还浪迹，痛饮笑吾曹。"]},{"t":"送人还关中","f":"五言律诗","c":["见君驱去马，忽起望乡思。","华岳寒逾峻，泾河绕自迟。","躬耕为谷口，把钓忆皇陂。","何日一尊酒，南山对不移。"]},{"t":"寄赠内弟玉园居","f":"五言律诗","c":["城市怜余独，乡居见尔稀。","年华仍雪树，疾病有柴扉。","烟起浦欲暝，沙寒鸿自饥。","一身固不保，万事莫嗔违。"]},{"t":"毒热在狱呈陈运使敩暨潘给事中希曾","f":"五言律诗","c":["此地饶炎热，南中恐未然。","有风番助暑，挥汗欲成泉。","鸟避栖深叶，蝇喧集满筵。","百忧吾共汝，流涕北风篇。"]},{"t":"延庆观访陈州王君","f":"五言律诗","c":["珠阁晴逾丽，山林午自和。","我来驱独马，笑尔溺双鹅。","腊雪融楼薄，溪风傍竹多。","虽非宛丘习，吾醉亦婆娑。"]},{"t":"徙泰公方丈秋夜","f":"五言律诗","c":["秋林风色暮，游子念征衣。","鸿雁俱高起，江山独未归。","月临莲室静，萤傍竹林微。","喜对离群友，吾生本息机。"]},{"t":"康状元话武功山水","f":"五言律诗","c":["梦寐关中好，连年未得归。","侧闻武功胜，佳兴益翻飞。","水绕褒斜出，山从盩厔围。","因君觅水竹，为买钓鱼矶。"]},{"t":"发京吕状元送出城","f":"五言律诗","c":["旭日清霜丽，关河独雁飞。","征蓬各自远，会面后应稀。","渭水萦秦塞，南山绕汉畿。","料君乡思切，只恐未能归。"]},{"t":"答何子问讯三首 其一","f":"五言律诗","c":["伊汝投簪日，怜余罥网罗。","江湖鸿雁绝，道路虎狼多。","万死还乡井，潜身葺薜萝。","天涯岁仍晚，无路觅羊何。"]},{"t":"答何子问讯三首 其二","f":"五言律诗","c":["仲夏辞梁地，中秋出夏台。","醉行燕市月，留滞菊花杯。","日暮千行泪，天寒一雁来。","亦知张季子，不为食鲈回。"]},{"t":"答何子问讯三首 其三","f":"五言律诗","c":["弱冠真怜汝，投闲更可哀。","山高桐柏观，水曲范滂台。","假寐凭岩桂，潜行倚岸梅。","此时谁借问，日短暮寒催。"]},{"t":"阻雨明港寄何子二首 其一","f":"五言律诗","c":["白日云犹动，青山雨忽来。","计程今夜会，策马出村回。","月对荆门上，天从梦泽开。","旅灯依港宿，吟苦独徘徊。"]},{"t":"阻雨明港寄何子二首 其二","f":"五言律诗","c":["微微山日舒，彼美碧山隅。","信宿犹难遣，经年秪重吁。","花含明日艳，月助此宵孤。","久拟申城醉，香醪语尔沽。"]},{"t":"贤隐寺集赠","f":"五言律诗","c":["水落移舟稳，山行酒暂随。","寺高垂路细，林密见僧迟。","楼阁登临日，江淮独去时。","不应聊驻此，愈重白云思。"]},{"t":"汉上遇钟参政","f":"五言古诗","c":["长安一为别，十载但书传。","我自河南至，君来自沔川。","偶逢知万事，重会是何年。","馆静风依马，江鸣雨濯船。","情多看转默，酒后惜分眠。","明发孤帆疾，愁经大别边。"]},{"t":"赠钟子汉上","f":"五言律诗","c":["君为薇省使，几度紫薇开。","发以忧时白，舟巡累月回。","汉川惊会面，江南助停杯。","巳约同船下，安能晓霁来。"]},{"t":"独对亭赠人过访","f":"五言律诗","c":["孤亭瞰巨壑，五老对衔卮。","日出峰烟起，风凉谷树悲。","石泉秋听急，山路晚归迟。","异日东南赏，应深庐岳思。"]},{"t":"发贵溪高子辈舟送","f":"五言律诗","c":["旌旗飞近邑，鼓吹送前舟。","礼饯诸生侍，英寮并节游。","长风驱瞑色，密霰响寒洲。","见月帆犹进，山阴恨子猷。"]},{"t":"寄赠林都御史二首 其一","f":"五言律诗","c":["锦水啼莺起，巴山春望微。","干戈满眼急，江汉一舟归。","花送琴书色，霜留斧钺威。","所伤豺虎乱，公也息鸥机。"]},{"t":"寄赠林都御史二首 其二","f":"五言律诗","c":["诸葛能安蜀，穰苴本善兵。","向来优起诏，番作急流行。","老益丹心壮，忧惟白发惊。","秪怜川父老，涕泣挽归旌。"]},{"t":"赠何君辞官归里","f":"五言律诗","c":["三年牧夷邵，万里竟归舟。","瘴离程番雨，雪乘江汉流。","琴书顿县邑，五马向山楼。","棠树苗民种，清阴应旧州。"]},{"t":"新喻遇薛子送赠二首 其一","f":"五言律诗","c":["故旧日益远，寸心奚所安。","雨留杯酒暂，明发楚途漫。","炎暑百蛮尽，风霜五月寒。","知君近南斗，时倚镆铘看。"]},{"t":"新喻遇薛子送赠二首 其二","f":"五言律诗","c":["解剑别此水，怜君向桂林。","徒持一杯酒，其柰故人心。","瘴疠秋行霁，沅湘马度深。","衡阳虽更远，莫遣雁书沉。"]},{"t":"立春寄杨君京口","f":"五言律诗","c":["一水相望隔，飘飘楚越身。","北风犹送雨，南国暗增春。","云入金山接，波添彭泽新。","妙高峰上酒，对酌是何辰。"]},{"t":"顾子谪全州赠二首 其一","f":"五言律诗","c":["楚城悲远望，君去更悠悠。","十月逢南雁，章江兄北流。","寒沙带宿莽，霜日下孤舟。","明发湘东路，应添吊屈愁。"]},{"t":"顾子谪全州赠二首 其二","f":"五言律诗","c":["苍梧遗舜迹，白云秋气愁。","君得人文地，相传是此州。","山连夜郎密，瘴入桂林收。","独有思亲泪，非缘逐客流。"]},{"t":"与樾堂子晚步四首 其一","f":"五言律诗","c":["有伴沙行稳，无云楚望深。","江湖席下出，楼观鸟边阴。","共系南来迹，孤帆北逝心。","徘徊忽复晚，朗月散松林。"]},{"t":"与樾堂子晚步四首 其二","f":"五言律诗","c":["晚俯林烟静，居然尽一城。","江围三面白，雨过四时清。","沙广偏升月，花疏转唤莺。","可言南岫矮，青槩斗牛平。"]},{"t":"与樾堂子晚步四首 其三","f":"五言律诗","c":["北郭浮沙暝，西山拥坐真。","日犹衔殿阁，江巳下星辰。","禹服苗风杂，丰郊剑气伸。","独嗟征舰日，歌吹满城闉。"]},{"t":"与樾堂子晚步四首 其四","f":"五言律诗","c":["美树沙能秀，高花夏不疏。","江山百战后，登眺两人初。","楚月垂鲛泪，燕山涩雁书。","异时羊续壁，喜接豫章鱼。"]},{"t":"九日楚山太华君同登","f":"五言律诗","c":["不入襄阳府，秋山每自来。","那知楚峰上，还共菊花杯。","帽落层云迥，风生万壑开。","却思羊叔子，岘首独悲哀。"]},{"t":"送郑生南归二首 其一","f":"五言律诗","c":["梁园杯酒罢，江上泛舟归。","白日孤帆隐，青天一鸟飞。","路分和靖宅，潮接予陵矶。","羡尔随玄豹，还山戏彩衣。"]},{"t":"送郑生南归二首 其二","f":"五言律诗","c":["挂席南风便，烟霞北望深。","逢人著皂帽，采药鍊黄金。","五月三江路，扁舟四海心。","方山有丛桂，谁与结云林。"]},{"t":"繁台书院同边子三首 其一","f":"五言律诗","c":["壶觞聊首夏，文史更孤台。","地主更来几，登临每复陪。","径兰迎节秀，岩鸽扑骢回。","落日凭轩外，苍苍四岳开。"]},{"t":"繁台书院同边子三首 其二","f":"五言律诗","c":["驻赏林红减，登吟野绿围。","故人率尔遇，时序暗中违。","气突芒砀断，云低孟泽飞。","昔贤谁复此，无羡酒酣归。"]},{"t":"繁台书院同边子三首 其三","f":"五言律诗","c":["兴剧攀巍坐，翛然俯日斜。","亭扶盘石树，崖缀殿春花。","薜服宾游幰，青衿闪钓槎。","绸缪不欲别，风野暮鸣笳。"]},{"t":"台馆访李秀才濂","f":"五言律诗","c":["李生梁国彦，少小事沉冥。","春日古台上，独行枫树青。","花侵映雪壁，鸟下草玄亭。","野阔看无际，浮云似洞庭。"]},{"t":"寄许监察二首 其一","f":"五言律诗","c":["为问乘骢使，经春北未回。","句删淇竹写，尊泛邺花开。","昏晓行山外，风云每自来。","不知铜雀上，临望几徘徊。"]},{"t":"寄许监察二首 其二","f":"五言律诗","c":["初拟周三晋，何时巳百泉。","吏人跳水外，骢马白杨边。","坐忆孙登啸，行吟卫女篇。","倒看峰不极，炎日有霜烟。"]},{"t":"柬黄子二首 其一","f":"五言律诗","c":["约隐情非饰，今归悔即迟。","田园荒欲尽，亲友半相疑。","杯酒惟黄子，儒门是白眉。","可能东郭柳，日往听黄鹂。"]},{"t":"柬黄子二首 其二","f":"五言律诗","c":["径菊陶能得，田瓜邵独勤。","为农消日月，倚杖看风云。","插柳俄成树，笼鹅忽一群。","不须忧万事，客至且醺醺。"]},{"t":"许君话游感旧四首 其一","f":"五言律诗","c":["几日离泉上，泉香满绣衣。","坐谈观水事，想见采菱归。","石柱新留姓，山藜亦借威。","知君薄朱绂，兴在白云飞。"]},{"t":"许君话游感旧四首 其二","f":"五言律诗","c":["泉馆旧曾到，跳珠今若何。","数年鱼不小，题壁客应多。","照日输金浪，回风散锦涡。","君今树菡萏，勿逼古龙窝。"]},{"t":"许君话游感旧四首 其三","f":"五言律诗","c":["亭榭逢君复，源泉改色流。","喷珠连地涌，仰镜合天浮。","掇蛤曾兼石，移家欲狎鸥。","猎心萌自鄙，日往水边头。"]},{"t":"许君话游感旧四首 其四","f":"五言律诗","c":["昔访仙潭鲤，春阴阻独行。","至今看绝顶，长日有云生。","尔昨褰帷过，同深把钓情。","何时掣金鬣，携手万峰晴。"]},{"t":"酬唐礼部见寄二首 其一","f":"五言律诗","c":["万事中年懒，诸人近日疏。","不忘惟墨客，愿见有音书。","倚伏休询鵩，生涯且钓鱼。","问奇终缺酒，不是草玄居。"]},{"t":"酬唐礼部见寄二首 其二","f":"五言律诗","c":["蹈虎看贤达，攀龙几奋飞。","长歌百年内，惨淡万情归。","种竹从过槛，栽桑不虑衣。","神交古有在，莫遣北鸿稀。"]},{"t":"赠张工部汴上","f":"五言律诗","c":["天意焚宫殿，臣心急栋梁。","未花辞魏阙，酷暑向咸阳。","遇我真倾盖，忧时每罢觞。","尘沙一万里，分手向垂杨。"]},{"t":"答许监察百泉和章兼泄所感三首 其一","f":"五言律诗","c":["疏迂甘病足，天地合藏身。","未即辞城市，何缘谢世人。","恨无山在眼，愿与鹿为邻。","暑日情真倍，萧萧水石滨。"]},{"t":"答许监察百泉和章兼泄所感三首 其二","f":"五言律诗","c":["吾门客不到，永昼雀堪罗。","竹色间巾拂，池凉飐芰荷。","片云蹙日卷，双燕掠虫过。","忽忆台端使，诗成只自哦。"]},{"t":"答许监察百泉和章兼泄所感三首 其三","f":"五言律诗","c":["睡起看云坐，敲门报吏来。","受书惊鲤跃，投李得琼回。","思为源泉剧，辞遵北兴裁。","不须共林石，三复野情开。"]},{"t":"和许监察闻报之作","f":"五言律诗","c":["忽尔西边信，飞传过洛阳。","几酋齐豕突，何将最鹰扬。","杀气黄河接，烽烟紫塞长。","筹兵有谏疏，早晚达明光。"]},{"t":"送张监察还朝","f":"五言律诗","c":["北极星辰入，山河斧钺归。","乌争车鹭疾，雨逆盖云飞。","御柳元摇佩，台花且袭衣。","圣心虚采纳，忍使谏书希。"]},{"t":"伏日许君馆亭晚酌二首 其一","f":"五言律诗","c":["暑阁含风暮，林亭透日疏。","俯池閒白羽，把酒跃金鱼。","兴触山花发，心同水叶舒。","孰言台务剧，镇日有琴书。"]},{"t":"伏日许君馆亭晚酌二首 其二","f":"五言律诗","c":["树色寒文簟，池光隐玉壶。","敞筵真不暑，爱客忽忘晡。","乌返争栖柏，鱼欢自戏蒲。","回看阛阓子，天地一洪垆。"]},{"t":"送陈左使赴贵州二首 其一","f":"五言律诗","c":["万里洞庭西，秋风入五溪。","瘴天开斧钺，山驿断虹蜺。","水出牂牁绕，城深井宿低。","堂间花树紫，箫鼓阅雕题。"]},{"t":"送陈左使赴贵州二首 其二","f":"五言律诗","c":["郡县收殊俗，封疆托此臣。","去披炎岭雾，坐使瘴花春。","獠部知徭赋，夷官学缙绅。","谁期召伯树，蔽芾五溪滨。"]},{"t":"早秋监察许君见过","f":"五言律诗","c":["五柳骢偏系，三山雨乍过。","夏蝉犹咽竹，夕露欲倾荷。","眷此青云客，怀余白石歌。","相看恨易晚，灯火发烟萝。"]},{"t":"寄王赣榆","f":"五言律诗","c":["自汝谪东县，朝朝看海头。","书才一纸到，别巳十年周。","日就晚潮落，城浮淮水流。","知君负楚调，激烈向清秋。"]},{"t":"寄李濂兼呈何子","f":"五言律诗","c":["识汝尘埃际，飞腾步步高。","许身元稷契，努力更风骚。","暂亦游香署，终能夺锦袍。","仲言应过数，万里两鸿毛。"]},{"t":"寄王生","f":"五言律诗","c":["重九书新寄，他时意独伤。","故山吾别久，篱菊晚谁芳。","日月徒鸿雁，乾坤尚虎狼。","松楸围几大，人发泪千行。"]},{"t":"酬寄徐子秋日登镜光阁见忆","f":"五言律诗","c":["岁晚湖间阁，秋临共尔曹。","路疑银汉上，身近紫宸高。","霜色诸天镜，窗风四海涛。","别离谁复此，槛望独挥毫。"]},{"t":"赠孟明府自桂林量移汶上","f":"五言律诗","c":["少年东邑宰，万里北还人。","挂巳他时苦，花须满眼春。","偶逢思宿昔，临别见交亲。","莫小牛刀试，元为骢马臣。"]},{"t":"寄王子苏州三首 其一","f":"五言律诗","c":["独立望南天，秋空月会圆。","此时一尊酒，忆尔隔婵娟。","并马游燕日，孤舟去越年。","断肠今万里，心折暮江前。"]},{"t":"寄王子苏州三首 其二","f":"五言律诗","c":["三十乌台使，投冠竟黑头。","田野是故里，江海有新舟。","把酒看鸿举，开窗面虎丘。","不须嘅今古，吾伴鹿麋游。"]},{"t":"寄王子苏州三首 其三","f":"五言律诗","c":["旧交多鬼录，吾子独仙乡。","幸自饶强健，何心说庙廊。","稻输吴郡白，橘足洞庭黄。","饱饭教儿女，摊书日满床。"]},{"t":"寄张孟县","f":"五言律诗","c":["同年多出宰，独尔得河阳。","背郭围王屋，开门对北邙。","词章前令掩，桃李旧花香。","何日乘云起，双凫入帝乡。"]},{"t":"酬徐子春日登楼见寄","f":"五言律诗","c":["三月垂杨合，风花满帝州。","伊予直北望，尔上几层楼。","紫塞连天起，黄河抱地流。","春烟动万里，何处觅前游。"]},{"t":"送许监察还朝二首 其一","f":"五言律诗","c":["杯酒岂无友，知音谁复多。","君今万里去，吾柰好春何。","路草随轺碧，山莺近驿歌。","尚思文话地，骢马月中过。"]},{"t":"送许监察还朝二首 其二","f":"五言律诗","c":["吾园花烂漫，子特驻骢看。","偶念明朝别，先违两地欢。","胜之元执斧，陶氏合投冠。","去住情俱得，离杯莫放乾。"]},{"t":"再赠许君","f":"五言律诗","c":["缘岸百花开，楼船三月回。","人依铁瓮望，鸟避柏乌来。","礼乐还朝疏，山川画笏才。","太微遥巳入，新彩近三台。"]},{"t":"边君生日来访时近中秋不虞雷雹二首 其一","f":"五言律诗","c":["怪尔生辰日，高轩特过吾。","秋惊飞雹至，雨逐去云无。","上寿须君子，同声愧老夫。","母劳问隐显，乘月有清壶。"]},{"t":"边君生日来访时近中秋不虞雷雹二首 其二","f":"五言律诗","c":["雹过天仍雨，庭空晚复雷。","连床慨往昔，阻马得徘徊。","暗蕊香宾席，秋灯焰寿杯。","非君有家庆，肯放夜轺回。"]},{"t":"繁台院阁饯沈子之云南拜怀刘子二首 其一","f":"五言律诗","c":["斗酒重阳后，危楼万里前。","停云忽蔽地，起鹤故横天。","斜日留倾盖，疏花影别筵。","忍看骢马使，遥向碧鸡边。"]},{"t":"繁台院阁饯沈子之云南拜怀刘子二首 其二","f":"五言律诗","c":["岂料吾刘沈，提刑继入滇。","经过此台上，共醉菊花筵。","日落杯光动，楼空海色连。","无论即万里，身世转蓬前。"]},{"t":"送侄木甥嘉会试","f":"五言律诗","c":["二子趋南省，同车向北燕。","苦心冲雁雪，得意伫花天。","合浦珠光会，丰城宝气连。","谅怀鹏举志，吐胆凤楼前。"]},{"t":"繁台冬饯翟子三首 其一","f":"五言律诗","c":["野馆逢君日，相逢复惜违。","暖崖花尚发，冬树果初肥。","斧钺从天至，家山傍海归。","悬知称庆处，不独锦为衣。"]},{"t":"繁台冬饯翟子三首 其二","f":"五言律诗","c":["邦君荣大礼，星使返三台。","路指东方入，尊留南郭开。","馆深私自静，筵暮月还来。","明日山河异，无言不醉回。"]},{"t":"繁台冬饯翟子三首 其三","f":"五言律诗","c":["为慕梁台胜，纡君驻马观。","风霜当夜急，楼阁近星寒。","酩酊犹更独，徘徊数倚阑。","知君有家国，忍向北云看。"]},{"t":"丙子生日答内弟玑","f":"五言律诗","c":["今夜今年聚，谁知骨肉稀。","汝犹悲燎粥，子岂那于飞。","对火霜威入，侵杯月色微。","斗斜灯更续，不是醉无归。"]},{"t":"雪后寺集夜别王子","f":"五言律诗","c":["僧夜晴游地，月高钟磬闻。","塔光斜照雪，香气上蒸云。","客向杯前聚，途于醉后分。","别离谁不尔，缱绻独斯文。"]},{"t":"早春怀上方寺","f":"五言律诗","c":["此寺城中僻，边城野四围。","青天直塔上，落日称僧归。","殿古松风入，台春草雪微。","觅碑吾不懒，所虑鸟惊飞。"]},{"t":"春日过李氏因赠","f":"五言律诗","c":["偶忆孩童日，能禁老大悲。","向来门巷接，长是酒筵随。","礼乐儒门旧，风花世路疑。","不须辞夜饮，春月正逶迤。"]},{"t":"送郑生","f":"五言律诗","c":["河水未尽脱，怪尔驾舟还。","言向金陵去，春登江上山。","渌波元楚徼，芳草自吴关。","宝剑男儿在，那忧行路艰。"]},{"t":"柬张含","f":"五言律诗","c":["战国侯嬴里，梁园李白杯。","夏骄惟溽雨，秋弱尚鸣雷。","病馆经旬滞，归旌万里催。","别书期早寄，莫俟北鸿回。"]},{"t":"憩长葛端壁寺遇遇使人王卿赍监察毛君诗劄到困顿中口占驰寄亦咎游山之约","f":"五言律诗","c":["远为长葛憩，忽接许昌吟。","不睹暮云句，那知春别心。","早花连颍岸，晚日下嵩岑。","咫尺盟难践，何须问古今。"]},{"t":"月下柬张含","f":"五言律诗","c":["风餐凉雨过，露坐晚林幽。","汝对梁园月，孰如金齿秋。","常星皆北拱，滇海独西流。","万里清光在，应怀今夜游。"]},{"t":"送张含","f":"五言律诗","c":["明发车南指，滇城更复南。","秋惊洞庭叶，雪压贵州岚。","念汝此行远，求官今尚淹。","保昌山坞侧，好结望京庵。"]},{"t":"秋日读王子赴江西时诸曹赠行篇什感赋","f":"五言律诗","c":["接揽江西辔，同怀振铎年。","匡庐并突兀，鄱水日悠然。","子进薇花省，子归莲叶船。","梁园邂逅地，把酒对秋天。"]},{"t":"繁台送张内史侍母还蜀同毛袁监察三首 其一","f":"五言律诗","c":["幸值高秋霁，何愁蜀道难。","顾瞻知国念，跋涉为亲欢。","露菊沿江熟，风林过栈寒。","故园如有梦，应在五云端。"]},{"t":"繁台送张内史侍母还蜀同毛袁监察三首 其二","f":"五言律诗","c":["翰苑飞名久，梁园接席初。","文谈白日下，凉露碧林疏。","剑阁天真险，巴山锦不如。","馔亲知尽乐，日日有姜鱼。"]},{"t":"繁台送张内史侍母还蜀同毛袁监察三首 其三","f":"五言律诗","c":["饮暮不归去，繁台秋正深。","侍臣轩偶遇，骢马酒同临。","去国三川路，停云万里心。","西南雁不到，吾迟尺鱼音。"]},{"t":"丁丑重九繁台酒集","f":"五言律诗","c":["高会今秋始，重阳逐岁同。","上台寒日午，开阁古林风。","且约黄花醉，休嗟白发翁。","旧游不须问，天际有飞鸿。"]},{"t":"寄王宪使二首 其一","f":"五言律诗","c":["反侧须开县，安危亦仗兵。","饶山夹岸密，鄱水向秋清。","部使轻裘入，馀黎里饭迎。","怪来服从易，为惧靖南名。"]},{"t":"寄王宪使二首 其二","f":"五言律诗","c":["传尔提刑地，思予揽辔游。","湖山不改秀，蛇虎向来忧。","卖剑元能事，褰帷啻此州。","范公芳未泯，亭在北山头。"]},{"t":"寄崔内史病还邺","f":"五言律诗","c":["漳浦新归客，文园旧病身。","乾坤金马外，杖屦碧山春。","书合虞卿著，耕非桀溺伦。","汉庭文赋笔，谁及茂陵臣。"]},{"t":"早春宴黄宅","f":"五言律诗","c":["岐路风花里，乾坤醉眼中。","事随年共异，春与昔还同。","相聚今何夕，相看各巳翁。","夜和杯更暖，休负烛花红。"]},{"t":"送右辖王子逼除赴嵩山之役以狱事","f":"五言律诗","c":["遽有嵩山役，恰然逢此春。","旌旗拂岫入，车马驻萝新。","坐爱溪花发，行怜寨兽驯。","时雷苏万物，君重系累民。"]},{"t":"送佘生南监","f":"五言律诗","c":["江门柳色暗，四月浪花高。","尔抱鱼龙志，休随雀燕曹。","金山入紫气，璧水动青袍。","倘虑音书隔，南风有顺毛。"]},{"t":"繁台秋饯何子二首 其一","f":"五言律诗","c":["会少怜君暂，台孤引望频。","清秋属过雁，落日有征人。","华岳元通洛，黄河不弃秦。","异时愁独上，千里见嶙峋。"]},{"t":"繁台秋饯何子二首 其二","f":"五言律诗","c":["候吏催迟暮，游人怨解携。","十年内供奉，万里竟关西。","地古饶文物，时平罢鼓鼙。","巡行有佳兴，应遍绝崖题。"]},{"t":"再饯何子","f":"五言律诗","c":["武场重布席，文士此分襟。","人世东西路，秋天旦暮阴。","杯光摇弱草，庭色下饥禽。","他日关中使，无忘汴上音。"]},{"t":"喜李生自京师归","f":"五言律诗","c":["北极星齐入，中原尔独归。","田园自松菊，身世有庭闱。","鱼可一钱买，花常四季飞。","感时台莫上，恐湿贾生衣。"]},{"t":"送柳仪宾进圣节表","f":"五言律诗","c":["万国生辰表，天王北狩时。","鸡鸣元紫禁，虎拜亦丹墀。","汉树霜枫古，尧蓂露荚移。","无辞醉宫酒，当是旧朝仪。"]},{"t":"中秋别郑生","f":"五言律诗","c":["别离谁独免，此别是中秋。","尔上袁宏艇，予登庾亮楼。","羽衣飘北槛，渔笛起中流。","炯炯共明月，那堪两地愁。"]},{"t":"已卯元日内弟玑见过二首 其一","f":"五言律诗","c":["内弟元朝过，柴门午一开。","柏尊吾足办，椒颂尔须裁。","天地冰霜变，江湖日月催。","鬓毛斑欲甚，谁忍复春来。"]},{"t":"已卯元日内弟玑见过二首 其二","f":"五言律诗","c":["汝今年四十，而我八年多。","世路怜书剑，生涯笑薜萝。","游将花并放，醉拟鸟同歌。","莫问朝元日，伤心是玉珂。"]},{"t":"送戴氏","f":"五言律诗","c":["两河飞雨尽，万里不尘沙。","白马朝天客，春风御柳花。","声名新上计，袍笏旧传家。","谅有兰台擢，应难舍伏伽。"]},{"t":"寄毛监察","f":"五言律诗","c":["江汉归鸿雁，乾坤罢虎狼。","薜萝吾故土，骢马尔何乡。","岸树霜先赤，篱花晚自黄。","向来杯酒地，台柏但苍苍。"]},{"t":"雪中郑生见访","f":"五言律诗","c":["万户风花起，吾门尔一开。","惊看破履迹，笑指白须来。","驴为登桥熟，船非访戴回。","今朝梁苑赋，合试马卿才。"]},{"t":"雪中苏生以诗见过","f":"五言律诗","c":["楚楚眉山裔，儒林羡白眉。","朅来白雪里，惠我阳春词。","结绶终相庆，投珠莫自悲。","长安马蹄疾，是尔看花时。"]},{"t":"春初大道观访苏生","f":"五言律诗","c":["草生坛雪尽，宛宛孤云辉。","怪尔黄庭罢，双鹅不换归。","窗镫留夕照，栏竹伴春晖。","安得频过此，谈玄两不违。"]},{"t":"寄陈浚","f":"五言律诗","c":["借问垂双翅，何时奋一飞。","黄金不易就，黑发渐应稀。","山雪骑驴出，江风捲钓归。","所嗟冠盖地，独尔薜萝衣。"]},{"t":"赠僧怀让越人也嗜酒其居有借树轩","f":"五言律诗","c":["访旧来东社，焚香对病禅。","素琴真与寂，浊酒及通玄。","邻树当经牖，春花落讲筵。","不逢支遁语，谁解月中传。"]},{"t":"逢郏王子","f":"五言律诗","c":["相思汝水月，相见帝城春。","紫逻云烟迥，青门柳色新。","岂如题凤侣，疑是好鹅宾。","醉即挥鞭别，金龟报主人。"]},{"t":"徐子过别因而留宿","f":"五言律诗","c":["岂是陈蕃榻，能淹孺子栖。","无言向春月，难寐及晨鸡。","钩幔回春色，梳头过鸟啼。","如何艳阳节，与尔惜分携。"]},{"t":"洪法寺遇乡僧","f":"五言律诗","c":["烂熳春游处，重来冬日凄。","松风犹故壑，露叶巳新蹊。","废井浮阳出，巍阡冻雾栖。","逢僧话乡曲，寒望转萋迷。"]},{"t":"送张生还金齿二首 其一","f":"五言律诗","c":["万里来何事，三人此复过。","高秋鸿雁下，落木洞庭波。","岁月长途老，风云后进多。","百蛮家更远，自爱莫蹉跎。"]},{"t":"送张生还金齿二首 其二","f":"五言律诗","c":["大雅流重译，殊方挺上才。","批鳞书几上，塌翅首频回。","白发南荒路，秋风北宋台。","三杯邂逅地，为尔一徘徊。"]},{"t":"送郑淳入闽","f":"五言律诗","c":["江海发春涛，南浮二月舠。","花行浙口盛，云近武夷高。","土布离乡贵，杉鸡诧客号。","延平津倘过，珍閟匣中刀。"]},{"t":"送王左史入觐","f":"五言律诗","c":["帝里花应待，王筵醴暂违。","舟从泰水上，人是锦衣归。","日月瞻新衮，风云壮旧畿。","辞朝君即返，莫赋北山薇。"]},{"t":"送侄竹赴京听除","f":"五言律诗","c":["皇王宝历开，汝上黄金台。","气色三光正，人心万国来。","拜除将檄入，辞谢柚香回。","幸会风云路，行伸騕袅才。"]},{"t":"送伍长垣赴召二首 其一","f":"五言律诗","c":["君赴兰台召，谁看此县花。","久知骢是马，当许鹭随车。","日月新明主，乾坤旧一家。","异时缣帛赏，应首及孙伽。"]},{"t":"送伍长垣赴召二首 其二","f":"五言律诗","c":["要地徵名尹，新朝急俊臣。","班升玉笋晓，台散紫兰春。","万水元趋海，群星自拱辰。","谁言大河上，白首有垂纶。"]},{"t":"寄熊御史塞上","f":"五言律诗","c":["汉官持斧处，天险惜离群。","塞口孤城断，峰腰细涧分。","胡天秋更惨，杀气暮还云。","定有忧边计，缄驰达圣君。"]},{"t":"秋日王子台上","f":"五言律诗","c":["暑霁名王会，台成上客过。","清秋疏草木，落日上笙歌。","天地衔杯尽，风云傍槛多。","圣明今御极，谁复虑干戈。"]},{"t":"酬钱子锡山之招","f":"五言律诗","c":["南迁公约我，北望我怀公。","阳羡春芽秀，荆溪早稻红。","乘槎伍胥口，采药洞庭东。","何日酬吾志，江涛日夜风。"]},{"t":"送王子如淞江","f":"五言律诗","c":["宝剑寒无色，苍然海上行。","异书探战伐，高论动公卿。","何日为毛遂，前身是贾生。","谁怜同学子，章句独虚名。"]},{"t":"晚过孟氏雷雨遽至会王子亦来二首 其一","f":"五言律诗","c":["王褒真畏友，孟浩复多才。","下马云徐暮，开尊雨骤来。","疾雷当户落，惊电触檐回。","坐待明星出，无疑晓漏催。"]},{"t":"晚过孟氏雷雨遽至会王子亦来二首 其二","f":"五言律诗","c":["霁月出还没，骄雷东复西。","千门萤火动，六月候虫啼。","共是天涯客，能忘雨后题。","吾诗催仗汝，好放片云低。"]},{"t":"僧园秋集同田生二首 其一","f":"五言律诗","c":["榴竹晴相媚，秋光满给孤。","微风捎果重，残暑入林无。","宝塔金杯映，青天白鹤呼。","不须谈浩劫，吾醉亦忘吾。"]},{"t":"僧园秋集同田生二首 其二","f":"五言律诗","c":["自笑红颜日，僧今白首看。","秋风修竹过，台殿碧梧残。","钟磬昏仍起，壶觞醉不乾。","塔层思尽上，恐逼斗牛寒。"]},{"t":"春日宴山泉王子之第同左田二子二首 其一","f":"五言律诗","c":["入殿笙箫合，开筵锦绣围。","苑枝春竞发，台日晚犹辉。","语燕窥吟管，飞花坐舞衣。","二豪同酩酊，与尔月中归。"]},{"t":"春日宴山泉王子之第同左田二子二首 其二","f":"五言律诗","c":["巳恨韶华剧，能孤烂熳游。","莺啼檐树换，蝶戏槛花流。","宾客朝开苑，笙歌晚入楼。","但看今会者，孰与汉枚邹。"]},{"t":"酬赠阁老刘公四首 其一","f":"五言律诗","c":["雷奋龙犹卧，云俱鹤自闲。","一杯莘野月，双屐谢公山。","贵客常辞避，田夫数往还。","桂庭秋偃蹇，公醉拉谁攀。"]},{"t":"酬赠阁老刘公四首 其二","f":"五言律诗","c":["大号更嘉靖，明公会古稀。","老惊诗律健，闲爱醉游归。","庭户罗花竹，儿孙导綵衣。","向非千仞览，那见太平辉。"]},{"t":"酬赠阁老刘公四首 其三","f":"五言律诗","c":["寿席秋能半，宾庭月故圆。","前身金粟佛，今代玉堂仙。","兔巧元供药，龟灵岂算年。","蝇头灯下字，犹注紫霞编。"]},{"t":"酬赠阁老刘公四首 其四","f":"五言律诗","c":["野绿情真逸，山香望独高。","酒嫌裴相浅，诗掩乐天豪。","公实当三老，吾虚受二毛。","人遐室幸迩，音惠莫言劳。"]},{"t":"送田生读书上方寺三首 其一","f":"五言律诗","c":["嗜静甘违俗，藏修合就僧。","绿移开径竹，寒扫护窗藤。","殿阁秋阴下，琴书爽气增。","不须匡氏壁，常有玉莲灯。"]},{"t":"送田生读书上方寺三首 其二","f":"五言律诗","c":["寺压孤城断，堂开积水围。","一僧当茗灶，群鹭狎荷衣。","被酒时登塔，持书晚坐矶。","鹤腾知客至，嗟汝咏而归。"]},{"t":"送田生读书上方寺三首 其三","f":"五言律诗","c":["凉雨满庭户，冷然松桂幽。","隔云清磬湿，向夜一灯留。","萤火辉书幌，乌啼上佛楼。","让多今古意，先著宋春秋。"]},{"t":"登钟楼答田秀才","f":"五言律诗","c":["老足秋能健，朋游崄益豪。","眼当孤阁放，身巳百层高。","霜壁摇朱杞，风檐落白蒿。","生平望东海，一钓有连鳌。"]},{"t":"别郑生","f":"五言律诗","c":["白首还离别，长途倍苦辛。","愤时惟按剑，避世谩垂纶。","江海烟霜日，乾坤去住身。","临河见双雁，杳杳向秋旻。"]},{"t":"送白帅留守中都","f":"五言律诗","c":["幕府开淮甸，山河绕汉陵。","晓霜迎旆入，王气及秋澄。","弩卧铜牙涩，矛抛绿藓增。","黄金印如斗，应有异时徵。"]},{"t":"再送白帅","f":"五言律诗","c":["圣主下龙章，将军入凤阳。","地盘淮海壮，天拥汉陵长。","棨戟新开府，威名古辟疆。","卜年元万世，王道是金汤。"]},{"t":"再送郑生","f":"五言律诗","c":["闻君数日住，使我百忧宽。","池馆杯觞易，天涯故旧难。","久晴冬欲暖，近水晚犹寒。","借取防身剑，慇勤醉里看。"]},{"t":"谭刘二子过赏牡丹二首 其一","f":"五言律诗","c":["载酒来朋远，寻芳出郭遥。","遇花双盖住，系柳一骢骄。","野席留香迥，晴尊助艳娇。","谁言阑百宝，吾有玉鸾箫。"]},{"t":"谭刘二子过赏牡丹二首 其二","f":"五言律诗","c":["学舞花将起，矜歌鸟自来。","日筵随荫徙，风袂入香开。","李白昭阳调，姚黄洛下杯。","古今君莫问，且促醉轺回。"]},{"t":"春日寄题崔学士后渠书屋七首 其一","f":"五言律诗","c":["草阁临何地，花天想后渠。","傍墙应植柳，俯岸几跳鱼。","好撰王褒颂，休亲郭橐书。","改元新礼制，侧席待相如。"]},{"t":"春日寄题崔学士后渠书屋七首 其二","f":"五言律诗","c":["石白云花瑩，湍青水叶香。","野情鸥鸟足，纱帽世涂忘。","问字船能过，听莺客不妨。","无言浑是暇，当有草玄忙。"]},{"t":"春日寄题崔学士后渠书屋七首 其三","f":"五言律诗","c":["鲍客春还邺，崔渠遂盛传。","水溶漳岸日，草碧魏城天。","径竹竿竿秀，汀花朵朵鲜。","但无醒酒石，物物胜平泉。"]},{"t":"春日寄题崔学士后渠书屋七首 其四","f":"五言律诗","c":["敞敞渠边屋，煇煇座右铭。","竹琴晴愈静，萝烛夜还青。","洹水明卿月，陈家聚德星。","泥中虽近戏，仆隶解谈经。"]},{"t":"春日寄题崔学士后渠书屋七首 其五","f":"五言律诗","c":["是否龟蒙鸭，将无逸少鹅。","内官聊一戏，道士敢烦过。","自坐莆矶饮，谁攀桂棹歌。","绝弦知不易，白眼向山河。"]},{"t":"春日寄题崔学士后渠书屋七首 其六","f":"五言律诗","c":["赋笔多崔瑗，朋车愧吕安。","碧渠何日到，云树一春看。","南果枇杷活，西郊苜蓿宽。","觅君终系马，舣棹是何滩。"]},{"t":"春日寄题崔学士后渠书屋七首 其七","f":"五言律诗","c":["且养岷山鸟，休焚学士鱼。","穷通不在我，水竹漫成居。","绿薜深藏屋，丹花浅映渠。","几时朝圣主，人拟治安书。"]},{"t":"小园花发谭刘二君订游涉夏始至席上三首 其一","f":"五言律诗","c":["尚有春留赏，无言客过迟。","砌红残芍药，园绿半荼縻。","邂逅情真倍，追随酒莫辞。","有怀君尽放，得意是佳期。"]},{"t":"小园花发谭刘二君订游涉夏始至席上三首 其二","f":"五言律诗","c":["缱绻杯侵夜，迂徐月转庭。","醉寻松影立，凉爱竹风听。","老去朋情恕，年来世事经。","玉绳天历历，谁识少微星。"]},{"t":"小园花发谭刘二君订游涉夏始至席上三首 其三","f":"五言律诗","c":["涉夏榴能绽，深更客尚游。","群行逢树问，独立为花留。","就月还移席，呼儿重洗瓯。","醉眸横北斗，曙角起城头。"]},{"t":"送吕广文四川衡聘","f":"五言律诗","c":["大省文衡重，名师礼聘遥。","阁云寒暑旆，栈月引星轺。","古帝蚕丛国，今人驷马桥。","好将杨马辈，收取贡清朝。"]},{"t":"赠孟监司赴任三首 其一","f":"五言律诗","c":["南辍江湖棹，东飞海岱旗。","勇辞知至性，强起为名时。","气节聊城箭，文章孔庙碑。","秋风立马地，莫动季鹰思。"]},{"t":"赠孟监司赴任三首 其二","f":"五言律诗","c":["汶上篇仍在，齐东节重过。","绕台新柏秀，匝县旧花多。","海色摇行幰，山云护咏窝。","谈天君一问，稷下近如何。"]},{"t":"赠孟监司赴任三首 其三","f":"五言律诗","c":["麋鹿游山性，蛟龙卧水心。","得云终一起，食野不孤吟。","汝去观沧海，予常慕孔林。","何时挈尊酒，同蹑太山岑。"]},{"t":"送谭子二首 其一","f":"五言律诗","c":["国谥逾年至，王臣触暑行。","水花邀去节，山鸟劝离觥。","久客交人广，携家念土轻。","玉筵颁扇目，应注使回名。"]},{"t":"送谭子二首 其二","f":"五言律诗","c":["聚赏蜂初课，分携燕巳雏。","泥惊落夏簟，花忆倒春壶。","水路风旗进，晴船暑气无。","五云赤日外，缥缈是皇都。"]},{"t":"赠监察阻雨郊馆","f":"五言律诗","c":["积雨淹征旆，层城隔论文。","一尊真惜酒，万里正横云。","京国骢谣属，闽江道派分。","美名吾实羡，何处接高芬。"]},{"t":"庭菊纷披有怀王喻二君子","f":"五言律诗","c":["雁急秋真晚，园空菊自黄。","露团番有色，风度不随香。","却忆初开日，君来夜把觞。","忍今看烂熳，独绕碧篱傍。"]},{"t":"晚秋王喻二监察见过二首 其一","f":"五言律诗","c":["自种吾堂菊，无人共把卮。","昨来三径雨，忽与两骢期。","槛霁花逾爽，林寒酒故随。","坐忘俱酩酊，莫遣白衣知。"]},{"t":"晚秋王喻二监察见过二首 其二","f":"五言律诗","c":["霜日来骢并，晴杯汎菊频。","古今元逆旅，天地几閒身。","雁阵寒从急，篱香晚自新。","豪吟不知夜，圆月在高旻。"]},{"t":"菊日任君见过","f":"五言律诗","c":["菊筵开遇雨，秋色转增孤。","冷翠元浮席，流香故洒壶。","蕊沾卷袖摘，径滑倩人扶。","莫谓无开霁，斜阳酒重沽。"]},{"t":"寄郑生二首 其一","f":"五言律诗","c":["故菊开谁对，新醪怅尔违。","耳憎木叶下，心与塞鸿归。","儿女催蓬鬓，家园滞綵衣。","问君称庆暇，何处采山薇。"]},{"t":"寄郑生二首 其二","f":"五言律诗","c":["节序仍黄菊，乾坤更白头。","文章宁益世，衣食暂宽忧。","遇客谁谈剑，思君独倚楼。","远江寒细细，似有北行舟。"]},{"t":"月夜繁台会两监察二首 其一","f":"五言律诗","c":["蹃叶风交落，台骢晚并行。","时寒物色换，意远世缘轻。","异国同觞地，危楼片月情。","暝烟凭槛里，汴水冻犹声。"]},{"t":"月夜繁台会两监察二首 其二","f":"五言律诗","c":["万里危楼夜，中天朗月时。","快心真托酒，凝望转停卮。","野色霜元迥，林光烛并移。","依依檐畔鹊，先占独栖枝。"]},{"t":"送李生还郡二首 其一","f":"五言律诗","c":["宦美庭闱隔，情深郡檄催。","腊江舟自稳，暮日首频回。","洞橘黄金摘，吴鱼白雪来。","汝亲知更乐，愿展治邦才。"]},{"t":"送李生还郡二首 其二","f":"五言律诗","c":["伯道吴门水，梁公冀北云。","依亲岁聿暮，趋郡袂还分。","腊动苏台色，春回震泽薰。","重过应未远，良吏汉廷闻。"]},{"t":"甥嘉北采出其谒逢干庙之作予为和之嘉时谪茂州判","f":"五言律诗","c":["汝谒双忠庙，徘徊几度吟。","暴云连海白，积水带城阴。","自抆看碑泪，谁知驻马心。","未须悲远窜，不死是恩深。"]},{"t":"送甥嘉之茂州次玉溪侍御韵三首 其一","f":"五言律诗","c":["巳诧齐东谪，能堪蜀道行。","自甘穷塞窜，争柰倚闾情。","剑阁云中栈，蓬婆雪外城。","大江秋见底，待尔濯长缨。"]},{"t":"送甥嘉之茂州次玉溪侍御韵三首 其二","f":"五言律诗","c":["蜀道元非易，人言此更难。","虎风生万壑，蛇径动千盘。","北望常思阙，西来不为官。","无言羌性异，汝当郡民看。"]},{"t":"送甥嘉之茂州次玉溪侍御韵三首 其三","f":"五言律诗","c":["雪山天地外，经夏雪难消。","气冷三城戌，光通万里桥。","谁言州不好，汝去蹃宁遥。","纵使胡笳夜，犹能梦入朝。"]},{"t":"郊原迟王豸使","f":"五言律诗","c":["岂少银鞍马，冲泥许故游。","清风微进草，晴日澹生秋。","扫径童将倦，看笼鹤但收。","异时高李会，佳迹至今留。"]},{"t":"王豸使至","f":"五言律诗","c":["晴游番幸雨，午出更便风。","柳重陶潜宅，花沾御史骢。","达人元野性，浊酒本村翁。","酌罢桑麻晚，归灯一径红。"]},{"t":"王豸使既返东月皎升乃与李曹二子径觞吹台之巅口占柬黄子","f":"五言律诗","c":["王归不待月，二子共登台。","天地划然皎，山河相荡回。","虫鸣崖底叶，雁影掌中杯。","为问山阴客，还能棹雪来。"]},{"t":"秋日吕公西园同玉溪侍御二首 其一","f":"五言律诗","c":["圃胜城能曲，台高野更秋。","席陪骢马出，情为碧云留。","移坐铺林叶，添樽面水流。","潜思歌舞地，指点问王州。"]},{"t":"秋日吕公西园同玉溪侍御二首 其二","f":"五言律诗","c":["入院看垂杮，临畦羡引泉。","寒荽自满地，疏树不妨天。","野老疑旌旆，林乌下酒筵。","无云但游衍，公意在桑田。"]},{"t":"西园酒半会玉溪侍御瓜代报至再赋二首 其一","f":"五言律诗","c":["北使还朝近，西城返照深。","霜情留果实，晚意付花心。","风助林皋爽，云横海岳阴。","兹游如在念，应有寄南音。"]},{"t":"西园酒半会玉溪侍御瓜代报至再赋二首 其二","f":"五言律诗","c":["胜地留宾切，离筵散酒迟。","网鱼生跃案，摘枣脆连枝。","草夕鸣蛩动，天秋过雁知。","河桥明日事，愿尽掌中卮。"]},{"t":"见和君病起须白辄有所赠亦咎其酒过","f":"五言律诗","c":["诧汝须添白，将无病苦形。","眼前真过隙，身外是浮萍。","客到留棋局，儿呼检药经。","昔人曾颂酒，吾意不如醒。"]},{"t":"和郑生行经凤阳","f":"五言律诗","c":["浩荡兴龙地，盘旋踞虎形。","海吞淮水白，天插楚峰青。","帝宅精灵聚，陵宫虎豹扃。","万年禋祭礼，有道赖朝廷。"]},{"t":"初冬见雪和鲍生","f":"五言律诗","c":["密云初布暝，疏雨忽成花。","气浅冰从薄，寒轻白自斜。","敝裘谁念汝，孤棹独思家。","江上冥冥雁，春风迟去槎。"]},{"t":"郑生至自泰山二首 其一","f":"五言律诗","c":["昨汝登东岳，何峰是绝峰。","有无丈人石，几许大夫松。","海日低波鸟，岩雷起窟龙。","谁言天下小，化外亦王封。"]},{"t":"寄鲍崇儒","f":"五言律诗","c":["去日犹零雪，庭葵遽复花。","新诗谁和汝，久客自成家。","水国乾侵夏，田风莽带沙。","长淮日易暮，珍重早栖鸦。"]},{"t":"送赵训学满归二首 其一","f":"五言律诗","c":["六旬千里客，九载一毡归。","路远琴书重，官贫妻子饥。","塞云迎老鬓，河色恋征衣。","会有秋行伴，关山新雁飞。"]},{"t":"送赵训学满归二首 其二","f":"五言律诗","c":["宋代陈无巳，唐时郑广文。","道高官独冷，名美世同闻。","汝挈一毡去，予怜双袂分。","潸潸白首泪，长向渭西云。"]},{"t":"秋过内弟漫赋二首 其一","f":"五言律诗","c":["赫赫乘龙地，萧萧罗雀门。","桑麻犹世业，书史但儿孙。","数过看颜帖，今来为菊樽。","显亲君太晚，愿化北溟鲲。"]},{"t":"秋过内弟漫赋二首 其二","f":"五言律诗","c":["主宾俱不饮，相对坐同深。","幸有黄花兴，无论白发心。","游虫纷落日，高叶下疏林。","静里闻鸿雁，疑添往岁音。"]},{"t":"赠陈生嘉言二首 其一","f":"五言律诗","c":["少小期鹏运，于今尚未飞。","蒿深仲蔚宅，鹑结宪生衣。","背郭元桑树，临河只钓矶。","奉亲知不苦，馔有白鱼肥。"]},{"t":"赠陈生嘉言二首 其二","f":"五言律诗","c":["白屋山中相，黄河水后田。","家无酿酒秫，人索买书钱。","雨过云留野，风来浪接天。","行行牛角上，犹挂古人编。"]},{"t":"七夕雪台子过东庄","f":"五言律诗","c":["村落元相接，园林亦互游。","酒天携榼就，花夜对床留。","忽尔双星候，泠然万木秋。","谁期白头日，萧洒共丹丘。"]},{"t":"赠程生东游","f":"五言律诗","c":["邹鲁风犹在，芒砀气有无。","霸心空大泽，儒行乃长途。","野艇冰迷雁，村楼冻集乌。","无劳怨岁暮，随处是江湖。"]},{"t":"寄题高子君山别业二首 其一","f":"五言律诗","c":["一山背城起，万古号为君。","秀揽江心月，雄吞海面云。","金陵通地脉，玉港发人文。","羡彼投簪客，中年卧紫氛。"]},{"t":"寄题高子君山别业二首 其二","f":"五言律诗","c":["季札坟边业，春申邑后山。","一江平展镜，两港曲成环。","不雨云烟拥，长春草木斑。","隐君梯万丈，倘许世人攀。"]},{"t":"送刘尹赴徵","f":"五言律诗","c":["恋别当炎暑，淹留到夕晖。","徵书昨日下，循吏古人稀。","风树凉移席，庭萱晚就衣。","明朝五云里，争看两凫飞。"]},{"t":"冬日寺集观赵帅射","f":"五言律诗","c":["万里横霜气，长风快顺毛。","将军只弩发，叠中两鸿号。","取石敲新火，开鲜弄宝刀。","回头问僧者，何处得醇醪。"]},{"t":"丁亥寒食柬养素","f":"五言律诗","c":["细雨秾花候，高斋独坐辰。","春风无病物，清世有閒人。","树湿莺穿稳，泥香燕下频。","遥思养素者，何处卧松筠。"]},{"t":"喜程生自吴中回致五岳黄山人音问二首 其一","f":"五言律诗","c":["烂熳梁园树，江舟尔恰回。","苑桃惟旧列，墙柳半新栽。","枝为来人袅，花迎笑口开。","吴门春更好，几上虎丘台。"]},{"t":"喜程生自吴中回致五岳黄山人音问二首 其二","f":"五言律诗","c":["黄子吾真畏，程生尔更奇。","江城倾盖日，渭北暮云时。","宝剑神终合，冥鸿性不移。","忽思千里驾，惭愧昔人为。"]},{"t":"伏日载酒寻高司封读书处二首 其一","f":"五言律诗","c":["郑门古城曲，小筑成幽园。","为厌朝簪扰，兼辞人境喧。","矮堂交杂树，炎日驻游轩。","默默林中意，相看对一尊。"]},{"t":"伏日载酒寻高司封读书处二首 其二","f":"五言律诗","c":["养寂为园卧，寻幽当暑过。","林深得日薄，地静觉蝉多。","旧业元粳稻，新亭复薜萝。","谁怜朱绂客，遽恋白云窝。"]},{"t":"怀五岳山人黄勉之","f":"五言律诗","c":["吴下元多士，黄生更妙才。","心常在五岳，名巳动三台。","系自汝南出，文从西汉来。","各天难见汝，翘首独徘徊。"]},{"t":"郊居东竹溪子","f":"五言律诗","c":["当春弄杯盏，花落恨纷纷。","重来日复几，飞叶满秋云。","寒流下雁影，古戍噪鸦群。","残菊犹堪把，长谣独忆君。"]},{"t":"闻吴郡黄山人将游五岳寄赠二首 其一","f":"五言律诗","c":["昨报三吴客，将寻五岳游。","薜萝应制服，春水正宜舟。","二室云中峻，三花烟外浮。","住居吾幸迩，先肯到嵩丘。"]},{"t":"闻吴郡黄山人将游五岳寄赠二首 其二","f":"五言律诗","c":["天柱峰头雪，莲花岭畔云。","朗吟惟李白，独往更黄君。","婚嫁今应毕，藜鞋有幸分。","共跻恒岱遍，归著五游文。"]},{"t":"东庄冬夜别程生自邑","f":"五言律诗","c":["万里孤村夜，疏灯对语心。","风枝时响牖，寒月故明林。","秦陇新游壮，江湖旧恨侵。","侧知南橐重，为有华山吟。"]},{"t":"巳丑八月京口逢五岳山人","f":"五言律诗","c":["夜雨清池馆，晨光散石林。","一舟相过日，千里独来心。","树拥江声断，潮生山气阴。","异时怀旧意，应比未逢深。"]},{"t":"京口杨相国园赠五岳山人","f":"五言律诗","c":["远客乘秋至，名园水竹分。","林寒番易两，池静合偏云。","卧疴思知己，逢君惬素闻。","萧萧绿云里，谁解有论文。"]},{"t":"九日黄花镇","f":"五言律诗","c":["黄花遇九日，风雨不逢花。","水涌石梁断，溪吞山郭斜。","将军午宴客，欲醉忽闻笳。","困苦墩楼卒，经年谁见家。"]},{"t":"九日应变斋居","f":"五言律诗","c":["时变逢摇落，斋心对暮天。","未擒可汗日，新起泰陵年。","听雁真无那，看花益泫然。","将归思临水，愁绝宋生篇。"]},{"t":"九日慈恩寺阁二首 其一","f":"五言律诗","c":["宝地元依海，珠林更假山。","登临重九遇，城阙五云还。","歌吹喧侯里，边烽入汉关。","望乡归未得，能对菊花斑。"]},{"t":"九日慈恩寺阁二首 其二","f":"五言律诗","c":["敕寺四围湖，秋林层阁孤。","天空木更响，风口帽还扶。","鱼群席下跃，鸟影镜中趋。","泛菊看山海，寒烟暮有无。"]},{"t":"生日写怀","f":"五言律诗","c":["腊日明朝是，浮生此岁过。","黄云薄暮积，白发向来多。","壮士看雄剑，幽人恋薜萝。","异时论出处，窃虑各蹉跎。"]},{"t":"十二月十日","f":"五言律诗","c":["今日吾兄寿，萧条自举觞。","燕山非故里，汴水亦他乡。","河鲤行思海，原鸰飞畏霜。","客居怜小侄，潜望白云长。"]},{"t":"腊日退朝口号","f":"五言律诗","c":["霁色催寒腊，鸡声下紫宸。","至尊深抱戚，粥食罢尝新。","宫雾戎戎薄，城鸦款款驯。","小臣怜岁序，翘首待阳春。"]},{"t":"七月十五月食不见追往有叹","f":"五言律诗","c":["月食今年再，中元与上元。","春晴灯火乱，秋瞑雨云繁。","汉将高城垒，胡尘满塞垣。","孤臣万古泪，偏洒泰陵园。"]},{"t":"月食","f":"五言律诗","c":["有明终不减，暂掩亦何亏。","万国喧呼地，三更鼓角悲。","轮生桂与发，光复兔还随。","显晦每如此，人生秪自疑。"]},{"t":"元日汴上雪霁","f":"五言律诗","c":["旭日薰江舰，晴云丽竹扉。","檐花雪色静，庭筱碧滋归。","岁月高儿女，行藏老蕨薇。","眼看人共醉，椒酒不堪挥。"]},{"t":"清明河上寓楼独酌","f":"五言律诗","c":["一自违京邑，飘飘叹此游。","桃花是往岁，竹叶转新愁。","暮雨津城树，春帆水国楼。","汴河堤上柳，烟色似皇州。"]},{"t":"庚午除日","f":"五言律诗","c":["于今将四十，始悟昔年非。","白发谁能那，红颜我渐违。","行藏沙上鸟，日月故山薇。","怅望劳歌起，风河柳色归。"]},{"t":"辛未元日","f":"五言律诗","c":["万事浑如昨，蹉跎四十临。","取途伤老马，闻道愧前禽。","日变风云气，春生海岳阴。","趁时聊物赏，此外更何心。"]},{"t":"中秋南康","f":"五言律诗","c":["同是中秋月，匡庐只自看。","故临石镜上，偏傍落星滩。","北望关山隔，南飞乌鹊寒。","凤歌喧太液，光忆满长安。"]},{"t":"庐山九日","f":"五言律诗","c":["庐山随晚坐，江汉净秋襟。","九日黄花雨，书堂红叶深。","细云飘古帙，寒兕吼空林。","不用风吹帽，尊前有静琴。"]},{"t":"上元滕阁宴二首 其一","f":"五言律诗","c":["滕阁上元宜，章江登宴时。","衣冠还大国，唐宋自残碑。","灯火阑堪凭，风尘泪欲垂。","黄云驱日暮，回首见征旗。"]},{"t":"上元滕阁宴二首 其二","f":"五言律诗","c":["阳浦通新雾，阴城带古楼。","君王罢歌舞，栋宇白云留。","草色岁年换，客心江水流。","暮昏仍一望，灯火万家州。"]},{"t":"九日薛楼会集二首 其一","f":"五言律诗","c":["不倦登楼目，遥怜秋色重。","枫村叠暗浦，霜日抱孤峰。","楚越窗中地，江山战后容。","倚阑浑不语，吾欲采芙蓉。"]},{"t":"九日薛楼会集二首 其二","f":"五言律诗","c":["恰送重阳日，能禁孤雁来。","林稀山尽出，风顺橹齐开。","况是薛楼会，难孤江上杯。","菊芳看莫厌，秋色异乡催。"]},{"t":"清明曲江亭阁","f":"五言律诗","c":["寒食花争丽，丰江柳独深。","此行元慷慨，落日更登临。","浩荡五湖际，风烟千里阴。","坐看舟楫急，徒切济川心。"]},{"t":"端午赣州晚发","f":"五言律诗","c":["戏倦龙舟返，吾驱彩鹢行。","晚天闻古驿，转眼过孤城。","袅袅云生濑，悠悠弟忆兄。","泛蒲虽念我，宁解岭边情。"]},{"t":"南康除夕","f":"五言律诗","c":["畏途值除夕，会我得投閒。","海雪寒城古，江春碧草还。","星河挂岳树，灯烛熨归颜。","窃计临家日，蔷薇满旧山。"]},{"t":"南康元夕二首 其一","f":"五言律诗","c":["四海逢今夕，孤城有独身。","干戈犹野哭，梅柳自江春。","月向平湖满，灯于静夜亲。","罢喧风乍起，嗟尔楚南人。"]},{"t":"南康元夕二首 其二","f":"五言律诗","c":["嘈嘈市鼓动，松月静吾门。","灯火思今夜，风光满故园。","天明淹舞袖，尘暗失游轩。","老鬓江山异，愁看旌旆繁。"]},{"t":"元夕风起南康","f":"五言律诗","c":["岳云黄袅袅，夜半忽凄风。","度市春灯乱，穿梅野树空。","人依青岸酌，月漾碧湖中。","拟尽江城赏，无欺蜡炬红。"]},{"t":"乙亥立秋","f":"五言律诗","c":["今日秋风起，连年湿病苏。","应时微雨歇，侵晓断云徂。","巳复寒蝉集，空嗟蕙草孤。","步檐惊骤健，一叶下庭梧。"]},{"t":"中秋二首 其一","f":"五言律诗","c":["汉江江上月，今夕去年看。","尚忆岘山曲，秋城波色寒。","故乡仍节序，衰鬓且儒冠。","桂子真谁种，天空落未乾。"]},{"t":"中秋二首 其二","f":"五言律诗","c":["辉辉众星没，宛宛孤轮高。","万古今宵月，青天首自搔。","广闺萤息照，悬树鸟分毛。","寂寞枚乘笔，空怀八月涛。"]},{"t":"戊寅元夕","f":"五言律诗","c":["春色闰冬后，元宵惊蛰边。","软尘欺月散，繁火夺星悬。","车马中原地，笙歌全盛年。","无劳验花烬，难测是皇天。"]},{"t":"中秋喜客携酒见访二首 其一","f":"五言律诗","c":["节有吾家会，天能此夜阴。","蟾蜍逐月没，桂子落云深。","同是悲秋客，况怀天柱心。","引杯光欲闪，徙倚向东林。"]}]};